final_template:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_key" {
  description = "Set to true to create a standard AWS-managed KMS key"
  type        = bool
  default     = true
}

variable "create_replica_key" {
  description = "Set to true to create a multi-region replica key (standard)"
  type        = bool
  default     = false
}

variable "key_usage" {
  description = "Intended use of the key (ENCRYPT_DECRYPT, SIGN_VERIFY, etc.)"
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Spec of the key (SYMMETRIC_DEFAULT, RSA_2048, etc.)"
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "multi_region" {
  description = "Indicates whether the key is a multi-region key (primary)"
  type        = bool
  default     = false
}

variable "description" {
  description = "Description of the key"
  type        = string
  default     = "Managed by Terraform"
}

variable "tags" {
  description = "Tags to apply to the key"
  type        = map(string)
  default     = {}
}

variable "primary_key_arn" {
  description = "ARN of the primary key for replica keys"
  type        = string
  default     = ""
}

# Policy variables
variable "key_owners" {
  description = "List of IAM ARNs that are key owners (full access)"
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "List of IAM ARNs that are key administrators"
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM ARNs that are key users (encrypt/decrypt etc.)"
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "List of IAM ARNs for service users (e.g., AWS services)"
  type        = list(string)
  default     = []
}

variable "ec2_auto_scaling_roles" {
  description = "List of IAM ARNs for EC2 Auto Scaling roles"
  type        = list(string)
  default     = []
}

variable "symmetric_users" {
  description = "List of IAM ARNs for symmetric crypto operations"
  type        = list(string)
  default     = []
}

variable "hmac_users" {
  description = "List of IAM ARNs for HMAC operations"
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_users" {
  description = "List of IAM ARNs for asymmetric public encryption operations"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "List of IAM ARNs for asymmetric sign/verify operations"
  type        = list(string)
  default     = []
}

variable "route53_dnssec_users" {
  description = "List of IAM ARNs for Route53 DNSSEC signing"
  type        = list(string)
  default     = []
}

variable "custom_policy_statements" {
  description = "List of custom policy statements (each is a map with Sid, Effect, Action, Resource, Principal, Condition)"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = list(object({
      type        = string
      identifiers = list(string)
    }))
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "override_policy_document" {
  description = "If provided, this JSON policy document will be used instead of the generated one"
  type        = string
  default     = ""
}

# Alias variables
variable "aliases" {
  description = "Map of alias names (or name prefixes) to create. Key is alias name (without 'alias/'), value is a map with optional 'name' (exact) or 'name_prefix' (prefix)."
  type = map(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = {}
}

# Grant variables
variable "grants" {
  description = "List of grants to create. Each grant has grantee_principal, operations, retiring_principal (optional), and constraints (optional)."
  type = list(object({
    grantee_principal = string
    operations        = list(string)
    retiring_principal = optional(string)
    constraints = optional(object({
      encryption_context_subset = optional(map(string))
      encryption_context_equals = optional(map(string))
    }))
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  # Key ID and ARN from the active key resource
  key_id  = var.create_key ? aws_kms_key.this[0].key_id : aws_kms_replica_key.this[0].key_id
  key_arn = var.create_key ? aws_kms_key.this[0].arn : aws_kms_replica_key.this[0].arn

  # Use custom policy if override is provided
  use_custom_policy = var.override_policy_document != ""

  # Account ID, partition
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# ------------------------------------------------------------------------------
# Key Resources
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.create_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true
  key_usage               = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  multi_region            = var.multi_region
  policy                  = local.use_custom_policy ? var.override_policy_document : data.aws_iam_policy_document.key_policy[0].json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "this" {
  count = var.create_replica_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = 30
  enabled                 = true
  policy                  = local.use_custom_policy ? var.override_policy_document : data.aws_iam_policy_document.key_policy[0].json
  tags                    = var.tags

  # Primary key ARN
  primary_key_arn = var.primary_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Key Policy Document (only if not overridden)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "key_policy" {
  count = local.use_custom_policy ? 0 : 1

  # Root account full access
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Key owners
  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []
    content {
      sid    = "Allow access for Key Owners"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_owners
      }
      actions   = ["kms:*"]
      resources = ["*"]
    }
  }

  # Key administrators
  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "Allow access for Key Administrators"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion"
      ]
      resources = ["*"]
    }
  }

  # Standard key users
  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "Allow use of the key"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Service users
  dynamic "statement" {
    for_each = length(var.service_users) > 0 ? [1] : []
    content {
      sid    = "Allow access for AWS Services"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.service_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # EC2 Auto Scaling roles
  dynamic "statement" {
    for_each = length(var.ec2_auto_scaling_roles) > 0 ? [1] : []
    content {
      sid    = "Allow Auto Scaling to use the key"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.ec2_auto_scaling_roles
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Symmetric crypto users
  dynamic "statement" {
    for_each = length(var.symmetric_users) > 0 ? [1] : []
    content {
      sid    = "Allow symmetric cryptographic operations"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.symmetric_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # HMAC users
  dynamic "statement" {
    for_each = length(var.hmac_users) > 0 ? [1] : []
    content {
      sid    = "Allow HMAC operations"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.hmac_users
      }
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Asymmetric public encryption users
  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "Allow asymmetric public encryption operations"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encryption_users
      }
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKeyPair*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Asymmetric sign/verify users
  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "Allow asymmetric sign/verify operations"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_users
      }
      actions = [
        "kms:Sign",
        "kms:Verify",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Route53 DNSSEC users
  dynamic "statement" {
    for_each = length(var.route53_dnssec_users) > 0 ? [1] : []
    content {
      sid    = "Allow Route53 DNSSEC signing"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = var.route53_dnssec_users
      }
      actions = [
        "kms:GetPublicKey",
        "kms:Sign",
        "kms:DescribeKey"
      ]
      resources = ["*"]
    }
  }

  # Custom policy statements
  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Aliases
# ------------------------------------------------------------------------------
resource "aws_kms_alias" "this" {
  for_each = var.aliases

  name          = each.value.name != null ? "alias/${each.value.name}" : null
  name_prefix   = each.value.name_prefix != null ? "alias/${each.value.name_prefix}" : null
  target_key_id = local.key_id
}

# ------------------------------------------------------------------------------
# Grants
# ------------------------------------------------------------------------------
resource "aws_kms_grant" "this" {
  for_each = { for idx, grant in var.grants : idx => grant }

  name              = "grant-${each.key}"
  key_id            = local.key_id
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = each.value.constraints != null ? [each.value.constraints] : []
    content {
      encryption_context_subset = constraints.value.encryption_context_subset
      encryption_context_equals = constraints.value.encryption_context_equals
    }
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "key_arn" {
  description = "ARN of the created KMS key"
  value       = local.key_arn
}

output "key_id" {
  description = "ID of the created KMS key"
  value       = local.key_id
}

output "alias_arns" {
  description = "Map of alias names to ARNs"
  value = {
    for alias_name, alias in aws_kms_alias.this : alias_name => alias.arn
  }
}

output "grant_ids" {
  description = "List of grant IDs"
  value = [for grant in aws_kms_grant.this : grant.grant_id]
}

terraform {
  required_version = ">= 1.0, < 2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "topic_name" {
  description = "Name of the SNS topic. For FIFO topics, the name must end with '.fifo'."
  type        = string
  default     = "my-sns-topic"
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for the SNS topic."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of a customer managed KMS key to use when create_kms_key is false. Must not be the AWS managed SNS key ('alias/aws/sns')."
  type        = string
  default     = null
  validation {
    condition     = var.create_kms_key || (var.kms_key_arn != null && var.kms_key_arn != "alias/aws/sns")
    error_message = "Either create a KMS key (create_kms_key = true) or provide a valid CMK ARN (not the AWS managed SNS key)."
  }
}

variable "topic_policy_json" {
  description = "Optional JSON policy document to attach to the SNS topic."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Whether to enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN for application delivery failure feedback."
  type        = string
  default     = null
}

variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN for HTTP delivery failure feedback."
  type        = string
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN for Lambda delivery failure feedback."
  type        = string
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN for SQS delivery failure feedback."
  type        = string
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN for Firehose delivery failure feedback."
  type        = string
  default     = null
}

variable "application_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for application success feedback."
  type        = number
  default     = null
}

variable "http_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for HTTP success feedback."
  type        = number
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Lambda success feedback."
  type        = number
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for SQS success feedback."
  type        = number
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Firehose success feedback."
  type        = number
  default     = null
}

variable "subscriptions" {
  description = "Map of subscriptions to create on the SNS topic."
  type = map(object({
    endpoint                      = string
    protocol                      = string
    confirmation_timeout_in_minutes = optional(number)
    endpoint_auto_confirms        = optional(bool)
    raw_message_delivery          = optional(bool)
    filter_policy                 = optional(string)
    filter_policy_scope           = optional(string)
    redrive_policy                = optional(string)
  }))
  default = {}
}

# KMS Key and Alias (conditional)
data "aws_iam_policy_document" "sns_kms_key_policy" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow CloudWatch Logs to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Allow SNS service to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key for SNS topic ${var.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_key_policy[0].json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/sns/${var.topic_name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# SNS Topic
resource "aws_sns_topic" "main" {
  name = var.topic_name

  kms_master_key_id = var.create_kms_key ? aws_kms_key.sns[0].arn : var.kms_key_arn

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication

  application_failure_feedback_role_arn = var.application_failure_feedback_role_arn
  http_failure_feedback_role_arn        = var.http_failure_feedback_role_arn
  lambda_failure_feedback_role_arn      = var.lambda_failure_feedback_role_arn
  sqs_failure_feedback_role_arn         = var.sqs_failure_feedback_role_arn
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn

  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  http_success_feedback_sample_rate        = var.http_success_feedback_sample_rate
  lambda_success_feedback_sample_rate      = var.lambda_success_feedback_sample_rate
  sqs_success_feedback_sample_rate         = var.sqs_success_feedback_sample_rate
  firehose_success_feedback_sample_rate    = var.firehose_success_feedback_sample_rate

  lifecycle {
    prevent_destroy = true
  }
}

# Optional Topic Policy
resource "aws_sns_topic_policy" "main" {
  count = var.topic_policy_json != null ? 1 : 0

  arn    = aws_sns_topic.main.arn
  policy = var.topic_policy_json
}

# Subscriptions
resource "aws_sns_topic_subscription" "main" {
  for_each = var.subscriptions

  topic_arn = aws_sns_topic.main.arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol

  confirmation_timeout_in_minutes = lookup(each.value, "confirmation_timeout_in_minutes", null)
  endpoint_auto_confirms          = lookup(each.value, "endpoint_auto_confirms", null)
  raw_message_delivery            = lookup(each.value, "raw_message_delivery", null)
  filter_policy                   = lookup(each.value, "filter_policy", null)
  filter_policy_scope             = lookup(each.value, "filter_policy_scope", null)
  redrive_policy                  = lookup(each.value, "redrive_policy", null)
}

# Data sources for account and region (used in KMS policy)
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------- Variables ----------
variable "create_iam_developer_group" {
  description = "Toggle creation of the IAM developers group"
  type        = bool
  default     = true
}

variable "create_iam_read_only_and_s3_full_access_policy" {
  description = "Toggle creation of the IAM read-only and S3 full access policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Toggle attachment of the policy to the developers group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle creation of IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_console_screenshot_policy" {
  description = "Toggle creation of the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Toggle attachment of EC2 screenshot policy to each user"
  type        = bool
  default     = true
}

variable "create_group_membership" {
  description = "Toggle group membership for users"
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Toggle creation of the EC2 instance role"
  type        = bool
  default     = true
}

variable "iam_group_name" {
  description = "Name of the IAM group"
  type        = string
  default     = "developers"
}

variable "iam_users" {
  description = "List of IAM user names to create"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for the S3 full access policy (placeholder)"
  type        = string
  default     = "example-bucket"
}

# ---------- Data Sources ----------
data "aws_iam_policy_document" "iam_read_only_and_s3_full_access" {
  statement {
    effect = "Allow"
    actions = [
      "iam:Get*",
      "iam:List*"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket"
    ]
    resources = ["arn:aws:s3:::${var.s3_bucket_name}/*"]
  }
}

data "aws_iam_policy_document" "ec2_get_console_screenshot" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:GetConsoleScreenshot"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "instance_role_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# ---------- Resources ----------
# IAM Group
resource "aws_iam_group" "developers" {
  count = var.create_iam_developer_group ? 1 : 0
  name  = var.iam_group_name
}

# IAM Policy: Read only + S3 full access
resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count       = var.create_iam_read_only_and_s3_full_access_policy ? 1 : 0
  name        = "iam_read_only_and_s3_full_access"
  description = "Allows read-only IAM access and object-level S3 access to a specific bucket"
  policy      = data.aws_iam_policy_document.iam_read_only_and_s3_full_access.json
}

# Group Policy Attachment
resource "aws_iam_group_policy_attachment" "read_only_s3_full_access_to_group" {
  count = var.create_iam_developer_group && var.create_iam_read_only_and_s3_full_access_policy && var.create_group_policy_attachment ? 1 : 0
  group = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

# IAM Users
resource "aws_iam_user" "this" {
  for_each = var.create_iam_users ? toset(var.iam_users) : toset([])
  name     = each.key
  tags = {
    user_created_by = "terraform"
  }
}

# IAM Policy: EC2 Console Screenshot
resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count       = var.create_ec2_console_screenshot_policy ? 1 : 0
  name        = "ec2_get_console_screenshot"
  description = "Allows EC2 console screenshot access"
  policy      = data.aws_iam_policy_document.ec2_get_console_screenshot.json
}

# User Policy Attachments (EC2 screenshot policy)
resource "aws_iam_user_policy_attachment" "ec2_screenshot_to_user" {
  for_each = var.create_iam_users && var.create_ec2_console_screenshot_policy && var.create_user_policy_attachments ? toset(var.iam_users) : toset([])
  user     = each.key
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

# Group Membership
resource "aws_iam_group_membership" "developers" {
  count = var.create_iam_developer_group && var.create_iam_users && var.create_group_membership ? 1 : 0
  name  = "developers-membership"
  group = aws_iam_group.developers[0].name
  users = [for user in var.iam_users : aws_iam_user.this[user].name]
}

# EC2 Instance Role
resource "aws_iam_role" "instance_role" {
  count              = var.create_ec2_instance_role ? 1 : 0
  name               = "instance_role"
  assume_role_policy = data.aws_iam_policy_document.instance_role_assume_role.json
}

# Attach AWS managed IAMReadOnlyAccess to instance role
resource "aws_iam_role_policy_attachment" "instance_role_readonly" {
  count      = var.create_ec2_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# ------------------------------------------------------------------------------
# TERRAFORM SETTINGS
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "create_backup_vault" {
  description = "Conditionally create the backup vault"
  type        = bool
  default     = true
}

variable "create_vault_notifications" {
  description = "Conditionally create SNS topic and vault notifications"
  type        = bool
  default     = true
}

variable "create_backup_iam_role" {
  description = "Conditionally create the IAM role for AWS Backup"
  type        = bool
  default     = true
}

variable "create_backup_plan" {
  description = "Conditionally create the backup plan"
  type        = bool
  default     = true
}

variable "create_backup_selection" {
  description = "Conditionally create backup selections"
  type        = bool
  default     = true
}

variable "create_global_settings" {
  description = "Conditionally create global settings"
  type        = bool
  default     = true
}

variable "create_region_settings" {
  description = "Conditionally create region settings"
  type        = bool
  default     = true
}

variable "create_vault_access_policy" {
  description = "Conditionally create vault access policy"
  type        = bool
  default     = true
}

variable "backup_vault_name" {
  description = "Explicit name for the backup vault (overrides default naming)"
  type        = string
  default     = ""
}

variable "backup_plan_name" {
  description = "Explicit name for the backup plan (overrides default naming)"
  type        = string
  default     = ""
}

variable "backup_selection_name" {
  description = "Explicit name for the backup selection (overrides default naming)"
  type        = string
  default     = ""
}

variable "sns_topic_name" {
  description = "Explicit name for the SNS topic (overrides default naming)"
  type        = string
  default     = ""
}

variable "iam_role_name" {
  description = "Explicit name for the IAM role (overrides default naming)"
  type        = string
  default     = ""
}

variable "kms_key_arn" {
  description = "ARN of KMS key for vault encryption (defaults to AWS managed backup key)"
  type        = string
  default     = ""
}

variable "sns_kms_key_arn" {
  description = "ARN of KMS key for SNS topic encryption (defaults to AWS managed SNS key)"
  type        = string
  default     = ""
}

variable "is_organization_member" {
  description = "Whether the AWS account is a member of AWS Organizations (enables cross-account backup)"
  type        = bool
  default     = false
}

variable "backup_plan_rules" {
  description = "List of backup plan rules"
  type = list(object({
    rule_name           = string
    target_vault_name   = string
    schedule            = string
    start_window        = number
    completion_window   = number
    recovery_point_tags = map(string)
    lifecycle = object({
      cold_storage_after_days = number
      delete_after_days       = number
    })
    copy_action = list(object({
      destination_vault_arn = string
      lifecycle = object({
        cold_storage_after_days = number
        delete_after_days       = number
      })
    }))
  }))
  default = [
    {
      rule_name           = "daily-backup"
      target_vault_name   = ""
      schedule            = "cron(0 5 * * ? *)"
      start_window        = 60
      completion_window   = 120
      recovery_point_tags = {}
      lifecycle = {
        cold_storage_after_days = 30
        delete_after_days       = 365
      }
      copy_action = []
    }
  ]
}

variable "backup_selections" {
  description = "List of backup selection configurations"
  type = list(object({
    name       = string
    resources  = list(string)
    selection_tag = list(object({
      type  = string
      key   = string
      value = string
    }))
  }))
  default = [
    {
      name       = ""
      resources  = []
      selection_tag = [
        {
          type  = "STRINGEQUALS"
          key   = "Backup"
          value = "true"
        }
      ]
    }
  ]
}

# ------------------------------------------------------------------------------
# DATA SOURCES (static lookups only)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

data "aws_kms_key" "backup_default" {
  count    = var.create_backup_vault && var.kms_key_arn == "" ? 1 : 0
  key_id   = "alias/aws/backup"
}

data "aws_kms_key" "sns_default" {
  count  = var.create_vault_notifications && var.sns_kms_key_arn == "" ? 1 : 0
  key_id = "alias/aws/sns"
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  prefix_lower      = lower(var.prefix)
  environment_lower = lower(var.environment)

  vault_name_constructed    = "${local.prefix_lower}-backup-vault-${local.environment_lower}"
  plan_name_constructed     = "${local.prefix_lower}-backup-plan-${local.environment_lower}"
  selection_name_constructed = "${local.prefix_lower}-backup-selection-${local.environment_lower}"
  sns_topic_name_constructed = "${local.prefix_lower}-backup-notifications-${local.environment_lower}"
  iam_role_name_constructed  = "${local.prefix_lower}-backup-role-${local.environment_lower}"

  vault_name    = var.backup_vault_name != "" ? var.backup_vault_name : local.vault_name_constructed
  plan_name     = var.backup_plan_name != "" ? var.backup_plan_name : local.plan_name_constructed
  selection_name = var.backup_selection_name != "" ? var.backup_selection_name : local.selection_name_constructed
  sns_topic_name = var.sns_topic_name != "" ? var.sns_topic_name : local.sns_topic_name_constructed
  iam_role_name  = var.iam_role_name != "" ? var.iam_role_name : local.iam_role_name_constructed

  common_tags = {
    Name        = local.vault_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }

  vault_kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : (
    var.create_backup_vault && var.kms_key_arn == "" ? data.aws_kms_key.backup_default[0].arn : ""
  )

  sns_kms_key_arn_final = var.sns_kms_key_arn != "" ? var.sns_kms_key_arn : (
    var.create_vault_notifications && var.sns_kms_key_arn == "" ? data.aws_kms_key.sns_default[0].arn : ""
  )
}

# ------------------------------------------------------------------------------
# RESOURCES
# ------------------------------------------------------------------------------

# 1. Backup Vault
resource "aws_backup_vault" "main" {
  count = var.create_backup_vault ? 1 : 0

  name        = local.vault_name
  kms_key_arn = local.vault_kms_key_arn
  force_destroy = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# 2. SNS Topic (for vault notifications)
resource "aws_sns_topic" "backup_notifications" {
  count = var.create_vault_notifications ? 1 : 0

  name              = local.sns_topic_name
  kms_master_key_id = local.sns_kms_key_arn_final

  tags = merge(local.common_tags, {
    Name = local.sns_topic_name
  })
}

# 3. IAM Role for AWS Backup
resource "aws_iam_role" "backup" {
  count = var.create_backup_iam_role ? 1 : 0

  name = local.iam_role_name

  assume_role_policy = data.aws_iam_policy_document.backup_assume_role[0].json

  tags = merge(local.common_tags, {
    Name = local.iam_role_name
  })
}

data "aws_iam_policy_document" "backup_assume_role" {
  count = var.create_backup_iam_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  count = var.create_backup_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  count = var.create_backup_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# 4. Backup Plan
resource "aws_backup_plan" "main" {
  count = var.create_backup_plan ? 1 : 0

  name = local.plan_name

  dynamic "rule" {
    for_each = var.backup_plan_rules
    content {
      rule_name         = rule.value.rule_name
      target_vault_name = rule.value.target_vault_name != "" ? rule.value.target_vault_name : aws_backup_vault.main[0].name
      schedule          = rule.value.schedule
      start_window      = rule.value.start_window
      completion_window = rule.value.completion_window

      recovery_point_tags = rule.value.recovery_point_tags

      lifecycle {
        cold_storage_after = rule.value.lifecycle.cold_storage_after_days
        delete_after       = rule.value.lifecycle.delete_after_days
      }

      dynamic "copy_action" {
        for_each = rule.value.copy_action
        content {
          destination_vault_arn = copy_action.value.destination_vault_arn
          lifecycle {
            cold_storage_after = copy_action.value.lifecycle.cold_storage_after_days
            delete_after       = copy_action.value.lifecycle.delete_after_days
          }
        }
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.plan_name
  })
}

# 5. Backup Selections
resource "aws_backup_selection" "main" {
  count = var.create_backup_selection ? length(var.backup_selections) : 0

  name         = var.backup_selections[count.index].name != "" ? var.backup_selections[count.index].name : "${local.selection_name}-${count.index}"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.main[0].id

  resources = var.backup_selections[count.index].resources

  dynamic "selection_tag" {
    for_each = var.backup_selections[count.index].selection_tag
    content {
      type  = selection_tag.value.type
      key   = selection_tag.value.key
      value = selection_tag.value.value
    }
  }
}

# 6. Global Settings
resource "aws_backup_global_settings" "main" {
  count = var.create_global_settings && var.is_organization_member ? 1 : 0

  global_settings = {
    isCrossAccountBackupEnabled = "true"
  }
}

# 7. Region Settings
resource "aws_backup_region_settings" "main" {
  count = var.create_region_settings ? 1 : 0

  resource_type_opt_in_preference = {
    "Aurora"          = true
    "DynamoDB"        = true
    "EBS"             = true
    "EC2"             = true
    "EFS"             = true
    "FSx"             = true
    "RDS"             = true
    "Storage Gateway" = true
  }
}

# 8. Vault Access Policy
data "aws_iam_policy_document" "vault_access" {
  count = var.create_vault_access_policy ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.account_id]
    }
    actions = [
      "backup:StartBackupJob",
      "backup:StartRestoreJob",
      "backup:DescribeBackupVault"
    ]
    resources = [aws_backup_vault.main[0].arn]
  }

  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = [
      "backup:StartBackupJob",
      "backup:StartRestoreJob",
      "backup:DescribeBackupVault"
    ]
    resources = [aws_backup_vault.main[0].arn]
  }
}

resource "aws_backup_vault_policy" "main" {
  count = var.create_vault_access_policy ? 1 : 0

  backup_vault_name = aws_backup_vault.main[0].name
  policy            = data.aws_iam_policy_document.vault_access[0].json
}

# 9. Vault Notifications
resource "aws_backup_vault_notifications" "main" {
  count = var.create_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main[0].name
  sns_topic_arn       = aws_sns_topic.backup_notifications[0].arn
  backup_vault_events = ["BACKUP_JOB_STARTED", "RESTORE_JOB_COMPLETED"]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.10.0.0/16"
}

variable "subnet_names" {
  description = "Names for the seven subnets"
  type        = list(string)
  default     = ["web", "app", "db", "mgmt", "web2", "app2", "db2"]
}

variable "route_table_names" {
  description = "Names for the two route tables"
  type        = list(string)
  default     = ["public", "private"]
}

variable "associations_map" {
  description = "Mapping of subnet indices to route table names"
  type        = map(list(number))
  default = {
    public  = [0, 3, 4]
    private = [1, 2, 5, 6]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "ntier primary"
  }
}

resource "aws_subnet" "subnet" {
  count             = 7
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = var.subnet_names[count.index]
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ntier primary"
  }

  depends_on = [aws_subnet.subnet]
}

resource "aws_route_table" "rt" {
  count  = 2
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.route_table_names[count.index]
  }
}

resource "aws_route_table_association" "public" {
  for_each = { for idx in var.associations_map["public"] : idx => idx }

  subnet_id      = aws_subnet.subnet[tonumber(each.key)].id
  route_table_id = aws_route_table.rt[0].id
}

resource "aws_route_table_association" "private" {
  for_each = { for idx in var.associations_map["private"] : idx => idx }

  subnet_id      = aws_subnet.subnet[tonumber(each.key)].id
  route_table_id = aws_route_table.rt[1].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "multi-cluster-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  private_subnet_cidrs = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]
  public_subnet_cidrs = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]
  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnets = local.private_subnet_cidrs
  public_subnets  = local.public_subnet_cidrs

  enable_nat_gateway   = true
  single_nat_gateway   = true
  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }
  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "cluster1_additional_sg"
  vpc_id      = module.vpc.vpc_id
  tags        = local.tags
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "cluster2_additional_sg"
  vpc_id      = module.vpc.vpc_id
  tags        = local.tags
}

resource "aws_security_group_rule" "cluster1_egress_ipv4" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [module.vpc.vpc_cidr_block]
  security_group_id = aws_security_group.cluster1_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_egress_ipv4" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [module.vpc.vpc_cidr_block]
  security_group_id = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "pool_name" {
  type    = string
  default = "Pool name"
}

variable "alias_attributes" {
  type    = list(string)
  default = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type    = list(string)
  default = []
}

variable "email_verification_message" {
  type    = string
  default = "Some message {####}"
}

variable "email_verification_subject" {
  type    = string
  default = "Some subject"
}

variable "mfa_configuration" {
  type    = string
  default = "OPTIONAL"
}

variable "sms_authentication_message" {
  type    = string
  default = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type    = string
  default = "SMS verification message {####}"
}

variable "verification_message_template_by_link" {
  type    = map(string)
  default = {}
}

variable "sms_configuration" {
  type    = map(string)
  default = {
    external_id   = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  type = list(map(any))
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

variable "invite_message_template" {
  type    = map(string)
  default = {}
}

variable "admin_create_user_only" {
  type    = bool
  default = false
}

variable "software_token_mfa_enabled" {
  type    = bool
  default = true
}

variable "case_sensitive_username" {
  type    = bool
  default = null
}

variable "device_configuration" {
  type    = map(any)
  default = {}
}

variable "lambda_trigger_config_map" {
  type    = map(string)
  default = {}
}

variable "custom_schema_attributes" {
  type = list(map(any))
  default = [
    {
      name                = "email"
      required            = true
      mutable             = true
      attribute_data_type = "String"
    }
  ]
}

variable "client_app_names" {
  type    = list(string)
  default = []
}

variable "client_generate_secret" {
  type    = bool
  default = false
}

variable "token_validities" {
  type    = map(number)
  default = {
    access_token  = 120
    id_token      = 120
    refresh_token = 7
  }
}

variable "token_validity_units" {
  type    = map(string)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "allowed_oauth_flows_user_pool_client" {
  type    = bool
  default = false
}

variable "enable_token_revocation" {
  type    = bool
  default = true
}

variable "explicit_auth_flows" {
  type    = list(string)
  default = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "prevent_user_existence_errors" {
  type    = string
  default = "LEGACY"
}

variable "read_attributes" {
  type    = list(string)
  default = []
}

variable "write_attributes" {
  type    = list(string)
  default = []
}

variable "callback_urls" {
  type    = list(string)
  default = []
}

variable "logout_urls" {
  type    = list(string)
  default = []
}

variable "allowed_oauth_flows" {
  type    = list(string)
  default = []
}

variable "allowed_oauth_scopes" {
  type    = list(string)
  default = []
}

variable "supported_identity_providers" {
  type    = list(string)
  default = []
}

variable "group_name" {
  type    = string
  default = ""
}

variable "group_precedence" {
  type    = number
  default = 0
}

variable "group_role_arn" {
  type    = string
  default = ""
}

variable "domain_string" {
  type    = string
  default = ""
}

variable "acm_certificate_arn" {
  type    = string
  default = ""
}

variable "create_route53_record" {
  type    = bool
  default = false
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

# Locals
locals {
  enable_sms_config     = length(var.sms_configuration.external_id) > 0 && length(var.sms_configuration.sns_caller_arn) > 0
  enable_device_config  = length(keys(var.device_configuration)) > 0
  enable_lambda_config  = length(keys(var.lambda_trigger_config_map)) > 0
  triggers              = var.lambda_trigger_config_map
}

# IAM role for Lambda triggers (one per trigger type)
resource "aws_iam_role" "lambda_trigger" {
  for_each = local.triggers

  name = "${var.pool_name}-lambda-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  for_each = local.triggers

  role       = aws_iam_role.lambda_trigger[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Local file to create a placeholder zip for Lambda functions
resource "null_resource" "placeholder_zip" {
  triggers = {
    always = timestamp()
  }

  provisioner "local-exec" {
    command = "echo 'exports.handler = async () => ({ statusCode: 200, body: \"ok\" });' > index.js && zip -j placeholder.zip index.js && rm index.js"
  }
}

# Placeholder Lambda function for each trigger
resource "aws_lambda_function" "trigger" {
  for_each = local.triggers

  filename      = "placeholder.zip"
  function_name = "${var.pool_name}-trigger-${each.key}"
  role          = aws_iam_role.lambda_trigger[each.key].arn
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  publish       = false

  depends_on = [
    null_resource.placeholder_zip
  ]

  lifecycle {
    ignore_changes = [
      filename,
    ]
  }
}

# Main Cognito User Pool
resource "aws_cognito_user_pool" "main" {
  name = var.pool_name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "sms_configuration" {
    for_each = local.enable_sms_config ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive_username != null ? [1] : []
    content {
      case_sensitive = var.case_sensitive_username
    }
  }

  dynamic "device_configuration" {
    for_each = local.enable_device_config ? [1] : []
    content {
      challenge_required_on_new_device      = lookup(var.device_configuration, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(var.device_configuration, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "lambda_config" {
    for_each = local.enable_lambda_config ? [1] : []
    content {
      create_auth_challenge          = lookup(local.triggers, "create_auth_challenge", null)
      custom_message                 = lookup(local.triggers, "custom_message", null)
      define_auth_challenge          = lookup(local.triggers, "define_auth_challenge", null)
      post_authentication            = lookup(local.triggers, "post_authentication", null)
      post_confirmation              = lookup(local.triggers, "post_confirmation", null)
      pre_authentication             = lookup(local.triggers, "pre_authentication", null)
      pre_sign_up                    = lookup(local.triggers, "pre_sign_up", null)
      pre_token_generation           = lookup(local.triggers, "pre_token_generation", null)
      user_migration                 = lookup(local.triggers, "user_migration", null)
      verify_auth_challenge_response = lookup(local.triggers, "verify_auth_challenge_response", null)

      custom_email_sender {
        lambda_arn     = lookup(local.triggers, "custom_email_sender", null)
        lambda_version = "$LATEST"
      }

      custom_sms_sender {
        lambda_arn     = lookup(local.triggers, "custom_sms_sender", null)
        lambda_version = "$LATEST"
      }
    }
  }

  verification_message_template {
    default_email_option = lookup(var.verification_message_template_by_link, "default_email_option", null)
    email_message        = lookup(var.verification_message_template_by_link, "email_message", null)
    email_subject        = lookup(var.verification_message_template_by_link, "email_subject", null)
    sms_message          = lookup(var.verification_message_template_by_link, "sms_message", null)
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = var.recovery_mechanisms[0].name
      priority = var.recovery_mechanisms[0].priority
    }
    recovery_mechanism {
      name     = var.recovery_mechanisms[1].name
      priority = var.recovery_mechanisms[1].priority
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only
    dynamic "invite_message_template" {
      for_each = length(keys(var.invite_message_template)) > 0 ? [1] : []
      content {
        email_message = lookup(var.invite_message_template, "email_message", null)
        email_subject = lookup(var.invite_message_template, "email_subject", null)
        sms_message   = lookup(var.invite_message_template, "sms_message", null)
      }
    }
  }

  dynamic "schema" {
    for_each = var.custom_schema_attributes
    content {
      name                = schema.value.name
      required            = lookup(schema.value, "required", null)
      mutable             = lookup(schema.value, "mutable", null)
      attribute_data_type = schema.value.attribute_data_type

      dynamic "string_attribute_constraints" {
        for_each = schema.value.attribute_data_type == "String" && contains(keys(schema.value), "min_length") ? [1] : []
        content {
          min_length = lookup(schema.value, "min_length", null)
          max_length = lookup(schema.value, "max_length", null)
        }
      }
    }
  }

  lifecycle {
    ignore_changes = []
  }
}

# User Pool Clients
resource "aws_cognito_user_pool_client" "client" {
  for_each = toset(var.client_app_names)

  user_pool_id = aws_cognito_user_pool.main.id
  name         = each.key

  generate_secret = var.client_generate_secret

  access_token_validity  = var.token_validities.access_token
  id_token_validity      = var.token_validities.id_token
  refresh_token_validity = var.token_validities.refresh_token

  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }

  allowed_oauth_flows_user_pool_client = var.allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.enable_token_revocation
  explicit_auth_flows                  = var.explicit_auth_flows
  prevent_user_existence_errors        = var.prevent_user_existence_errors

  read_attributes  = var.read_attributes
  write_attributes = var.write_attributes

  callback_urls           = var.callback_urls
  logout_urls             = var.logout_urls
  allowed_oauth_flows     = var.allowed_oauth_flows
  allowed_oauth_scopes    = var.allowed_oauth_scopes
  supported_identity_providers = var.supported_identity_providers
}

# User Group (conditional)
resource "aws_cognito_user_group" "group" {
  count = var.group_name != "" ? 1 : 0

  user_pool_id = aws_cognito_user_pool.main.id
  name         = var.group_name
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : null
}

# User Pool Domain (conditional)
resource "aws_cognito_user_pool_domain" "domain" {
  count = var.domain_string != "" ? 1 : 0

  domain           = var.domain_string
  user_pool_id     = aws_cognito_user_pool.main.id
  certificate_arn  = var.acm_certificate_arn != "" ? var.acm_certificate_arn : null
}

# Route53 A-record (conditional)
resource "aws_route53_record" "alias" {
  count = var.create_route53_record && var.route53_zone_id != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = aws_cognito_user_pool_domain.domain[0].domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "byoip_pool_name" {
  description = "BYOIP pool name for the Elastic IP"
  type        = string
  default     = "amazon"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "vpc_igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

# Subnet A (Public – but public IP mapping disabled per security policy)
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "Subnet-A-Public"
  }
}

# Subnet B (Private)
resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "Subnet-B-Private"
  }
}

# Subnet C (Private)
resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = "Subnet-C-Private"
  }
}

# Route Table (Public)
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpc_igw.id
  }

  tags = {
    Name = var.route_table_name
  }
}

# Route Table Association (only Subnet A)
resource "aws_route_table_association" "public_subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

# Elastic IP (VPC-scoped, using BYOIP pool)
resource "aws_eip" "nat_eip" {
  domain           = "vpc"
  public_ipv4_pool = var.byoip_pool_name
}

# NAT Gateway (placed in Subnet B as requested)
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.subnet_b.id

  depends_on = [aws_internet_gateway.vpc_igw]

  tags = {
    Name = var.nat_gateway_name
  }
}

# Security Group (DefaultSecurityGroup) – egress restricted to VPC CIDR
resource "aws_security_group" "default_sg" {
  name        = "DefaultSecurityGroup"
  description = "Default security group allowing outbound traffic only within the VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr_block]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "tags" {
  description = "Optional tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "tag_key" {
  description = "Tag key used for backup selection conditions"
  type        = string
  default     = "backup"
}

variable "enable_continuous_backup" {
  description = "Enable continuous backup for the daily plan"
  type        = bool
  default     = false
}

variable "enable_notifications" {
  description = "Enable backup vault notifications via SNS"
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for backup notifications"
  type        = string
  default     = "backup-notifications"
}

variable "notification_events" {
  description = "List of backup events to send notifications for"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# KMS Key for backup vault encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "main" {
  description             = "KMS key for AWS Backup vault encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Backup Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Backup Vault
# ------------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.main.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM Role for Backup
# ------------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  name = "${var.vault_name}-backup-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ------------------------------------------------------------------------------
# Backup Plans
# ------------------------------------------------------------------------------
resource "aws_backup_plan" "daily" {
  name = "${var.vault_name}-daily"

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  rule {
    rule_name               = "daily_backup_rule"
    target_vault_name       = aws_backup_vault.main.name
    schedule                = "cron(0 12 ? * * *)"
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  tags = var.tags
}

resource "aws_backup_plan" "weekly" {
  name = "${var.vault_name}-weekly"

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 ? * 1 *)"

    lifecycle {
      delete_after = 31
    }
  }

  tags = var.tags
}

resource "aws_backup_plan" "monthly" {
  name = "${var.vault_name}-monthly"

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 1 * ? *)"

    lifecycle {
      delete_after = 366
    }
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Backup Selections
# ------------------------------------------------------------------------------
resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "daily"
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "weekly"
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = "monthly"
  }
}

# ------------------------------------------------------------------------------
# Notifications (conditional)
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "backup_notifications" {
  count = var.enable_notifications ? 1 : 0
  name  = var.sns_topic_name
  tags  = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_notifications" "main" {
  count = var.enable_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = aws_sns_topic.backup_notifications[0].arn
  backup_vault_events = var.notification_events
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag value"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = var.region
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-igw"
  })
}

# Public subnets
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-public-subnet-${count.index}"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-public-subnets"
  })
}

# Associate public subnets with public route table
resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-eip-${count.index}"
  })
}

# NAT Gateways (one per private subnet, placed in the corresponding public subnet)
resource "aws_nat_gateway" "nat" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-gw-${count.index}"
  })

  depends_on = [aws_internet_gateway.main]
}

# Private subnets
resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-private-subnet-${count.index}"
  })
}

# Private route tables (one per private subnet, each with a route to the corresponding NAT Gateway)
resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-private-subnets-${count.index}"
  })
}

# Associate private subnets with their respective private route tables
resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_eks" {
  description = "Boolean flag to control creation of the EKS cluster"
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster's access config"
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the cluster VPC configuration"
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  description = "List of control plane subnet IDs (takes precedence over subnet_ids)"
  type        = list(string)
  default     = []
}

locals {
  # Use control_plane_subnet_ids if provided, otherwise fall back to subnet_ids
  subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks-cluster" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks-cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks-cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name       = var.cluster_name
  role_arn   = aws_iam_role.eks-cluster.arn
  version    = var.cluster_version

  vpc_config {
    subnet_ids = local.subnet_ids
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

