terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Data Sources
# ---------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------------------------------------------------
variable "name" {
  description = "Global prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment identifier"
  type        = string
  default     = "STAGE"
}

# Conditional enable flags
variable "enable_sns_topic" {
  description = "Flag to create SNS topic"
  type        = bool
  default     = true
}

variable "enable_sns_topic_policy" {
  description = "Flag to create standalone SNS topic policy"
  type        = bool
  default     = false
}

variable "enable_sns_topic_subscription" {
  description = "Flag to create SNS topic subscriptions"
  type        = bool
  default     = false
}

variable "enable_sns_sms_preferences" {
  description = "Flag to create SNS SMS preferences"
  type        = bool
  default     = false
}

variable "enable_sns_platform_application" {
  description = "Flag to create SNS platform application"
  type        = bool
  default     = false
}

# SNS Topic variables
variable "topic_name" {
  description = "Name of the SNS topic (mutually exclusive with topic_name_prefix)"
  type        = string
  default     = ""
}

variable "topic_name_prefix" {
  description = "Prefix for the SNS topic name (mutually exclusive with topic_name)"
  type        = string
  default     = ""
}

variable "topic_display_name" {
  description = "Display name for the SNS topic"
  type        = string
  default     = ""
}

variable "topic_policy" {
  description = "JSON policy document for the SNS topic"
  type        = string
  default     = ""
}

variable "kms_key_id" {
  description = "KMS key ID (ARN) for encrypting SNS messages. If empty, a new KMS key is created."
  type        = string
  default     = ""
}

# Feedback roles and sample rates (per protocol)
variable "application_success_feedback_role_arn" {
  description = "ARN of the IAM role for application success feedback"
  type        = string
  default     = ""
}

variable "application_failure_feedback_role_arn" {
  description = "ARN of the IAM role for application failure feedback"
  type        = string
  default     = ""
}

variable "application_success_feedback_sample_rate" {
  description = "Sample rate for application success feedback (0-100)"
  type        = number
  default     = 100
}

variable "http_success_feedback_role_arn" {
  description = "ARN of the IAM role for HTTP success feedback"
  type        = string
  default     = ""
}

variable "http_failure_feedback_role_arn" {
  description = "ARN of the IAM role for HTTP failure feedback"
  type        = string
  default     = ""
}

variable "http_success_feedback_sample_rate" {
  description = "Sample rate for HTTP success feedback (0-100)"
  type        = number
  default     = 100
}

variable "lambda_success_feedback_role_arn" {
  description = "ARN of the IAM role for Lambda success feedback"
  type        = string
  default     = ""
}

variable "lambda_failure_feedback_role_arn" {
  description = "ARN of the IAM role for Lambda failure feedback"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate for Lambda success feedback (0-100)"
  type        = number
  default     = 100
}

variable "sqs_success_feedback_role_arn" {
  description = "ARN of the IAM role for SQS success feedback"
  type        = string
  default     = ""
}

variable "sqs_failure_feedback_role_arn" {
  description = "ARN of the IAM role for SQS failure feedback"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate for SQS success feedback (0-100)"
  type        = number
  default     = 100
}

# Topic Policy variables
variable "topic_policy_document" {
  description = "JSON policy document for the standalone topic policy"
  type        = string
  default     = ""
}

variable "topic_policy_topic_arn" {
  description = "ARN of the topic to attach the policy to. If empty, defaults to the created topic."
  type        = string
  default     = ""
}

# Subscription variables
variable "subscription_endpoints" {
  description = "List of subscription endpoints (SQS queue names or other protocol endpoints)"
  type        = list(string)
  default     = []
}

variable "subscription_protocols" {
  description = "List of protocols corresponding to each endpoint (default 'sqs')"
  type        = list(string)
  default     = []
}

variable "subscription_confirmation_timeout_in_minutes" {
  description = "Timeout for subscription confirmation"
  type        = number
  default     = 1
}

variable "subscription_endpoint_auto_confirms" {
  description = "Whether the endpoint auto-confirms"
  type        = bool
  default     = false
}

variable "subscription_raw_message_delivery" {
  description = "Enable raw message delivery"
  type        = bool
  default     = false
}

variable "subscription_filter_policy" {
  description = "JSON filter policy"
  type        = string
  default     = ""
}

variable "subscription_delivery_policy" {
  description = "JSON delivery policy"
  type        = string
  default     = ""
}

variable "subscription_topic_arn_override" {
  description = "Override topic ARN for subscriptions"
  type        = string
  default     = ""
}

# SMS Preferences variables
variable "sms_monthly_spend_limit" {
  description = "Maximum monthly SMS spend limit in USD"
  type        = number
  default     = 1.0
}

variable "sms_delivery_status_iam_role_arn" {
  description = "IAM role ARN for SMS delivery status. If empty, a new role is created."
  type        = string
  default     = ""
}

variable "sms_success_sample_rate" {
  description = "Sample rate for SMS delivery status (0-100)"
  type        = number
  default     = 100
}

variable "sms_default_sender_id" {
  description = "Default sender ID for SMS"
  type        = string
  default     = ""
}

variable "sms_default_sms_type" {
  description = "Default SMS type (Promotional or Transactional)"
  type        = string
  default     = "Promotional"
}

variable "sms_usage_report_s3_bucket" {
  description = "S3 bucket name for SMS usage reports. If empty, a new bucket is created."
  type        = string
  default     = ""
}

# Platform Application variables
variable "platform" {
  description = "Platform type for the SNS platform application (e.g., GCM, APNS, ADM)"
  type        = string
  default     = ""
}

variable "platform_credential" {
  description = "Platform credential string (e.g., API key for GCM). Stored in Secrets Manager."
  type        = string
  default     = ""
  sensitive   = true
}

variable "platform_principal" {
  description = "Platform principal (optional, e.g., for APNs)"
  type        = string
  default     = ""
}

variable "event_delivery_failure_topic_arn" {
  description = "Topic ARN for delivery failure events"
  type        = string
  default     = ""
}

variable "event_endpoint_created_topic_arn" {
  description = "Topic ARN for endpoint created events"
  type        = string
  default     = ""
}

variable "event_endpoint_deleted_topic_arn" {
  description = "Topic ARN for endpoint deleted events"
  type        = string
  default     = ""
}

variable "event_endpoint_updated_topic_arn" {
  description = "Topic ARN for endpoint updated events"
  type        = string
  default     = ""
}

variable "platform_success_feedback_role_arn" {
  description = "IAM role ARN for platform application success feedback"
  type        = string
  default     = ""
}

variable "platform_failure_feedback_role_arn" {
  description = "IAM role ARN for platform application failure feedback"
  type        = string
  default     = ""
}

variable "platform_success_feedback_sample_rate" {
  description = "Sample rate for platform application success feedback (0-100)"
  type        = number
  default     = 100
}

# ---------------------------------------------------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------------------------------------------------
locals {
  name_lower      = lower(var.name)
  env_lower       = lower(var.environment)
  default_topic_name = "${local.name_lower}-sns-${local.env_lower}"

  # Topic name: use name if provided, else name_prefix, else default
  topic_name = var.topic_name != "" ? var.topic_name : (
    var.topic_name_prefix != "" ? null : local.default_topic_name
  )
  topic_name_prefix = var.topic_name_prefix != "" && var.topic_name == "" ? var.topic_name_prefix : null

  # Display name: if empty, use default
  display_name = var.topic_display_name != "" ? var.topic_display_name : local.default_topic_name

  # Conditionally resolve the topic ARN only when the topic is created
  topic_arn = var.enable_sns_topic ? aws_sns_topic.main[0].arn : ""

  # Subscription endpoints and protocols as a map
  subscription_map = {
    for idx, ep in var.subscription_endpoints :
    idx => {
      endpoint  = ep
      protocol  = try(var.subscription_protocols[idx], "sqs")
      filter    = var.subscription_filter_policy
      delivery  = var.subscription_delivery_policy
    }
  }

  # Indices where protocol is sqs (to create SQS queues)
  sqs_subscription_indices = {
    for idx, sub in local.subscription_map : idx => idx if sub.protocol == "sqs"
  }

  # Resolve topic ARN for subscriptions using a direct conditional to avoid coalesce issues
  subscription_topic_arn = var.subscription_topic_arn_override != "" ? var.subscription_topic_arn_override : local.topic_arn

  # SMS preferences
  sms_s3_bucket_name = var.sms_usage_report_s3_bucket != "" ? var.sms_usage_report_s3_bucket : "${local.name_lower}-sns-sms-reports-${local.env_lower}"

  # Platform application name
  platform_app_name = "${local.name_lower}-sns-plat-app-${local.env_lower}"

  # Determine if we need to create a KMS key
  create_kms_key = var.enable_sns_topic && var.kms_key_id == "" ? 1 : 0
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS Key for SNS Topic (if needed)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  count = local.create_kms_key

  description             = "SNS topic encryption key for ${local.default_topic_name}"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable SNS Service"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "${local.name_lower}-sns-kms-${local.env_lower}"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM Roles for SNS Topic Feedback (per protocol)
# ---------------------------------------------------------------------------------------------------------------------
locals {
  # Create role only if enable_sns_topic is true and the respective ARN variable is empty
  create_app_feedback_role      = var.enable_sns_topic && var.application_success_feedback_role_arn == "" && var.application_failure_feedback_role_arn == ""
  create_http_feedback_role     = var.enable_sns_topic && var.http_success_feedback_role_arn == "" && var.http_failure_feedback_role_arn == ""
  create_lambda_feedback_role   = var.enable_sns_topic && var.lambda_success_feedback_role_arn == "" && var.lambda_failure_feedback_role_arn == ""
  create_sqs_feedback_role      = var.enable_sns_topic && var.sqs_success_feedback_role_arn == "" && var.sqs_failure_feedback_role_arn == ""
}

resource "aws_iam_role" "sns_feedback_app" {
  count = local.create_app_feedback_role ? 1 : 0

  name = "${local.name_lower}-sns-feedback-app-${local.env_lower}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${local.name_lower}-sns-feedback-app-${local.env_lower}"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "sns_feedback_app" {
  count = local.create_app_feedback_role ? 1 : 0

  name = "${local.name_lower}-sns-feedback-app-policy"
  role = aws_iam_role.sns_feedback_app[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role" "sns_feedback_http" {
  count = local.create_http_feedback_role ? 1 : 0

  name = "${local.name_lower}-sns-feedback-http-${local.env_lower}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${local.name_lower}-sns-feedback-http-${local.env_lower}"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "sns_feedback_http" {
  count = local.create_http_feedback_role ? 1 : 0

  name = "${local.name_lower}-sns-feedback-http-policy"
  role = aws_iam_role.sns_feedback_http[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role" "sns_feedback_lambda" {
