    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "sns_feedback_lambda" {
  count = local.create_lambda_feedback_role ? 1 : 0

  name = "${local.name_lower}-sns-feedback-lambda-policy"
  role = aws_iam_role.sns_feedback_lambda[0].id

