# ---------------------------------------------------------------------------------------------------------------------
# SNS Topic
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "main" {
  count = var.enable_sns_topic ? 1 : 0

  name         = local.topic_name
  name_prefix  = local.topic_name_prefix
  display_name = local.display_name
  policy       = var.topic_policy != "" ? var.topic_policy : null

  kms_master_key_id = var.kms_key_id != "" ? var.kms_key_id : try(aws_kms_key.sns[0].arn, null)

  # Feedback roles – use variables if provided, otherwise fallback to created roles
  application_success_feedback_role_arn = try(coalesce(var.application_success_feedback_role_arn, aws_iam_role.sns_feedback_app[0].arn), "")
  application_failure_feedback_role_arn = try(coalesce(var.application_failure_feedback_role_arn, aws_iam_role.sns_feedback_app[0].arn), "")
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate

  http_success_feedback_role_arn = try(coalesce(var.http_success_feedback_role_arn, aws_iam_role.sns_feedback_http[0].arn), "")
  http_failure_feedback_role_arn = try(coalesce(var.http_failure_feedback_role_arn, aws_iam_role.sns_feedback_http[0].arn), "")
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate

  lambda_success_feedback_role_arn = try(coalesce(var.lambda_success_feedback_role_arn, aws_iam_role.sns_feedback_lambda[0].arn), "")
  lambda_failure_feedback_role_arn = try(coalesce(var.lambda_failure_feedback_role_arn, aws_iam_role.sns_feedback_lambda[0].arn), "")
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate

  sqs_success_feedback_role_arn = try(coalesce(var.sqs_success_feedback_role_arn, aws_iam_role.sns_feedback_sqs[0].arn), "")
  sqs_failure_feedback_role_arn = try(coalesce(var.sqs_failure_feedback_role_arn, aws_iam_role.sns_feedback_sqs[0].arn), "")
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate

  tags = {
    Name        = local.topic_name
    Environment = var.environment
  }

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SQS Queues for Subscription Endpoints (if protocol is sqs)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sqs_queue" "subscription" {
  for_each = var.enable_sns_topic_subscription && local.subscription_topic_arn != "" ? local.sqs_subscription_indices : {}

  name = "${local.name_lower}-sns-sub-${each.value}-${local.env_lower}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sqs:SendMessage"
        Resource = "arn:aws:sqs:*:*:${local.name_lower}-sns-sub-${each.value}-${local.env_lower}"
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = local.topic_arn
          }
        }
      }
    ]
  })

  tags = {
    Name        = "${local.name_lower}-sns-sub-${each.value}-${local.env_lower}"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS Topic Subscriptions
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "list" {
  for_each = var.enable_sns_topic_subscription && local.subscription_topic_arn != "" ? local.subscription_map : {}

  topic_arn = local.subscription_topic_arn

  protocol = each.value.protocol
  endpoint = each.value.protocol == "sqs" ? aws_sqs_queue.subscription[each.key].arn : each.value.endpoint

  confirmation_timeout_in_minutes = var.subscription_confirmation_timeout_in_minutes
  endpoint_auto_confirms          = var.subscription_endpoint_auto_confirms
  raw_message_delivery            = var.subscription_raw_message_delivery
  filter_policy                   = each.value.filter != "" ? each.value.filter : null
  delivery_policy                 = each.value.delivery != "" ? each.value.delivery : null

  lifecycle {
    precondition {
      condition     = local.subscription_topic_arn != ""
      error_message = "A valid topic ARN is required for subscriptions. Provide subscription_topic_arn_override or enable the SNS topic."
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Standalone SNS Topic Policy
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic_policy" "standalone" {
  count = var.enable_sns_topic_policy && (var.topic_policy_topic_arn != "" || var.enable_sns_topic) ? 1 : 0

  arn    = try(coalesce(var.topic_policy_topic_arn, aws_sns_topic.main[0].arn), "")
  policy = var.topic_policy_document

  lifecycle {
    precondition {
      condition     = var.topic_policy_topic_arn != "" || var.enable_sns_topic
      error_message = "Either topic_policy_topic_arn must be provided or enable_sns_topic must be true to create a topic policy."
    }
  }
}

