    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "sns_sms_delivery_status" {
  count = var.enable_sns_sms_preferences && var.sms_delivery_status_iam_role_arn == "" ? 1 : 0

  name = "${local.name_lower}-sns-sms-delivery-status-policy"
