  })
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 Bucket for SMS Usage Reports
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "sns_sms_reports" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  bucket = local.sms_s3_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "sns_sms_reports" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  bucket = aws_s3_bucket.sns_sms_reports[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sns_sms_reports" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  bucket = aws_s3_bucket.sns_sms_reports[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "sns_sms_reports" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  bucket = aws_s3_bucket.sns_sms_reports[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "sns_sms_reports" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  bucket = aws_s3_bucket.sns_sms_reports[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSNSWrite"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          "arn:aws:s3:::${local.sms_s3_bucket_name}",
          "arn:aws:s3:::${local.sms_s3_bucket_name}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS SMS Preferences
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_sms_preferences" "main" {
  count = var.enable_sns_sms_preferences ? 1 : 0

  monthly_spend_limit              = var.sms_monthly_spend_limit
  delivery_status_iam_role_arn     = coalesce(var.sms_delivery_status_iam_role_arn, try(aws_iam_role.sns_sms_delivery_status[0].arn, ""))
  delivery_status_success_sampling_rate = var.sms_success_sample_rate
  default_sender_id                 = var.sms_default_sender_id != "" ? var.sms_default_sender_id : null
  default_sms_type                  = var.sms_default_sms_type
  usage_report_s3_bucket            = aws_s3_bucket.sns_sms_reports[0].id
}

