# SNS Platform Application
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_platform_application" "main" {
  count = var.enable_sns_platform_application ? 1 : 0

  name         = local.platform_app_name
  platform     = var.platform
  platform_credential = aws_secretsmanager_secret_version.platform_credential[0].secret_string
  platform_principal = var.platform_principal != "" ? var.platform_principal : null

  event_delivery_failure_topic_arn = var.event_delivery_failure_topic_arn != "" ? var.event_delivery_failure_topic_arn : null
  event_endpoint_created_topic_arn  = var.event_endpoint_created_topic_arn != "" ? var.event_endpoint_created_topic_arn : null
  event_endpoint_deleted_topic_arn  = var.event_endpoint_deleted_topic_arn != "" ? var.event_endpoint_deleted_topic_arn : null
  event_endpoint_updated_topic_arn  = var.event_endpoint_updated_topic_arn != "" ? var.event_endpoint_updated_topic_arn : null

  success_feedback_role_arn  = coalesce(var.platform_success_feedback_role_arn, try(aws_iam_role.sns_plat_success[0].arn, ""))
  failure_feedback_role_arn  = coalesce(var.platform_failure_feedback_role_arn, try(aws_iam_role.sns_plat_failure[0].arn, ""))
  success_feedback_sample_rate = var.platform_success_feedback_sample_rate
}

# Required providers and version
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for partition DNS suffix
data "aws_partition" "current" {}

# Variables
variable "name" {
  description = "Module name; defaults to 'default' if null or empty"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "bus_config" {
  description = "Event bus configuration (optional); must be non-null"
  type        = any
  default     = {}

  validation {
    condition     = var.bus_config != null
    error_message = "bus_config must not be null."
  }
}

variable "rules" {
  description = "List of event rules; must be non-null"
  type        = list(any)
  default     = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  description = "List of event targets; must be non-null"
  type        = list(any)
  default     = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

# Local value for normalized name
locals {
  name = var.name != null && var.name != "" ? var.name : "default"
}

# Event bus (only if name is not "default")
resource "aws_cloudwatch_event_bus" "custom" {
  count = local.name != "default" ? 1 : 0

  name = local.name
  tags = var.tags

  event_source_name = try(var.bus_config.event_source_name, null)
}

# IAM role for EventBridge to invoke targets
resource "aws_iam_role" "invoke" {
  name = "${local.name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.${data.aws_partition.current.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# IAM policy for invoke role
resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.name}-invoke-targets"
  role = aws_iam_role.invoke.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

# Event rules
resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for r in var.rules : r.name => r }

  name                = each.key
  description         = try(each.value.description, null)
  event_pattern       = try(each.value.event_pattern, null)
  schedule_expression = try(each.value.schedule_expression, null)
  event_bus_name      = local.name != "default" ? local.name : "default"

  tags = var.tags
}

# Event targets
resource "aws_cloudwatch_event_target" "this" {
  for_each = { for t in var.targets : "${t.rule}-${t.arn}" => t }

  rule           = each.value.rule
  arn            = each.value.arn
  event_bus_name = local.name != "default" ? local.name : "default"
  role_arn       = strcontains(each.value.arn, "stateMachine") ? aws_iam_role.invoke.arn : null

  depends_on = [
    aws_cloudwatch_event_rule.this,
    aws_iam_role.invoke
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type        = string
  default     = "default"
  description = "Base name used for resource naming and tagging."
}

variable "kms_key_arn" {
  type        = string
  default     = ""
  description = "Optional KMS key ARN for vault encryption. If empty, AWS default KMS key is used."
}

variable "vault_policy" {
  type        = string
  default     = ""
  description = "Optional JSON policy document for the backup vault. Attached only when non-empty."
}

variable "schedule" {
  type        = string
  default     = "cron(0 5 * * ? *)"
  description = "Cron expression for the backup schedule."
}

variable "start_window" {
  type        = number
  default     = 60
  description = "Start window for the backup rule in minutes."
}

variable "completion_window" {
  type        = number
  default     = 120
  description = "Completion window for the backup rule in minutes."
}

variable "destination_vault_map" {
  type        = map(string)
  default     = {}
  description = "Map of destination region to vault ARN for copy actions. Key is region, value is vault ARN."
}

variable "sns_topic_arn" {
  type        = string
  default     = ""
  description = "Optional SNS topic ARN for vault event notifications. Configured only when non-empty."
}

variable "tag_key" {
  type        = string
  default     = "Backup"
  description = "Tag key used for backup selection filtering."
}

variable "tag_value" {
  type        = string
  default     = "true"
  description = "Tag value used for backup selection filtering."
}

locals {
  job_tag = "${var.name}-backup"
}

# IAM Role for AWS Backup
resource "aws_iam_role" "backup" {
  name               = "aws-backup-${var.name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup Vault
resource "aws_backup_vault" "this" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null
  tags = {
    Job = local.job_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Backup Vault Policy (conditional)
resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# Backup Plan
resource "aws_backup_plan" "this" {
  name = "plan-${var.name}-backup"
  tags = {
    Job = local.job_tag
  }

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window
    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_map
      content {
        destination_vault_arn = copy_action.value
      }
    }
  }
}

# Backup Selection
resource "aws_backup_selection" "this" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id
  resources    = []  # Can be empty; tag-based selection is used

  condition {
    # Empty condition block - no additional conditions
  }

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = var.tag_value
  }
}

# Backup Vault Notifications (conditional)
resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  description = "Base name for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name for resource naming"
  type        = string
  default     = "STAGE"
}

variable "enable_efs_file_system" {
  description = "Flag to create the EFS file system"
  type        = bool
  default     = true
}

variable "enable_efs_mount_target" {
  description = "Flag to create mount targets"
  type        = bool
  default     = false
}

variable "enable_efs_file_system_policy" {
  description = "Flag to create a file system policy"
  type        = bool
  default     = false
}

variable "enable_efs_access_point" {
  description = "Flag to create an access point"
  type        = bool
  default     = false
}

variable "creation_token" {
  description = "Unique creation token for the file system (defaults to name_prefix)"
  type        = string
  default     = ""
}

variable "performance_mode" {
  description = "Performance mode of the file system: generalPurpose or maxIO"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode: bursting or provisioned"
  type        = string
  default     = "bursting"
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s (required when throughput_mode = provisioned)"
  type        = number
  default     = null
}

variable "encrypted" {
  description = "Enable encryption at rest"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "KMS key ID for encryption (defaults to AWS managed key)"
  type        = string
  default     = null
}

variable "lifecycle_policy_rules" {
  description = "List of lifecycle policy rules to transition files to IA storage"
  type = list(object({
    transition_to_ia = string
  }))
  default = [
    {
      transition_to_ia = "AFTER_30_DAYS"
    }
  ]
}

variable "subnet_ids" {
  description = "List of subnet IDs for mount targets"
  type        = list(string)
  default     = []
}

variable "mount_target_ip_address" {
  description = "Optional IP address for the first mount target (applied to all if only one subnet provided)"
  type        = string
  default     = null
}

variable "mount_target_security_groups" {
  description = "List of security group IDs for mount targets"
  type        = list(string)
  default     = []
}

variable "file_system_id_override_mount_target" {
  description = "Override file system ID for mount targets (when not using the created file system)"
  type        = string
  default     = ""
}

variable "file_system_policy" {
  description = "JSON policy document for the file system"
  type        = string
  default     = ""
}

variable "file_system_id_override_policy" {
  description = "Override file system ID for the file system policy"
  type        = string
  default     = ""
}

variable "access_point_posix_user" {
  description = "POSIX user settings for the access point"
  type = object({
    uid            = number
    gid            = number
    secondary_gids = list(number)
  })
  default = {
    uid            = 0
    gid            = 0
    secondary_gids = []
  }
}

variable "access_point_root_directory" {
  description = "Root directory configuration for the access point"
  type = object({
    path = string
    creation_info = object({
      owner_uid   = number
      owner_gid   = number
      permissions = string
    })
  })
  default = {
    path = "/"
    creation_info = {
      owner_uid   = 0
      owner_gid   = 0
      permissions = "0755"
    }
  }
}

variable "file_system_id_override_access_point" {
  description = "Override file system ID for the access point"
  type        = string
  default     = ""
}

locals {
  name_prefix = "${lower(var.name)}-${lower(var.environment)}-"
  # Determine the file system ID from the created resource (only if enabled)
  efs_file_system_id = var.enable_efs_file_system ? try(aws_efs_file_system.this[0].id, null) : null
  # Use explicit override if provided, otherwise fall back to the created file system ID
  effective_mount_target_fs_id = var.file_system_id_override_mount_target != "" ? var.file_system_id_override_mount_target : local.efs_file_system_id
  effective_policy_fs_id       = var.file_system_id_override_policy != "" ? var.file_system_id_override_policy : local.efs_file_system_id
  effective_access_point_fs_id = var.file_system_id_override_access_point != "" ? var.file_system_id_override_access_point : local.efs_file_system_id
}

# ---------------------------------------------------------------------------------------------------------------------
# EFS FILE SYSTEM
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_efs_file_system" "this" {
  count = var.enable_efs_file_system ? 1 : 0

  creation_token                 = var.creation_token != "" ? var.creation_token : local.name_prefix
  performance_mode               = var.performance_mode
  throughput_mode                = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null
  encrypted                      = var.encrypted
  kms_key_id                     = var.kms_key_id

  dynamic "lifecycle_policy" {
    for_each = var.lifecycle_policy_rules
    content {
      transition_to_ia = lifecycle_policy.value.transition_to_ia
    }
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name        = "${local.name_prefix}efs"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# EFS MOUNT TARGETS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_efs_mount_target" "this" {
  for_each = var.enable_efs_mount_target && local.effective_mount_target_fs_id != null ? toset(var.subnet_ids) : toset([])

  file_system_id  = local.effective_mount_target_fs_id
  subnet_id       = each.key
  ip_address      = var.mount_target_ip_address
  security_groups = length(var.mount_target_security_groups) > 0 ? var.mount_target_security_groups : null
}

# ---------------------------------------------------------------------------------------------------------------------
# EFS FILE SYSTEM POLICY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_efs_file_system_policy" "this" {
  count = var.enable_efs_file_system_policy && local.effective_policy_fs_id != null ? 1 : 0

  file_system_id = local.effective_policy_fs_id
  policy         = var.file_system_policy
}

# ---------------------------------------------------------------------------------------------------------------------
# EFS ACCESS POINT
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_efs_access_point" "this" {
  count = var.enable_efs_access_point && local.effective_access_point_fs_id != null ? 1 : 0

  file_system_id = local.effective_access_point_fs_id

  posix_user {
    uid            = var.access_point_posix_user.uid
    gid            = var.access_point_posix_user.gid
    secondary_gids = var.access_point_posix_user.secondary_gids
  }

  root_directory {
    path = var.access_point_root_directory.path
    creation_info {
      owner_uid   = var.access_point_root_directory.creation_info.owner_uid
      owner_gid   = var.access_point_root_directory.creation_info.owner_gid
      permissions = var.access_point_root_directory.creation_info.permissions
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "name" {
  description = "Prefix for resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment identifier"
  type        = string
  default     = "STAGE"
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

# Boolean flags to control resource creation
variable "enable_codeartifact_domain" {
  description = "Enable CodeArtifact domain creation"
  type        = bool
  default     = true
}

variable "enable_codeartifact_domain_permissions_policy" {
  description = "Enable CodeArtifact domain permissions policy"
  type        = bool
  default     = false
}

variable "enable_codeartifact_repository" {
  description = "Enable CodeArtifact repository creation"
  type        = bool
  default     = false
}

variable "enable_codeartifact_repository_permissions_policy" {
  description = "Enable CodeArtifact repository permissions policy"
  type        = bool
  default     = false
}

# Domain explicit overrides
variable "domain_name" {
  description = "Explicit name for the CodeArtifact domain (falls back to constructed name if empty)"
  type        = string
  default     = ""
}

variable "domain_kms_key_arn" {
  description = "ARN of the KMS key to encrypt the domain (optional)"
  type        = string
  default     = ""
}

# Domain permissions policy overrides
variable "domain_permissions_policy_document" {
  description = "JSON policy document for the domain permissions policy"
  type        = string
  default     = ""
}

variable "domain_owner_id" {
  description = "AWS account ID of the domain owner (optional)"
  type        = string
  default     = ""
}

variable "domain_policy_revision" {
  description = "Revision of the domain policy to update (optional)"
  type        = string
  default     = ""
}

# Repository explicit overrides
variable "repository_name" {
  description = "Explicit name for the CodeArtifact repository (falls back to constructed name if empty)"
  type        = string
  default     = ""
}

variable "repository_description" {
  description = "Description for the repository"
  type        = string
  default     = ""
}

variable "repository_domain_owner" {
  description = "AWS account ID of the domain owner for the repository (optional)"
  type        = string
  default     = ""
}

variable "repository_upstream_names" {
  description = "List of upstream repository names to associate"
  type        = list(string)
  default     = []
}

variable "repository_external_connections" {
  description = "List of external connection names (e.g., 'public:npmjs')"
  type        = list(string)
  default     = []
}

# Repository permissions policy overrides
variable "repository_permissions_policy_document" {
  description = "JSON policy document for the repository permissions policy"
  type        = string
  default     = ""
}

variable "repository_policy_domain_owner" {
  description = "AWS account ID of the domain owner for the repository permissions policy (optional)"
  type        = string
  default     = ""
}

variable "repository_policy_revision" {
  description = "Revision of the repository policy to update (optional)"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# CodeArtifact Domain
# ------------------------------------------------------------------------------
resource "aws_codeartifact_domain" "this" {
  count = var.enable_codeartifact_domain ? 1 : 0

  domain = lower(
    var.domain_name != "" ? var.domain_name : "${lower(var.name)}-codeartifact-domain-${lower(var.environment)}"
  )

  encryption_key = var.domain_kms_key_arn != "" ? var.domain_kms_key_arn : null

  tags = merge(
    {
      Name = lower(
        var.domain_name != "" ? var.domain_name : "${lower(var.name)}-codeartifact-domain-${lower(var.environment)}"
      )
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# CodeArtifact Domain Permissions Policy
# ------------------------------------------------------------------------------
resource "aws_codeartifact_domain_permissions_policy" "this" {
  count = var.enable_codeartifact_domain_permissions_policy ? 1 : 0

  domain = var.domain_name != "" ? lower(var.domain_name) : aws_codeartifact_domain.this[0].domain

  policy_document = var.domain_permissions_policy_document

  domain_owner   = var.domain_owner_id != "" ? var.domain_owner_id : null
  policy_revision = var.domain_policy_revision != "" ? var.domain_policy_revision : null

  depends_on = [aws_codeartifact_domain.this]
}

# ------------------------------------------------------------------------------
# CodeArtifact Repository
# ------------------------------------------------------------------------------
resource "aws_codeartifact_repository" "this" {
  count = var.enable_codeartifact_repository ? 1 : 0

  repository = lower(
    var.repository_name != "" ? var.repository_name : "${lower(var.name)}-codeartifact-repository-${lower(var.environment)}"
  )

  domain = aws_codeartifact_domain.this[0].domain

  description = var.repository_description != "" ? var.repository_description : null
  domain_owner = var.repository_domain_owner != "" ? var.repository_domain_owner : null

  dynamic "upstream" {
    for_each = var.repository_upstream_names
    content {
      repository_name = upstream.value
    }
  }

  dynamic "external_connections" {
    for_each = var.repository_external_connections
    content {
      external_connection_name = external_connections.value
    }
  }

  tags = merge(
    {
      Name = lower(
        var.repository_name != "" ? var.repository_name : "${lower(var.name)}-codeartifact-repository-${lower(var.environment)}"
      )
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# CodeArtifact Repository Permissions Policy
# ------------------------------------------------------------------------------
resource "aws_codeartifact_repository_permissions_policy" "this" {
  count = var.enable_codeartifact_repository_permissions_policy ? 1 : 0

  domain = aws_codeartifact_domain.this[0].domain

  repository = var.repository_name != "" ? lower(var.repository_name) : aws_codeartifact_repository.this[0].repository

  policy_document = var.repository_permissions_policy_document

  domain_owner   = var.repository_policy_domain_owner != "" ? var.repository_policy_domain_owner : null
  policy_revision = var.repository_policy_revision != "" ? var.repository_policy_revision : null

  depends_on = [
    aws_codeartifact_domain.this,
    aws_codeartifact_repository.this
  ]

  lifecycle {
    create_before_destroy = true
  }
}

# Variables
variable "rolename" {
  default = "WizAccess-Role"
}

variable "remote-arn" {
  default = "arn:aws:iam::830522659852:role/prod-us43-AssumeRoleDelegator"
}

variable "external-id" {
  default = "fc959d31-537c-4108-8b87-9af9e0c9b8d2"
}

# Local values for read-only actions
