    "connect:Describe*", "connect:List*", "connect:Get*",
    "dynamodb:Describe*", "dynamodb:Get*", "dynamodb:List*", "dynamodb:Query", "dynamodb:Scan",
    "ec2:Describe*", "ec2:Get*", "ec2:List*",
    "ecr:Describe*", "ecr:Get*", "ecr:List*",
