    "efs:Describe*", "efs:List*", "efs:Get*",
    "emr:Describe*", "emr:List*", "emr:Get*",
    "ssm:Describe*", "ssm:Get*", "ssm:List*",
    "glacier:Describe*", "glacier:Get*", "glacier:List*",
    "glue:Describe*", "glue:Get*", "glue:List*", "glue:Batch*",
    "health:Describe*", "health:List*",
    "kafka:Describe*", "kafka:List*", "kafka:Get*",
    "kendra:Describe*", "kendra:List*", "kendra:Get*",
    "kinesisanalytics:Describe*", "kinesisanalytics:List*", "kinesisanalytics:Get*",
