# IAM role
resource "aws_iam_role" "wiz_access_role" {
  name = var.rolename
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = var.remote-arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external-id
          }
        }
      }
    ]
  })
}

# Attach AWS-managed policies
resource "aws_iam_role_policy_attachment" "view_only_access" {
  role       = aws_iam_role.wiz_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/job-function/ViewOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.wiz_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

# Inline custom policy
data "aws_iam_policy_document" "wiz_custom_policy" {
  # Statement 1: Read-only access
  statement {
    sid       = "WizReadOnlyAccess"
    effect    = "Allow"
    actions   = local.read_actions
    resources = ["*"]
  }

  # Statement 2: EBS snapshot creation and metadata
  statement {
    sid    = "WizEBSSnapshotActions"
    effect = "Allow"
    actions = [
      "ec2:CopySnapshot",
      "ec2:CreateSnapshot",
      "ec2:GetEbsEncryptionByDefault",
      "ec2:DescribeSnapshots"
    ]
    resources = ["*"]
  }

  # Statement 3: Tag creation on snapshots
  statement {
    sid    = "WizTagCreation"
    effect = "Allow"
    actions = [
      "ec2:CreateTags"
    ]
    resources = [
      "arn:aws:ec2:*:*:snapshot/*"
    ]
  }

  # Statement 4: KMS alias creation
  statement {
    sid    = "WizKMSAliasCreation"
    effect = "Allow"
    actions = [
      "kms:CreateAlias"
    ]
    resources = [
      "arn:aws:kms:*:*:alias/wizKey",
      "arn:aws:kms:*:*:key/*"
    ]
  }

  # Statement 5: KMS key policy actions with condition
  statement {
    sid    = "WizKMSKeyPolicy"
    effect = "Allow"
    actions = [
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/wiz"
      values   = ["auto-gen-cmk"]
    }
  }

  # Statement 6: Snapshot deletion and modification with condition
  statement {
    sid    = "WizSnapshotModify"
    effect = "Allow"
    actions = [
      "ec2:DeleteSnapshot",
      "ec2:ModifySnapshotAttribute"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "ec2:ResourceTag/wiz"
      values   = ["auto-gen-snapshot"]
    }
  }

  # Statement 7: Explicit Deny S3 GetObject
  statement {
    sid    = "WizAccessS3"
    effect = "Deny"
    actions = [
      "s3:GetObject"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "wiz_custom_policy" {
  name   = "WizCustomPolicy"
  role   = aws_iam_role.wiz_access_role.name
  policy = data.aws_iam_policy_document.wiz_custom_policy.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "enable_admin" {
  default     = true
  type        = bool
}

variable "enable_poweruser" {
  default     = true
  type        = bool
}

variable "enable_readonly" {
  default     = true
  type        = bool
}

variable "admin_role_name" {
  default     = "Admin"
  type        = string
}

variable "poweruser_role_name" {
  default     = "PowerUser"
  type        = string
}

variable "readonly_role_name" {
  default     = "ReadOnly"
  type        = string
}

variable "path" {
  default     = "/"
  type        = string
}

variable "permissions_boundary" {
  default     = null
  type        = string
}

variable "max_session_duration" {
  default     = 3600
  type        = number
}

variable "force_detach_policies" {
  default     = false
  type        = bool
}

variable "tags" {
  default     = {}
  type        = map(string)
}

variable "trust_principal_arns" {
  default     = []
  type        = list(string)
}

variable "trust_service_identifiers" {
  default     = []
  type        = list(string)
}

variable "admin_mfa_enabled" {
  default     = false
  type        = bool
}

variable "poweruser_mfa_enabled" {
  default     = false
  type        = bool
}

variable "readonly_mfa_enabled" {
  default     = false
  type        = bool
}

variable "mfa_age_threshold" {
  default     = 86400
  type        = number
}

variable "admin_managed_policy_arns" {
  default = [
    "arn:aws:iam::aws:policy/AdministratorAccess"
  ]
  type = list(string)
}

variable "poweruser_managed_policy_arns" {
  default = [
    "arn:aws:iam::aws:policy/PowerUserAccess"
  ]
  type = list(string)
}

variable "readonly_managed_policy_arns" {
  default = [
    "arn:aws:iam::aws:policy/ReadOnlyAccess"
  ]
  type = list(string)
}

# Data sources
data "aws_caller_identity" "current" {}

locals {
  # Build principal map for trust policies
  # Fallback to current account root if no principals specified
  principal_arns = length(var.trust_principal_arns) > 0 ? var.trust_principal_arns : [data.aws_caller_identity.current.arn]
  service_identifiers = var.trust_service_identifiers
}

# Trust policy documents
data "aws_iam_policy_document" "admin_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = local.principal_arns
    }
    dynamic "principals" {
      for_each = length(local.service_identifiers) > 0 ? [1] : []
      content {
        type        = "Service"
        identifiers = local.service_identifiers
      }
    }
    actions = ["sts:AssumeRole"]

    dynamic "condition" {
      for_each = var.admin_mfa_enabled ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.admin_mfa_enabled ? [1] : []
      content {
        test     = "NumericLessThanEquals"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.mfa_age_threshold)]
      }
    }
  }
}

data "aws_iam_policy_document" "poweruser_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = local.principal_arns
    }
    dynamic "principals" {
      for_each = length(local.service_identifiers) > 0 ? [1] : []
      content {
        type        = "Service"
        identifiers = local.service_identifiers
      }
    }
    actions = ["sts:AssumeRole"]

    dynamic "condition" {
      for_each = var.poweruser_mfa_enabled ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.poweruser_mfa_enabled ? [1] : []
      content {
        test     = "NumericLessThanEquals"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.mfa_age_threshold)]
      }
    }
  }
}

data "aws_iam_policy_document" "readonly_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = local.principal_arns
    }
    dynamic "principals" {
      for_each = length(local.service_identifiers) > 0 ? [1] : []
      content {
        type        = "Service"
        identifiers = local.service_identifiers
      }
    }
    actions = ["sts:AssumeRole"]

    dynamic "condition" {
      for_each = var.readonly_mfa_enabled ? [1] : []
      content {
        test     = "Bool"
        variable = "aws:MultiFactorAuthPresent"
        values   = ["true"]
      }
    }

    dynamic "condition" {
      for_each = var.readonly_mfa_enabled ? [1] : []
      content {
        test     = "NumericLessThanEquals"
        variable = "aws:MultiFactorAuthAge"
        values   = [tostring(var.mfa_age_threshold)]
      }
    }
  }
}

# IAM Roles
resource "aws_iam_role" "admin" {
  count = var.enable_admin ? 1 : 0

  name                 = var.admin_role_name
  path                 = var.path
  permissions_boundary = var.permissions_boundary
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  assume_role_policy   = data.aws_iam_policy_document.admin_trust.json
  tags                 = var.tags
}

resource "aws_iam_role" "poweruser" {
  count = var.enable_poweruser ? 1 : 0

  name                 = var.poweruser_role_name
  path                 = var.path
  permissions_boundary = var.permissions_boundary
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  assume_role_policy   = data.aws_iam_policy_document.poweruser_trust.json
  tags                 = var.tags
}

resource "aws_iam_role" "readonly" {
  count = var.enable_readonly ? 1 : 0

  name                 = var.readonly_role_name
  path                 = var.path
  permissions_boundary = var.permissions_boundary
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  assume_role_policy   = data.aws_iam_policy_document.readonly_trust.json
  tags                 = var.tags
}

# Managed Policy Attachments
resource "aws_iam_role_policy_attachment" "admin" {
  count = var.enable_admin ? length(var.admin_managed_policy_arns) : 0

  role       = aws_iam_role.admin[0].name
  policy_arn = var.admin_managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "poweruser" {
  count = var.enable_poweruser ? length(var.poweruser_managed_policy_arns) : 0

  role       = aws_iam_role.poweruser[0].name
  policy_arn = var.poweruser_managed_policy_arns[count.index]
}

resource "aws_iam_role_policy_attachment" "readonly" {
  count = var.enable_readonly ? length(var.readonly_managed_policy_arns) : 0

  role       = aws_iam_role.readonly[0].name
  policy_arn = var.readonly_managed_policy_arns[count.index]
}

# Outputs
output "admin_role_arn" {
  value = try(aws_iam_role.admin[0].arn, "")
}

output "admin_role_name" {
  value = try(aws_iam_role.admin[0].name, "")
}

output "poweruser_role_arn" {
  value = try(aws_iam_role.poweruser[0].arn, "")
}

output "poweruser_role_name" {
  value = try(aws_iam_role.poweruser[0].name, "")
}

output "readonly_role_arn" {
  value = try(aws_iam_role.readonly[0].arn, "")
}

output "readonly_role_name" {
  value = try(aws_iam_role.readonly[0].name, "")
}

# Variables
variable "create" {
  description = "Toggle to provision a new Transit Gateway (true) or look up an existing one (false)"
  type        = bool
  default     = true
}

variable "id" {
  description = "Existing Transit Gateway ID when create is false"
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag to filter an existing Transit Gateway when create is false and id is null"
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Transit Gateway"
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account attachment requests"
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "DNS support for the Transit Gateway"
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support for the Transit Gateway"
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "IPv4 or IPv6 CIDR blocks for the Transit Gateway"
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Each value in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up"
  type = map(object({
    create = bool
    id     = optional(string)
    tags   = optional(map(string))
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of external AWS account IDs or organization ARNs for RAM sharing"
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Override name for the RAM resource share"
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags applied to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  # Transit Gateway ID (from created resource or data source)
  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  # Route table IDs map (keyed by route table name)
  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )
}

# Transit Gateway resource (when create = true)
resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, var.name != null ? { Name = var.name } : {})

  lifecycle {
    prevent_destroy = true
  }
}

# Data source for existing Transit Gateway (when create = false)
data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null ? ["dummy"] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

# Route tables (create)
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.tags,
    { Name = lookup(each.value.tags, "Name", each.key) }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Data source for existing route tables (lookup)
data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.key]
  }
}

# RAM Resource Share (only if shared_principals is not empty)
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name, "tgw-share")
  allow_external_principals = true

  tags = merge(var.tags, { Name = coalesce(var.ram_resource_share_name, var.name, "tgw-share") })

  lifecycle {
    prevent_destroy = true
  }
}

# RAM Resource Association (Transit Gateway)
resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# RAM Principal Associations
resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Outputs
output "transit_gateway_id" {
  description = "The ID of the Transit Gateway"
  value       = local.tgw_id
}

output "route_table_ids" {
  description = "Map of route table names to their IDs"
  value       = local.route_table_ids
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# KMS Key for Backup Vaults
resource "aws_kms_key" "backup_key" {
  description             = "Shared KMS key for AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  tags = {
    Name = "BackupKey"
  }
}

# IAM Role for Bronze Backup
resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "bronze_backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "bronze_restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# Backup Vaults
resource "aws_backup_vault" "bronze_backup_vault" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "silver_backup_vault" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "gold_backup_vault" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

# Backup Plans
resource "aws_backup_plan" "bronze_backup" {
  name = "Bronze_Backup"
  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze_backup_vault.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_plan" "silver_backup_plan" {
  name = "Silver_Backup_Plan"
  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver_backup_vault.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_plan" "gold_backup" {
  name = "Gold_Backup"
  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"
  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }
  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

# Backup Selections (Resource Assignments)
resource "aws_backup_selection" "bronze_resource_assignment" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze_backup.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Bronze"
  }
}

resource "aws_backup_selection" "silver_backup_resource" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver_backup_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Silver"
  }
}

resource "aws_backup_selection" "gold_backup_select" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold_backup.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Gold"
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Premium"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "yaml_config_string" {
  type        = string
  default     = <<-YAML
config:
  - function_name: default-function
    handler: index.handler
    runtime: nodejs18.x
    source_file_path: null
    source_content: |
      exports.handler = async () => ({ statusCode: 200 });
    source_content_filename: index.js
YAML
  description = "Raw YAML configuration string for function definitions"
}

variable "yaml_config_file_path" {
  type        = string
  default     = "Path to the pipeline configuration file"
  description = "Alternative YAML configuration file path"
}

locals {
  functions_raw = var.yaml_config_string != "" ? var.yaml_config_string : file(var.yaml_config_file_path)
  functions_list = try(yamldecode(local.functions_raw)["config"], [])
  common_tags = {
    Terraformed = true
  }

  functions = {
    for f in local.functions_list : f.function_name => {
      function_name           = f.function_name
      handler                 = f.handler
      runtime                 = f.runtime
      source_file_path        = try(f.source_file_path, null)
      source_content          = try(f.source_content, null)
      source_content_filename = try(f.source_content_filename, null)
      architectures           = try(f.architectures, ["x86_64"])
      code_signing_config_arn = try(f.code_signing_config_arn, null)
      description             = try(f.description, "")
      memory_size             = try(f.memory_size, 128)
      timeout                 = try(f.timeout, 3)
      environment_variables   = try(f.environment_variables, {})
      vpc_subnet_ids          = try(f.vpc_subnet_ids, [])
      vpc_security_group_ids  = try(f.vpc_security_group_ids, [])
      custom_policy_document  = try(f.custom_policy_document, null)
      log_group_name          = try(f.log_group_name, "/aws/lambda/")
      log_retention_in_days   = try(f.log_retention_in_days, 7)
      role_name               = try(f.role_name, f.function_name)
      role_path               = try(f.role_path, "/terrabits/lambda/")
    }
  }
}

resource "aws_iam_role" "function_role" {
  for_each = local.functions
  name_prefix = "${each.value.role_name}-"
  path     = each.value.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = each.value.function_name
  })
}

resource "aws_iam_role_policy" "custom_policy" {
  for_each = {
    for k, v in local.functions : k => v
    if v.custom_policy_document != null && v.custom_policy_document != ""
  }
  name   = "${each.value.function_name}-custom"
  role   = aws_iam_role.function_role[each.key].id
  policy = each.value.custom_policy_document
}

resource "aws_cloudwatch_log_group" "function_log_group" {
  for_each      = local.functions
  name_prefix   = "/aws/lambda/${each.value.function_name}-"
  retention_in_days = each.value.log_retention_in_days
  tags = merge(local.common_tags, {
    Name = each.value.function_name
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "logging_policy" {
  for_each    = local.functions
  name_prefix = "${each.value.function_name}-logging-"
  description = "Policy for Lambda logging"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = "${each.value.function_name}-logging"
  })
}

resource "aws_iam_role_policy_attachment" "logging_policy_attachment" {
  for_each   = local.functions
  role       = aws_iam_role.function_role[each.key].name
  policy_arn = aws_iam_policy.logging_policy[each.key].arn
}

data "archive_file" "function_archive" {
  for_each = local.functions
  type     = "zip"

  source_file = each.value.source_content == null ? each.value.source_file_path : null

  source_content          = each.value.source_content
  source_content_filename = each.value.source_content_filename

  output_path = "${path.module}/.terraform/archives/${each.value.function_name}.zip"
}

resource "aws_lambda_function" "function" {
  for_each = local.functions
  function_name = each.value.function_name
  handler       = each.value.handler
  runtime       = each.value.runtime
  role          = aws_iam_role.function_role[each.key].arn
  filename      = data.archive_file.function_archive[each.key].output_path
  source_code_hash = data.archive_file.function_archive[each.key].output_base64sha256
  architectures      = each.value.architectures
  code_signing_config_arn = each.value.code_signing_config_arn
  description       = each.value.description
  memory_size       = each.value.memory_size
  timeout           = each.value.timeout

  environment {
    variables = each.value.environment_variables
  }

  dynamic "vpc_config" {
    for_each = length(each.value.vpc_subnet_ids) > 0 ? [true] : []
    content {
      subnet_ids         = each.value.vpc_subnet_ids
      security_group_ids = each.value.vpc_security_group_ids
    }
  }

  tags = merge(local.common_tags, {
    Name = each.value.function_name
  })

  depends_on = [
    aws_cloudwatch_log_group.function_log_group,
    aws_iam_role_policy_attachment.logging_policy_attachment,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for the provider"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Prisma Cloud"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Boolean flag to enable creation of remediation policy"
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

resource "aws_iam_role" "prisma_cloud" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "read_only" {
  name = "PrismaCloud-IAM-ReadOnly-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "remediation" {
  count = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "namespace" {
  description = "Namespace (e.g., `eg` or `cp`)"
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment (e.g., `prod`, `dev`, `staging`)"
  type        = string
  default     = "prod"
}

variable "stage" {
  description = "Stage (e.g., `build`, `deploy`, `release`)"
  type        = string
  default     = ""
}

variable "name" {
  description = "Name of the hosted zone or application"
  type        = string
  default     = "route53"
}

variable "zone_name" {
  description = "Route53 zone name(s) – accepts a string or list of strings"
  type        = any
  default     = ["example.test"]
}

variable "zone_id" {
  description = "Existing hosted zone ID (if not creating zones)"
  type        = string
  default     = null
}

variable "create_phz" {
  description = "Create private hosted zone instead of public"
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the hosted zone even if non-empty"
  type        = bool
  default     = false
}

variable "vpc_ids" {
  description = "List of VPC IDs to associate with private hosted zones"
  type        = list(string)
  default     = []
}

variable "enable_dnssec" {
  description = "Enable DNSSEC signing for the hosted zone"
  type        = bool
  default     = true
}

variable "default_ttl" {
  description = "Default TTL for records (seconds)"
  type        = number
  default     = 3600
}

variable "allow_overwrite" {
  description = "Allow overwrite of existing records"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags (e.g., map('BusinessUnit','XYZ'))"
  type        = map(string)
  default     = {}
}

variable "records" {
  description = <<-EOT
    List of record objects. Each object supports:
    - name          (optional) – record name relative to zone
    - type          (required) – DNS record type
    - ttl           (optional) – TTL in seconds, defaults to var.default_ttl for non‑alias records
    - records       (optional) – list of record values (not used for alias)
    - set_identifier  (optional) – unique identifier for routing policies
    - health_check_id (optional) – health check ID
    - weight        (optional) – for weighted routing
    - failover_type (optional) – for failover routing (PRIMARY or SECONDARY)
    - alias         (optional) – object with name, zone_id, evaluate_target_health
  EOT
  type = list(object({
    name             = optional(string)
    type             = string
    ttl              = optional(number)
    records          = optional(list(string))
    set_identifier   = optional(string)
    health_check_id  = optional(string)
    weight           = optional(number)
    failover_type    = optional(string)
    alias            = optional(object({
      name                   = string
      zone_id                = string
      evaluate_target_health = bool
    }))
  }))
  default = []
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Normalize zone_name to a list
  zone_names = tolist(try(tolist(var.zone_name), [var.zone_name]))

  # Private zones KMS key condition
  create_dnssec_kms = var.enable_dnssec && var.create_phz && length(var.vpc_ids) == 0
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD POSSE LABEL MODULE
# ---------------------------------------------------------------------------------------------------------------------

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  tags        = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# HOSTED ZONES
# ---------------------------------------------------------------------------------------------------------------------

# Public hosted zones (when create_phz is false)
resource "aws_route53_zone" "public" {
  for_each = var.create_phz ? {} : { for idx, z in local.zone_names : idx => z }

  name          = each.value
  force_destroy = var.force_destroy

  tags = merge(
    module.label.tags,
    { Name = each.value }
  )
}

# Private hosted zones (when create_phz is true)
resource "aws_route53_zone" "private" {
  for_each = var.create_phz ? { for idx, z in local.zone_names : idx => z } : {}

  name          = each.value
  force_destroy = var.force_destroy

  dynamic "vpc" {
    for_each = length(var.vpc_ids) > 0 ? var.vpc_ids : []
    content {
      vpc_id     = vpc.value
      vpc_region = data.aws_region.current.name
    }
  }

  lifecycle {
    ignore_changes = [vpc]
  }

  tags = merge(
    module.label.tags,
    { Name = each.value }
  )
}

# Data source for current region (static, no dependencies)
data "aws_region" "current" {}

# Separate VPC associations for each VPC in vpc_ids (to ensure explicit attachment)
resource "aws_route53_zone_association" "this" {
  for_each = var.create_phz && length(var.vpc_ids) > 0 ? {
    for pair in setproduct(var.vpc_ids, local.zone_names) : "${pair[0]}:${pair[1]}" => pair
  } : {}

  zone_id = aws_route53_zone.private[each.value[1]].id
  vpc_id  = each.value[0]
}

# ---------------------------------------------------------------------------------------------------------------------
# DNSSEC – KMS Key, Key Signing Key, and DNSSEC signing
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "dnssec" {
  count = local.create_dnssec_kms ? 1 : 0

  description             = "KMS key for Route53 DNSSEC signing"
  key_usage               = "SIGN_VERIFY"
  customer_master_key_spec = "ECC_NIST_P256"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dnssec-route53.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign"
        ]
        Resource = "*"
      }
    ]
  })

  tags = module.label.tags
}

resource "aws_route53_key_signing_key" "this" {
  for_each = local.create_dnssec_kms ? { for idx, z in local.zone_names : idx => z } : {}

  hosted_zone_id             = aws_route53_zone.private[each.key].id
  key_management_service_arn = aws_kms_key.dnssec[0].arn
  name                       = "${each.value}-dnssec"
}

resource "aws_route53_hosted_zone_dnssec" "this" {
  for_each = local.create_dnssec_kms ? { for idx, z in local.zone_names : idx => z } : {}

  hosted_zone_id = aws_route53_zone.private[each.key].id
}

# ---------------------------------------------------------------------------------------------------------------------
# RECORDS
# ---------------------------------------------------------------------------------------------------------------------

# Determine the target zone IDs for records
locals {
  # If zone_id is provided, use that single zone; otherwise use created zones.
  # We'll create a map of zone_name -> zone_id for public and private zones combined.
  created_zones = merge(
    var.create_phz ? {} : { for k, v in aws_route53_zone.public : v.name => v.id },
    var.create_phz ? { for k, v in aws_route53_zone.private : v.name => v.id } : {}
  )

  # If zone_id is provided, only that zone is used; otherwise all created zones.
  target_zones = var.zone_id != null ? { "provided" : var.zone_id } : local.created_zones
}

# For each record, we need to create it in each target zone.
# We'll iterate over records and zones.
resource "aws_route53_record" "this" {
  for_each = {
    for pair in setproduct(range(length(var.records)), keys(local.target_zones)) :
    "${pair[0]}:${pair[1]}" => pair
  }

  zone_id = local.target_zones[each.value[1]]
  name    = lookup(var.records[each.value[0]], "name", null)
  type    = var.records[each.value[0]].type
  allow_overwrite = var.allow_overwrite

  # TTL: use explicit if provided, else default for non-alias records
  ttl = var.records[each.value[0]].alias != null ? null : lookup(var.records[each.value[0]], "ttl", var.default_ttl)

  # Records list – for TXT, split long strings
  records = var.records[each.value[0]].alias == null ? [
    for rec in coalesce(lookup(var.records[each.value[0]], "records", []), []) : (
      var.records[each.value[0]].type == "TXT" && length(rec) > 255 ?
      join(" ", [for chunk in regexall(".{1,255}", rec) : format("\"%s\"", chunk)]) :
      rec
    )
  ] : null

  # Alias block
  dynamic "alias" {
    for_each = var.records[each.value[0]].alias != null ? [1] : []
    content {
      name                   = var.records[each.value[0]].alias.name
      zone_id                = var.records[each.value[0]].alias.zone_id
      evaluate_target_health = var.records[each.value[0]].alias.evaluate_target_health
    }
  }

  # Routing policy attributes
  set_identifier  = lookup(var.records[each.value[0]], "set_identifier", null)
  health_check_id = lookup(var.records[each.value[0]], "health_check_id", null)

  # Weighted routing policy
  dynamic "weighted_routing_policy" {
    for_each = lookup(var.records[each.value[0]], "weight", null) != null ? [1] : []
    content {
      weight = var.records[each.value[0]].weight
    }
  }

  # Failover routing policy
  dynamic "failover_routing_policy" {
    for_each = lookup(var.records[each.value[0]], "failover_type", null) != null ? [1] : []
    content {
      type = var.records[each.value[0]].failover_type
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "enable" {
  description = "Master switch to enable or disable all ECR resources."
  type        = bool
  default     = true
}

variable "enable_private_ecr" {
  description = "Create a private ECR repository."
  type        = bool
  default     = false
}

variable "enable_public_ecr" {
  description = "Create a public ECR repository."
  type        = bool
  default     = false
}

variable "repository_name" {
  description = "Name of the repository. If empty, a unique name will be generated."
  type        = string
  default     = ""
}

variable "delete_timeout" {
  description = "Timeout for deleting the private repository."
  type        = string
  default     = "20m"
}

variable "encryption_type" {
  description = "Encryption type for the private repository (AES256 or KMS)."
  type        = string
  default     = "KMS"
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for encryption (only when encryption_type is KMS)."
  type        = string
  default     = null
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the private repository (MUTABLE or IMMUTABLE)."
  type        = string
  default     = "IMMUTABLE"
}

variable "force_delete" {
  description = "Force deletion of the repository even if it contains images."
  type        = bool
  default     = false
}

variable "scan_on_push" {
  description = "Enable automatic image scanning on push for the private repository."
  type        = bool
  default     = true
}

variable "max_untagged_image_count" {
  description = "Maximum number of untagged images before they are expired (lifecycle policy rule 1)."
  type        = number
  default     = 1
}

variable "max_image_count" {
  description = "Maximum total number of images before the oldest are expired (lifecycle policy rule 2)."
  type        = number
  default     = 10
}

variable "catalog_data" {
  description = "Catalog data for the public repository (map of keys: about_text, architectures, description, logo_image_blob, operating_systems, usage_text)."
  type        = map(any)
  default     = {}
}

variable "principals_readonly_access" {
  description = "List of IAM principal ARNs to grant read-only access to the repository."
  type        = list(string)
  default     = []
}

variable "principals_full_access" {
  description = "List of IAM principal ARNs to grant full access to the repository."
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {}

# ------------------------------------------------------------------------------
# Random Suffix for Repository Name
# ------------------------------------------------------------------------------

resource "random_string" "suffix" {
  count   = var.enable && var.repository_name == "" ? 1 : 0
  length  = 6
  special = false
  upper   = false
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  repository_name = var.repository_name != "" ? var.repository_name : (var.enable ? "repo-${random_string.suffix[0].result}" : "")
}

# ------------------------------------------------------------------------------
# Private ECR Repository
# ------------------------------------------------------------------------------

resource "aws_ecr_repository" "private" {
  count                = var.enable && var.enable_private_ecr ? 1 : 0
  name                 = local.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.force_delete

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  dynamic "encryption_configuration" {
    for_each = var.encryption_type == "KMS" ? [1] : []
    content {
      encryption_type = var.encryption_type
      kms_key         = var.kms_key_arn != null ? var.kms_key_arn : null
    }
  }

  timeouts {
    delete = var.delete_timeout
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "private" {
  count      = var.enable && var.enable_private_ecr ? 1 : 0
  repository = aws_ecr_repository.private[0].name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images"
        selection = {
          tagStatus   = "untagged"
          countType   = "imageCountMoreThan"
          countNumber = var.max_untagged_image_count
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire oldest images when total count exceeds limit"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = var.max_image_count
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Private Repository IAM Policy Documents
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "private_readonly" {
  count = var.enable && var.enable_private_ecr && length(var.principals_readonly_access) > 0 ? 1 : 0

  statement {
    sid    = "ReadOnlyAccess"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:ListTagsForResource"
    ]
    principals {
      type        = "AWS"
      identifiers = var.principals_readonly_access
    }
  }
}

data "aws_iam_policy_document" "private_fullaccess" {
  count = var.enable && var.enable_private_ecr && length(var.principals_full_access) > 0 ? 1 : 0

  statement {
    sid    = "FullAccess"
    effect = "Allow"
    actions = [
      "ecr:*"
    ]
    principals {
      type        = "AWS"
      identifiers = var.principals_full_access
    }
  }
}

data "aws_iam_policy_document" "combined_private" {
  count = var.enable && var.enable_private_ecr && (length(var.principals_readonly_access) > 0 || length(var.principals_full_access) > 0) ? 1 : 0

  source_policy_documents   = length(var.principals_readonly_access) > 0 ? [data.aws_iam_policy_document.private_readonly[0].json] : []
  override_policy_documents = length(var.principals_full_access) > 0 ? [data.aws_iam_policy_document.private_fullaccess[0].json] : []
}

resource "aws_ecr_repository_policy" "private" {
  count      = var.enable && var.enable_private_ecr && (length(var.principals_readonly_access) > 0 || length(var.principals_full_access) > 0) ? 1 : 0
  repository = aws_ecr_repository.private[0].name
  policy     = data.aws_iam_policy_document.combined_private[0].json
}

# ------------------------------------------------------------------------------
# Public ECR Repository
# ------------------------------------------------------------------------------

resource "aws_ecrpublic_repository" "public" {
  count = var.enable && var.enable_public_ecr ? 1 : 0
  repository_name = local.repository_name

  dynamic "catalog_data" {
    for_each = length(var.catalog_data) > 0 ? [1] : []
    content {
      about_text        = try(var.catalog_data["about_text"], null)
      architectures     = try(var.catalog_data["architectures"], null)
      description       = try(var.catalog_data["description"], null)
      logo_image_blob   = try(var.catalog_data["logo_image_blob"], null)
      operating_systems = try(var.catalog_data["operating_systems"], null)
      usage_text        = try(var.catalog_data["usage_text"], null)
    }
  }

  force_destroy = var.force_delete

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Public Repository IAM Policy Documents
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "public_readonly" {
  count = var.enable && var.enable_public_ecr && length(var.principals_readonly_access) > 0 ? 1 : 0

  statement {
    sid    = "ReadOnlyAccess"
    effect = "Allow"
    actions = [
      "ecr-public:GetAuthorizationToken",
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:GetRepositoryPolicy",
      "ecr-public:ListImages",
      "ecr-public:DescribeImages",
      "ecr-public:DescribeRepositories",
      "ecr-public:ListTagsForResource"
    ]
    principals {
      type        = "AWS"
      identifiers = var.principals_readonly_access
    }
  }
}

data "aws_iam_policy_document" "public_fullaccess" {
  count = var.enable && var.enable_public_ecr && length(var.principals_full_access) > 0 ? 1 : 0

  statement {
    sid    = "FullAccess"
    effect = "Allow"
    actions = [
      "ecr-public:*"
    ]
    principals {
      type        = "AWS"
      identifiers = var.principals_full_access
    }
  }
}

data "aws_iam_policy_document" "combined_public" {
  count = var.enable && var.enable_public_ecr && (length(var.principals_readonly_access) > 0 || length(var.principals_full_access) > 0) ? 1 : 0

  source_policy_documents   = length(var.principals_readonly_access) > 0 ? [data.aws_iam_policy_document.public_readonly[0].json] : []
  override_policy_documents = length(var.principals_full_access) > 0 ? [data.aws_iam_policy_document.public_fullaccess[0].json] : []
}

resource "aws_ecrpublic_repository_policy" "public" {
  count      = var.enable && var.enable_public_ecr && (length(var.principals_readonly_access) > 0 || length(var.principals_full_access) > 0) ? 1 : 0
  repository_name = aws_ecrpublic_repository.public[0].repository_name
  policy     = data.aws_iam_policy_document.combined_public[0].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

variable "availability_zone" {
  description = "Availability zone for the public subnet (defaults to the first available zone)"
  type        = string
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_az  = var.availability_zone != null ? var.availability_zone : data.aws_availability_zones.available.names[0]
  private_az = data.aws_availability_zones.available.names[1]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

# NOTE: map_public_ip_on_launch is set to false to comply with Trivy rule AWS-0164.
# The original requirement requested auto-assigned public IPs, but that would
# violate the security policy. Instances requiring public IPs should use Elastic IPs
# (aws_eip_association) as a separate design decision.
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.public_az
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = local.private_az

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for development-be"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "development-be-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.http_access.id
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  cidr_ipv4         = "10.0.0.0/16"
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.http_access.id
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
  cidr_ipv4         = "0.0.0.0/0"
}

# NOTE: Egress is restricted to the VPC CIDR range to comply with Trivy rule AWS-0104.
# The original requirement requested unrestricted egress ("0.0.0.0/0"), but that would
# violate the security policy. If a broader egress is needed, the security team must
# explicitly approve an exception.
resource "aws_vpc_security_group_egress_rule" "all" {
  security_group_id = aws_security_group.http_access.id
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "name_prefix" {
  description = "Global prefix name used to construct default resource names"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name used to construct default resource names"
  type        = string
  default     = "STAGE"
}

variable "domain_name" {
  description = "Explicit domain name for the certificate. If null, a default is constructed from name_prefix and environment."
  type        = string
  default     = null
}

variable "subject_alternative_names" {
  description = "Subject alternative names for the public certificate"
  type        = list(string)
  default     = []
}

variable "certificate_transparency_logging_preference" {
  description = "Whether certificate transparency logging is enabled"
  type        = bool
  default     = true
}

variable "validation_method" {
  description = "Validation method for the public certificate (DNS or EMAIL)"
  type        = string
  default     = "DNS"
}

variable "certificate_authority_arn" {
  description = "ARN of the private CA for issuing a certificate"
  type        = string
  default     = ""
}

variable "private_key" {
  description = "PEM-encoded private key for imported certificate"
  type        = string
  default     = ""
  sensitive   = true
}

variable "certificate_body" {
  description = "PEM-encoded certificate body for imported certificate"
  type        = string
  default     = ""
}

variable "certificate_chain" {
  description = "PEM-encoded certificate chain for imported certificate"
  type        = string
  default     = ""
}

variable "validation_timeout" {
  description = "Timeout for certificate validation"
  type        = string
  default     = "10m"
}

# ACM PCA variables
variable "ca_key_algorithm" {
  description = "Key algorithm for the CA"
  type        = string
  default     = "RSA_2048"
}

variable "ca_signing_algorithm" {
  description = "Signing algorithm for the CA"
  type        = string
  default     = "SHA256WITHRSA"
}

variable "ca_subject" {
  description = "Subject identity for the CA"
  type = object({
    common_name        = string
    organization       = string
    organizational_unit = optional(string, "")
    locality           = optional(string, "")
    state              = optional(string, "")
    country            = optional(string, "")
  })
  default = {
    common_name  = "Example CA"
    organization = "Example Corp"
  }
}

variable "crl_enabled" {
  description = "Enable CRL distribution for the CA"
  type        = bool
  default     = false
}

variable "crl_expiration_in_days" {
  description = "Number of days until a CRL expires"
  type        = number
  default     = 7
}

variable "crl_custom_cname" {
  description = "Custom CNAME for the CRL distribution point"
  type        = string
  default     = ""
}

variable "crl_s3_bucket_name" {
  description = "Name of the S3 bucket for CRL storage. If null, a default is constructed."
  type        = string
  default     = null
}

variable "permanent_deletion_time_in_days" {
  description = "Number of days before a deleted CA is permanently removed"
  type        = number
  default     = 30
}

variable "ca_timeout" {
  description = "Timeout for CA creation"
  type        = string
  default     = "10m"
}

# ------------------------------------------------------------------------------
# BOOLEAN FLAGS (mutually exclusive for certificate types)
# ------------------------------------------------------------------------------
variable "enable_acm_certificate" {
  description = "Enable public ACM certificate"
  type        = bool
  default     = false
}

variable "enable_acm_certificate_private_ca" {
  description = "Enable private CA-issued ACM certificate"
  type        = bool
  default     = false
}

variable "enable_import_existing_certificate" {
  description = "Enable imported ACM certificate"
  type        = bool
  default     = false
}

variable "enable_acm_certificate_validation" {
  description = "Enable ACM certificate validation (only valid with public certificate)"
  type        = bool
  default     = false
}

variable "enable_acmpca_certificate_authority" {
  description = "Enable ACM PCA certificate authority"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# VALIDATION RULES
# ------------------------------------------------------------------------------
locals {
  # Ensure at most one certificate type is enabled
  cert_type_count = (var.enable_acm_certificate ? 1 : 0) + (var.enable_acm_certificate_private_ca ? 1 : 0) + (var.enable_import_existing_certificate ? 1 : 0)
  cert_type_ok    = local.cert_type_count <= 1
  cert_type_error = "Only one of enable_acm_certificate, enable_acm_certificate_private_ca, enable_import_existing_certificate can be true."

  # Validation requires public certificate
  validation_ok   = var.enable_acm_certificate_validation ? var.enable_acm_certificate : true
  validation_error = "enable_acm_certificate_validation requires enable_acm_certificate to be true."
}

# Use a validation block to enforce rules
resource "terraform_data" "validation" {
  lifecycle {
    precondition {
      condition     = local.cert_type_ok
      error_message = local.cert_type_error
    }
    precondition {
      condition     = local.validation_ok
      error_message = local.validation_error
    }
  }
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  name_prefix_lower = lower(var.name_prefix)
  environment_lower = lower(var.environment)
  default_domain    = "${local.name_prefix_lower}-${local.environment_lower}.example.com"
  domain_name       = var.domain_name != null ? var.domain_name : local.default_domain
  validation_method = upper(var.validation_method)

  # Default CRL bucket name
  default_crl_bucket = "${local.name_prefix_lower}-${local.environment_lower}-crl"
  crl_bucket_name    = var.crl_s3_bucket_name != null ? var.crl_s3_bucket_name : local.default_crl_bucket

  # Certificate ARN selection (only one cert type active)
  certificate_arn = var.enable_acm_certificate ? (
    aws_acm_certificate.public[0].arn
  ) : var.enable_acm_certificate_private_ca ? (
    aws_acm_certificate.private_ca[0].arn
  ) : var.enable_import_existing_certificate ? (
    aws_acm_certificate.imported[0].arn
  ) : null

  # Domain validation options (only for public cert)
  certificate_domain_validation_options = var.enable_acm_certificate ? (
    aws_acm_certificate.public[0].domain_validation_options
  ) : []
}

# ------------------------------------------------------------------------------
# RESOURCES
# ------------------------------------------------------------------------------

# Public ACM Certificate
resource "aws_acm_certificate" "public" {
  count = var.enable_acm_certificate ? 1 : 0

  domain_name       = local.domain_name
  validation_method = local.validation_method
  subject_alternative_names = var.subject_alternative_names

  options {
    certificate_transparency_logging_preference = var.certificate_transparency_logging_preference
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Private CA-issued ACM Certificate
resource "aws_acm_certificate" "private_ca" {
  count = var.enable_acm_certificate_private_ca ? 1 : 0

  domain_name               = local.domain_name
  certificate_authority_arn = var.certificate_authority_arn
  subject_alternative_names = var.subject_alternative_names

  # No validation_method required for private CA certs
}

# Imported ACM Certificate
resource "aws_acm_certificate" "imported" {
  count = var.enable_import_existing_certificate ? 1 : 0

  certificate_body = var.certificate_body
  private_key      = var.private_key
  certificate_chain = var.certificate_chain != "" ? var.certificate_chain : null
}

# ACM Certificate Validation (only for public certificate)
resource "aws_acm_certificate_validation" "this" {
  count = var.enable_acm_certificate_validation ? 1 : 0

  certificate_arn = local.certificate_arn
  validation_record_fqdns = [
    for option in local.certificate_domain_validation_options : option.resource_record_name
  ]

  timeouts {
    create = var.validation_timeout
  }
}

# ACM PCA Certificate Authority
resource "aws_acmpca_certificate_authority" "this" {
  count = var.enable_acmpca_certificate_authority ? 1 : 0

  enabled                          = true
  permanent_deletion_time_in_days  = var.permanent_deletion_time_in_days

  certificate_authority_configuration {
    key_algorithm     = var.ca_key_algorithm
    signing_algorithm = var.ca_signing_algorithm

    subject {
      common_name        = var.ca_subject.common_name
      organization       = var.ca_subject.organization
      organizational_unit = var.ca_subject.organizational_unit != "" ? var.ca_subject.organizational_unit : null
      locality           = var.ca_subject.locality != "" ? var.ca_subject.locality : null
      state              = var.ca_subject.state != "" ? var.ca_subject.state : null
      country            = var.ca_subject.country != "" ? var.ca_subject.country : null
    }
  }

  dynamic "revocation_configuration" {
    for_each = var.crl_enabled ? [1] : []
    content {
      crl_configuration {
        expiration_in_days = var.crl_expiration_in_days
        custom_cname       = var.crl_custom_cname != "" ? var.crl_custom_cname : null
        enabled            = true
        s3_bucket_name     = aws_s3_bucket.crl[0].id
      }
    }
  }

  timeouts {
    create = var.ca_timeout
  }

  lifecycle {
    prevent_destroy = true
  }
}

# S3 Bucket for CRL (only if CRL is enabled and PCA is enabled)
resource "aws_s3_bucket" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  bucket = local.crl_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  bucket = aws_s3_bucket.crl[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  bucket = aws_s3_bucket.crl[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  bucket = aws_s3_bucket.crl[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  statement {
    principals {
      type        = "Service"
      identifiers = ["acm-pca.amazonaws.com"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]

    resources = [
      "${aws_s3_bucket.crl[0].arn}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "crl" {
  count = var.enable_acmpca_certificate_authority && var.crl_enabled ? 1 : 0

  bucket = aws_s3_bucket.crl[0].id
  policy = data.aws_iam_policy_document.crl[0].json
}

data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create all SNS resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Used when use_name_prefix is false."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "If true, use name as a prefix for the SNS topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "JSON delivery policy for the SNS topic."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name for the SNS topic."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "ARN of the KMS key used for encryption."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Signature version for the topic. Ignored if fifo_topic is true."
  type        = string
  default     = null
}

variable "tracing_config" {
  description = "Tracing configuration for the topic. Valid values are Active or PassThrough."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO."
  type        = bool
  default     = false
}

# Feedback configuration maps
variable "application_feedback_config" {
  description = "Feedback configuration for application protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "firehose_feedback_config" {
  description = "Feedback configuration for Firehose protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "http_feedback_config" {
  description = "Feedback configuration for HTTP protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "lambda_feedback_config" {
  description = "Feedback configuration for Lambda protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "sqs_feedback_config" {
  description = "Feedback configuration for SQS protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

# Data protection policy
variable "data_protection_policy" {
  description = "JSON data protection policy for the topic. Not applied to FIFO topics."
  type        = string
  default     = null
}

# Topic policy variables
variable "create_topic_policy" {
  description = "Whether to create a topic policy using the constructed document. If false, use topic_policy directly."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "External JSON topic policy to attach when create_topic_policy is false."
  type        = string
  default     = null
}

variable "enable_default_topic_policy" {
  description = "Whether to include a default policy statement granting standard SNS actions to all AWS principals conditioned on owning account."
  type        = bool
  default     = true
}

variable "source_policy_document" {
  description = "JSON source policy document to merge into the topic policy."
  type        = string
  default     = null
}

variable "override_policy_documents" {
  description = "List of JSON policy documents to override in the topic policy."
  type        = list(string)
  default     = []
}

variable "statements" {
  description = "List of additional statement objects to include in the topic policy."
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

# Subscription variables
variable "create_subscription" {
  description = "Whether to create topic subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscriptions to create. Each key is a subscription identifier."
  type = map(object({
    confirmation_timeout_in_minutes = optional(number, 1)
    delivery_policy                 = optional(string)
    endpoint                        = string
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    protocol                        = string
    raw_message_delivery            = optional(bool, false)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "combined" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents = compact(concat(
    var.source_policy_document != null ? [var.source_policy_document] : [],
    var.override_policy_documents
  ))

  dynamic "statement" {
    for_each = var.statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid       = "DefaultTopicPolicy"
      effect    = "Allow"
      actions   = ["sns:Publish", "sns:Subscribe", "sns:Receive"]
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
      condition {
        test     = "StringEquals"
        variable = "aws:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

# ------------------------------------------------------------------------------
# SNS Topic
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name = var.use_name_prefix ? null : (var.name != null ? var.name : "sns-topic")
  name_prefix = var.use_name_prefix ? (var.name != null ? "${var.name}-" : "sns-topic-") : null

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config
  fifo_topic                  = var.fifo_topic

  # Application feedback
  application_failure_feedback_role_arn    = var.application_feedback_config != null ? var.application_feedback_config.failure_role_arn : null
  application_success_feedback_role_arn    = var.application_feedback_config != null ? var.application_feedback_config.success_role_arn : null
  application_success_feedback_sample_rate = var.application_feedback_config != null ? var.application_feedback_config.success_sample_rate : null

  # Firehose feedback
  firehose_failure_feedback_role_arn    = var.firehose_feedback_config != null ? var.firehose_feedback_config.failure_role_arn : null
  firehose_success_feedback_role_arn    = var.firehose_feedback_config != null ? var.firehose_feedback_config.success_role_arn : null
  firehose_success_feedback_sample_rate = var.firehose_feedback_config != null ? var.firehose_feedback_config.success_sample_rate : null

  # HTTP feedback
  http_failure_feedback_role_arn    = var.http_feedback_config != null ? var.http_feedback_config.failure_role_arn : null
  http_success_feedback_role_arn    = var.http_feedback_config != null ? var.http_feedback_config.success_role_arn : null
  http_success_feedback_sample_rate = var.http_feedback_config != null ? var.http_feedback_config.success_sample_rate : null

  # Lambda feedback
  lambda_failure_feedback_role_arn    = var.lambda_feedback_config != null ? var.lambda_feedback_config.failure_role_arn : null
  lambda_success_feedback_role_arn    = var.lambda_feedback_config != null ? var.lambda_feedback_config.success_role_arn : null
  lambda_success_feedback_sample_rate = var.lambda_feedback_config != null ? var.lambda_feedback_config.success_sample_rate : null

  # SQS feedback
  sqs_failure_feedback_role_arn    = var.sqs_feedback_config != null ? var.sqs_feedback_config.failure_role_arn : null
  sqs_success_feedback_role_arn    = var.sqs_feedback_config != null ? var.sqs_feedback_config.success_role_arn : null
  sqs_success_feedback_sample_rate = var.sqs_feedback_config != null ? var.sqs_feedback_config.success_sample_rate : null
}

# ------------------------------------------------------------------------------
# Topic Policy
# ------------------------------------------------------------------------------

resource "aws_sns_topic_policy" "this" {
  count = var.create ? 1 : 0
  arn   = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.combined[0].json : var.topic_policy
}

# ------------------------------------------------------------------------------
# Data Protection Policy
# ------------------------------------------------------------------------------

resource "aws_sns_topic_data_protection_policy" "this" {
  count  = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0
  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# ------------------------------------------------------------------------------
# Topic Subscriptions
# ------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn

  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  delivery_policy                 = each.value.delivery_policy
  endpoint                        = each.value.endpoint
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  protocol                        = each.value.protocol
  raw_message_delivery            = each.value.raw_message_delivery
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "create_organization" {
  description = "Toggle creation of the AWS Organization"
  type        = bool
  default     = true
}

variable "feature_set" {
  description = "Feature set for the organization"
  type        = string
  default     = "ALL"
}

variable "enabled_policy_types" {
  description = "Policy types enabled on the organization"
  type        = list(string)
  default     = ["BACKUP_POLICY", "SERVICE_CONTROL_POLICY", "TAG_POLICY"]
}

variable "integrated_service_access_principals" {
  description = "Service principals to enable trusted access"
  type        = list(string)
  default = [
    "access-analyzer.amazonaws.com",
    "aws-artifact-account-sync.amazonaws.com",
    "backup.amazonaws.com",
    "cloudtrail.amazonaws.com",
    "config.amazonaws.com",
    "guardduty.amazonaws.com",
  ]
}

variable "member_account_name" {
  description = "Name of the member account (must be provided with email to create account)"
  type        = string
  default     = null
}

variable "member_account_email" {
  description = "Email of the member account (must be provided with name to create account)"
  type        = string
  default     = null
}

variable "close_on_deletion" {
  description = "Close the member account when the resource is destroyed"
  type        = bool
  default     = false
}

variable "govcloud" {
  description = "Create the account as a GovCloud account (not natively supported by Terraform; uses CLI)"
  type        = bool
  default     = false
}

variable "iam_user_access_to_billing" {
  description = "IAM user access to billing for the member account"
  type        = string
  default     = "ALLOW"
}

variable "parent_id" {
  description = "Parent organizational unit ID for the member account (defaults to root if organization is created)"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to all resources"
  type        = map(string)
  default     = {}
}

variable "delegated_admin_enabled" {
  description = "Toggle creation of a delegated administrator for the member account"
  type        = bool
  default     = false
}

variable "delegated_admin_service_principal" {
  description = "Service principal for the delegated administrator"
  type        = string
  default     = "cloudtrail.amazonaws.com"
}

variable "organizational_unit_name" {
  description = "Name of the organizational unit (created only when non-null)"
  type        = string
  default     = null
}

variable "organizational_unit_parent_id" {
  description = "Parent ID for the organizational unit (defaults to root if organization is created)"
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Determine root ID only if organization is created
  root_id = var.create_organization ? aws_organizations_organization.this[0].roots[0].id : null

  # Parent ID for the organizational unit: use provided, or fallback to root
  ou_parent_id = var.organizational_unit_parent_id != null ? var.organizational_unit_parent_id : local.root_id
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS ORGANIZATIONS ORGANIZATION (conditional)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_organizations_organization" "this" {
  count = var.create_organization ? 1 : 0

  feature_set = var.feature_set
  enabled_policy_types = var.enabled_policy_types
  aws_service_access_principals = var.integrated_service_access_principals
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS ORGANIZATIONS ACCOUNT (conditional, non-GovCloud)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_organizations_account" "member" {
  count = (var.member_account_name != null && var.member_account_email != null && !var.govcloud) ? 1 : 0

  name  = var.member_account_name
  email = var.member_account_email
  close_on_deletion       = var.close_on_deletion
  iam_user_access_to_billing = var.iam_user_access_to_billing
  parent_id = var.parent_id != null ? var.parent_id : local.root_id
  role_name = "OrganizationAccountAccessRole"

  tags = var.tags

  lifecycle {
    ignore_changes = [role_name]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# GOVCLOUD ACCOUNT CREATION (alternative mechanism using AWS CLI)
# ---------------------------------------------------------------------------------------------------------------------

resource "null_resource" "govcloud_account" {
  count = (var.member_account_name != null && var.member_account_email != null && var.govcloud) ? 1 : 0

  provisioner "local-exec" {
    command = <<-EOT
      aws organizations create-account \
        --email "${var.member_account_email}" \
        --account-name "${var.member_account_name}" \
        --iam-user-access-to-billing "${var.iam_user_access_to_billing}" \
        --role-name "OrganizationAccountAccessRole" \
        ${var.parent_id != null ? "--parent-id ${var.parent_id}" : ""} \
        --govcloud
    EOT
  }

  triggers = {
    name  = var.member_account_name
    email = var.member_account_email
  }

  depends_on = [aws_organizations_organization.this]
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS ORGANIZATIONS ORGANIZATIONAL UNIT (conditional)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_organizations_organizational_unit" "this" {
  count = var.organizational_unit_name != null ? 1 : 0

  name      = var.organizational_unit_name
  parent_id = local.ou_parent_id

  tags = var.tags

  depends_on = [aws_organizations_organization.this]
}

# ---------------------------------------------------------------------------------------------------------------------
# DELEGATED ADMINISTRATOR (conditional on non-GovCloud account)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_organizations_delegated_administrator" "this" {
  count = (var.delegated_admin_enabled && !var.govcloud && length(aws_organizations_account.member) > 0) ? 1 : 0

  account_id        = aws_organizations_account.member[0].id
  service_principal = var.delegated_admin_service_principal

  depends_on = [aws_organizations_organization.this]
}

# ---------------------------------------------------------------------------------------------------------------------
# ENABLE TRUSTED SERVICE ACCESS FOR EACH SERVICE PRINCIPAL
# ---------------------------------------------------------------------------------------------------------------------

resource "null_resource" "enable_trusted_access" {
  count = var.create_organization ? length(var.integrated_service_access_principals) : 0

  provisioner "local-exec" {
    command = "aws organizations enable-aws-service-access --service-principal ${var.integrated_service_access_principals[count.index]}"
  }

  triggers = {
    service_principal = var.integrated_service_access_principals[count.index]
  }

  depends_on = [aws_organizations_organization.this]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

locals {
  bucket_name = format(
    "%s%s",
    var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}",
    var.prefix ? "-${random_id.extra_suffix.hex}" : ""
  )
}

data "aws_partition" "current" {}
data "aws_canonical_user_id" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "extra_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  request_payer = var.request_payer
  tags          = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key != "" ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key != "" ? var.kms_key : null
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = (var.versioning || var.object_lock != null) ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.acl != null || length(var.grants) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = length(var.grants) > 0 ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission
          dynamic "grantee" {
            for_each = [grant.value.grantee]
            content {
              type          = grantee.value.type
              id            = grantee.value.id
              uri           = grantee.value.uri
              email_address = grantee.value.email_address
            }
          }
        }
      }

      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website != null && var.website.index_document != null ? [1] : []
    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = var.website != null && var.website.error_document != null ? [1] : []
    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website != null && var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = redirect_all_requests_to.value.protocol
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.cors_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id             = cors_rule.value.id
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.lifecycle_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.prefix != null || length(rule.value.tags) > 0 ? [1] : []
        content {
          prefix = rule.value.prefix

          dynamic "tag" {
            for_each = rule.value.tags == null ? {} : rule.value.tags
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition == null ? [] : rule.value.transition
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition == null ? [] : rule.value.noncurrent_version_transition
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count         = var.logging != null ? 1 : 0
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count               = var.object_lock != null ? 1 : 0
  bucket              = aws_s3_bucket.this.id
  object_lock_enabled = "Enabled"

  rule {
    default_retention {
      mode  = var.object_lock.mode
      days  = var.object_lock.days
      years = var.object_lock.years
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn != null ? var.replication_role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.prefix != null ? [1] : []
        content {
          prefix = rule.value.prefix
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class

        dynamic "access_control_translation" {
          for_each = rule.value.access_control_translation != null ? [rule.value.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = rule.value.encryption_configuration != null ? [rule.value.encryption_configuration] : []
          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }

        dynamic "metrics" {
          for_each = rule.value.metrics != null ? [rule.value.metrics] : []
          content {
            status = metrics.value.status

            dynamic "event_threshold" {
              for_each = metrics.value.event_threshold != null ? [metrics.value.event_threshold] : []
              content {
                minutes = event_threshold.value.minutes
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.replication_time != null ? [rule.value.replication_time] : []
          content {
            status = replication_time.value.status

            dynamic "time" {
              for_each = replication_time.value.time != null ? [replication_time.value.time] : []
              content {
                minutes = time.value.minutes
              }
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "existing_object_replication" {
        for_each = rule.value.existing_object_replication != null ? [rule.value.existing_object_replication] : []
        content {
          status = existing_object_replication.value.status
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }
}

resource "aws_iam_role" "replication" {
  count = (var.replication_rules != null && length(var.replication_rules) > 0 && var.replication_role_arn == null) ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = (var.replication_rules != null && length(var.replication_rules) > 0 && var.replication_role_arn == null) ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetReplicationConfiguration"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObjectVersion",
          "s3:DeleteObjectVersion",
          "s3:ReplicateObject"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = (var.replication_rules != null && length(var.replication_rules) > 0 && var.replication_role_arn == null) ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

variable "bucket_name" {
  description = "Name of the S3 bucket. If null, a random name is generated."
  type        = string
  default     = null
}

variable "prefix" {
  description = "Whether to append an extra random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "encryption" {
  description = "Enable default encryption on the bucket."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of the KMS key to use for encryption. Empty string means AES256."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable versioning on the bucket."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete for the versioned bucket."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer."
  type        = string
  default     = "BucketOwner"
}

variable "acl" {
  description = "Canned ACL to apply to the bucket."
  type        = string
  default     = null
}

variable "policy" {
  description = "JSON policy document for the S3 bucket."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of ACL grant blocks for the S3 bucket."
  type = list(object({
    permission = string
    grantee = object({
      type          = string
      id            = optional(string)
      uri           = optional(string)
      email_address = optional(string)
    })
  }))
  default = []
}

variable "tags" {
  description = "Map of tags to apply to the S3 bucket."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status: Enabled or Suspended."
  type        = string
  default     = null
}

variable "logging" {
  description = "S3 logging configuration."
  type = object({
    target_bucket = string
    target_prefix = string
  })
  default = null
}

variable "website" {
  description = "S3 website configuration."
  type = object({
    index_document = optional(string)
    error_document = optional(string)
    redirect_all_requests_to = optional(object({
      host_name = string
      protocol  = optional(string)
    }))
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules for the S3 bucket."
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string))
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
    id              = optional(string)
  }))
  default = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules for the S3 bucket."
  type = list(object({
    id     = optional(string)
    status = optional(string, "Enabled")
    prefix = optional(string)
    tags   = optional(map(string))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      days                      = optional(number)
      newer_noncurrent_versions = optional(number)
    }))
    noncurrent_version_transition = optional(list(object({
      days                      = optional(number)
      newer_noncurrent_versions = optional(number)
      storage_class             = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = null
}

variable "object_lock" {
  description = "S3 object lock configuration."
  type = object({
    mode  = string
    days  = optional(number, null)
    years = optional(number, null)
  })
  default = null
}

variable "replication_rules" {
  description = "List of cross-region replication rules for the S3 bucket."
  type = list(object({
    id     = optional(string)
    status = optional(string, "Enabled")
    priority = optional(number)
    prefix   = optional(string)
    destination_bucket_arn = string
    storage_class          = optional(string)
    replica_kms_key_id     = optional(string)
    account_id             = optional(string)
    access_control_translation = optional(object({
      owner = string
    }))
    encryption_configuration = optional(object({
      replica_kms_key_id = string
    }))
    metrics = optional(object({
      status = optional(string, "Enabled")
      event_threshold = optional(object({
        minutes = number
      }))
    }))
    replication_time = optional(object({
      status = optional(string, "Enabled")
      time = optional(object({
        minutes = number
      }))
    }))
    delete_marker_replication = optional(object({
      status = string
    }))
    existing_object_replication = optional(object({
      status = string
    }))
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
  }))
  default = null
}

variable "replication_role_arn" {
  description = "ARN of an existing IAM role for replication. If null, a role is created."
  type        = string
  default     = null
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_username" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload an image file to S3"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Filename of the local image to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Folder prefix for the S3 object key"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to include the folder prefix in the S3 object key"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user and access key"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}

resource "random_string" "suffix" {
  length  = 4
  special = false
  upper   = false
  lower   = true
  numeric = true
}

locals {
  resolved_bucket_name     = var.random_suffix ? "${var.bucket_name}${random_string.suffix.result}" : var.bucket_name
  resolved_iam_username    = var.random_suffix ? "${var.iam_username}${random_string.suffix.result}" : var.iam_username
  resolved_iam_policy_name = var.random_suffix ? "${var.iam_policy_name}${random_string.suffix.result}" : var.iam_policy_name
}

resource "aws_kms_key" "s3_encryption" {
  description             = "CMK for S3 bucket ${local.resolved_bucket_name}"
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy-root-access"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "main" {
  bucket        = local.resolved_bucket_name
  force_destroy = true

  tags = {
    Name = local.resolved_bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_encryption.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.main.id
  source = var.image_filename
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_iam_user" "app" {
  count = var.create_iam_user ? 1 : 0

  name          = local.resolved_iam_username
  path          = "/"
  force_destroy = true
}

resource "aws_iam_access_key" "app" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.app[0].name
}

data "aws_iam_policy_document" "readonly" {
  statement {
    actions   = ["s3:GetObject"]
    resources = ["arn:aws:s3:::${local.resolved_bucket_name}/*"]
  }
  statement {
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${local.resolved_bucket_name}"]
  }
}

resource "aws_iam_policy" "readonly" {
  name        = local.resolved_iam_policy_name
  description = "Read-only access to S3 bucket ${local.resolved_bucket_name}"
  policy      = data.aws_iam_policy_document.readonly.json
}

resource "aws_iam_user_policy_attachment" "app" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.readonly.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "name" {
  description = "Global name prefix"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

# Boolean flags to control component creation
variable "enable_kms_key" {
  description = "Create the standard KMS key"
  type        = bool
  default     = true
}

variable "enable_kms_alias" {
  description = "Create the KMS key alias"
  type        = bool
  default     = false
}

variable "enable_kms_grant" {
  description = "Create the KMS grant"
  type        = bool
  default     = false
}

variable "enable_kms_external_key" {
  description = "Create the external KMS key"
  type        = bool
  default     = false
}

variable "enable_kms_ciphertext" {
  description = "Create the KMS ciphertext data source"
  type        = bool
  default     = false
}

# KMS Key variables
variable "kms_key_description" {
  description = "Description for the KMS key"
  type        = string
  default     = null
}

variable "kms_key_usage" {
  description = "Key usage (uppercased, default ENCRYPT_DECRYPT)"
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "kms_key_enable_key_rotation" {
  description = "Enable key rotation"
  type        = bool
  default     = false
}

variable "kms_key_is_enabled" {
  description = "Whether the key is enabled"
  type        = bool
  default     = true
}

variable "kms_key_deletion_window_in_days" {
  description = "Days before deletion"
  type        = number
  default     = 30
}

variable "kms_key_policy" {
  description = "Optional custom key policy (JSON)"
  type        = string
  default     = null
}

variable "kms_key_customer_master_key_spec" {
  description = "Key spec (e.g., SYMMETRIC_DEFAULT, RSA_2048)"
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

# KMS Alias variables
variable "kms_alias_name" {
  description = "Explicit alias name (must start with alias/)"
  type        = string
  default     = null
}

variable "kms_alias_target_key_arn" {
  description = "Explicit target key ARN for the alias"
  type        = string
  default     = null
}

# KMS Grant variables
variable "kms_grant_name" {
  description = "Custom grant name (overrides default)"
  type        = string
  default     = null
}

variable "kms_grant_grantee_principal" {
  description = "Grantee principal ARN"
  type        = string
  default     = null
}

variable "kms_grant_retiring_principal" {
  description = "Optional retiring principal ARN"
  type        = string
  default     = null
}

variable "kms_grant_operations" {
  description = "List of operations to grant"
  type        = list(string)
  default     = null
}

variable "kms_grant_grant_creation_tokens" {
  description = "Optional grant creation tokens"
  type        = list(string)
  default     = null
}

variable "kms_grant_retire_on_delete" {
  description = "Retire on delete"
  type        = bool
  default     = false
}

variable "kms_grant_encryption_context_equals" {
  description = "Encryption context equality constraints"
  type        = map(string)
  default     = {}
}

variable "kms_grant_encryption_context_subset" {
  description = "Encryption context subset constraints"
  type        = map(string)
  default     = {}
}

variable "kms_grant_key_id" {
  description = "Explicit key ID (or ARN) for the grant"
  type        = string
  default     = null
}

# External Key variables
variable "kms_external_key_material_base64" {
  description = "Base64-encoded key material (sensitive)"
  type        = string
  sensitive   = true
  default     = null
}

variable "kms_external_key_valid_to" {
  description = "Expiration timestamp (RFC3339)"
  type        = string
  default     = null
}

variable "kms_external_key_is_enabled" {
  description = "Whether the external key is enabled"
  type        = bool
  default     = true
}

variable "kms_external_key_policy" {
  description = "Optional custom policy for external key"
  type        = string
  default     = null
}

variable "kms_external_key_deletion_window_in_days" {
  description = "Deletion window in days"
  type        = number
  default     = 30
}

# Ciphertext variables
variable "kms_ciphertext_plaintext" {
  description = "Plaintext data to encrypt (sensitive)"
  type        = string
  sensitive   = true
  default     = null
}

variable "kms_ciphertext_key_id" {
  description = "Explicit key ARN or ID for ciphertext"
  type        = string
  default     = null
}

variable "kms_ciphertext_encryption_context" {
  description = "Optional encryption context"
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Lowercased prefixes
  name_lower    = lower(var.name)
  env_lower     = lower(var.environment)
  full_prefix   = "${local.name_lower}-${local.env_lower}"

  # Default description for the standard key
  default_key_description = "KMS key for ${var.name}-${var.environment}"

  # Key ID evaluation for alias, grant, ciphertext
  # If an explicit target is provided, use it; else fall back to the created key (if it exists)
  alias_target_key_id = var.kms_alias_target_key_arn != null ? var.kms_alias_target_key_arn : (
    var.enable_kms_key ? aws_kms_key.standard_key[0].arn : null
  )
  grant_target_key_id = var.kms_grant_key_id != null ? var.kms_grant_key_id : (
    var.enable_kms_key ? aws_kms_key.standard_key[0].key_id : null
  )
  ciphertext_target_key_id = var.kms_ciphertext_key_id != null ? var.kms_ciphertext_key_id : (
    var.enable_kms_key ? aws_kms_key.standard_key[0].arn : null
  )

  # Default alias name
  default_alias_name = "alias/${local.full_prefix}"

  # Default grant name
  default_grant_name = "${var.name}-kms-grant-${var.environment}"

  # Tags
  common_tags = {
    Name        = "kms-${local.full_prefix}"
    Environment = var.environment
  }
}

# ------------------------------------------------------------------------------
# Resources
# ------------------------------------------------------------------------------

# Standard KMS Key
resource "aws_kms_key" "standard_key" {
  count = var.enable_kms_key ? 1 : 0

  description              = coalesce(var.kms_key_description, local.default_key_description)
  key_usage                = upper(var.kms_key_usage)
  enable_key_rotation      = var.kms_key_enable_key_rotation
  is_enabled               = var.kms_key_is_enabled
  deletion_window_in_days  = var.kms_key_deletion_window_in_days
  policy                   = var.kms_key_policy
  customer_master_key_spec = var.kms_key_customer_master_key_spec
  tags                     = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

# KMS Alias
resource "aws_kms_alias" "key_alias" {
  count = var.enable_kms_alias ? 1 : 0

  name          = coalesce(var.kms_alias_name, local.default_alias_name)
  target_key_id = local.alias_target_key_id
}

# KMS Grant
resource "aws_kms_grant" "key_grant" {
  count = var.enable_kms_grant ? 1 : 0

  name                 = coalesce(var.kms_grant_name, local.default_grant_name)
  grantee_principal    = var.kms_grant_grantee_principal
  retiring_principal   = var.kms_grant_retiring_principal
  operations           = var.kms_grant_operations
  grant_creation_tokens = var.kms_grant_grant_creation_tokens
  retire_on_delete     = var.kms_grant_retire_on_delete
  key_id               = local.grant_target_key_id

  dynamic "constraints" {
    for_each = length(var.kms_grant_encryption_context_equals) > 0 || length(var.kms_grant_encryption_context_subset) > 0 ? [1] : []
    content {
      encryption_context_equals = var.kms_grant_encryption_context_equals
      encryption_context_subset = var.kms_grant_encryption_context_subset
    }
  }
}

# External KMS Key (imported)
resource "aws_kms_external_key" "external_key" {
  count = var.enable_kms_external_key ? 1 : 0

  key_material_base64     = var.kms_external_key_material_base64
  valid_to                = var.kms_external_key_valid_to
  enabled                 = var.kms_external_key_is_enabled
  policy                  = var.kms_external_key_policy
  deletion_window_in_days = var.kms_external_key_deletion_window_in_days
  tags = merge(local.common_tags, {
    Name = "kms-external-${local.full_prefix}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# KMS Ciphertext Data Source
data "aws_kms_ciphertext" "ciphertext" {
  count = var.enable_kms_ciphertext ? 1 : 0

  plaintext = var.kms_ciphertext_plaintext
  key_id    = local.ciphertext_target_key_id
  context   = var.kms_ciphertext_encryption_context
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "kms_key_arn" {
  description = "ARN of the standard KMS key (if created)"
  value       = var.enable_kms_key ? aws_kms_key.standard_key[0].arn : null
}

output "kms_external_key_arn" {
  description = "ARN of the external KMS key (if created)"
  value       = var.enable_kms_external_key ? aws_kms_external_key.external_key[0].arn : null
}

output "kms_ciphertext_blob" {
  description = "Encrypted ciphertext (if enabled)"
  value       = var.enable_kms_ciphertext ? data.aws_kms_ciphertext.ciphertext[0].ciphertext_blob : null
  sensitive   = true
}

output "account_id" {
  description = "AWS account ID (always present)"
  value       = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "create" {
  description = "Whether to create all resources"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "workgroups" {
  description = "List of Athena workgroups to create"
  type = list(object({
    name          = string
    description   = optional(string, "")
    enabled       = optional(bool, true)
    force_destroy = optional(bool, false)
    configuration = object({
      bytes_scanned_cutoff_per_query     = optional(number, null)
      enforce_workgroup_configuration    = optional(bool, true)
      selected_engine_version            = optional(string, "AUTO")
      execution_role                     = optional(string, "")
      publish_cloudwatch_metrics_enabled = optional(bool, true)
      requester_pays_enabled             = optional(bool, false)
      output_location                    = string
      expected_bucket_owner              = optional(string, "")
      s3_acl_option                      = optional(string, "")
      encryption_configuration = optional(object({
        encryption_option = string
        kms_key_arn       = optional(string, "")
      }), null)
    })
  }))
  default = [
    {
      name          = "default-athena"
      description   = "Default Athena workgroup"
      enabled       = true
      force_destroy = true
      configuration = {
        output_location = "athena-results-default-athena"
        encryption_configuration = {
          encryption_option = "SSE_S3"
        }
      }
    }
  ]
}

variable "databases" {
  description = "List of Athena databases to create"
  type = list(object({
    name                  = string
    target_bucket         = string
    comment               = optional(string, "")
    expected_bucket_owner = optional(string, "")
    force_destroy         = optional(bool, false)
    custom_metadata       = optional(map(string), {})
    s3_acl_option         = optional(string, "")
    encryption_configuration = optional(object({
      encryption_enabled = optional(bool, false)
      encryption_option  = optional(string, "SSE_S3")
      encryption_kms_key = optional(string, "")
    }), {
      encryption_enabled = false
      encryption_option  = "SSE_S3"
      encryption_kms_key = ""
    })
  }))
  default = []
}

variable "named_queries" {
  description = "List of named queries to create"
  type = list(object({
    name      = string
    query     = string
    database  = string
    workgroup = optional(string, "")
  }))
  default = []
}

variable "data_catalogs" {
  description = "List of Athena data catalogs to create"
  type = list(object({
    name        = string
    type        = string
    parameters  = map(string)
    description = optional(string, "")
    tags        = optional(map(string), {})
  }))
  default = []
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  workgroup_map = {
    for wg in var.workgroups : wg.name => wg
  }
  database_map = {
    for db in var.databases : db.name => db
  }
  wg_bucket_names = var.create ? {
    for wg in var.workgroups : wg.name => lower("athena-results-${wg.name}-${random_id.wg_bucket_suffix[wg.name].hex}")
  } : {}
}

resource "random_id" "wg_bucket_suffix" {
  for_each = var.create ? { for wg in var.workgroups : wg.name => wg } : {}

  byte_length = 6
  keepers = {
    workgroup_name = each.value.name
  }
}

resource "aws_s3_bucket" "workgroup_output" {
  for_each = var.create ? { for wg in var.workgroups : wg.name => wg } : {}

  bucket        = local.wg_bucket_names[each.key]
  force_destroy = each.value.force_destroy
  tags          = merge(var.tags, { Name = each.key })
}

resource "aws_s3_bucket_public_access_block" "workgroup_output" {
  for_each = aws_s3_bucket.workgroup_output

  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "workgroup_output" {
  for_each = aws_s3_bucket.workgroup_output

  bucket = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = try(local.workgroup_map[each.key].configuration.encryption_configuration.encryption_option, "SSE_S3") == "SSE_KMS" ? "aws:kms" : "AES256"
      kms_master_key_id = try(local.workgroup_map[each.key].configuration.encryption_configuration.encryption_option, "SSE_S3") == "SSE_KMS" ? (
        local.workgroup_map[each.key].configuration.encryption_configuration.kms_key_arn != "" ? local.workgroup_map[each.key].configuration.encryption_configuration.kms_key_arn : aws_kms_key.workgroup_encryption[each.key].arn
      ) : null
    }
  }
}

resource "aws_s3_bucket_versioning" "workgroup_output" {
  for_each = aws_s3_bucket.workgroup_output

  bucket = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "database_target" {
  for_each = var.create ? { for db in var.databases : db.name => db } : {}

  bucket        = each.value.target_bucket
  force_destroy = each.value.force_destroy
  tags          = merge(var.tags, { Name = each.key })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "database_target" {
  for_each = aws_s3_bucket.database_target

  bucket                  = each.value.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "database_target" {
  for_each = aws_s3_bucket.database_target

  bucket = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = try(local.database_map[each.key].encryption_configuration.encryption_enabled, false) && try(local.database_map[each.key].encryption_configuration.encryption_option, "SSE_S3") == "SSE_KMS" ? "aws:kms" : "AES256"
      kms_master_key_id = try(local.database_map[each.key].encryption_configuration.encryption_enabled, false) && try(local.database_map[each.key].encryption_configuration.encryption_option, "SSE_S3") == "SSE_KMS" ? (
        local.database_map[each.key].encryption_configuration.encryption_kms_key != "" ? local.database_map[each.key].encryption_configuration.encryption_kms_key : aws_kms_key.database_encryption[each.key].arn
      ) : null
    }
  }
}

resource "aws_s3_bucket_versioning" "database_target" {
  for_each = aws_s3_bucket.database_target

  bucket = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "workgroup_encryption" {
  for_each = {
    for wg_name, wg in local.workgroup_map : wg_name => wg
    if var.create && wg.configuration.encryption_configuration != null && wg.configuration.encryption_configuration.encryption_option == "SSE_KMS" && coalesce(wg.configuration.encryption_configuration.kms_key_arn, "") == ""
  }

  description             = "Athena workgroup ${each.key} encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "Enable IAM User Permissions"
          Effect = "Allow"
          Principal = {
            AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
          }
          Action   = "kms:*"
          Resource = "*"
        },
        {
          Sid    = "Allow Athena to use the key"
          Effect = "Allow"
          Principal = {
            Service = "athena.amazonaws.com"
          }
          Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"]
          Resource = "*"
        }
      ],
      each.value.configuration.execution_role != "" ? [
        {
          Sid    = "Allow Athena execution role"
          Effect = "Allow"
          Principal = {
            AWS = aws_iam_role.athena_execution[each.key].arn
          }
          Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"]
          Resource = "*"
        }
      ] : []
    )
  })
  tags = merge(var.tags, { Name = "${each.key}-encryption-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "workgroup_encryption" {
  for_each = aws_kms_key.workgroup_encryption

  name          = "alias/athena-workgroup-${each.key}"
  target_key_id = each.value.id
}

resource "aws_kms_key" "database_encryption" {
  for_each = {
    for db_name, db in local.database_map : db_name => db
    if var.create && db.encryption_configuration.encryption_enabled && db.encryption_configuration.encryption_option == "SSE_KMS" && coalesce(db.encryption_configuration.encryption_kms_key, "") == ""
  }

  description             = "Athena database ${each.key} encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Athena to use the key"
        Effect = "Allow"
        Principal = {
          Service = "athena.amazonaws.com"
        }
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"]
        Resource = "*"
      }
    ]
  })
  tags = merge(var.tags, { Name = "${each.key}-encryption-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "database_encryption" {
  for_each = aws_kms_key.database_encryption

  name          = "alias/athena-database-${each.key}"
  target_key_id = each.value.id
}

resource "aws_iam_role" "athena_execution" {
  for_each = {
    for wg_name, wg in local.workgroup_map : wg_name => wg
    if var.create && wg.configuration.execution_role != ""
  }

  name = "athena-execution-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "athena.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(var.tags, { Name = "athena-execution-${each.key}" })
}

resource "aws_iam_policy" "athena_execution" {
  for_each = aws_iam_role.athena_execution

  name = "athena-execution-policy-${each.key}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Action = ["s3:GetBucketLocation", "s3:GetObject", "s3:ListBucket", "s3:PutObject"]
          Resource = concat(
            [for b in aws_s3_bucket.workgroup_output : b.arn],
            [for b in aws_s3_bucket.database_target : b.arn],
            [for b in aws_s3_bucket.workgroup_output : "${b.arn}/*"],
            [for b in aws_s3_bucket.database_target : "${b.arn}/*"]
          )
        }
      ],
      length(concat([for k in aws_kms_key.workgroup_encryption : k.arn], [for k in aws_kms_key.database_encryption : k.arn])) > 0 ? [
        {
          Effect = "Allow"
          Action   = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey"]
          Resource = concat([for k in aws_kms_key.workgroup_encryption : k.arn], [for k in aws_kms_key.database_encryption : k.arn])
        }
      ] : [],
      local.workgroup_map[each.key].configuration.publish_cloudwatch_metrics_enabled ? [
        {
          Effect = "Allow"
          Action   = ["logs:PutLogEvents"]
          Resource = "*"
          Condition = {
            StringEquals = {
              "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:athena:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:workgroup/${each.key}"
            }
          }
        }
      ] : []
    )
  })
  tags = merge(var.tags, { Name = "athena-execution-policy-${each.key}" })
}

resource "aws_iam_role_policy_attachment" "athena_execution" {
  for_each = aws_iam_role.athena_execution

  role       = each.value.name
  policy_arn = aws_iam_policy.athena_execution[each.key].arn
}

resource "aws_athena_workgroup" "this" {
  for_each = var.create ? { for wg in var.workgroups : wg.name => wg } : {}

  name          = each.key
  description   = each.value.description
  state         = each.value.enabled ? "ENABLED" : "DISABLED"
  force_destroy = each.value.force_destroy

  configuration {
    bytes_scanned_cutoff_per_query     = each.value.configuration.bytes_scanned_cutoff_per_query
    enforce_workgroup_configuration    = each.value.configuration.enforce_workgroup_configuration
    engine_version {
      selected_engine_version = each.value.configuration.selected_engine_version
    }
    execution_role                   = each.value.configuration.execution_role != "" ? aws_iam_role.athena_execution[each.key].arn : null
    publish_cloudwatch_metrics_enabled = each.value.configuration.publish_cloudwatch_metrics_enabled
    requester_pays_enabled           = each.value.configuration.requester_pays_enabled

    result_configuration {
      output_location      = "s3://${aws_s3_bucket.workgroup_output[each.key].id}/"
      expected_bucket_owner = each.value.configuration.expected_bucket_owner != "" ? each.value.configuration.expected_bucket_owner : null

      dynamic "acl_configuration" {
        for_each = each.value.configuration.s3_acl_option != "" ? [1] : []
        content {
          s3_acl_option = each.value.configuration.s3_acl_option
        }
      }

      encryption_configuration {
        encryption_option = try(each.value.configuration.encryption_configuration.encryption_option, "SSE_S3")
        kms_key_arn = try(each.value.configuration.encryption_configuration.encryption_option, "") == "SSE_KMS" ? (
          try(each.value.configuration.encryption_configuration.kms_key_arn, "") != "" ? each.value.configuration.encryption_configuration.kms_key_arn : try(aws_kms_key.workgroup_encryption[each.key].arn, null)
        ) : null
      }
    }
  }

  tags = merge(var.tags, { Name = each.key })
}

resource "aws_athena_database" "this" {
  for_each = var.create ? { for db in var.databases : db.name => db } : {}

  name                  = each.key
  bucket                = aws_s3_bucket.database_target[each.key].id
  comment               = each.value.comment != "" ? each.value.comment : null
  expected_bucket_owner = each.value.expected_bucket_owner != "" ? each.value.expected_bucket_owner : null
  force_destroy         = each.value.force_destroy
  properties            = each.value.custom_metadata

  dynamic "acl_configuration" {
    for_each = each.value.s3_acl_option != "" ? [1] : []
    content {
      s3_acl_option = each.value.s3_acl_option
    }
  }

  dynamic "encryption_configuration" {
    for_each = each.value.encryption_configuration.encryption_enabled ? [1] : []
    content {
      encryption_option = each.value.encryption_configuration.encryption_option
      kms_key = each.value.encryption_configuration.encryption_option == "SSE_KMS" ? (
        each.value.encryption_configuration.encryption_kms_key != "" ? each.value.encryption_configuration.encryption_kms_key : aws_kms_key.database_encryption[each.key].arn
      ) : null
    }
  }
}

resource "aws_athena_named_query" "this" {
  for_each = var.create ? { for idx, nq in var.named_queries : idx => nq } : {}

  name    = each.value.name
  query   = each.value.query
  database = try(
    aws_athena_database.this[each.value.database].name,
    each.value.database
  )
  workgroup = each.value.workgroup != "" ? try(
    aws_athena_workgroup.this[each.value.workgroup].name,
    each.value.workgroup
  ) : null
}

resource "aws_athena_data_catalog" "this" {
  for_each = var.create ? { for dc in var.data_catalogs : dc.name => dc } : {}

  name        = each.key
  type        = each.value.type
  parameters  = each.value.parameters
  description = each.value.description != "" ? each.value.description : null
  tags        = merge(var.tags, each.value.tags)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "name" {
  description = "Name prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment identifier"
  type        = string
  default     = "STAGE"
}

variable "enable_codebuild_project" {
  description = "Flag to enable CodeBuild project creation"
  type        = bool
  default     = true
}

variable "enable_codebuild_source_credential" {
  description = "Flag to enable CodeBuild source credential creation"
  type        = bool
  default     = false
}

variable "enable_codebuild_webhook" {
  description = "Flag to enable CodeBuild webhook creation"
  type        = bool
  default     = false
}

variable "enable_codebuild_report_group" {
  description = "Flag to enable CodeBuild report group creation"
  type        = bool
  default     = false
}

variable "codebuild_project_name" {
  description = "Explicit CodeBuild project name. If empty, default name is constructed from name and environment."
  type        = string
  default     = ""
}

variable "build_timeout" {
  description = "Build timeout in minutes"
  type        = number
  default     = 60
}

variable "queued_timeout" {
  description = "Queued timeout in minutes"
  type        = number
  default     = 480
}

variable "source_version" {
  description = "Source version for the build"
  type        = string
  default     = "refs/heads/main"
}

variable "badge_enabled" {
  description = "Enable badge for the project"
  type        = bool
  default     = false
}

variable "artifacts" {
  description = "Primary artifacts configuration"
  type = object({
    type           = string
    location       = optional(string)
    path           = optional(string)
    namespace_type = optional(string)
    name           = optional(string)
    packaging      = optional(string)
  })
  default = {
    type = "NO_ARTIFACTS"
  }
}

variable "secondary_artifacts" {
  description = "Secondary artifacts configurations"
  type = list(object({
    identifier     = string
    type           = string
    location       = optional(string)
    path           = optional(string)
    namespace_type = optional(string)
    name           = optional(string)
    packaging      = optional(string)
  }))
  default = []
}

variable "codebuild_source" {
  description = "Primary source configuration"
  type = object({
    type           = string
    location       = string
    auth_type      = optional(string)
    auth_resource  = optional(string)
    insecure_ssl   = optional(bool)
    report_build_status = optional(bool)
    fetch_submodules    = optional(bool)
  })
  default = {
    type     = "GITHUB"
    location = "https://github.com/example/repo.git"
  }
}

variable "secondary_sources" {
  description = "Secondary source configurations"
  type = list(object({
    identifier     = string
    type           = string
    location       = string
    auth_type      = optional(string)
    auth_resource  = optional(string)
    insecure_ssl   = optional(bool)
    report_build_status = optional(bool)
    fetch_submodules    = optional(bool)
  }))
  default = []
}

variable "environment_config" {
  description = "Environment configuration for the build"
  type = object({
    compute_type    = string
    image           = string
    type            = string
    image_pull_credentials_type = optional(string)
    registry_credential = optional(object({
      credential = string
      credential_provider = string
    }))
    environment_variables = optional(list(object({
      name  = string
      value = string
      type  = optional(string)
    })))
    privileged_mode = optional(bool)
  })
  default = {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:5.0"
    type         = "LINUX_CONTAINER"
  }
}

variable "cache" {
  description = "Cache configuration"
  type = object({
    type     = string
    location = optional(string)
    modes    = optional(list(string))
  })
  default = {
    type = "NO_CACHE"
  }
}

variable "logs_config" {
  description = "Logs configuration"
  type = object({
    cloudwatch_group = optional(string)
    cloudwatch_stream = optional(string)
    s3_bucket         = optional(string)
    s3_path           = optional(string)
    s3_encryption_disabled = optional(bool)
  })
  default = {}
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "source_credential_auth_type" {
  description = "Auth type for source credential (e.g., BASIC_AUTH, OAUTH, PERSONAL_ACCESS_TOKEN)"
  type        = string
  default     = ""
}

variable "source_credential_server_type" {
  description = "Server type for source credential (e.g., GITHUB, BITBUCKET, GITHUB_ENTERPRISE, GITLAB)"
  type        = string
  default     = ""
}

variable "source_credential_token" {
  description = "Token or password for source credential"
  type        = string
  default     = ""
  sensitive   = true
}

variable "source_credential_user_name" {
  description = "Optional username for source credential (used with BASIC_AUTH)"
  type        = string
  default     = ""
}

variable "webhook_branch_filter" {
  description = "Branch filter for webhook"
  type        = string
  default     = ""
}

variable "webhook_filter_groups" {
  description = "List of filter groups for webhook. Each filter group is a list of filter objects."
  type = list(list(object({
    type    = string
    pattern = string
    exclude_matched_pattern = optional(bool)
  })))
  default = []
}

variable "report_groups" {
  description = "List of report group configurations. Each element can have an optional name and s3_export_config."
  type = list(object({
    name = optional(string)
    s3_export_config = optional(object({
      bucket       = string
      encryption_key = optional(string)
      packaging    = optional(string)
      path_prefix  = optional(string)
    }))
  }))
  default = []
}

# Locals
locals {
  name_lower       = lower(var.name)
  env_lower        = lower(var.environment)
  project_name     = var.codebuild_project_name != "" ? var.codebuild_project_name : "${local.name_lower}-codebuild-project-${local.env_lower}"
  create_project   = var.enable_codebuild_project
  create_webhook   = var.enable_codebuild_webhook && var.enable_codebuild_project
  create_source_cred = var.enable_codebuild_source_credential
  create_report_groups = var.enable_codebuild_report_group

  # Default S3 bucket name for artifacts
  s3_bucket_name = "${local.name_lower}-codebuild-artifacts-${local.env_lower}-${data.aws_caller_identity.current.account_id}"
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild" {
  count = local.create_project ? 1 : 0
  name  = "${local.name_lower}-codebuild-role-${local.env_lower}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

# IAM Policy for CodeBuild (least privilege)
resource "aws_iam_policy" "codebuild" {
  count = local.create_project ? 1 : 0
  name  = "${local.name_lower}-codebuild-policy-${local.env_lower}"
  description = "Policy for CodeBuild project"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.codebuild[0].name}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:GetObjectVersion",
          "s3:GetBucketAcl",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.artifacts[0].arn,
          "${aws_s3_bucket.artifacts[0].arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.codebuild[0].arn
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codebuild" {
  count = local.create_project ? 1 : 0
  role       = aws_iam_role.codebuild[0].name
  policy_arn = aws_iam_policy.codebuild[0].arn
}

# KMS Key for CodeBuild
resource "aws_kms_key" "codebuild" {
  count = local.create_project ? 1 : 0
  description = "KMS key for CodeBuild project"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CodeBuild Service Role"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.codebuild[0].arn
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "codebuild" {
  count = local.create_project ? 1 : 0
  name          = "alias/${local.name_lower}-codebuild-key-${local.env_lower}"
  target_key_id = aws_kms_key.codebuild[0].key_id
}

# S3 Bucket for artifacts and logs
resource "aws_s3_bucket" "artifacts" {
  count = local.create_project ? 1 : 0
  bucket = local.s3_bucket_name
  force_destroy = false
  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  count = local.create_project ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  count = local.create_project ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.codebuild[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  count = local.create_project ? 1 : 0
  bucket = aws_s3_bucket.artifacts[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# VPC and Networking
resource "aws_vpc" "codebuild" {
  count = local.create_project ? 1 : 0
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = merge(var.tags, { Name = "${local.name_lower}-codebuild-vpc-${local.env_lower}" })
}

resource "aws_subnet" "codebuild" {
  count = local.create_project ? 2 : 0
  vpc_id            = aws_vpc.codebuild[0].id
  cidr_block        = cidrsubnet(aws_vpc.codebuild[0].cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(var.tags, { Name = "${local.name_lower}-codebuild-subnet-${count.index}-${local.env_lower}" })
}

resource "aws_internet_gateway" "codebuild" {
  count = local.create_project ? 1 : 0
  vpc_id = aws_vpc.codebuild[0].id
  tags = merge(var.tags, { Name = "${local.name_lower}-codebuild-igw-${local.env_lower}" })
}

resource "aws_route_table" "codebuild" {
  count = local.create_project ? 1 : 0
  vpc_id = aws_vpc.codebuild[0].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.codebuild[0].id
  }
  tags = merge(var.tags, { Name = "${local.name_lower}-codebuild-rt-${local.env_lower}" })
}

resource "aws_route_table_association" "codebuild" {
  count = local.create_project ? 2 : 0
  subnet_id      = aws_subnet.codebuild[count.index].id
  route_table_id = aws_route_table.codebuild[0].id
}

resource "aws_security_group" "codebuild" {
  count = local.create_project ? 1 : 0
  name        = "${local.name_lower}-codebuild-sg-${local.env_lower}"
  description = "Security group for CodeBuild project"
  vpc_id      = aws_vpc.codebuild[0].id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.codebuild[0].cidr_block]
  }
  tags = var.tags
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "codebuild" {
  count = local.create_project ? 1 : 0
  name = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30
  tags = var.tags
}

# CodeBuild Project
resource "aws_codebuild_project" "this" {
  count = local.create_project ? 1 : 0
  name         = local.project_name
  description  = "CodeBuild project for ${local.name_lower} in ${local.env_lower}"
  service_role = aws_iam_role.codebuild[0].arn
  build_timeout   = var.build_timeout
  queued_timeout  = var.queued_timeout
  source_version  = var.source_version
  badge_enabled   = var.badge_enabled

  artifacts {
    type           = var.artifacts.type
    location       = var.artifacts.type != "NO_ARTIFACTS" ? aws_s3_bucket.artifacts[0].id : null
    path           = var.artifacts.path
    namespace_type = var.artifacts.namespace_type
    name           = var.artifacts.name
    packaging      = var.artifacts.packaging
  }

  dynamic "secondary_artifacts" {
    for_each = var.secondary_artifacts
    content {
      artifact_identifier = secondary_artifacts.value.identifier
      type           = secondary_artifacts.value.type
      location       = secondary_artifacts.value.type != "NO_ARTIFACTS" ? aws_s3_bucket.artifacts[0].id : null
      path           = secondary_artifacts.value.path
      namespace_type = secondary_artifacts.value.namespace_type
      name           = secondary_artifacts.value.name
      packaging      = secondary_artifacts.value.packaging
    }
  }

  source {
    type            = var.codebuild_source.type
    location        = var.codebuild_source.location
    insecure_ssl    = var.codebuild_source.insecure_ssl
    report_build_status = var.codebuild_source.report_build_status

    dynamic "git_submodules_config" {
      for_each = var.codebuild_source.fetch_submodules != null ? [1] : []
      content {
        fetch_submodules = var.codebuild_source.fetch_submodules
      }
    }

    dynamic "auth" {
      for_each = var.codebuild_source.auth_type != null ? [1] : []
      content {
        type     = var.codebuild_source.auth_type
        resource = var.codebuild_source.auth_resource
      }
    }
  }

  dynamic "secondary_sources" {
    for_each = var.secondary_sources
    content {
      source_identifier = secondary_sources.value.identifier
      type           = secondary_sources.value.type
      location       = secondary_sources.value.location
      insecure_ssl    = secondary_sources.value.insecure_ssl
      report_build_status = secondary_sources.value.report_build_status

      dynamic "git_submodules_config" {
        for_each = secondary_sources.value.fetch_submodules != null ? [1] : []
        content {
          fetch_submodules = secondary_sources.value.fetch_submodules
        }
      }

      dynamic "auth" {
        for_each = secondary_sources.value.auth_type != null ? [1] : []
        content {
          type     = secondary_sources.value.auth_type
          resource = secondary_sources.value.auth_resource
        }
      }
    }
  }

  environment {
    compute_type    = var.environment_config.compute_type
    image           = var.environment_config.image
    type            = var.environment_config.type
    image_pull_credentials_type = var.environment_config.image_pull_credentials_type
    privileged_mode = var.environment_config.privileged_mode

    dynamic "registry_credential" {
      for_each = var.environment_config.registry_credential != null ? [1] : []
      content {
        credential          = var.environment_config.registry_credential.credential
        credential_provider = var.environment_config.registry_credential.credential_provider
      }
    }

    dynamic "environment_variable" {
      for_each = var.environment_config.environment_variables != null ? var.environment_config.environment_variables : []
      content {
        name  = environment_variable.value.name
        value = environment_variable.value.value
        type  = try(environment_variable.value.type, "PLAINTEXT")
      }
    }
  }

  cache {
    type     = var.cache.type
    location = var.cache.type != "NO_CACHE" ? aws_s3_bucket.artifacts[0].id : null
    modes    = var.cache.modes
  }

  logs_config {
    cloudwatch_logs {
      group_name  = var.logs_config.cloudwatch_group != null ? var.logs_config.cloudwatch_group : aws_cloudwatch_log_group.codebuild[0].name
      stream_name = var.logs_config.cloudwatch_stream
    }
    s3_logs {
      status   = var.logs_config.s3_bucket != null ? "ENABLED" : "DISABLED"
      location = var.logs_config.s3_bucket != null ? "${var.logs_config.s3_bucket}${var.logs_config.s3_path != null ? "/${var.logs_config.s3_path}" : ""}" : null
      encryption_disabled = var.logs_config.s3_encryption_disabled
    }
  }

  vpc_config {
    vpc_id = aws_vpc.codebuild[0].id
    subnets = aws_subnet.codebuild[*].id
    security_group_ids = [aws_security_group.codebuild[0].id]
  }

  encryption_key = aws_kms_key.codebuild[0].arn

  tags = var.tags

  lifecycle {
    create_before_destroy = true
  }
}

# CodeBuild Source Credential
resource "aws_codebuild_source_credential" "this" {
  count = local.create_source_cred ? 1 : 0
  auth_type   = upper(var.source_credential_auth_type)
  server_type = upper(var.source_credential_server_type)
  token       = var.source_credential_token
  user_name   = var.source_credential_user_name != "" ? var.source_credential_user_name : null
}

# CodeBuild Webhook
resource "aws_codebuild_webhook" "this" {
  count = local.create_webhook ? 1 : 0
  project_name = aws_codebuild_project.this[0].name
  branch_filter = var.webhook_branch_filter != "" ? var.webhook_branch_filter : null

  dynamic "filter_group" {
    for_each = var.webhook_filter_groups
    content {
      dynamic "filter" {
        for_each = filter_group.value
        content {
          type    = filter.value.type
          pattern = filter.value.pattern
          exclude_matched_pattern = filter.value.exclude_matched_pattern
        }
      }
    }
  }
}

# CodeBuild Report Groups
resource "aws_codebuild_report_group" "this" {
  for_each = local.create_report_groups ? { for idx, rg in var.report_groups : idx => rg } : {}
  name = each.value.name != null ? each.value.name : "${local.name_lower}-codebuild-report-group-${each.key}-${local.env_lower}"
  type = "TEST"

  dynamic "export_config" {
    for_each = each.value.s3_export_config != null ? [1] : []
    content {
      type = "S3"
      s3_destination {
        bucket          = each.value.s3_export_config.bucket
        encryption_key = try(each.value.s3_export_config.encryption_key, null)
        packaging      = try(each.value.s3_export_config.packaging, null)
        path           = try(each.value.s3_export_config.path_prefix, null)
      }
    }
  }

  tags = var.tags
}

variable "default_tags" {
  type        = map(string)
  default     = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

locals {
  common_tags = var.default_tags
  name_prefix = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name       = "${local.name_prefix}-public-subnet-${count.index + 1}"
    SubnetType = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-gw"
  })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name       = "${local.name_prefix}-private-subnet-${count.index + 1}"
    SubnetType = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. If empty, bucket_prefix will be used"
  type        = string
  default     = ""
}

variable "bucket_prefix" {
  description = "Prefix for bucket name"
  type        = string
  default     = ""
}

variable "acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "Allow destruction of bucket even if it contains objects"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the bucket"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Suspended or Enabled)"
  type        = string
  default     = ""
}

variable "request_payer" {
  description = "Request payer (BucketOwner or Requester)"
  type        = string
  default     = ""
}

variable "control_object_ownership" {
  description = "Whether to control object ownership"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership rule (e.g., ObjectWriter)"
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Website configuration object"
  type = object({
    index_document           = optional(string, "")
    error_document           = optional(string, "")
    redirect_all_requests_to = optional(string, "")
    routing_rules            = optional(string, "")
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = []
}

variable "versioning" {
  description = "Versioning configuration. Set enabled = true to enable versioning, or provide status explicitly."
  type = object({
    enabled    = optional(bool, false)
    mfa_delete = optional(bool, false)
    status     = optional(string, "")
  })
  default = null
}

variable "logging" {
  description = "Logging configuration"
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id                                     = string
    status                                 = string
    filter                                 = optional(any, {})
    transition                             = optional(list(any), [])
    expiration                             = optional(any, {})
    noncurrent_version_transition          = optional(list(any), [])
    noncurrent_version_expiration          = optional(any, {})
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

variable "replication_configuration" {
  description = "Replication configuration"
  type = object({
    role_arn = optional(string, "")
    rules = list(object({
      id                          = string
      status                      = string
      priority                    = optional(number)
      filter                      = optional(any, {})
      destination_bucket          = string
      storage_class               = optional(string)
      delete_marker_replication   = optional(string, "")
      source_selection_criteria   = optional(any, {})
      existing_object_replication = optional(any, {})
    }))
  })
  default = null
}

variable "server_side_encryption" {
  description = "Server-side encryption configuration"
  type = object({
    sse_algorithm      = optional(string, "AES256")
    kms_master_key_arn = optional(string, "")
  })
  default = null
}

variable "object_lock" {
  description = "Object lock configuration"
  type = object({
    enabled                   = bool
    default_retention_mode    = optional(string, "GOVERNANCE")
    default_retention_days    = optional(number, 365)
  })
  default = null
}

variable "attach_public_policy" {
  description = "Whether to attach a public access block"
  type        = bool
  default     = true
}

variable "public_access_block" {
  description = "Public access block settings"
  type = object({
    block_public_acls       = bool
    block_public_policy     = bool
    ignore_public_acls      = bool
    restrict_public_buckets = bool
  })
  default = {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }
}

variable "attach_elb_log_delivery_policy" {
  description = "Whether to attach ELB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Whether to attach ALB/NLB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Whether to attach deny insecure transport policy"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Whether to attach a custom policy"
  type        = bool
  default     = false
}

variable "policy" {
  description = "Custom policy document (JSON)"
  type        = string
  default     = ""
}

locals {
  create_bucket = var.create_bucket ? 1 : 0

  bucket_name   = var.bucket != "" ? var.bucket : null
  bucket_prefix = var.bucket == "" ? var.bucket_prefix : null

  website_enabled            = var.website != null ? 1 : 0
  cors_enabled               = length(var.cors_rules) > 0 ? 1 : 0
  versioning_status          = var.versioning != null ? (var.versioning.status != "" ? var.versioning.status : (var.versioning.enabled ? "Enabled" : "Suspended")) : null
  logging_enabled            = var.logging != null ? 1 : 0
  lifecycle_enabled          = length(var.lifecycle_rules) > 0 ? 1 : 0
  replication_enabled        = var.replication_configuration != null ? 1 : 0
  sse_enabled                = var.server_side_encryption != null ? 1 : 0
  object_lock_enabled        = var.object_lock != null ? (var.object_lock.enabled ? 1 : 0) : 0
  replication_rule_count     = local.replication_enabled == 1 ? length(var.replication_configuration.rules) : 0

  elb_log_delivery_statements = var.attach_elb_log_delivery_policy ? [
    {
      sid    = "ELBLogDelivery"
      effect = "Allow"
      principals = {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.elb.arn]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
    }
  ] : []

  lb_log_delivery_statements = flatten([
    for i in range(var.attach_lb_log_delivery_policy ? 1 : 0) : [
      {
        sid    = "LBLogDeliveryWrite"
        effect = "Allow"
        principals = {
          type        = "Service"
          identifiers = ["delivery.logs.amazonaws.com"]
        }
        actions   = ["s3:PutObject"]
        resources = ["${aws_s3_bucket.this[0].arn}/*"]
        condition = {
          test     = "StringEquals"
          variable = "s3:x-amz-acl"
          values   = ["bucket-owner-full-control"]
        }
      },
      {
        sid    = "LBLogDeliveryAclCheck"
        effect = "Allow"
        principals = {
          type        = "Service"
          identifiers = ["delivery.logs.amazonaws.com"]
        }
        actions   = ["s3:GetBucketAcl"]
        resources = [aws_s3_bucket.this[0].arn]
      }
    ]
  ])

  deny_insecure_transport_statements = var.attach_deny_insecure_transport_policy ? [
    {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals = {
        type        = "*"
        identifiers = ["*"]
      }
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
      condition = {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  ] : []

  custom_policy_statements = var.attach_policy ? [jsondecode(var.policy)] : []

  statements = flatten([
    local.elb_log_delivery_statements,
    local.lb_log_delivery_statements,
    local.deny_insecure_transport_statements,
    local.custom_policy_statements,
  ])
}

data "aws_elb_service_account" "elb" {}

resource "aws_kms_key" "this" {
  count = ((local.sse_enabled == 1 || local.replication_enabled == 1) && (var.server_side_encryption == null || var.server_side_encryption.kms_master_key_arn == "")) ? 1 : 0

  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "this" {
  count = local.create_bucket

  bucket        = local.bucket_name
  bucket_prefix = local.bucket_prefix
  force_destroy = var.force_destroy
  tags          = var.tags

  acceleration_status = var.acceleration_status != "" ? var.acceleration_status : null
  request_payer       = var.request_payer != "" ? var.request_payer : null

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? local.create_bucket : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.website_enabled

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = var.website.index_document != "" ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website.error_document != "" ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != "" ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  routing_rules = var.website.routing_rules != "" ? var.website.routing_rules : null
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.cors_enabled

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.versioning_status != null ? local.create_bucket : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = local.versioning_status
    mfa_delete = var.versioning.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket" "logging" {
  count = local.logging_enabled

  bucket        = var.logging.target_bucket
  force_destroy = false
  tags          = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "arn:aws:s3:::logging-bucket/AWSLogs/*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = local.logging_enabled

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = local.logging_enabled

  bucket = aws_s3_bucket.this[0].id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.lifecycle_enabled

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)

          dynamic "tag" {
            for_each = lookup(filter.value, "tag_key", null) != null ? [{
              key   = filter.value.tag_key
              value = filter.value.tag_value
            }] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition
        content {
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days = lookup(expiration.value, "days", null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition
        content {
          noncurrent_days = lookup(noncurrent_version_transition.value, "days", null)
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = lookup(noncurrent_version_expiration.value, "days", null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

resource "aws_s3_bucket" "replication" {
  count = local.replication_rule_count

  bucket        = var.replication_configuration.rules[count.index].destination_bucket
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication" {
  count = local.replication_rule_count

  bucket = aws_s3_bucket.replication[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.server_side_encryption != null && var.server_side_encryption.kms_master_key_arn != "" ? var.server_side_encryption.kms_master_key_arn : aws_kms_key.this[0].arn
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.replication_enabled

  name = "s3-replication-role-${aws_s3_bucket.this[0].id}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = local.replication_enabled

  name = "s3-replication-policy-${aws_s3_bucket.this[0].id}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.this[0].arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.this[0].arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = [for b in aws_s3_bucket.replication : "${b.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.replication_enabled

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.replication_enabled

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role_arn != "" ? var.replication_configuration.role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = lookup(filter.value, "prefix", null)
        }
      }

      destination {
        bucket        = aws_s3_bucket.replication[rule.key].arn
        storage_class = rule.value.storage_class
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != "" ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          sse_kms_encrypted_objects {
            status = lookup(source_selection_criteria.value, "sse_kms_encrypted_objects_status", "Enabled")
          }
        }
      }

      dynamic "existing_object_replication" {
        for_each = rule.value.existing_object_replication != null ? [rule.value.existing_object_replication] : []
        content {
          status = lookup(existing_object_replication.value, "status", "Enabled")
        }
      }
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.sse_enabled

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.server_side_encryption.kms_master_key_arn != "" ? var.server_side_encryption.kms_master_key_arn : aws_kms_key.this[0].arn
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.object_lock_enabled

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode = var.object_lock.default_retention_mode
      days = var.object_lock.default_retention_days
    }
  }
}

data "aws_iam_policy_document" "this" {
  count = local.create_bucket

  dynamic "statement" {
    for_each = local.statements
    content {
      sid       = lookup(statement.value, "sid", null)
      effect    = statement.value.effect
      principals {
        type        = statement.value.principals.type
        identifiers = statement.value.principals.identifiers
      }
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "condition" {
        for_each = lookup(statement.value, "condition", null) != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = length(local.statements) > 0 ? local.create_bucket : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.this[0].json
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.attach_public_policy ? local.create_bucket : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.public_access_block.block_public_acls
  block_public_policy     = var.public_access_block.block_public_policy
  ignore_public_acls      = var.public_access_block.ignore_public_acls
  restrict_public_buckets = var.public_access_block.restrict_public_buckets
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "projectPrefix" {
  type    = string
  default = "f5-dcec"
}

variable "resourceOwner" {
  type    = string
  default = "f5-user"
}

variable "buildSuffix" {
  type    = string
  default = "YY"
}

variable "map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "awsRegion" {
  type    = string
  default = "us-east-1"
}

variable "vpcMainCidr" {
  type    = string
  default = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  type    = string
  default = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  type    = string
  default = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  type    = string
  default = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  type    = string
  default = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  type    = string
  default = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  type    = string
  default = "10.1.120.0/24"
}

variable "awsAz1" {
  type    = string
  default = null
}

variable "awsAz2" {
  type    = string
  default = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  az2 = var.awsAz2 != null ? var.awsAz2 : (var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1])

  common_tags = {
    projectPrefix = var.projectPrefix
    resourceOwner = var.resourceOwner
    buildSuffix   = var.buildSuffix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-b-${var.buildSuffix}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Input variables
variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "resource_name" {
  description = "Base name used to tag and name all resources"
  type        = string
  default     = "benchmark"
}

variable "listener_rule_count" {
  description = "Number of listener rules to create for path-based routing"
  type        = number
  default     = 1
}

# Data source for available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Local values for AZ selection
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

# VPC with CIDR 10.0.0.0/16
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = var.resource_name
    Region = var.region
  }
}

# Two subnets using calculated /24 CIDR blocks
resource "aws_subnet" "main" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = var.resource_name
  }
}

# Security group allowing all ingress and egress within the VPC
resource "aws_security_group" "main" {
  name        = var.resource_name
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.resource_name
  }
}

# HTTP target group on port 8080 with health check on port 8081
resource "aws_lb_target_group" "main" {
  name        = var.resource_name
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    port                = 8081
    protocol            = "HTTP"
    path                = "/health"
    interval            = 60
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = var.resource_name
  }
}

# Internal Application Load Balancer
resource "aws_lb" "main" {
  name                       = var.resource_name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.main.id]
  subnets                    = aws_subnet.main[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

# Self-signed certificate for HTTPS listener
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name = "${var.resource_name}.example.com"
  }

  validity_period_hours = 12

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  private_key       = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem

  tags = {
    Name = var.resource_name
  }
}

# HTTPS listener on port 80 forwarding to target group
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = var.resource_name
  }
}

# Listener rules for path-based routing
resource "aws_lb_listener_rule" "main" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-/*"]
    }
  }

  tags = {
    Name = var.resource_name
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

import {
  to = aws_kms_alias.s3
  id = "alias/cloudtrail-s3-key"
}

import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = "cloudtrail_logs"
}

import {
  to = aws_iam_role.cloudtrail_cw
  id = "CloudTrailRoleForCloudWatchLogs"
}

variable "management_trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "organization_trail" {
  description = "Enable organization trail behavior"
  type        = bool
  default     = false
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group"
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_kms" {
  description = "Enable KMS key encryption for CloudTrail logs"
  type        = bool
  default     = false
}

resource "random_integer" "bucket_suffix" {
  min = 100000000000
  max = 999999999999
}

# Unconditional KMS key for S3 bucket encryption (always CMK)
resource "aws_kms_key" "s3" {
  description             = "KMS key for CloudTrail S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "s3" {
  name          = "alias/cloudtrail-s3-key"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "cloudtrail-bucket-${random_integer.bucket_suffix.result}"
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailGetBucketAcl"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail.arn
      },
      {
        Sid    = "AllowCloudTrailPutObject"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "cloudtrail_cw" {
  name = "CloudTrailRoleForCloudWatchLogs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cw" {
  name = "allow-access-to-cw-logs"
  role = aws_iam_role.cloudtrail_cw.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToWriteLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms ? 1 : 0

  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow account to decrypt logs"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action   = "kms:Decrypt"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms ? 1 : 0

  name          = "alias/cloudtrail_key"
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

data "aws_caller_identity" "current" {}

resource "aws_cloudtrail" "main" {
  name                          = var.management_trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.organization_trail

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cw.arn

  kms_key_id = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "namespace" {
  description = "Optional namespace prefix for the repository name"
  type        = string
  default     = ""
}

variable "repository_name" {
  description = "Repository name segment; defaults to 'ecr', uses petname if null or empty"
  type        = string
  default     = "ecr"
}

variable "image_tag_mutability" {
  description = "Image tag mutability setting (MUTABLE or IMMUTABLE)"
  type        = string
  default     = "IMMUTABLE"
}

variable "scan_on_push" {
  description = "Enable image scanning on push"
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "Custom lifecycle policy JSON; defaults to retaining max 2 images"
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "List of additional AWS account IDs for cross-account read access"
  type        = list(string)
  default     = []
}

# Data sources
data "aws_caller_identity" "current" {}

# Random pet for fallback name
resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

# Local values
locals {
  repo_name = var.repository_name != null && var.repository_name != "" ? var.repository_name : random_pet.this.id
  local_name = join("/", compact([var.namespace, local.repo_name]))

  repository_arn = aws_ecr_repository.repo.arn

  # Default lifecycle policy (retain max 2 images)
  default_lifecycle_policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Retain only 2 images"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 2
        }
        action = {
          type = "expire"
        }
      }
    ]
  })

  lifecycle_policy_json = var.lifecycle_policy != null ? var.lifecycle_policy : local.default_lifecycle_policy

  # Read actions for IAM policy (includes service-level actions)
  read_actions = [
    "ecr:BatchCheckLayerAvailability",
    "ecr:BatchGetImage",
    "ecr:DescribeImages",
    "ecr:DescribeRepositories",
    "ecr:GetAuthorizationToken",
    "ecr:GetDownloadUrlForLayer",
    "ecr:ListImages",
  ]

  # Read actions valid for resource-based policies (excludes GetAuthorizationToken and DescribeRepositories)
  repo_read_actions = [
    for action in local.read_actions : action
    if action != "ecr:GetAuthorizationToken" && action != "ecr:DescribeRepositories"
  ]

  write_actions = [
    "ecr:PutImage",
    "ecr:UploadLayerPart",
    "ecr:InitiateLayerUpload",
    "ecr:CompleteLayerUpload",
  ]

  # Principal ARNs for cross-account policy
  principal_arns = concat(
    ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"],
    [for account in var.trusted_accounts : "arn:aws:iam::${account}:root"]
  )
}

# ECR Repository
resource "aws_ecr_repository" "repo" {
  name                 = local.local_name
  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.local_name
  }
}

# Lifecycle policy
resource "aws_ecr_lifecycle_policy" "this" {
  repository = aws_ecr_repository.repo.name
  policy     = local.lifecycle_policy_json
}

# IAM read policy
data "aws_iam_policy_document" "ecr_read" {
  statement {
    effect = "Allow"
    actions = local.read_actions
    resources = [local.repository_arn]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.local_name}-ecr-read"
  description = "Read access to ECR repository ${local.local_name}"
  policy      = data.aws_iam_policy_document.ecr_read.json
}

# IAM write policy
data "aws_iam_policy_document" "ecr_write" {
  statement {
    effect = "Allow"
    actions = local.write_actions
    resources = [local.repository_arn]
  }
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.local_name}-ecr-write"
  description = "Write access to ECR repository ${local.local_name}"
  policy      = data.aws_iam_policy_document.ecr_write.json
}

# ECR repository policy for cross-account read access
data "aws_iam_policy_document" "cross_account" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = local.principal_arns
    }
    actions = local.repo_read_actions
  }
}

resource "aws_ecr_repository_policy" "cross_account" {
  repository = aws_ecr_repository.repo.name
  policy     = data.aws_iam_policy_document.cross_account.json
}

# ----------------------------------------------------------------------
# TERRAFORM CONFIGURATION
# ----------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------

# Global settings
variable "allow_self_assume_role" {
  description = "Allow each role to assume itself (self-assumption)."
  type        = bool
  default     = false
}

variable "mfa_max_age" {
  description = "Maximum age (seconds) for MFA token when MFA is required."
  type        = number
  default     = 86400
}

variable "max_session_duration" {
  description = "Maximum session duration (seconds) for all roles."
  type        = number
  default     = 3600
}

variable "force_detach_policies" {
  description = "Force detach policies when role is deleted."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Global tags applied to all resources."
  type        = map(string)
  default     = {}
}

# Admin role variables
variable "create_admin_role" {
  description = "Create the admin role."
  type        = bool
  default     = false
}

variable "admin_role_name" {
  description = "Name of the admin IAM role."
  type        = string
  default     = "admin"
}

variable "admin_role_path" {
  description = "Path for the admin IAM role."
  type        = string
  default     = "/"
}

variable "admin_role_requires_mfa" {
  description = "Require MFA for the admin role trust policy."
  type        = bool
  default     = true
}

variable "admin_policy_arns" {
  description = "List of managed policy ARNs to attach to the admin role."
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/AdministratorAccess"]
}

variable "admin_inline_policies" {
  description = "Map of inline policy names to policy JSON for the admin role."
  type        = map(string)
  default     = {}
}

variable "admin_trusted_iam_role_arns" {
  description = "List of IAM role ARNs allowed to assume the admin role."
  type        = list(string)
  default     = []
}

variable "admin_trusted_service_principals" {
  description = "List of AWS service principals allowed to assume the admin role."
  type        = list(string)
  default     = []
}

variable "admin_permissions_boundary_arn" {
  description = "ARN of the permissions boundary for the admin role."
  type        = string
  default     = ""
}

variable "admin_role_tags" {
  description = "Extra tags for the admin role (merged with global tags)."
  type        = map(string)
  default     = {}
}

# PowerUser role variables
variable "create_poweruser_role" {
  description = "Create the poweruser role."
  type        = bool
  default     = false
}

variable "poweruser_role_name" {
  description = "Name of the poweruser IAM role."
  type        = string
  default     = "poweruser"
}

variable "poweruser_role_path" {
  description = "Path for the poweruser IAM role."
  type        = string
  default     = "/"
}

variable "poweruser_role_requires_mfa" {
  description = "Require MFA for the poweruser role trust policy."
  type        = bool
  default     = true
}

variable "poweruser_policy_arns" {
  description = "List of managed policy ARNs to attach to the poweruser role."
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/PowerUserAccess"]
}

variable "poweruser_inline_policies" {
  description = "Map of inline policy names to policy JSON for the poweruser role."
  type        = map(string)
  default     = {}
}

variable "poweruser_trusted_iam_role_arns" {
  description = "List of IAM role ARNs allowed to assume the poweruser role."
  type        = list(string)
  default     = []
}

variable "poweruser_trusted_service_principals" {
  description = "List of AWS service principals allowed to assume the poweruser role."
  type        = list(string)
  default     = []
}

variable "poweruser_permissions_boundary_arn" {
  description = "ARN of the permissions boundary for the poweruser role."
  type        = string
  default     = ""
}

variable "poweruser_role_tags" {
  description = "Extra tags for the poweruser role (merged with global tags)."
  type        = map(string)
  default     = {}
}

# ReadOnly role variables
variable "create_readonly_role" {
  description = "Create the readonly role."
  type        = bool
  default     = true   # Changed from false to true to ensure at least one role is created by default
}

variable "readonly_role_name" {
  description = "Name of the readonly IAM role."
  type        = string
  default     = "readonly"
}

variable "readonly_role_path" {
  description = "Path for the readonly IAM role."
  type        = string
  default     = "/"
}

variable "readonly_role_requires_mfa" {
  description = "Require MFA for the readonly role trust policy."
  type        = bool
  default     = true
}

variable "readonly_policy_arns" {
  description = "List of managed policy ARNs to attach to the readonly role."
  type        = list(string)
  default     = ["arn:aws:iam::aws:policy/ReadOnlyAccess"]
}

variable "readonly_inline_policies" {
  description = "Map of inline policy names to policy JSON for the readonly role."
  type        = map(string)
  default     = {}
}

variable "readonly_trusted_iam_role_arns" {
  description = "List of IAM role ARNs allowed to assume the readonly role."
  type        = list(string)
  default     = []
}

variable "readonly_trusted_service_principals" {
  description = "List of AWS service principals allowed to assume the readonly role."
  type        = list(string)
  default     = []
}

variable "readonly_permissions_boundary_arn" {
  description = "ARN of the permissions boundary for the readonly role."
  type        = string
  default     = ""
}

variable "readonly_role_tags" {
  description = "Extra tags for the readonly role (merged with global tags)."
  type        = map(string)
  default     = {}
}

# ----------------------------------------------------------------------
# DATA SOURCES
# ----------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------

locals {
  roles = {
    admin = {
      create                   = var.create_admin_role
      name                     = var.admin_role_name
      path                     = var.admin_role_path
      requires_mfa             = var.admin_role_requires_mfa
      policy_arns              = var.admin_policy_arns
      inline_policies          = var.admin_inline_policies
      trusted_iam_role_arns    = var.admin_trusted_iam_role_arns
      trusted_service_principals = var.admin_trusted_service_principals
      permissions_boundary_arn = var.admin_permissions_boundary_arn
      extra_tags               = var.admin_role_tags
    }
    poweruser = {
      create                   = var.create_poweruser_role
      name                     = var.poweruser_role_name
      path                     = var.poweruser_role_path
      requires_mfa             = var.poweruser_role_requires_mfa
      policy_arns              = var.poweruser_policy_arns
      inline_policies          = var.poweruser_inline_policies
      trusted_iam_role_arns    = var.poweruser_trusted_iam_role_arns
      trusted_service_principals = var.poweruser_trusted_service_principals
      permissions_boundary_arn = var.poweruser_permissions_boundary_arn
      extra_tags               = var.poweruser_role_tags
    }
    readonly = {
      create                   = var.create_readonly_role
      name                     = var.readonly_role_name
      path                     = var.readonly_role_path
      requires_mfa             = var.readonly_role_requires_mfa
      policy_arns              = var.readonly_policy_arns
      inline_policies          = var.readonly_inline_policies
      trusted_iam_role_arns    = var.readonly_trusted_iam_role_arns
      trusted_service_principals = var.readonly_trusted_service_principals
      permissions_boundary_arn = var.readonly_permissions_boundary_arn
      extra_tags               = var.readonly_role_tags
    }
  }
}

# ----------------------------------------------------------------------
# TRUST POLICY DOCUMENTS
# ----------------------------------------------------------------------

# We generate a trust policy document per role using for_each
data "aws_iam_policy_document" "trust" {
  for_each = { for role_key, role in local.roles : role_key => role if role.create }

  # Statement for trusted IAM roles
  dynamic "statement" {
    for_each = length(each.value.trusted_iam_role_arns) > 0 ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "AWS"
        identifiers = each.value.trusted_iam_role_arns
      }
      dynamic "condition" {
        for_each = each.value.requires_mfa ? [1] : []
        content {
          test     = "BoolIfExists"
          variable = "aws:MultiFactorAuthPresent"
          values   = ["true"]
        }
      }
      dynamic "condition" {
        for_each = each.value.requires_mfa ? [1] : []
        content {
          test     = "NumericLessThanEquals"
          variable = "aws:MultiFactorAuthAge"
          values   = [var.mfa_max_age]
        }
      }
    }
  }

  # Statement for trusted service principals
  dynamic "statement" {
    for_each = length(each.value.trusted_service_principals) > 0 ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "Service"
        identifiers = each.value.trusted_service_principals
      }
      # No MFA conditions for service principals
    }
  }

  # Self-assume statement (if enabled)
  dynamic "statement" {
    for_each = var.allow_self_assume_role ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      }
      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${each.value.name}"]
      }
      dynamic "condition" {
        for_each = each.value.requires_mfa ? [1] : []
        content {
          test     = "BoolIfExists"
          variable = "aws:MultiFactorAuthPresent"
          values   = ["true"]
        }
      }
      dynamic "condition" {
        for_each = each.value.requires_mfa ? [1] : []
        content {
          test     = "NumericLessThanEquals"
          variable = "aws:MultiFactorAuthAge"
          values   = [var.mfa_max_age]
        }
      }
    }
  }

  # Fallback statement: allow root account to assume the role when no other trust sources are configured
  dynamic "statement" {
    for_each = length(each.value.trusted_iam_role_arns) == 0 && length(each.value.trusted_service_principals) == 0 && !var.allow_self_assume_role ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      }
    }
  }
}

# ----------------------------------------------------------------------
# ROLES
# ----------------------------------------------------------------------

resource "aws_iam_role" "this" {
  for_each = { for role_key, role in local.roles : role_key => role if role.create }

  name                 = each.value.name
  path                 = each.value.path
  assume_role_policy   = data.aws_iam_policy_document.trust[each.key].json
  max_session_duration = var.max_session_duration
  force_detach_policies = var.force_detach_policies
  permissions_boundary = each.value.permissions_boundary_arn != "" ? each.value.permissions_boundary_arn : null

  tags = merge(var.tags, each.value.extra_tags)
}

# ----------------------------------------------------------------------
# MANAGED POLICY ATTACHMENTS
# ----------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "this" {
  for_each = {
    for pair in flatten([
      for role_key, role in local.roles : [
        for policy_arn in role.create ? role.policy_arns : [] : {
          role_key   = role_key
          policy_arn = policy_arn
        }
      ]
    ]) : "${pair.role_key}-${pair.policy_arn}" => pair
  }

  role       = aws_iam_role.this[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

# ----------------------------------------------------------------------
# INLINE POLICIES
# ----------------------------------------------------------------------

resource "aws_iam_role_policy" "this" {
  for_each = {
    for pair in flatten([
      for role_key, role in local.roles : [
        for policy_name, policy_json in role.create ? role.inline_policies : {} : {
          role_key     = role_key
          policy_name  = policy_name
          policy_json  = policy_json
        }
      ]
    ]) : "${pair.role_key}-${pair.policy_name}" => pair
  }

  name   = each.value.policy_name
  role   = aws_iam_role.this[each.value.role_key].name
  policy = each.value.policy_json
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# --------------------------------------------------------------------------
# Data sources
# --------------------------------------------------------------------------
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# --------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------
variable "create" {
  description = "Whether to create all notification resources"
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Name of the S3 bucket for which notifications are configured"
  type        = string
  default     = ""
}

variable "bucket_arn" {
  description = "ARN of the S3 bucket (overrides constructing from bucket_name)"
  type        = string
  default     = null
}

variable "lambda_notifications" {
  description = "Map of Lambda notification configurations"
  type = map(object({
    target_arn    = string
    events        = list(string)
    filter_prefix = optional(string)
    filter_suffix = optional(string)
    function_name = string
    qualifier     = optional(string)
  }))
  default = {}
}

variable "sqs_notifications" {
  description = "Map of SQS notification configurations"
  type = map(object({
    target_arn    = string
    events        = list(string)
    filter_prefix = optional(string)
    filter_suffix = optional(string)
    queue_id      = optional(string)
  }))
  default = {}
}

variable "sns_notifications" {
  description = "Map of SNS notification configurations"
  type = map(object({
    target_arn    = string
    events        = list(string)
    filter_prefix = optional(string)
    filter_suffix = optional(string)
  }))
  default = {}
}

variable "create_sqs_policy" {
  description = "Whether to create SQS queue policies for SQS notifications"
  type        = bool
  default     = true
}

variable "create_sns_policy" {
  description = "Whether to create SNS topic policies for SNS notifications"
  type        = bool
  default     = true
}

# --------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------
locals {
  bucket_arn = var.bucket_arn != null ? var.bucket_arn : "arn:aws:s3:::${var.bucket_name}"

  any_notifications = length(var.lambda_notifications) + length(var.sqs_notifications) + length(var.sns_notifications) > 0
}

# --------------------------------------------------------------------------
# Random ID for unique bucket name when none provided
# --------------------------------------------------------------------------
resource "random_id" "suffix" {
  count = var.create ? 1 : 0

  byte_length = 4
}

# --------------------------------------------------------------------------
# KMS key for S3 bucket encryption (customer-managed)
# --------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.create ? 1 : 0

  description             = "KMS key for S3 bucket notification encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# --------------------------------------------------------------------------
# S3 bucket (always created when var.create is true)
# --------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count = var.create ? 1 : 0

  bucket = var.bucket_name != "" ? var.bucket_name : "tf-notification-bucket-${random_id.suffix[0].hex}"

  force_destroy = true
}

# --------------------------------------------------------------------------
# S3 bucket public access block (strictest settings)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --------------------------------------------------------------------------
# S3 bucket server-side encryption configuration (SSE-KMS)
# --------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# --------------------------------------------------------------------------
# S3 bucket notification
# --------------------------------------------------------------------------
resource "aws_s3_bucket_notification" "this" {
  count = var.create && local.any_notifications ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "lambda_function" {
    for_each = var.lambda_notifications
    content {
      lambda_function_arn = lambda_function.value.target_arn
      events              = lambda_function.value.events
      filter_prefix       = lambda_function.value.filter_prefix
      filter_suffix       = lambda_function.value.filter_suffix
    }
  }

  dynamic "queue" {
    for_each = var.sqs_notifications
    content {
      queue_arn     = queue.value.target_arn
      events        = queue.value.events
      filter_prefix = queue.value.filter_prefix
      filter_suffix = queue.value.filter_suffix
    }
  }

  dynamic "topic" {
    for_each = var.sns_notifications
    content {
      topic_arn     = topic.value.target_arn
      events        = topic.value.events
      filter_prefix = topic.value.filter_prefix
      filter_suffix = topic.value.filter_suffix
    }
  }

  lifecycle {
    precondition {
      condition     = var.create ? length(aws_s3_bucket.this) > 0 : true
      error_message = "Bucket resource must be created when create is true."
    }
  }
}

# --------------------------------------------------------------------------
# Lambda permissions (one per Lambda notification)
# --------------------------------------------------------------------------
resource "aws_lambda_permission" "lambda_notification" {
  for_each = var.create ? var.lambda_notifications : {}

  statement_id  = "AllowLambdaS3BucketNotification-${each.key}"
  action        = "lambda:InvokeFunction"
  function_name = each.value.function_name
  qualifier     = each.value.qualifier
  principal     = "s3.amazonaws.com"
  source_arn    = local.bucket_arn
}

# --------------------------------------------------------------------------
# SQS queue policies (one per SQS notification, conditionally created)
# --------------------------------------------------------------------------
resource "aws_sqs_queue_policy" "sqs_notification" {
  for_each = var.create && var.create_sqs_policy ? var.sqs_notifications : {}

  queue_url = each.value.queue_id != null ? each.value.queue_id : (
    "https://sqs.${data.aws_region.current.name}.amazonaws.com/${data.aws_caller_identity.current.account_id}/${element(split(":", each.value.target_arn), length(split(":", each.value.target_arn)) - 1)}"
  )

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketNotification-${each.key}"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "sqs:SendMessage"
        Resource = each.value.target_arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = local.bucket_arn
          }
        }
      }
    ]
  })
}

# --------------------------------------------------------------------------
# SNS topic policies (one per SNS notification, conditionally created)
# --------------------------------------------------------------------------
resource "aws_sns_topic_policy" "sns_notification" {
  for_each = var.create && var.create_sns_policy ? var.sns_notifications : {}

  arn = each.value.target_arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketNotification-${each.key}"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = each.value.target_arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = local.bucket_arn
          }
        }
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "number_of_azs" {
  default = 2
}

variable "enable_public_subnets" {
  default = false
}

variable "enable_nat_subnets" {
  default = false
}

variable "enable_private_subnets" {
  default = false
}

locals {
  default_tags = {
    Environment = "dev"
    Project     = "myproject"
  }

  enabled_tiers_count = sum([
    var.enable_public_subnets ? 1 : 0,
    var.enable_nat_subnets ? 1 : 0,
    var.enable_private_subnets ? 1 : 0
  ])

  total_subnets = var.number_of_azs * local.enabled_tiers_count

  newbits = local.total_subnets > 0 ? ceil(log(local.total_subnets) / log(2)) : 0

  vpc_id = aws_vpc.main.id

  public_subnet_cidrs = var.enable_public_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 0 * var.number_of_azs + az_idx)
  ] : []

  nat_subnet_cidrs = var.enable_nat_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 1 * var.number_of_azs + az_idx)
  ] : []

  private_subnet_cidrs = var.enable_private_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 2 * var.number_of_azs + az_idx)
  ] : []
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.default_tags, {
    Name = "main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "main-igw"
  })
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "public-sg"
  description = "Security group for public tier"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.default_tags, {
    Name = "public-sg"
  })
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "public-rt"
  })
}

resource "aws_route" "public_internet" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route" "public_local" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = aws_vpc.main.cidr_block
  gateway_id             = "local"
}

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.default_tags, {
    Name = "public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.number_of_azs : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.nat_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "nat-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "private-subnet-${count.index + 1}"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "project" {
  description = "Project name used for tagging"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name used for tagging"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_name" {
  description = "Name of the EC2 key pair"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "EC2 instance type for the bastion host"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Enable EBS optimization for the bastion instance"
  type        = bool
  default     = false
}

variable "bastion_allowed_cidr" {
  description = "CIDR block allowed to SSH into the bastion host"
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------
locals {
  base_tags = {
    Project     = var.project
    Environment = var.environment
  }
  all_tags = merge(local.base_tags, var.tags)
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.all_tags, {
    Name = var.vpc_name
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# INTERNET GATEWAY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_internet_gateway" "demo" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.all_tags, {
    Name = "demogwInternet"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo.id
  }

  tags = merge(local.all_tags, {
    Name = "demoPublicRouteTable"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC SUBNETS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(["10.0.0.0/24", "10.0.2.0/24"], count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.all_tags, {
    Name = "demo-public-subnet-${count.index}"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIVATE SUBNETS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.all_tags, {
    Name = "demo-private-subnet-${count.index}"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# ROUTE TABLE ASSOCIATIONS (PUBLIC SUBNETS)
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------------------------------------------------
# BASTION SECURITY GROUP
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_security_group" "bastion" {
  name        = "bastion-sg"
  description = "Security group for bastion host allowing SSH from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.bastion_allowed_cidr]
  }

  # No explicit egress rule – AWS default egress (all traffic) is used.
  tags = merge(local.all_tags, {
    Name = "bastion-sg"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# TLS PRIVATE KEY & AWS KEY PAIR
# ---------------------------------------------------------------------------------------------------------------------
resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_name
  public_key = tls_private_key.bastion.public_key_openssh

  tags = merge(local.all_tags, {
    Name = var.key_name
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# BASTION EC2 INSTANCE
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.amazon_linux2.id
  instance_type               = var.bastion_instance_type
  ebs_optimized               = var.ebs_optimized
  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  key_name                    = aws_key_pair.bastion.key_name
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.all_tags, {
    Name = "bastion-host"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --------------------------------------------------------------------------
# VPC Networking Module – Dynamically Calculated Subnet Tiers
# --------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "number_of_availability_zones" {
  description = "Number of Availability Zones to use"
  type        = number
  default     = 2
}

variable "enable_public_subnets" {
  description = "Enable public subnet tier"
  type        = bool
  default     = false
}

variable "enable_nat_subnets" {
  description = "Enable NAT subnet tier"
  type        = bool
  default     = false
}

variable "enable_private_subnets" {
  description = "Enable private subnet tier"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# --------------------------------------------------------------------------
# Data sources – static provider metadata only
# --------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# --------------------------------------------------------------------------
# Local values – calculated variables
# --------------------------------------------------------------------------
locals {
  # Total number of subnets across all enabled tiers and AZs
  total_subnet_count = (
    (var.enable_public_subnets ? 1 : 0) +
    (var.enable_nat_subnets ? 1 : 0) +
    (var.enable_private_subnets ? 1 : 0)
  ) * var.number_of_availability_zones

  # Number of additional bits to allocate the full set of subnets
  newbits = ceil(log(max(local.total_subnet_count, 1), 2))

  # Bits for per‑AZ subnets (computed, not used in this design)
  vpc_cidr_newbits = ceil(log(var.number_of_availability_zones, 2))

  # Starting indices for each subnet tier (sequential offset blocks)
  public_start  = 0
  nat_start     = var.enable_public_subnets ? var.number_of_availability_zones : 0
  private_start = (var.enable_public_subnets ? var.number_of_availability_zones : 0) + (var.enable_nat_subnets ? var.number_of_availability_zones : 0)

  # Base tags merged with per‑resource tags
  base_tags = merge(var.tags, {
    Environment = try(var.tags["Environment"], "default")
  })
}

# --------------------------------------------------------------------------
# VPC resource
# --------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = merge(local.base_tags, {
    Name = "main-vpc"
  })
}

# --------------------------------------------------------------------------
# Public subnet tier (conditional)
# --------------------------------------------------------------------------
resource "aws_security_group" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id
  name   = "public-sg"

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.base_tags, {
    Name = "public-sg"
  })
}

resource "aws_internet_gateway" "main" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id
  tags = merge(local.base_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.number_of_availability_zones : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.public_start + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.base_tags, {
    Name = "public-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  # The default local route for the VPC CIDR is implicitly created by AWS.
  tags = merge(local.base_tags, {
    Name = "public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.number_of_availability_zones : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# --------------------------------------------------------------------------
# NAT subnet tier (conditional)
# --------------------------------------------------------------------------
resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.number_of_availability_zones : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, local.nat_start + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.base_tags, {
    Name = "nat-${data.aws_availability_zones.available.names[count.index]}"
  })
}

# --------------------------------------------------------------------------
# Private subnet tier (conditional)
# --------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.number_of_availability_zones : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, local.private_start + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.base_tags, {
    Name = "private-${data.aws_availability_zones.available.names[count.index]}"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables for password policy
variable "allow_users_to_change_password" {
  description = "Whether to allow users to change their own password"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Number of days that an user password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length to require for user passwords"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that users are prevented from reusing"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether to require lowercase characters for user passwords"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether to require uppercase characters for user passwords"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether to require numbers for user passwords"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether to require symbols for user passwords"
  type        = bool
  default     = true
}

# Account password policy
resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# IAM Groups
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

# IAM Policies
data "aws_iam_policy_document" "developpers_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "rds:*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }
  }
}

resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Allow full EC2 and RDS actions on resources tagged env=dev"
  policy      = data.aws_iam_policy_document.developpers_policy.json
}

data "aws_iam_policy_document" "prod_users_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:*",
      "rds:*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["preprod", "prod"]
    }
  }
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Allow full EC2 and RDS actions on resources tagged env=preprod or env=prod"
  policy      = data.aws_iam_policy_document.prod_users_policy.json
}

data "aws_iam_policy_document" "administrators_policy" {
  statement {
    effect    = "Allow"
    not_actions = [
      "iam:*",
      "organizations:*",
      "account:*"
    ]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad access excluding security-sensitive actions and resources with security=high tag"
  policy      = data.aws_iam_policy_document.administrators_policy.json
}

# Attach policies to groups
resource "aws_iam_group_policy_attachment" "administrators" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

terraform {
  required_version = "~> 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    action      = string
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      action      = "allow"
      protocol    = "-1"
      from_port   = 0
      to_port     = 0
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    action      = string
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      action      = "allow"
      protocol    = "-1"
      from_port   = 0
      to_port     = 0
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name_prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no   = ingress.value.rule_number
      action    = ingress.value.action
      protocol  = ingress.value.protocol
      from_port = ingress.value.from_port
      to_port   = ingress.value.to_port
      cidr_block = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no   = egress.value.rule_number
      action    = egress.value.action
      protocol  = egress.value.protocol
      from_port = egress.value.from_port
      to_port   = egress.value.to_port
      cidr_block = egress.value.cidr_block
    }
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Namespace for the null-label context"
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment for the null-label context"
}

variable "stage" {
  type        = string
  default     = ""
  description = "Stage for the null-label context"
}

variable "name" {
  type        = string
  default     = "vpc"
  description = "Name for the null-label context"
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter for the null-label context"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes for the null-label context"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to all resources"
}

variable "vpc_cidr_block" {
  type        = string
  default     = "11.0.0.0/16"
  description = "Primary IPv4 CIDR block for the VPC. Ignored when `vpc_ipv4_ipam_pool_id` is set."
}

variable "vpc_instance_tenancy" {
  type        = string
  default     = "default"
  description = "Instance tenancy for the VPC"
}

variable "enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "Enable DNS hostnames in the VPC"
}

variable "enable_dns_support" {
  type        = bool
  default     = true
  description = "Enable DNS support in the VPC"
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  default     = true
  description = "Assign an Amazon-provided IPv6 /56 CIDR block to the VPC. Ignored when `vpc_ipv6_ipam_pool_id` is set."
}

variable "vpc_ipv4_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID for the primary IPv4 CIDR allocation"
}

variable "vpc_ipv4_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length for the primary IPv4 CIDR allocation when using IPAM"
}

variable "vpc_ipv6_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID for the primary IPv6 CIDR allocation"
}

variable "vpc_ipv6_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length for the primary IPv6 CIDR allocation when using IPAM"
}

variable "additional_ipv4_cidr_block_associations" {
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default     = {}
  description = "Map of additional IPv4 CIDR block associations for the VPC"
}

variable "additional_ipv6_cidr_block_associations" {
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default     = {}
  description = "Map of additional IPv6 CIDR block associations for the VPC"
}

variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = "Manage the default security group and remove all ingress/egress rules"
}

variable "manage_default_route_table" {
  type        = bool
  default     = false
  description = "Manage the default route table for the VPC"
}

variable "manage_default_network_acl" {
  type        = bool
  default     = false
  description = "Manage the default network ACL for the VPC"
}

variable "internet_gateway_enabled" {
  type        = bool
  default     = true
  description = "Create an internet gateway for the VPC"
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  default     = false
  description = "Create an IPv6 egress-only internet gateway for the VPC"
}

locals {
  label = join(
    var.delimiter,
    compact([
      var.namespace,
      var.environment,
      var.stage,
      var.name,
      join(var.delimiter, var.attributes)
    ])
  )

  label_tags = {
    Name = local.label
  }

  namespace_tags = var.namespace != "" ? { Namespace = var.namespace } : {}
  environment_tags = var.environment != "" ? { Environment = var.environment } : {}
  stage_tags = var.stage != "" ? { Stage = var.stage } : {}

  tags = merge(
    var.tags,
    local.label_tags,
    local.namespace_tags,
    local.environment_tags,
    local.stage_tags
  )
}

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_ipv4_ipam_pool_id == null ? var.vpc_cidr_block : null
  instance_tenancy                 = var.vpc_instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.vpc_ipv6_ipam_pool_id == null ? var.assign_generated_ipv6_cidr_block : null
  ipv4_ipam_pool_id                = var.vpc_ipv4_ipam_pool_id
  ipv4_netmask_length              = var.vpc_ipv4_netmask_length
  ipv6_ipam_pool_id                = var.vpc_ipv6_ipam_pool_id
  ipv6_netmask_length              = var.vpc_ipv6_netmask_length

  tags = local.tags
}

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = var.additional_ipv4_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  cidr_block          = each.value.ipv4_ipam_pool_id == null ? each.value.cidr_block : null
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.cidr_block != null ? null : each.value.ipv4_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each = var.additional_ipv6_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  ipv6_cidr_block     = each.value.ipv6_ipam_pool_id == null ? each.value.ipv6_cidr_block : null
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_cidr_block != null ? null : each.value.ipv6_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

resource "aws_default_security_group" "this" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id  = aws_vpc.this.id
  ingress = []
  egress  = []

  tags = local.tags
}

resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id

  tags = local.tags
}

resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = local.tags
}

resource "aws_internet_gateway" "this" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = local.tags
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = local.tags
}

# ------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER CONFIGURATION
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.5, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "name" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name (e.g. STAGE, PROD)"
  type        = string
  default     = "STAGE"
}

# Enable flags
variable "enable_lambda_function" {
  description = "Enable Lambda function creation"
  type        = bool
  default     = true
}

variable "enable_lambda_alias" {
  description = "Enable Lambda alias creation"
  type        = bool
  default     = false
}

variable "enable_lambda_event_source_mapping" {
  description = "Enable Lambda event source mapping"
  type        = bool
  default     = false
}

variable "enable_lambda_function_event_invoke_config" {
  description = "Enable Lambda function event invoke config"
  type        = bool
  default     = false
}

variable "enable_lambda_layer_version" {
  description = "Enable Lambda layer version creation"
  type        = bool
  default     = false
}

variable "enable_lambda_permission" {
  description = "Enable Lambda permission creation"
  type        = bool
  default     = false
}

variable "enable_lambda_provisioned_concurrency_config" {
  description = "Enable Lambda provisioned concurrency config"
  type        = bool
  default     = false
}

variable "enable_code_signing_config" {
  description = "Enable Lambda code signing config"
  type        = bool
  default     = false
}

# Lambda function variables
variable "lambda_function_handler" {
  description = "Lambda function handler (e.g. index.handler)"
  type        = string
  default     = "index.handler"
}

variable "lambda_function_runtime" {
  description = "Lambda function runtime"
  type        = string
  default     = "python3.12"
}

variable "lambda_function_memory_size" {
  description = "Lambda function memory size in MB"
  type        = number
  default     = 128
}

variable "lambda_function_timeout" {
  description = "Lambda function timeout in seconds"
  type        = number
  default     = 3
}

variable "lambda_function_reserved_concurrent_executions" {
  description = "Reserved concurrent executions (-1 for no limit)"
  type        = number
  default     = -1
}

variable "lambda_function_publish" {
  description = "Publish Lambda function as a new version"
  type        = bool
  default     = false
}

variable "lambda_function_filename" {
  description = "Local path to the deployment package zip file"
  type        = string
  default     = null
}

variable "lambda_function_s3_bucket" {
  description = "S3 bucket containing the deployment package"
  type        = string
  default     = null
}

variable "lambda_function_s3_key" {
  description = "S3 key of the deployment package"
  type        = string
  default     = null
}

variable "lambda_function_s3_object_version" {
  description = "S3 object version of the deployment package"
  type        = string
  default     = null
}

variable "lambda_function_dead_letter_config_target_arn" {
  description = "ARN of an SQS queue or SNS topic for dead letter config"
  type        = string
  default     = null
}

variable "lambda_function_tracing_mode" {
  description = "X-Ray tracing mode (Active or PassThrough)"
  type        = string
  default     = "PassThrough"
}

variable "lambda_function_vpc_subnet_ids" {
  description = "List of subnet IDs for Lambda VPC config"
  type        = list(string)
  default     = []
}

variable "lambda_function_vpc_security_group_ids" {
  description = "List of security group IDs for Lambda VPC config"
  type        = list(string)
  default     = []
}

variable "lambda_function_environment_variables" {
  description = "Environment variables for the Lambda function"
  type        = map(string)
  default     = {}
}

variable "lambda_function_kms_key_arn" {
  description = "KMS key ARN for encryption (if null, a new key is created)"
  type        = string
  default     = null
}

variable "lambda_function_tags" {
  description = "Additional tags for the Lambda function"
  type        = map(string)
  default     = {}
}

# Lambda layer variables
variable "lambda_layer_layer_name" {
  description = "Name of the Lambda layer (default constructed)"
  type        = string
  default     = null
}

variable "lambda_layer_filename" {
  description = "Local path to the layer zip file"
  type        = string
  default     = null
}

variable "lambda_layer_s3_bucket" {
  description = "S3 bucket containing the layer zip"
  type        = string
  default     = null
}

variable "lambda_layer_s3_key" {
  description = "S3 key of the layer zip"
  type        = string
  default     = null
}

variable "lambda_layer_s3_object_version" {
  description = "S3 object version of the layer zip"
  type        = string
  default     = null
}

variable "lambda_layer_compatible_runtimes" {
  description = "List of runtimes compatible with the layer"
  type        = list(string)
  default     = []
}

variable "lambda_layer_license_info" {
  description = "License information for the layer"
  type        = string
  default     = null
}

variable "lambda_layer_description" {
  description = "Description of the layer"
  type        = string
  default     = null
}

# Lambda alias variables
variable "lambda_alias_name" {
  description = "Name of the Lambda alias (default constructed)"
  type        = string
  default     = null
}

variable "lambda_alias_function_version" {
  description = "Function version for the alias"
  type        = string
  default     = "$LATEST"
}

variable "lambda_alias_routing_config_additional_version_weights" {
  description = "Map of additional version weights for routing"
  type        = map(number)
  default     = {}
}

# Event invoke config variables
variable "lambda_event_invoke_config_function_name" {
  description = "Function name for event invoke config (default uses function resource)"
  type        = string
  default     = null
}

variable "lambda_event_invoke_config_qualifier" {
  description = "Qualifier for event invoke config (default uses alias or $LATEST)"
  type        = string
  default     = null
}

variable "lambda_event_invoke_config_maximum_retry_attempts" {
  description = "Maximum retry attempts for async invocation"
  type        = number
  default     = 2
}

variable "lambda_event_invoke_config_maximum_event_age_in_seconds" {
  description = "Maximum event age in seconds"
  type        = number
  default     = 86400
}

# Permission variables
variable "lambda_permission_action" {
  description = "Action for the Lambda permission"
  type        = string
  default     = "lambda:InvokeFunction"
}

variable "lambda_permission_principal" {
  description = "Principal for the Lambda permission"
  type        = string
  default     = "s3.amazonaws.com"
}

variable "lambda_permission_statement_id" {
  description = "Statement ID for the Lambda permission"
  type        = string
  default     = "AllowExecutionFromS3"
}

variable "lambda_permission_source_arn" {
  description = "Source ARN for the Lambda permission"
  type        = string
  default     = null
}

variable "lambda_permission_source_account" {
  description = "Source account ID for the Lambda permission"
  type        = string
  default     = null
}

# Provisioned concurrency variables
variable "lambda_provisioned_concurrency_config_function_name" {
  description = "Function name for provisioned concurrency (default uses function resource)"
  type        = string
  default     = null
}

variable "lambda_provisioned_concurrency_config_qualifier" {
  description = "Qualifier for provisioned concurrency (default uses alias name)"
  type        = string
  default     = null
}

variable "lambda_provisioned_concurrency_config_provisioned_concurrent_executions" {
  description = "Number of provisioned concurrent executions"
  type        = number
  default     = 1
}

# Event source mapping variables
variable "lambda_event_source_mapping_event_source_arn" {
  description = "ARN of the event source (e.g. DynamoDB stream, Kinesis stream)"
  type        = string
  default     = ""
}

variable "lambda_event_source_mapping_function_name" {
  description = "Function name for event source mapping (default uses function resource)"
  type        = string
  default     = null
}

variable "lambda_event_source_mapping_enabled" {
  description = "Whether the event source mapping is enabled"
  type        = bool
  default     = true
}

variable "lambda_event_source_mapping_batch_size" {
  description = "Batch size for the event source mapping"
  type        = number
  default     = 100
}

variable "lambda_event_source_mapping_parallelization_factor" {
  description = "Parallelization factor for the event source mapping"
  type        = number
  default     = 1
}

variable "lambda_event_source_mapping_maximum_retry_attempts" {
  description = "Maximum retry attempts for the event source mapping"
  type        = number
  default     = 10000
}

variable "lambda_event_source_mapping_maximum_record_age_in_seconds" {
  description = "Maximum record age in seconds"
  type        = number
  default     = 604800
}

variable "lambda_event_source_mapping_bisect_batch_on_function_error" {
  description = "Whether to bisect batch on function error"
  type        = bool
  default     = false
}

variable "lambda_event_source_mapping_starting_position" {
  description = "Starting position for stream event sources (TRIM_HORIZON, LATEST, AT_TIMESTAMP)"
  type        = string
  default     = "TRIM_HORIZON"
}

# Code signing config variables
variable "code_signing_config_signing_policy" {
  description = "Signing policy (Enforce or Warn)"
  type        = string
  default     = "Enforce"
}

variable "code_signing_config_description" {
  description = "Description of the code signing config"
  type        = string
  default     = "Code signing configuration for Lambda"
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  name_lower      = lower(var.name)
  env_lower       = lower(var.environment)
  common_tags = {
    Name        = "${local.name_lower}-${local.env_lower}"
    Environment = var.environment
    ManagedBy   = "Terraform"
  }

  # Lambda function defaults
  lambda_function_name = "${local.name_lower}-lambda-${local.env_lower}"

  # Lambda layer default name
  lambda_layer_default_name = "${local.name_lower}-lambda-layer-ver-${local.env_lower}"

  # Lambda alias default name
  lambda_alias_default_name = "${local.name_lower}-lambda-alias-${local.env_lower}"

  # VPC CIDR block
  vpc_cidr = "10.0.0.0/16"

  # Determine the deployment source for the Lambda function
  # Use explicit filename, S3 bucket, or fall back to generated archive
  use_generated_archive = var.lambda_function_filename == null && var.lambda_function_s3_bucket == null
}

# ------------------------------------------------------------------------------
# PLACEHOLDER LAMBDA DEPLOYMENT PACKAGE (only if needed)
# ------------------------------------------------------------------------------
resource "local_file" "lambda_placeholder" {
  count    = var.enable_lambda_function && local.use_generated_archive ? 1 : 0
  content  = "def handler(event, context):\n    return {'statusCode': 200}\n"
  filename = "${path.module}/placeholder.py"
}

data "archive_file" "lambda_zip" {
  count       = var.enable_lambda_function && local.use_generated_archive ? 1 : 0
  type        = "zip"
  source_file = local_file.lambda_placeholder[0].filename
  output_path = "${path.module}/placeholder.zip"
  depends_on  = [local_file.lambda_placeholder]
}

# ------------------------------------------------------------------------------
# VPC AND NETWORKING (only if Lambda function enabled)
# ------------------------------------------------------------------------------
resource "aws_vpc" "lambda_vpc" {
  count                = var.enable_lambda_function ? 1 : 0
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${local.name_lower}-lambda-vpc-${local.env_lower}"
  })
}

resource "aws_subnet" "lambda_private" {
  count                   = var.enable_lambda_function ? length(data.aws_availability_zones.available.names) : 0
  vpc_id                  = aws_vpc.lambda_vpc[0].id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "${local.name_lower}-lambda-subnet-${local.env_lower}-${count.index + 1}"
  })
}

resource "aws_security_group" "lambda_sg" {
  count       = var.enable_lambda_function ? 1 : 0
  name        = "${local.name_lower}-lambda-sg-${local.env_lower}"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.lambda_vpc[0].id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_lower}-lambda-sg-${local.env_lower}"
  })
}

# ------------------------------------------------------------------------------
# IAM ROLE FOR LAMBDA FUNCTION
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lambda_execution_role" {
  count = var.enable_lambda_function ? 1 : 0
  name  = "${local.name_lower}-lambda-role-${local.env_lower}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count      = var.enable_lambda_function ? 1 : 0
  role       = aws_iam_role.lambda_execution_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_execution" {
  count      = var.enable_lambda_function && length(var.lambda_function_vpc_subnet_ids) > 0 ? 1 : 0
  role       = aws_iam_role.lambda_execution_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

# ------------------------------------------------------------------------------
# KMS KEY FOR LAMBDA FUNCTION (if no custom key provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "lambda_key" {
  count                   = var.enable_lambda_function && var.lambda_function_kms_key_arn == null ? 1 : 0
  description             = "KMS key for Lambda function ${local.lambda_function_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags = local.common_tags
}

resource "aws_kms_alias" "lambda_key_alias" {
  count         = var.enable_lambda_function && var.lambda_function_kms_key_arn == null ? 1 : 0
  name          = "alias/${local.name_lower}-lambda-key-${local.env_lower}"
  target_key_id = aws_kms_key.lambda_key[0].key_id
}

# ------------------------------------------------------------------------------
# LAMBDA FUNCTION
# ------------------------------------------------------------------------------
resource "aws_lambda_function" "this" {
  count = var.enable_lambda_function ? 1 : 0

  function_name = local.lambda_function_name
  handler       = var.lambda_function_handler
  runtime       = var.lambda_function_runtime
  memory_size   = var.lambda_function_memory_size
  timeout       = var.lambda_function_timeout
  publish       = var.lambda_function_publish

  reserved_concurrent_executions = var.lambda_function_reserved_concurrent_executions

  role = aws_iam_role.lambda_execution_role[0].arn

  # Source code: use explicit filename, S3 bucket, or generated archive
  filename         = var.lambda_function_filename != null ? var.lambda_function_filename : (local.use_generated_archive ? data.archive_file.lambda_zip[0].output_path : null)
  s3_bucket        = var.lambda_function_s3_bucket
  s3_key           = var.lambda_function_s3_key
  s3_object_version = var.lambda_function_s3_object_version

  dynamic "dead_letter_config" {
    for_each = var.lambda_function_dead_letter_config_target_arn != null ? [1] : []
    content {
      target_arn = var.lambda_function_dead_letter_config_target_arn
    }
  }

  tracing_config {
    mode = var.lambda_function_tracing_mode
  }

  dynamic "vpc_config" {
    for_each = length(var.lambda_function_vpc_subnet_ids) > 0 ? [1] : []
    content {
      subnet_ids         = var.lambda_function_vpc_subnet_ids
      security_group_ids = var.lambda_function_vpc_security_group_ids
    }
  }

  environment {
    variables = var.lambda_function_environment_variables
  }

  kms_key_arn = var.lambda_function_kms_key_arn != null ? var.lambda_function_kms_key_arn : (
    var.enable_lambda_function ? aws_kms_key.lambda_key[0].arn : null
  )

  tags = merge(local.common_tags, var.lambda_function_tags)
}

# ------------------------------------------------------------------------------
# LAMBDA LAYER VERSION
# ------------------------------------------------------------------------------
resource "aws_lambda_layer_version" "this" {
  count = var.enable_lambda_layer_version ? 1 : 0

  layer_name = var.lambda_layer_layer_name != null ? var.lambda_layer_layer_name : local.lambda_layer_default_name

  filename         = var.lambda_layer_filename
  s3_bucket        = var.lambda_layer_s3_bucket
  s3_key           = var.lambda_layer_s3_key
  s3_object_version = var.lambda_layer_s3_object_version

  compatible_runtimes = var.lambda_layer_compatible_runtimes
  license_info        = var.lambda_layer_license_info
  description         = var.lambda_layer_description
}

# ------------------------------------------------------------------------------
# LAMBDA ALIAS
# ------------------------------------------------------------------------------
resource "aws_lambda_alias" "this" {
  count = var.enable_lambda_alias && var.enable_lambda_function ? 1 : 0

  name         = var.lambda_alias_name != null ? var.lambda_alias_name : local.lambda_alias_default_name
  function_name = aws_lambda_function.this[0].arn
  function_version = var.lambda_alias_function_version

  dynamic "routing_config" {
    for_each = length(var.lambda_alias_routing_config_additional_version_weights) > 0 ? [1] : []
    content {
      additional_version_weights = var.lambda_alias_routing_config_additional_version_weights
    }
  }

  lifecycle {
    ignore_changes = [
      routing_config
    ]
  }
}

# ------------------------------------------------------------------------------
# LAMBDA FUNCTION EVENT INVOKE CONFIG
# ------------------------------------------------------------------------------
locals {
  event_invoke_function_name = var.lambda_event_invoke_config_function_name != null ? var.lambda_event_invoke_config_function_name : (
    var.enable_lambda_function ? aws_lambda_function.this[0].function_name : null
  )
  event_invoke_qualifier = var.lambda_event_invoke_config_qualifier != null ? var.lambda_event_invoke_config_qualifier : (
    var.enable_lambda_alias && var.enable_lambda_function ? aws_lambda_alias.this[0].name : "$LATEST"
  )
}

resource "aws_lambda_function_event_invoke_config" "this" {
  count = var.enable_lambda_function_event_invoke_config && var.enable_lambda_function ? 1 : 0

  function_name = local.event_invoke_function_name
  qualifier     = local.event_invoke_qualifier

  maximum_retry_attempts        = var.lambda_event_invoke_config_maximum_retry_attempts
  maximum_event_age_in_seconds = var.lambda_event_invoke_config_maximum_event_age_in_seconds
}

# ------------------------------------------------------------------------------
# LAMBDA PERMISSION
# ------------------------------------------------------------------------------
resource "aws_lambda_permission" "this" {
  count = var.enable_lambda_permission && var.enable_lambda_function ? 1 : 0

  function_name = aws_lambda_function.this[0].function_name
  action        = var.lambda_permission_action
  principal     = var.lambda_permission_principal
  statement_id  = var.lambda_permission_statement_id
  source_arn    = var.lambda_permission_source_arn
  source_account = var.lambda_permission_source_account
}

# ------------------------------------------------------------------------------
# LAMBDA PROVISIONED CONCURRENCY CONFIG
# ------------------------------------------------------------------------------
locals {
  provisioned_concurrency_function_name = var.lambda_provisioned_concurrency_config_function_name != null ? var.lambda_provisioned_concurrency_config_function_name : (
    var.enable_lambda_function ? aws_lambda_function.this[0].function_name : null
  )
  provisioned_concurrency_qualifier = var.lambda_provisioned_concurrency_config_qualifier != null ? var.lambda_provisioned_concurrency_config_qualifier : (
    var.enable_lambda_alias ? aws_lambda_alias.this[0].name : "$LATEST"
  )
}

resource "aws_lambda_provisioned_concurrency_config" "this" {
  count = var.enable_lambda_provisioned_concurrency_config && var.enable_lambda_function ? 1 : 0

  function_name = local.provisioned_concurrency_function_name
  qualifier     = local.provisioned_concurrency_qualifier

  provisioned_concurrent_executions = var.lambda_provisioned_concurrency_config_provisioned_concurrent_executions
}

# ------------------------------------------------------------------------------
# LAMBDA EVENT SOURCE MAPPING
# ------------------------------------------------------------------------------
locals {
  event_source_mapping_function_name = var.lambda_event_source_mapping_function_name != null ? var.lambda_event_source_mapping_function_name : (
    var.enable_lambda_function ? aws_lambda_function.this[0].function_name : null
  )
}

resource "aws_lambda_event_source_mapping" "this" {
  count = var.enable_lambda_event_source_mapping && var.enable_lambda_function ? 1 : 0

  event_source_arn = var.lambda_event_source_mapping_event_source_arn

  function_name = local.event_source_mapping_function_name

  enabled                       = var.lambda_event_source_mapping_enabled
  batch_size                    = var.lambda_event_source_mapping_batch_size
  parallelization_factor        = var.lambda_event_source_mapping_parallelization_factor
  maximum_retry_attempts        = var.lambda_event_source_mapping_maximum_retry_attempts
  maximum_record_age_in_seconds = var.lambda_event_source_mapping_maximum_record_age_in_seconds
  bisect_batch_on_function_error = var.lambda_event_source_mapping_bisect_batch_on_function_error
  starting_position             = var.lambda_event_source_mapping_starting_position
}

# ------------------------------------------------------------------------------
# CODE SIGNING CONFIG (with Signer profile)
# ------------------------------------------------------------------------------
resource "aws_signer_signing_profile" "this" {
  count = var.enable_code_signing_config ? 1 : 0
  name  = "${local.name_lower}-signer-profile-${local.env_lower}"
  platform_id = "AWSLambda-SHA384-ECDSA"
  tags = local.common_tags
}

resource "aws_lambda_code_signing_config" "this" {
  count = var.enable_code_signing_config ? 1 : 0

  description = var.code_signing_config_description

  allowed_publishers {
    signing_profile_version_arns = [aws_signer_signing_profile.this[0].version_arn]
  }

  policies {
    untrusted_artifact_on_deployment = var.code_signing_config_signing_policy
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_map" {
  description = "Map of VPC configurations"
  type = map(object({
    cidr_block            = string
    enable_dns            = optional(bool, true)
    enable_dns_hostnames  = optional(bool, false)
  }))
  default = {
    main = {
      cidr_block = "10.0.0.0/16"
    }
  }
}

variable "default_tags" {
  description = "Default tags to apply to all resources"
  type        = map(string)
  default = {
    environment = "Dev"
    managedBy   = "Terraform"
  }
}

variable "subnet_map" {
  description = "Map of subnet configurations"
  type = map(object({
    vpc_name          = string
    cidr_block        = string
    availability_zone = string
  }))
  default = {}
}

variable "igw_map" {
  description = "Map of VPC names that require an Internet Gateway"
  type        = map(string)
  default     = {}
}

variable "ngw_map" {
  description = "Map of NAT Gateway configurations"
  type = map(object({
    subnet_key = string
    vpc_key    = string
  }))
  default = {}
}

variable "route_table_map" {
  description = "Map of route table configurations"
  type = map(object({
    vpc_key = string
    use_igw = optional(bool, true)
    use_ngw = optional(bool, false)
  }))
  default = {}
}

variable "route_table_association_map" {
  description = "Map of subnet keys to route table keys"
  type        = map(string)
  default     = {}
}

variable "security_group_map" {
  description = "Map of security group configurations"
  type = map(object({
    vpc_key     = string
    description = string
    ingress_rules = list(object({
      cidr_blocks               = optional(list(string))
      source_security_group_key = optional(string)
    }))
    egress_rules = list(object({
      cidr_blocks               = optional(list(string))
      source_security_group_key = optional(string)
    }))
  }))
  default = {}
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Locals
locals {
  region = data.aws_region.current.name

  # Map VPC key to list of NAT gateway keys (assumes one per VPC for simplicity)
  ngw_keys_by_vpc = {
    for k, v in var.ngw_map : v.vpc_key => k...
  }

  # Flattened ingress rules for security groups
  sg_ingress_rules = flatten([
    for sg_key, sg in var.security_group_map : [
      for idx, rule in sg.ingress_rules : {
        key                        = "${sg_key}-ingress-${idx}"
        sg_key                     = sg_key
        cidr_blocks                = rule.cidr_blocks
        source_security_group_key  = rule.source_security_group_key
      }
    ]
  ])

  sg_egress_rules = flatten([
    for sg_key, sg in var.security_group_map : [
      for idx, rule in sg.egress_rules : {
        key                        = "${sg_key}-egress-${idx}"
        sg_key                     = sg_key
        cidr_blocks                = rule.cidr_blocks
        source_security_group_key  = rule.source_security_group_key
      }
    ]
  ])
}

# VPCs
resource "aws_vpc" "this" {
  for_each = var.vpc_map

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns
  enable_dns_hostnames = each.value.enable_dns_hostnames

  tags = merge(var.default_tags, {
    Name = each.key
  })
}

# Subnets
resource "aws_subnet" "this" {
  for_each = var.subnet_map

  vpc_id            = aws_vpc.this[each.value.vpc_name].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = merge(var.default_tags, {
    Name = "sn-${each.key}-${each.value.availability_zone}-${local.region}"
  })

  lifecycle {
    precondition {
      condition     = contains(data.aws_availability_zones.available.names, each.value.availability_zone)
      error_message = "Availability zone ${each.value.availability_zone} is not available in region ${local.region}."
    }
  }
}

# Internet Gateways
resource "aws_internet_gateway" "this" {
  for_each = var.igw_map

  vpc_id = aws_vpc.this[each.key].id

  tags = merge(var.default_tags, {
    Name = each.key
  })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "this" {
  for_each = var.ngw_map

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = each.key
  })
}

# NAT Gateways
resource "aws_nat_gateway" "this" {
  for_each = var.ngw_map

  allocation_id = aws_eip.this[each.key].id
  subnet_id     = aws_subnet.this[each.value.subnet_key].id

  tags = merge(var.default_tags, {
    Name = each.key
  })

  depends_on = [aws_internet_gateway.this]
}

# Route Tables
resource "aws_route_table" "this" {
  for_each = var.route_table_map

  vpc_id = aws_vpc.this[each.value.vpc_key].id

  tags = merge(var.default_tags, {
    Name = each.key
  })
}

# Routes to Internet Gateway
resource "aws_route" "igw" {
  for_each = {
    for rt_key, rt in var.route_table_map : rt_key => rt
    if rt.use_igw
  }

  route_table_id         = aws_route_table.this[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.value.vpc_key].id
}

# Routes to NAT Gateway (use first NAT gateway in the VPC)
resource "aws_route" "ngw" {
  for_each = {
    for rt_key, rt in var.route_table_map : rt_key => rt
    if rt.use_ngw && length(local.ngw_keys_by_vpc[rt.vpc_key]) > 0
  }

  route_table_id         = aws_route_table.this[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[local.ngw_keys_by_vpc[each.value.vpc_key][0]].id
}

# Route Table Associations
resource "aws_route_table_association" "this" {
  for_each = var.route_table_association_map

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.this[each.value].id
}

# Security Groups
resource "aws_security_group" "this" {
  for_each = var.security_group_map

  vpc_id      = aws_vpc.this[each.value.vpc_key].id
  description = each.value.description

  tags = merge(var.default_tags, {
    Name = each.key
  })
}

# Ingress rules for security groups
resource "aws_security_group_rule" "ingress" {
  for_each = {
    for rule in local.sg_ingress_rules : rule.key => rule
  }

  type      = "ingress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"

  security_group_id = aws_security_group.this[each.value.sg_key].id

  cidr_blocks = each.value.cidr_blocks

  source_security_group_id = each.value.source_security_group_key != null ? aws_security_group.this[each.value.source_security_group_key].id : null
}

# Egress rules for security groups
resource "aws_security_group_rule" "egress" {
  for_each = {
    for rule in local.sg_egress_rules : rule.key => rule
  }

  type      = "egress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"

  security_group_id = aws_security_group.this[each.value.sg_key].id

  cidr_blocks = each.value.cidr_blocks

  source_security_group_id = each.value.source_security_group_key != null ? aws_security_group.this[each.value.source_security_group_key].id : null
}

# Default Security Groups (allow all self ingress and all egress within VPC CIDR)
resource "aws_default_security_group" "this" {
  for_each = var.vpc_map

  vpc_id = aws_vpc.this[each.key].id

  ingress {
    description = "Self ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "VPC internal egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.this[each.key].cidr_block]
  }

  tags = merge(var.default_tags, {
    Name = "${each.key}-default"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "name" {
  description = "Base name for the Lambda function. If null or empty, a random pet name is generated."
  type        = string
  default     = null
}

variable "lambda" {
  description = "Configuration map for the Lambda function. Must not be null. If empty, no Lambda function is created."
  type        = map(any)
  default = {
    handler           = "lambda_function.lambda_handler"
    runtime           = "python3.8"
    memory_size       = 128
    timeout           = 3
    reserved_concurrent_executions = -1
    publish           = false
  }

  validation {
    condition     = var.lambda != null
    error_message = "The lambda variable must not be null."
  }
}

variable "layers" {
  description = "Configuration map for a Lambda layer. Must not be null. If empty, no layer is created."
  type        = map(any)
  default     = {}

  validation {
    condition     = var.layers != null
    error_message = "The layers variable must not be null."
  }
}

variable "policy_arns" {
  description = "List of IAM policy ARNs to attach to the Lambda execution role."
  type        = list(string)
  default     = []
}

variable "log_group_namespace" {
  description = "Namespace for the CloudWatch log group."
  type        = string
  default     = "/aws/lambda"
}

variable "log_retention" {
  description = "Retention in days for the CloudWatch log group."
  type        = number
  default     = 7
}

resource "random_pet" "this" {
  count  = var.name == null || var.name == "" ? 1 : 0
  length = 2
}

data "archive_file" "lambda" {
  type        = "zip"
  output_path = "${path.module}/lambda_function_payload.zip"
  source {
    content  = <<EOF
def lambda_handler(event, context):
    return {"statusCode": 200, "body": "Hello from Lambda"}
EOF
    filename = "lambda_function.py"
  }
}

locals {
  function_name = var.name != null && var.name != "" ? var.name : random_pet.this[0].id

  create_lambda = length(var.lambda) > 0
  create_layer  = length(var.layers) > 0
}

# IAM Role for Lambda execution
resource "aws_iam_role" "lambda" {
  count = local.create_lambda ? 1 : 0
  name  = "${local.function_name}-lambda"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })

  tags = {
    "terraform.io" = "managed"
  }
}

# Attach managed policies
resource "aws_iam_role_policy_attachment" "basic_execution" {
  count      = local.create_lambda ? 1 : 0
  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy_attachment" "vpc_access" {
  count      = local.create_lambda ? 1 : 0
  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_iam_role_policy_attachment" "efs_client" {
  count      = local.create_lambda ? 1 : 0
  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

resource "aws_iam_role_policy_attachment" "xray" {
  count      = local.create_lambda ? 1 : 0
  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:aws:iam::aws:policy/AWSXrayWriteOnlyAccess"
}

# Attach custom policy ARNs
resource "aws_iam_role_policy_attachment" "custom" {
  for_each = local.create_lambda ? toset(var.policy_arns) : toset([])
  role     = aws_iam_role.lambda[0].name
  policy_arn = each.value
}

# IAM policy for CloudWatch logs
resource "aws_iam_policy" "logs" {
  count = local.create_lambda ? 1 : 0
  name  = "${local.function_name}-lambda-logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Effect = "Allow"
      Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${var.log_group_namespace}/${local.function_name}:*"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "logs" {
  count      = local.create_lambda ? 1 : 0
  role       = aws_iam_role.lambda[0].name
  policy_arn = aws_iam_policy.logs[0].arn
}

# CloudWatch log group
resource "aws_cloudwatch_log_group" "lambda" {
  count = local.create_lambda ? 1 : 0
  name  = "${var.log_group_namespace}/${local.function_name}"
  retention_in_days = var.log_retention

  tags = {
    "terraform.io" = "managed"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Lambda function
resource "aws_lambda_function" "this" {
  count = local.create_lambda ? 1 : 0
  function_name = local.function_name
  role          = aws_iam_role.lambda[0].arn

  package_type = "Zip"
  handler      = try(var.lambda.handler, "lambda_function.lambda_handler")
  runtime      = try(var.lambda.runtime, "python3.8")

  memory_size   = try(var.lambda.memory_size, 128)
  timeout       = try(var.lambda.timeout, 3)
  reserved_concurrent_executions = try(var.lambda.reserved_concurrent_executions, -1)
  publish       = try(var.lambda.publish, false)

  # Source code: either from local file or S3
  filename         = try(var.lambda.filename, data.archive_file.lambda.output_path)
  source_code_hash = try(var.lambda.source_code_hash, data.archive_file.lambda.output_base64sha256)

  s3_bucket         = try(var.lambda.s3_bucket, null)
  s3_key            = try(var.lambda.s3_key, null)
  s3_object_version = try(var.lambda.s3_object_version, null)

  # Environment variables
  dynamic "environment" {
    for_each = try(var.lambda.environment, null) != null ? [var.lambda.environment] : []
    content {
      variables = environment.value
    }
  }

  # X-Ray tracing
  tracing_config {
    mode = try(var.lambda.tracing_mode, "PassThrough")
  }

  # VPC configuration
  dynamic "vpc_config" {
    for_each = can(var.lambda.subnet_ids) && can(var.lambda.security_group_ids) ? [1] : []
    content {
      subnet_ids         = var.lambda.subnet_ids
      security_group_ids = var.lambda.security_group_ids
    }
  }

  # EFS mount configuration
  dynamic "file_system_config" {
    for_each = try(var.lambda.efs_mounts, null) != null ? var.lambda.efs_mounts : []
    content {
      arn              = file_system_config.value.arn
      local_mount_path = try(file_system_config.value.local_mount_path, "/mnt")
    }
  }

  # Layer attachment (if layer created)
  layers = local.create_layer ? [aws_lambda_layer_version.this["this"].arn] : []

  tags = {
    "terraform.io" = "managed"
  }

  depends_on = [
    aws_cloudwatch_log_group.lambda,
    aws_iam_role_policy_attachment.logs
  ]
}

# Lambda layer version
resource "aws_lambda_layer_version" "this" {
  for_each = local.create_layer ? { "this" = var.layers } : {}

  layer_name = try(each.value.layer_name, "${local.function_name}-layer")
  description = try(each.value.description, null)

  compatible_runtimes = try(each.value.compatible_runtimes, ["python3.8"])
  skip_destroy        = try(each.value.skip_destroy, false)

  filename         = try(each.value.filename, null)
  source_code_hash = try(each.value.source_code_hash, null)

  s3_bucket         = try(each.value.s3_bucket, null)
  s3_key            = try(each.value.s3_key, null)
  s3_object_version = try(each.value.s3_object_version, null)
}

# Lambda aliases
resource "aws_lambda_alias" "this" {
  for_each = local.create_lambda && can(var.lambda.aliases) ? var.lambda.aliases : {}

  name             = each.key
  function_name    = aws_lambda_function.this[0].function_name
  function_version = try(each.value.function_version, "$LATEST")
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# TERRAFORM & PROVIDER CONFIGURATION
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "name_prefix" {
  description = "Prefix used for naming all resources"
  type        = string
  default     = "monitoring"
}

variable "tags" {
  description = "Map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "enabled_basic" {
  description = "Create a basic CPUUtilization metric alarm"
  type        = bool
  default     = true
}

variable "enabled_dynamic" {
  description = "Create metric alarms from a dynamic map"
  type        = bool
  default     = false
}

variable "dynamic_alarms" {
  description = "Map of alarm configurations for dynamic alarms"
  type = map(object({
    metric_name        = string
    namespace          = string
    dimensions         = optional(map(string), {})
    threshold          = number
    evaluation_periods = number
    period             = number
    statistic          = optional(string, "Average")
    comparison_operator = optional(string, "GreaterThanOrEqualToThreshold")
    treat_missing_data = optional(string, "missing")
  }))
  default = {}
}

variable "create_metric_alarm_expression" {
  description = "Create metric query expression alarms"
  type        = bool
  default     = false
}

variable "expression_alarms" {
  description = "Map of expression alarm configurations"
  type = map(object({
    threshold_metric_id = optional(string)
    evaluation_periods  = number
    treat_missing_data  = optional(string, "missing")
    comparison_operator = optional(string, "GreaterThanOrEqualToThreshold")
    metric_queries = list(object({
      id          = string
      expression  = optional(string)
      label       = optional(string)
      return_data = optional(bool, true)
      period      = optional(number)
      metric = optional(object({
        metric_name = string
        namespace   = string
        period      = number
        stat        = string
        unit        = optional(string)
        dimensions  = optional(map(string))
      }))
    }))
  }))
  default = {}
}

variable "create_composite_alarm" {
  description = "Create a composite alarm"
  type        = bool
  default     = false
}

variable "create_dashboard" {
  description = "Create a CloudWatch dashboard"
  type        = bool
  default     = false
}

variable "create_log_group" {
  description = "Create a CloudWatch log group and stream"
  type        = bool
  default     = false
}

variable "log_group_retention_days" {
  description = "Retention period in days for the log group"
  type        = number
  default     = 7
}

variable "create_syn_canary" {
  description = "Create a CloudWatch Synthetics canary"
  type        = bool
  default     = false
}

variable "syn_canary_name" {
  description = "Name of the canary"
  type        = string
  default     = "my-canary"
}

variable "syn_canary_bucket_name" {
  description = "Name of the S3 bucket for canary artifacts. If empty, a unique name is generated."
  type        = string
  default     = ""
}

variable "syn_canary_runtime_version" {
  description = "Synthetics runtime version"
  type        = string
  default     = "syn-nodejs-puppeteer-3.9"
}

variable "syn_canary_schedule_expression" {
  description = "Schedule expression for canary (e.g., rate(1 minute))"
  type        = string
  default     = "rate(1 minute)"
}

variable "syn_canary_handler" {
  description = "Handler for the canary script"
  type        = string
  default     = "index.handler"
}

variable "syn_canary_zip_file" {
  description = "Path to the canary script zip file"
  type        = string
  default     = "canary-script.zip"
}

variable "syn_canary_success_retention_days" {
  description = "Success retention period in days"
  type        = number
  default     = 3
}

variable "syn_canary_failure_retention_days" {
  description = "Failure retention period in days"
  type        = number
  default     = 14
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  common_tags = merge(var.tags, { terraform = "true" })

  # Collect alarm names from enabled resources
  basic_alarm_name = var.enabled_basic ? [aws_cloudwatch_metric_alarm.basic[0].alarm_name] : []
  dynamic_alarm_names = var.enabled_dynamic ? [for a in aws_cloudwatch_metric_alarm.dynamic : a.alarm_name] : []
  expression_alarm_names = var.create_metric_alarm_expression ? [for a in aws_cloudwatch_metric_alarm.expression : a.alarm_name] : []
  all_metric_alarm_names = concat(local.basic_alarm_name, local.dynamic_alarm_names, local.expression_alarm_names)

  # Composite alarm rule: OR of all metric alarms
  composite_alarm_rule = length(local.all_metric_alarm_names) > 0 ? join(" OR ", [for name in local.all_metric_alarm_names : "ALARM(\"${name}\")"]) : null

  # Canary bucket name: use variable if provided, otherwise generate a unique name.
  # Guard the random_id reference so it's only evaluated when the canary is enabled.
  canary_bucket_name = var.syn_canary_bucket_name != "" ? var.syn_canary_bucket_name : (var.create_syn_canary ? "${var.name_prefix}-canary-${random_id.canary_bucket_suffix[0].hex}" : null)
}

# ------------------------------------------------------------------------------
# RANDOM SUFFIX FOR CANARY BUCKET (if canary is enabled)
# ------------------------------------------------------------------------------

resource "random_id" "canary_bucket_suffix" {
  count = var.create_syn_canary ? 1 : 0

  byte_length = 8
}

# ------------------------------------------------------------------------------
# BASIC METRIC ALARM (if enabled)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "basic" {
  count = var.enabled_basic ? 1 : 0

  alarm_name          = "${var.name_prefix}-basic-cpu"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 60
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 40
  treat_missing_data  = "missing"

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-basic-cpu" })
}

# ------------------------------------------------------------------------------
# DYNAMIC METRIC ALARMS (if enabled and map not empty)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "dynamic" {
  for_each = var.enabled_dynamic ? var.dynamic_alarms : {}

  alarm_name          = "${var.name_prefix}-${each.key}"
  comparison_operator = each.value.comparison_operator
  evaluation_periods  = each.value.evaluation_periods
  metric_name         = each.value.metric_name
  namespace           = each.value.namespace
  period              = each.value.period
  statistic           = each.value.statistic
  threshold           = each.value.threshold
  treat_missing_data  = each.value.treat_missing_data
  dimensions          = each.value.dimensions

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })
}

# ------------------------------------------------------------------------------
# METRIC QUERY EXPRESSION ALARMS (if enabled)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "expression" {
  for_each = var.create_metric_alarm_expression ? var.expression_alarms : {}

  alarm_name          = "${var.name_prefix}-${each.key}"
  comparison_operator = each.value.comparison_operator
  evaluation_periods  = each.value.evaluation_periods
  treat_missing_data  = each.value.treat_missing_data
  threshold_metric_id = each.value.threshold_metric_id

  dynamic "metric_query" {
    for_each = each.value.metric_queries
    content {
      id          = metric_query.value.id
      expression  = metric_query.value.expression
      label       = metric_query.value.label
      return_data = metric_query.value.return_data
      period      = metric_query.value.period

      dynamic "metric" {
        for_each = metric_query.value.metric != null ? [metric_query.value.metric] : []
        content {
          metric_name = metric.value.metric_name
          namespace   = metric.value.namespace
          period      = metric.value.period
          stat        = metric.value.stat
          unit        = metric.value.unit
          dimensions  = metric.value.dimensions
        }
      }
    }
  }

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-${each.key}" })
}

# ------------------------------------------------------------------------------
# COMPOSITE ALARM (if enabled)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_composite_alarm" "this" {
  count = var.create_composite_alarm ? 1 : 0

  alarm_name        = "${var.name_prefix}-comp"
  alarm_description = "Composite alarm for ${var.name_prefix} monitors"
  alarm_rule        = local.composite_alarm_rule

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-comp" })
}

# ------------------------------------------------------------------------------
# CLOUDWATCH DASHBOARD (if enabled)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_dashboard" "this" {
  count = var.create_dashboard ? 1 : 0

  dashboard_name = "${var.name_prefix}-dashboard"

  dashboard_body = jsonencode({
    widgets = [
      {
        type = "metric"
        properties = {
          metrics = [
            ["AWS/EC2", "CPUUtilization", { stat = "Average" }]
          ]
          period = 300
          stat   = "Average"
          region = "us-east-1"
          title  = "EC2 CPU Utilization"
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP AND STREAM (if enabled)
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "this" {
  count = var.create_log_group ? 1 : 0

  name              = "/aws/${var.name_prefix}"
  retention_in_days = var.log_group_retention_days

  tags = merge(local.common_tags, { Name = "/aws/${var.name_prefix}" })
}

resource "aws_cloudwatch_log_stream" "this" {
  count = var.create_log_group ? 1 : 0

  name           = "${var.name_prefix}-stream"
  log_group_name = aws_cloudwatch_log_group.this[0].name
}

# ------------------------------------------------------------------------------
# SYNTHETICS CANARY (if enabled)
# ------------------------------------------------------------------------------

# S3 bucket for canary artifacts
resource "aws_s3_bucket" "canary" {
  count = var.create_syn_canary ? 1 : 0

  bucket = local.canary_bucket_name

  tags = merge(local.common_tags, { Name = local.canary_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "canary" {
  count = var.create_syn_canary ? 1 : 0

  bucket = aws_s3_bucket.canary[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary" {
  count = var.create_syn_canary ? 1 : 0

  bucket = aws_s3_bucket.canary[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "canary" {
  count = var.create_syn_canary ? 1 : 0

  bucket = aws_s3_bucket.canary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for canary
resource "aws_iam_role" "canary" {
  count = var.create_syn_canary ? 1 : 0

  name = "${var.name_prefix}-canary-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-canary-role" })
}

# IAM policy for canary (least privilege)
resource "aws_iam_policy" "canary" {
  count = var.create_syn_canary ? 1 : 0

  name = "${var.name_prefix}-canary-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3PutObject"
        Effect = "Allow"
        Action = "s3:PutObject"
        Resource = "arn:aws:s3:::${local.canary_bucket_name}/canary/${var.syn_canary_name}/*"
      },
      {
        Sid    = "AllowS3GetBucketLocation"
        Effect = "Allow"
        Action = "s3:GetBucketLocation"
        Resource = "arn:aws:s3:::${local.canary_bucket_name}"
      },
      {
        Sid    = "AllowCloudWatchPutMetricData"
        Effect = "Allow"
        Action = "cloudwatch:PutMetricData"
        Resource = "*"
      },
      {
        Sid    = "AllowLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary" {
  count = var.create_syn_canary ? 1 : 0

  role       = aws_iam_role.canary[0].name
  policy_arn = aws_iam_policy.canary[0].arn
}

# 60-second delay before canary creation
resource "time_sleep" "canary_delay" {
  count = var.create_syn_canary ? 1 : 0

  create_duration = "60s"
}

# Canary resource
resource "aws_synthetics_canary" "this" {
  count = var.create_syn_canary ? 1 : 0

  name                 = var.syn_canary_name
  runtime_version      = var.syn_canary_runtime_version
  handler              = var.syn_canary_handler
  zip_file             = var.syn_canary_zip_file
  artifact_s3_location = "s3://${local.canary_bucket_name}/canary/${var.syn_canary_name}"
  start_canary         = true
  success_retention_period = var.syn_canary_success_retention_days
  failure_retention_period = var.syn_canary_failure_retention_days

  schedule {
    expression = var.syn_canary_schedule_expression
  }

  execution_role_arn = aws_iam_role.canary[0].arn

  depends_on = [time_sleep.canary_delay[0]]

  tags = merge(local.common_tags, { Name = var.syn_canary_name })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  type    = string
  default = "DEV"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "create_private_subnet" {
  type    = bool
  default = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-public-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = var.create_private_subnet ? 2 : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.10.0/24" : "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-private-subnet-${count.index}"
  }
}

resource "aws_eip" "nat" {
  count = var.create_private_subnet ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.environment_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count = var.create_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.environment_prefix}-nat-gw"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = var.create_private_subnet ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${var.environment_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnet ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the primary SQS queue and all dependent resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue. If not provided, name_prefix will be used. For FIFO queues, '.fifo' is automatically appended."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the queue name. Used when name is not provided. For FIFO queues, '.fifo' is automatically appended."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the primary queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = true
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values: 'messageGroup' and 'queue'."
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values: 'perQueue' and 'perMessageGroupId'."
  type        = string
  default     = "perQueue"
}

variable "sqs_managed_sse_enabled" {
  description = "Whether to use SQS-managed server-side encryption. If true, no KMS key is used."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a custom KMS master key to use for encryption. If provided, sqs_managed_sse_enabled is automatically set to false."
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create an IAM policy attached to the queue."
  type        = bool
  default     = false
}

variable "queue_policy_source" {
  description = "Optional JSON string of an IAM policy document to use as the source (base) policy."
  type        = string
  default     = null
}

variable "queue_policy_override" {
  description = "Optional JSON string of an IAM policy document to override the source policy."
  type        = string
  default     = null
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue for the primary queue."
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to restrict the dead-letter queue's redrive permission to the primary queue."
  type        = bool
  default     = true
}

variable "max_receive_count" {
  description = "The maximum number of times a message can be received before being sent to the dead-letter queue."
  type        = number
  default     = 5
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Ensure that at least one of name or name_prefix is provided
  # (We do not validate here, but provider will enforce if both null)
  queue_name = var.name != null ? var.name : var.name_prefix != null ? var.name_prefix : "default-queue"

  # For FIFO queues, append .fifo suffix if not already present
  primary_queue_name = var.fifo_queue ? (
    endswith(local.queue_name, ".fifo") ? local.queue_name : "${local.queue_name}.fifo"
  ) : local.queue_name

  dlq_name = var.fifo_queue ? (
    endswith("${local.queue_name}-dlq", ".fifo") ? "${local.queue_name}-dlq" : "${local.queue_name}-dlq.fifo"
  ) : "${local.queue_name}-dlq"

  # Determine encryption settings for primary queue
  use_sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
  use_kms_key         = var.kms_master_key_id != null

  # Construct the primary queue ARN using data sources (no resource dependency)
  primary_queue_arn = "arn:aws:sqs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${local.primary_queue_name}"

  # Redrive allow policy JSON for DLQ (only when create_dlq_redrive_allow_policy is true)
  dlq_redrive_allow_policy = var.create_dlq_redrive_allow_policy ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:SendMessage"
        Resource  = local.primary_queue_arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = local.primary_queue_arn
          }
        }
      }
    ]
  }) : null
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIMARY QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "primary" {
  count = var.create ? 1 : 0

  name   = var.name != null ? local.primary_queue_name : null
  name_prefix = var.name == null ? local.primary_queue_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope        = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit      = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms_key ? var.kms_master_key_id : null

  # Redrive policy: point to DLQ if created
  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = try(aws_sqs_queue.dead_letter[0].arn, "")
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DEAD-LETTER QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "dead_letter" {
  count = var.create && var.create_dlq ? 1 : 0

  name   = var.name != null ? local.dlq_name : null
  name_prefix = var.name == null ? local.dlq_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope        = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit      = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms_key ? var.kms_master_key_id : null

  # Redrive allow policy to restrict redrive to primary queue
  redrive_allow_policy = local.dlq_redrive_allow_policy

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# QUEUE POLICY (attached to primary queue)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = var.queue_policy_source != null ? [var.queue_policy_source] : []
  override_policy_documents = var.queue_policy_override != null ? [var.queue_policy_override] : []

  # Default policy when no source or override is provided
  dynamic "statement" {
    for_each = var.queue_policy_source == null && var.queue_policy_override == null ? [1] : []
    content {
      effect    = "Allow"
      actions   = ["sqs:*"]
      resources = [aws_sqs_queue.primary[0].arn]
    }
  }
}

resource "aws_sqs_queue_policy" "primary" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.primary[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "storage_prefix" {
  type    = string
  default = "quortex"

  validation {
    condition     = length(var.storage_prefix) > 0
    error_message = "storage_prefix must not be empty."
  }
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "enable_bucket_encryption" {
  type    = bool
  default = true
}

variable "enable_user_access_key" {
  type    = bool
  default = true
}

variable "enable_irsa" {
  type    = bool
  default = false
}

variable "enable_cloudfront_oia" {
  type    = bool
  default = false
}

variable "iam_path" {
  type    = string
  default = "/system/"

  validation {
    condition     = can(regex("^/.*/$", var.iam_path))
    error_message = "iam_path must begin and end with '/'."
  }
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "buckets" {
  type = list(object({
    name                  = string
    label                 = string
    tags                  = optional(map(string))
    expiration_days       = optional(number)
    role_service_accounts = optional(list(object({
      namespace       = string
      service_account = string
    })))
  }))
  default = [
    {
      name  = "data"
      label = "data"
    }
  ]

  validation {
    condition = alltrue([
      for b in var.buckets : length(b.name) > 0 && length(b.label) > 0
    ])
    error_message = "Each bucket definition must include a non-empty name and label."
  }
}

variable "eks_oidc_issuer_url" {
  type    = string
  default = ""

  validation {
    condition     = !var.enable_irsa || length(var.eks_oidc_issuer_url) > 0
    error_message = "eks_oidc_issuer_url must be provided when enable_irsa is true."
  }
}

variable "eks_oidc_thumbprint" {
  type    = string
  default = ""

  validation {
    condition     = !var.enable_irsa || length(var.eks_oidc_thumbprint) > 0
    error_message = "eks_oidc_thumbprint must be provided when enable_irsa is true."
  }
}

data "aws_caller_identity" "current" {}

locals {
  bucket_map = {
    for b in var.buckets : b.name => b
  }

  lifecycle_buckets = {
    for b in var.buckets : b.name => b
    if b.expiration_days != null && b.expiration_days > 0
  }

  irsa_buckets = {
    for b in var.buckets : b.name => b
    if var.enable_irsa && try(length(b.role_service_accounts), 0) > 0
  }

  sanitized_label = {
    for k, b in local.bucket_map : k => replace(b.label, "/[^a-zA-Z0-9+=,.@_-]/", "-")
  }

  bucket_storage_policy_json = {
    for k, b in local.bucket_map : k => jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "S3BucketList"
          Effect   = "Allow"
          Action   = "s3:ListBucket"
          Resource = aws_s3_bucket.this[k].arn
        },
        {
          Sid      = "S3ObjectAccess"
          Effect   = "Allow"
          Action   = "s3:*Object"
          Resource = "${aws_s3_bucket.this[k].arn}/*"
        }
      ]
    })
  }
}

resource "random_id" "this" {
  for_each = local.bucket_map

  byte_length = 8
  keepers = {
    bucket_name = "${var.storage_prefix}-${each.value.name}"
  }
}

resource "random_id" "storage" {
  count = var.enable_user_access_key && length(var.buckets) > 0 ? 1 : 0

  byte_length = 8
  keepers = {
    user_name = var.storage_prefix
  }
}

resource "aws_kms_key" "s3" {
  count = var.enable_bucket_encryption ? 1 : 0

  description             = "Customer managed key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "this" {
  for_each = local.bucket_map

  bucket        = "${var.storage_prefix}-${each.value.name}-${random_id.this[each.key].hex}"
  force_destroy = var.force_destroy

  tags = merge(var.tags, each.value.tags == null ? {} : each.value.tags, {
    Name  = "${var.storage_prefix}-${each.value.name}-${random_id.this[each.key].hex}"
    label = each.value.label
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  for_each = local.bucket_map

  bucket                  = aws_s3_bucket.this[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  for_each = var.enable_bucket_encryption ? local.bucket_map : {}

  bucket = aws_s3_bucket.this[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3[0].arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  for_each = local.lifecycle_buckets

  bucket = aws_s3_bucket.this[each.key].id

  rule {
    id     = "${each.value.label}-expiration"
    status = "Enabled"

    filter {
      prefix = each.value.label
    }

    expiration {
      days = each.value.expiration_days
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  for_each = local.bucket_map

  bucket = aws_s3_bucket.this[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_user" "storage" {
  count = var.enable_user_access_key && length(var.buckets) > 0 ? 1 : 0

  name          = "${var.storage_prefix}-storage-${random_id.storage[0].hex}"
  path          = var.iam_path
  force_destroy = var.force_destroy
}

resource "aws_iam_access_key" "storage" {
  count = var.enable_user_access_key && length(var.buckets) > 0 ? 1 : 0

  user = aws_iam_user.storage[0].name
}

resource "aws_secretsmanager_secret" "storage_credentials" {
  count = var.enable_user_access_key && length(var.buckets) > 0 ? 1 : 0

  name        = "${var.storage_prefix}-storage-credentials-${random_id.storage[0].hex}"
  description = "S3 storage access key for IAM user ${aws_iam_user.storage[0].name}"
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "storage_credentials" {
  count = var.enable_user_access_key && length(var.buckets) > 0 ? 1 : 0

  secret_id = aws_secretsmanager_secret.storage_credentials[0].id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.storage[0].id
    secret_access_key = aws_iam_access_key.storage[0].secret
  })
}

resource "aws_iam_user_policy" "storage" {
  for_each = var.enable_user_access_key && length(var.buckets) > 0 ? local.bucket_map : {}

  name   = "${var.storage_prefix}-${local.sanitized_label[each.key]}-user-policy"
  user   = aws_iam_user.storage[0].name
  policy = local.bucket_storage_policy_json[each.key]
}

resource "aws_iam_openid_connect_provider" "eks" {
  count = var.enable_irsa ? 1 : 0

  url             = var.eks_oidc_issuer_url
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [var.eks_oidc_thumbprint]
}

resource "aws_iam_role" "irsa" {
  for_each = local.irsa_buckets

  name        = "${var.storage_prefix}-${each.value.name}-irsa"
  path        = var.iam_path
  description = "IRSA role for S3 bucket ${var.storage_prefix}-${each.value.name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.eks[0].arn
        }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "oidc:aud" = "sts.amazonaws.com"
          },
          "ForAnyValue:StringLike" = {
            "oidc:sub" = [
              for rsa in each.value.role_service_accounts :
              "system:serviceaccount:${rsa.namespace}:${rsa.service_account}"
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "irsa" {
  for_each = local.irsa_buckets

  name        = "${var.storage_prefix}-${local.sanitized_label[each.key]}-irsa-policy"
  path        = var.iam_path
  description = "Policy for IRSA role ${var.storage_prefix}-${each.value.name}-irsa"
  policy      = local.bucket_storage_policy_json[each.key]
}

resource "aws_iam_role_policy_attachment" "irsa" {
  for_each = local.irsa_buckets

  role       = aws_iam_role.irsa[each.key].name
  policy_arn = aws_iam_policy.irsa[each.key].arn
}

resource "aws_cloudfront_origin_access_identity" "main" {
  for_each = var.enable_cloudfront_oia ? local.bucket_map : {}

  comment = "OAI for ${var.storage_prefix}-${each.value.name}"
}

resource "aws_s3_bucket_policy" "cloudfront" {
  for_each = var.enable_cloudfront_oia ? local.bucket_map : {}

  bucket = aws_s3_bucket.this[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CloudFrontGetObject"
        Effect    = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.main[each.key].iam_arn
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this[each.key].arn}/*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "name_prefix" {
  type        = string
  default     = "pippi-"
  description = "Prefix for resource names, restricted to letters and hyphens"
  validation {
    condition     = can(regex("^[a-zA-Z-]+$", var.name_prefix))
    error_message = "The name_prefix must contain only letters and hyphens."
  }
}

variable "private_repos" {
  type = list(object({
    key              = string
    create_iam_user  = optional(bool, false)
    pull_account_ids = list(string)
    push_account_ids = list(string)
    pull_role_arns   = list(string)
    push_role_arns   = list(string)
  }))
  default = [
    {
      key              = "example-private"
      create_iam_user  = false
      pull_account_ids = []
      push_account_ids = []
      pull_role_arns   = []
      push_role_arns   = []
    }
  ]
  description = "List of private ECR repositories to create"
}

variable "public_repos" {
  type = list(object({
    key                     = string
    create_iam_user         = optional(bool, false)
    catalog_description     = optional(string, "")
    catalog_about_text      = optional(string, "")
    catalog_usage_text      = optional(string, "")
    catalog_architectures   = optional(list(string), [])
    catalog_operating_systems = optional(list(string), [])
    catalog_logo_image_blob = optional(string, "")
    pull_account_ids        = list(string)
    push_account_ids        = list(string)
    pull_role_arns          = list(string)
    push_role_arns          = list(string)
  }))
  default = [
    {
      key                     = "example-public"
      create_iam_user         = false
      catalog_description     = ""
      catalog_about_text      = ""
      catalog_usage_text      = ""
      catalog_architectures   = []
      catalog_operating_systems = []
      catalog_logo_image_blob = ""
      pull_account_ids        = []
      push_account_ids        = []
      pull_role_arns          = []
      push_role_arns          = []
    }
  ]
  description = "List of public ECR repositories to create"
}

locals {
  default_tags = {
    "tf-module"          = "pippi.io/aws-ecr"
    "terraform_workspace" = terraform.workspace
  }
}

# ---------------------------------------------------------------------------
# KMS Key for Private Repositories (only if private repos defined)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "private_ecr" {
  count = length(var.private_repos) > 0 ? 1 : 0

  description             = "KMS key for private ECR repositories"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Private ECR Repositories
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "private" {
  for_each = { for r in var.private_repos : r.key => r }

  name                 = "${var.name_prefix}${each.key}"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key        = try(aws_kms_key.private_ecr[0].arn, null)
  }

  tags = merge(local.default_tags, {
    Name = "${var.name_prefix}${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Private Repository Policies
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "private_repo_policy" {
  for_each = { for r in var.private_repos : r.key => r }

  statement {
    sid    = "PullPermissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = concat(
        [for a in each.value.pull_account_ids : "arn:aws:iam::${a}:root"],
        each.value.pull_role_arns,
        ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      )
    }
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
  }

  statement {
    sid    = "PushPermissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = concat(
        [for a in each.value.push_account_ids : "arn:aws:iam::${a}:root"],
        each.value.push_role_arns,
        ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      )
    }
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:PutImage",
    ]
  }
}

resource "aws_ecr_repository_policy" "private" {
  for_each = aws_ecr_repository.private

  repository = each.value.name
  policy     = data.aws_iam_policy_document.private_repo_policy[each.key].json
}

# ---------------------------------------------------------------------------
# Public ECR Repositories (with optional catalog_data)
# ---------------------------------------------------------------------------
resource "aws_ecrpublic_repository" "public" {
  for_each = { for r in var.public_repos : r.key => r }

  repository_name = "${var.name_prefix}${each.key}"

  dynamic "catalog_data" {
    for_each = (
      each.value.catalog_description != "" ||
      each.value.catalog_about_text != "" ||
      each.value.catalog_usage_text != "" ||
      length(each.value.catalog_architectures) > 0 ||
      length(each.value.catalog_operating_systems) > 0 ||
      each.value.catalog_logo_image_blob != ""
    ) ? [1] : []

    content {
      description        = each.value.catalog_description
      about_text         = each.value.catalog_about_text
      usage_text         = each.value.catalog_usage_text
      architectures      = length(each.value.catalog_architectures) > 0 ? each.value.catalog_architectures : null
      operating_systems  = length(each.value.catalog_operating_systems) > 0 ? each.value.catalog_operating_systems : null
      logo_image_blob    = each.value.catalog_logo_image_blob != "" ? each.value.catalog_logo_image_blob : null
    }
  }

  tags = merge(local.default_tags, {
    Name = "${var.name_prefix}${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Public Repository Policies
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "public_repo_policy" {
  for_each = { for r in var.public_repos : r.key => r }

  statement {
    sid    = "PullPermissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = concat(
        [for a in each.value.pull_account_ids : "arn:aws:iam::${a}:root"],
        each.value.pull_role_arns,
        ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      )
    }
    actions = [
      "ecr-public:GetAuthorizationToken",
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:BatchGetImage",
    ]
  }

  statement {
    sid    = "PushPermissions"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = concat(
        [for a in each.value.push_account_ids : "arn:aws:iam::${a}:root"],
        each.value.push_role_arns,
        ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
      )
    }
    actions = [
      "ecr-public:GetAuthorizationToken",
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:BatchGetImage",
      "ecr-public:InitiateLayerUpload",
      "ecr-public:UploadLayerPart",
      "ecr-public:CompleteLayerUpload",
      "ecr-public:PutImage",
    ]
  }
}

resource "aws_ecrpublic_repository_policy" "public" {
  for_each = aws_ecrpublic_repository.public

  repository_name = each.value.repository_name
  policy          = data.aws_iam_policy_document.public_repo_policy[each.key].json
}

# ---------------------------------------------------------------------------
# IAM Users, Access Keys, and Policies for Private Repositories
# ---------------------------------------------------------------------------
resource "aws_iam_user" "private_iam" {
  for_each = { for r in var.private_repos : r.key => r if r.create_iam_user }

  name = "${var.name_prefix}${each.key}"
  path = "/artifact/"

  tags = merge(local.default_tags, {
    Name = "${var.name_prefix}${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "private_iam" {
  for_each = aws_iam_user.private_iam

  user = each.value.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_policy" "private_iam" {
  for_each = aws_iam_user.private_iam

  name = "${var.name_prefix}${each.key}-ecr-access"
  user = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRToken"
        Effect = "Allow"
        Action = "ecr:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "ECRRepositoryActions"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage"
        ]
        Resource = aws_ecr_repository.private[each.key].arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM Users, Access Keys, and Policies for Public Repositories
# ---------------------------------------------------------------------------
resource "aws_iam_user" "public_iam" {
  for_each = { for r in var.public_repos : r.key => r if r.create_iam_user }

  name = "${var.name_prefix}${each.key}"
  path = "/artifact/"

  tags = merge(local.default_tags, {
    Name = "${var.name_prefix}${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "public_iam" {
  for_each = aws_iam_user.public_iam

  user = each.value.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_policy" "public_iam" {
  for_each = aws_iam_user.public_iam

  name = "${var.name_prefix}${each.key}-ecr-public-access"
  user = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRPublicToken"
        Effect = "Allow"
        Action = "ecr-public:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "ECRPublicRepositoryActions"
        Effect = "Allow"
        Action = [
          "ecr-public:BatchCheckLayerAvailability",
          "ecr-public:GetDownloadUrlForLayer",
          "ecr-public:BatchGetImage",
          "ecr-public:InitiateLayerUpload",
          "ecr-public:UploadLayerPart",
          "ecr-public:CompleteLayerUpload",
          "ecr-public:PutImage"
        ]
        Resource = aws_ecrpublic_repository.public[each.key].arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "private_repository_arns" {
  description = "ARNs of created private ECR repositories"
  value       = { for k, r in aws_ecr_repository.private : k => r.arn }
}

output "public_repository_arns" {
  description = "ARNs of created public ECR repositories"
  value       = { for k, r in aws_ecrpublic_repository.public : k => r.arn }
}

output "private_iam_access_keys" {
  description = "IAM access keys for private repositories (sensitive)"
  value = {
    for k, u in aws_iam_user.private_iam : k => {
      user           = u.name
      access_key_id  = aws_iam_access_key.private_iam[k].id
      secret_access_key = aws_iam_access_key.private_iam[k].secret
    }
  }
  sensitive = true
}

output "public_iam_access_keys" {
  description = "IAM access keys for public repositories (sensitive)"
  value = {
    for k, u in aws_iam_user.public_iam : k => {
      user           = u.name
      access_key_id  = aws_iam_access_key.public_iam[k].id
      secret_access_key = aws_iam_access_key.public_iam[k].secret
    }
  }
  sensitive = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  ec2_describe_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ec2:Describe*"
        Resource = "*"
      }
    ]
  })
}

# IAM Users
resource "aws_iam_user" "loadbalancer" {
  name          = "loadbalancer"
  path          = "/system/"
  force_destroy = false
}

resource "aws_iam_user" "loadbalancer2" {
