}

resource "aws_iam_user_policy" "loadbalancer_test3" {
  name   = "test3"
  user   = aws_iam_user.loadbalancer.name
  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer_test4" {
  name   = "test4"
  user   = aws_iam_user.loadbalancer.name
  policy = local.ec2_describe_policy
}

# Inline policies for loadbalancer2
resource "aws_iam_user_policy" "loadbalancer2_test2" {
  name   = "test2"
  user   = aws_iam_user.loadbalancer2.name
  policy = local.ec2_describe_policy
