resource "aws_iam_user_policy" "loadbalancer2_test22" {
  name   = "test22"
  user   = aws_iam_user.loadbalancer2.name
  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer2_test23" {
  name   = "test23"
  user   = aws_iam_user.loadbalancer2.name
  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer2_test24" {
