  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer3_test32" {
  name   = "test32"
  user   = aws_iam_user.loadbalancer3.name
  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer3_test33" {
  name   = "test33"
  user   = aws_iam_user.loadbalancer3.name
  policy = local.ec2_describe_policy
}

resource "aws_iam_user_policy" "loadbalancer3_test34" {
  name   = "test34"
  user   = aws_iam_user.loadbalancer3.name
  policy = local.ec2_describe_policy
}

# Outputs
output "loadbalancer_access_key_id" {
  value     = aws_iam_access_key.loadbalancer.id
  sensitive = true
}

output "loadbalancer_secret_access_key" {
  value     = aws_iam_access_key.loadbalancer.secret
  sensitive = true
}

output "loadbalancer2_access_key_id" {
  value     = aws_iam_access_key.loadbalancer2.id
  sensitive = true
}

output "loadbalancer2_secret_access_key" {
  value     = aws_iam_access_key.loadbalancer2.secret
  sensitive = true
}

output "loadbalancer3_access_key_id" {
  value     = aws_iam_access_key.loadbalancer3.id
  sensitive = true
}

output "loadbalancer3_secret_access_key" {
  value     = aws_iam_access_key.loadbalancer3.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "backup_name" {
  type        = string
  default     = "my-backup"
  description = "Name for the backup vault, plan, and IAM role."
  validation {
    condition     = length(var.backup_name) > 0
    error_message = "backup_name must not be empty."
  }
}

variable "account_type" {
  type        = string
  default     = "workload"
  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  type        = string
  default     = null
}

variable "vault_policy" {
  type        = string
  default     = null
}

variable "min_retention_days" {
  type        = number
  default     = null
}

variable "max_retention_days" {
  type        = number
  default     = null
}

variable "changeable_for_days" {
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  default     = null
}

variable "selection_resources" {
  type        = list(string)
  default     = []
}

variable "rule_schedule" {
  type        = string
  default     = "cron(0 5 ? * * *)"
}

variable "copy_destinations" {
  type = list(object({
    destination_region    = string
    destination_vault_arn = optional(string)
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
  }))
  default = []
}

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  sns_topic_arn     = var.sns_topic_arn
  backup_vault_events = [
    "BACKUP_JOB_FAILED",
    "COPY_JOB_FAILED",
  ]
}

data "aws_iam_policy" "aws_backup_service_role" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role" "aws_backup" {
  count = var.account_type == "workload" ? 1 : 0

  name = "aws-backup-${var.backup_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aws_backup" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.aws_backup[0].name
  policy_arn = data.aws_iam_policy.aws_backup_service_role.arn
}

resource "aws_backup_plan" "backup_plan" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = var.backup_name
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120
    recovery_point_tags = {
      Backup = "true"
    }

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.copy_destinations
      content {
        destination_vault_arn = try(
          copy_action.value.destination_vault_arn,
          "arn:aws:backup:${copy_action.value.destination_region}:${data.aws_caller_identity.current.account_id}:backup-vault:Default"
        )
        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          content {
            cold_storage_after = lifecycle.value.cold_storage_after
            delete_after       = lifecycle.value.delete_after
          }
        }
      }
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  count = var.account_type == "workload" ? 1 : 0

  iam_role_arn = aws_iam_role.aws_backup[0].arn
  plan_id      = aws_backup_plan.backup_plan[0].id
  name         = "${var.backup_name}-selection"

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }

  resources = length(var.selection_resources) > 0 ? var.selection_resources : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

variable "config_role_name" {
  type    = string
  default = null
}

locals {
  config_role_name = coalesce(var.config_role_name, random_pet.config_role_name.id)
  sns_topic_name   = "aws-config-sns-topic"

  config_rules = {
    cloudtrail_enabled = {
      name                = "cloudtrail-enabled"
      source_identifier   = "CLOUD_TRAIL_ENABLED"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = true
    }
    iam_pw_policy = {
      name                = "iam-pw-policy"
      source_identifier   = "IAM_PASSWORD_POLICY"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = true
    }
    ec2_vpc = {
      name                = "ec2-vpc"
      source_identifier   = "INSTANCES_IN_VPC"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    root_mfa_enabled = {
      name                = "root-mfa-enabled"
      source_identifier   = "ROOT_ACCOUNT_MFA_ENABLED"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = true
    }
    acm_expiration_check = {
      name                = "acm-expiration-check"
      source_identifier   = "ACM_CERTIFICATE_EXPIRATION_CHECK"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = true
    }
    ebs_inuse_check = {
      name                = "ebs-inuse-check"
      source_identifier   = "EC2_VOLUME_INUSE_CHECK"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    ec2_imdsv2_check = {
      name                = "ec2-imdsv2-check"
      source_identifier   = "EC2_IMDSV2_CHECK"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    rds_encrypted = {
      name                = "rds-encrypted"
      source_identifier   = "RDS_STORAGE_ENCRYPTED"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    rds_private = {
      name                = "rds-private"
      source_identifier   = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    rds_private_snapshots = {
      name                = "rds-private-snapshots"
      source_identifier   = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
      scope               = null
      input_parameters    = null
      scheduled_evaluation = false
    }
    required_tags = {
      name                = "required-tags"
      source_identifier   = "REQUIRED_TAGS"
      scope               = ["AWS::S3::Bucket"]
      input_parameters    = jsonencode({
        tag1Key = "terraform.io"
        tag2Key = "environment"
      })
      scheduled_evaluation = false
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "random_pet" "config_role_name" {
  length = 2
}

resource "random_pet" "bucket_suffix" {
  length = 2
}

resource "aws_kms_key" "config_s3_key" {
  description             = "KMS key for AWS Config S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "config_snapshots" {
  bucket        = "aws-config-snapshots-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_pet.bucket_suffix.id}"
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshots" {
  bucket                  = aws_s3_bucket.config_snapshots.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_s3_key.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_sns_topic" "config_sns" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.config_s3_key.arn
}

resource "aws_iam_role" "config_role" {
  name = local.config_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_role" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name   = "config-sns-publish"
  role   = aws_iam_role.config_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.config_sns.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "config_kms_policy" {
  name = "config-kms-policy"
  role = aws_iam_role.config_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.config_s3_key.arn
      }
    ]
  })
}

resource "aws_config_config_rule" "managed" {
  for_each                    = local.config_rules
  name                        = each.value.name
  maximum_execution_frequency = each.value.scheduled_evaluation ? "TwentyFour_Hours" : null
  input_parameters            = each.value.input_parameters

  source {
    owner             = "AWS"
    source_identifier = each.value.source_identifier
  }

  dynamic "scope" {
    for_each = each.value.scope == null ? [] : [each.value.scope]
    content {
      compliance_resource_types = scope.value
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0, < 6.0"
    }
  }
}

locals {
  project = "BJIT DevOps Task"
  author  = "Ariful Islam"
  common_tags = {
    Project = local.project
    Author  = local.author
  }
  public_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge({
    Name = "bjit-vpc"
  }, local.common_tags)
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge({
    Name = "bjit-public-subnet-${count.index + 1}"
  }, local.common_tags)
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge({
    Name = "bjit-private-subnet-${count.index + 1}"
  }, local.common_tags)
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge({
    Name = "bjit-igw"
  }, local.common_tags)
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge({
    Name = "bjit-public-rt"
  }, local.common_tags)
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge({
    Name = "bjit-private-rt-${count.index + 1}"
  }, local.common_tags)
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.id}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  tags = merge({
    Name = "bjit-s3-gateway-endpoint"
  }, local.common_tags)
}

resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for ALB allowing HTTP/HTTPS from internet"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
