resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "Security group for API servers allowing ports 8080 and 22 from VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
