  tags = merge({
    Name = "bjit-public-ssh-SG"
  }, local.common_tags)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "base_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  type    = list(string)
  default = null
}

locals {
  private_subnets_enabled = var.subnet_private_cidrs != null ? length(var.subnet_private_cidrs) > 0 : false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.subnet_public_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "${var.base_name}-public-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = length(var.subnet_public_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count             = local.private_subnets_enabled ? length(var.subnet_private_cidrs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "${var.base_name}-private-${count.index}"
  }
}

resource "aws_eip" "nat" {
  count  = local.private_subnets_enabled ? length(var.subnet_public_cidrs) : 0
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "nat" {
  count         = local.private_subnets_enabled ? length(var.subnet_public_cidrs) : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  depends_on    = [aws_internet_gateway.main]

  tags = {
    Name = "${var.base_name}-nat-${count.index}"
  }
}

resource "aws_route_table" "private" {
  count  = local.private_subnets_enabled ? length(var.subnet_public_cidrs) : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-private-rt-${count.index}"
  }
}

resource "aws_route" "private" {
  count                  = local.private_subnets_enabled ? length(var.subnet_public_cidrs) : 0
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = local.private_subnets_enabled ? length(var.subnet_private_cidrs) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-gateway-public"
  }
}

resource "aws_vpc_endpoint" "s3_private" {
  count             = local.private_subnets_enabled ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-gateway-private"
  }
}

resource "aws_security_group" "ecr" {
  name   = "${var.base_name}-ecr-sg"
  vpc_id = aws_vpc.main.id

  ingress {
    description = "HTTPS from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  dynamic "ingress" {
    for_each = local.private_subnets_enabled ? [1] : []
    content {
      description = "HTTPS from private subnets"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = var.subnet_private_cidrs
    }
  }

  tags = {
    Name = "${var.base_name}-ecr-sg"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "pub_sub_1_cidr" {
  description = "CIDR block for public subnet 1"
  type        = string
  default     = "10.0.1.0/24"
}

variable "pub_sub_2_cidr" {
  description = "CIDR block for public subnet 2"
  type        = string
  default     = "10.0.2.0/24"
}

variable "pvt_sub_1_cidr" {
  description = "CIDR block for private subnet 1"
  type        = string
  default     = "10.0.3.0/24"
}

variable "pvt_sub_2_cidr" {
  description = "CIDR block for private subnet 2"
  type        = string
  default     = "10.0.4.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "project-vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.project-vpc.id
  cidr_block              = var.pub_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.project-vpc.id
  cidr_block              = var.pub_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id                  = aws_vpc.project-vpc.id
  cidr_block              = var.pvt_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id                  = aws_vpc.project-vpc.id
  cidr_block              = var.pvt_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "pvt-sub-2"
  }
}

resource "aws_internet_gateway" "T-igw" {
  vpc_id = aws_vpc.project-vpc.id

  tags = {
    Name = "T-igw"
  }
}

resource "aws_route_table" "RT_PUBRT-1" {
  vpc_id = aws_vpc.project-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.T-igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table" "RT_PUBRT-2" {
  vpc_id = aws_vpc.project-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.T-igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.RT_PUBRT-1.id
}

resource "aws_route_table_association" "pub_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.RT_PUBRT-2.id
}

resource "aws_eip" "nat_eip_1" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_eip" "nat_eip_2" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "nat_gw_1" {
  allocation_id = aws_eip.nat_eip_1.id
  subnet_id     = aws_subnet.pub_sub_1.id
  connectivity_type = "public"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "nat_gw_2" {
  allocation_id = aws_eip.nat_eip_2.id
  subnet_id     = aws_subnet.pub_sub_2.id
  connectivity_type = "public"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_route_table" "RT_PVTRT-1" {
  vpc_id = aws_vpc.project-vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table" "RT_PVTRT-2" {
  vpc_id = aws_vpc.project-vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.RT_PVTRT-1.id
}

resource "aws_route_table_association" "pvt_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.RT_PVTRT-2.id
}

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public security group"
  vpc_id      = aws_vpc.project-vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_security_group" "pvt-seg" {
  name        = "pvt-seg"
  description = "Private security group"
  vpc_id      = aws_vpc.project-vpc.id

  ingress {
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ---------------------------------------------------------------------------------------------------------------------
data "aws_region" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# DYNAMODB TABLE
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name            = "PetType-index"
    hash_key        = "PetType"
    projection_type = "INCLUDE"
    non_key_attributes = [
      "PetName",
      "PetPrice"
    ]
    read_capacity  = 5
    write_capacity = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE FOR API GATEWAY TO CALL DYNAMODB
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_role" "apigw_dynamodb" {
  name = "apigw-dynamodb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name = "apigw-dynamodb-policy"
  role = aws_iam_role.apigw_dynamodb.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/PetType-index"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# API GATEWAY REST API
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "main" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
  api_key_source = "HEADER"
}

# ---------------------------------------------------------------------------------------------------------------------
# API GATEWAY RESOURCES AND METHODS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pets_pettype" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# POST /pets
resource "aws_api_gateway_method" "post_pets" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.pets.id
  http_method   = "POST"
  authorization = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method

  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "Item": {
    "id": {"S": "$context.requestId"},
    "PetType": {"S": "$input.path('$.PetType')"},
    "PetName": {"S": "$input.path('$.PetName')"},
    "PetPrice": {"N": "$input.path('$.PetPrice')"},
    "PetBoolean": {"BOOL": true}
  }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"
  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code
  response_templates = {
    "application/json" = ""
  }
}

# GET /pets/{PetType}
resource "aws_api_gateway_method" "get_pets_pettype" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.pets_pettype.id
  http_method   = "GET"
  authorization = "NONE"
  api_key_required = true
  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_pettype" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets_pettype.id
  http_method = aws_api_gateway_method.get_pets_pettype.http_method

  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "IndexName": "PetType-index",
  "KeyConditionExpression": "PetType = :v1",
  "ExpressionAttributeValues": {
    ":v1": {"S": "$util.urlDecode($input.params('PetType'))"}
  }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "get_pets_pettype_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets_pettype.id
  http_method = aws_api_gateway_method.get_pets_pettype.http_method
  status_code = "200"
  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pets_pettype" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets_pettype.id
  http_method = aws_api_gateway_method.get_pets_pettype.http_method
  status_code = aws_api_gateway_method_response.get_pets_pettype_200.status_code

  response_templates = {
    "application/json" = <<EOF
{
  "items": [
#foreach($item in $input.path('$.Items')) {
    "PetType": "$item.PetType.S",
    "PetName": "$item.PetName.S",
    "PetPrice": $item.PetPrice.N,
    "PetBoolean": $item.PetBoolean.BOOL
  }#if($foreach.hasNext),#end
#end
  ]
}
EOF
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# API GATEWAY DEPLOYMENT AND STAGE
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_api_gateway_deployment" "main" {
  depends_on = [
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pets_pettype,
    aws_api_gateway_method.post_pets,
    aws_api_gateway_method.get_pets_pettype,
    aws_api_gateway_integration_response.post_pets,
    aws_api_gateway_integration_response.get_pets_pettype
  ]

  rest_api_id = aws_api_gateway_rest_api.main.id

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "v1" {
  deployment_id = aws_api_gateway_deployment.main.id
  rest_api_id   = aws_api_gateway_rest_api.main.id
  stage_name    = "v1"
}

resource "aws_api_gateway_method_settings" "v1" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    logging_level      = "INFO"
    metrics_enabled    = true
    data_trace_enabled = false
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUDWATCH LOG GROUP FOR API GATEWAY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "apigw" {
  name              = "/aws/APIGW/terraform-apigw-dynamodb"
  retention_in_days = 14
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE FOR API GATEWAY TO WRITE CLOUDWATCH LOGS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_role" "apigw_cloudwatch" {
  name = "apigw-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_cloudwatch" {
  name = "apigw-cloudwatch-policy"
  role = aws_iam_role.apigw_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
      }
    ]
  })
}

resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUDWATCH LOG RESOURCE POLICY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name = "apigw-dynamodb-log-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "logs:PutLogEvents"
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_api_gateway_rest_api.main.execution_arn
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# API KEY, USAGE PLAN, AND USAGE PLAN KEY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_api_gateway_api_key" "main" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

resource "aws_api_gateway_usage_plan" "main" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.main.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "main" {
  key_id        = aws_api_gateway_api_key.main.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.main.id
}

variable "name" {
  type    = string
  default = "sadcloud"
}

variable "no_versioning" {
  type    = bool
  default = false
}

variable "no_default_encryption" {
  type    = bool
  default = false
}

variable "website_enabled" {
  type    = bool
  default = false
}

variable "no_logging" {
  type    = bool
  default = false
}

variable "allow_cleartext" {
  type    = bool
  default = false
}

variable "s3_getobject_only" {
  type    = bool
  default = false
}

variable "s3_public" {
  type    = bool
  default = false
}

variable "bucket_acl" {
  type    = string
  default = "log-delivery-write"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name         = var.name
  logging_bucket_name = "${var.name}-logging"
  getonly_bucket_name = "${var.name}-getonly"
  public_bucket_name  = "${var.name}-public"
}

# Primary bucket
resource "aws_s3_bucket" "main" {
  bucket_prefix = var.name
  force_destroy = true
}

# Ownership controls for primary bucket
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# Private ACL for primary bucket
resource "aws_s3_bucket_acl" "main" {
  bucket     = aws_s3_bucket.main.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.main]
}

# Versioning for primary bucket (conditional)
resource "aws_s3_bucket_versioning" "main" {
  count  = var.no_versioning ? 0 : 1
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

# KMS key for primary bucket encryption (conditional)
resource "aws_kms_key" "main" {
  count       = var.no_default_encryption ? 0 : 1
  description = "S3 bucket encryption key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

# Encryption for primary bucket using SSE-KMS (conditional)
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main[0].arn
    }
  }
}

# Website configuration for primary bucket (conditional)
resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

# Block all public access on primary bucket
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging bucket (conditional)
resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket_prefix = local.logging_bucket_name
  force_destroy = true
}

# Ownership controls for logging bucket
resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# ACL for logging bucket using the variable
resource "aws_s3_bucket_acl" "logging" {
  count      = var.no_logging ? 0 : 1
  bucket     = aws_s3_bucket.logging[0].id
  acl        = var.bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

# Block all public access on logging bucket
resource "aws_s3_bucket_public_access_block" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging configuration for primary bucket (conditional)
resource "aws_s3_bucket_logging" "main" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

# Bucket policy for cleartext denial (conditional)
resource "aws_s3_bucket_policy" "deny_cleartext" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Public read-only bucket (conditional)
resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket_prefix = local.getonly_bucket_name
  force_destroy = true
}

# Disable public access block on getonly bucket
resource "aws_s3_bucket_public_access_block" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

# Bucket policy for public read-only access
resource "aws_s3_bucket_policy" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource = [
          "${aws_s3_bucket.getonly[0].arn}/*"
        ]
      }
    ]
  })
}

# Public read-write bucket (conditional)
resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket_prefix = local.public_bucket_name
  force_destroy = true
}

# Disable public access block on public bucket
resource "aws_s3_bucket_public_access_block" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

# Bucket policy for full public read-write access
resource "aws_s3_bucket_policy" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

# --------------------------
# Service Roles (path /service-role/)
# --------------------------

resource "aws_iam_role" "agent_role" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "failback_role" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "conversion_server_role" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance_role" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "replication_server_role" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance_with_launch_actions_role" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# --------------------------
# Managed Policy Attachments (service roles)
# --------------------------

resource "aws_iam_role_policy_attachment" "agent_policy_attach" {
  role       = aws_iam_role.agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
}

resource "aws_iam_role_policy_attachment" "failback_policy_attach" {
  role       = aws_iam_role.failback_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
}

resource "aws_iam_role_policy_attachment" "conversion_server_policy_attach" {
  role       = aws_iam_role.conversion_server_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_policy_attach" {
  role       = aws_iam_role.recovery_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "replication_server_policy_attach" {
  role       = aws_iam_role.replication_server_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_policy_attach" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_ssm_attach" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# --------------------------
# Initializer Role (path /)
# --------------------------

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Policy for DRS initializer role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "drs:InitializeService"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:CreateInstanceProfile"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:AddRoleToInstanceProfile"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:ServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "ec2:*"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:AttachRolePolicy"
        Resource = "*"
        Condition = {
          StringLike = {
            "iam:PolicyARN" = "arn:aws:iam::aws:policy/service-role/AWSElasticDisasterRecovery*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "initializer_role" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initializer_policy_attach" {
  role       = aws_iam_role.initializer_role.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "prefix" {
  description = "Global prefix used in resource names"
  type        = string
  default     = "TEST"
}

variable "region" {
  description = "AWS region for all resources"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment label (e.g., STAGE, PROD)"
  type        = string
  default     = "STAGE"
}

# Feature flags
variable "enable_config_aggregate_authorization" {
  description = "Enable creation of aws_config_aggregate_authorization"
  type        = bool
  default     = false
}

variable "enable_config_config_rule" {
  description = "Enable creation of aws_config_config_rule"
  type        = bool
  default     = false
}

variable "enable_config_configuration_aggregator" {
  description = "Enable creation of aws_config_configuration_aggregator"
  type        = bool
  default     = false
}

variable "enable_config_configuration_recorder" {
  description = "Enable creation of aws_config_configuration_recorder"
  type        = bool
  default     = false
}

variable "enable_config_configuration_recorder_status" {
  description = "Enable creation of aws_config_configuration_recorder_status"
  type        = bool
  default     = false
}

variable "enable_config_delivery_channel" {
  description = "Enable creation of aws_config_delivery_channel"
  type        = bool
  default     = false
}

variable "enable_config_organization_managed_rule" {
  description = "Enable creation of aws_config_organization_managed_rule"
  type        = bool
  default     = false
}

variable "enable_config_organization_custom_rule" {
  description = "Enable creation of aws_config_organization_custom_rule"
  type        = bool
  default     = false
}

variable "enable_config_remediation_configuration" {
  description = "Enable creation of aws_config_remediation_configuration"
  type        = bool
  default     = false
}

variable "enable_organizations_organization" {
  description = "Enable organization features (required for organization rules)"
  type        = bool
  default     = false
}

# Aggregate authorization inputs
variable "aggregate_authorization_account_id" {
  description = "Account ID for aggregate authorization"
  type        = string
  default     = ""
}

variable "aggregate_authorization_region" {
  description = "Region for aggregate authorization"
  type        = string
  default     = ""
}

# Configuration aggregator inputs
variable "aggregator_account_sources" {
  description = "List of account sources for aggregator (account_id, regions)"
  type = list(object({
    account_id = string
    regions    = set(string)
  }))
  default = []
}

variable "aggregator_organization_source" {
  description = "Organization aggregation source (role_arn, all_regions)"
  type = object({
    role_arn    = string
    all_regions = optional(bool, true)
  })
  default = null
}

# Delivery channel inputs
variable "delivery_channel_s3_key_prefix" {
  description = "S3 key prefix for delivery channel"
  type        = string
  default     = ""
}

variable "delivery_channel_sns_topic_arn" {
  description = "SNS topic ARN for delivery channel (if empty, a new topic is created)"
  type        = string
  default     = ""
}

variable "delivery_channel_snapshot_delivery_properties" {
  description = "Snapshot delivery properties"
  type = object({
    delivery_frequency = string
  })
  default = null
}

# Managed rule inputs
variable "managed_rule_source_identifier" {
  description = "Source identifier for AWS managed rule"
  type        = string
  default     = "S3_BUCKET_VERSIONING_ENABLED"
}

variable "managed_rule_scope" {
  description = "Scope for the config rule"
  type = object({
    tag_key                   = optional(string)
    tag_value                 = optional(string)
    compliance_resource_id    = optional(string)
    compliance_resource_types = optional(set(string))
  })
  default = null
}

# Organization managed rule inputs
variable "organization_managed_rule_identifier" {
  description = "Rule identifier for organization managed rule"
  type        = string
  default     = "IAM_PASSWORD_POLICY"
}

variable "organization_managed_rule_excluded_accounts" {
  description = "List of excluded accounts for organization managed rule"
  type        = set(string)
  default     = []
}

# Custom rule inputs
variable "organization_custom_rule_lambda_function_arn" {
  description = "ARN of Lambda function for custom rule"
  type        = string
  default     = ""
}

variable "organization_custom_rule_trigger_types" {
  description = "Trigger types for custom rule"
  type        = set(string)
  default     = ["ConfigurationItemChangeNotification"]
}

variable "organization_custom_rule_excluded_accounts" {
  description = "Excluded accounts for custom rule"
  type        = set(string)
  default     = []
}

variable "organization_custom_rule_resource_types_scope" {
  description = "Resource types scope for custom rule"
  type        = set(string)
  default     = []
}

# Remediation inputs
variable "remediation_configuration_target_type" {
  description = "Target type for remediation (e.g., SSM_DOCUMENT)"
  type        = string
  default     = "SSM_DOCUMENT"
}

variable "remediation_configuration_target_id" {
  description = "Target ID for remediation"
  type        = string
  default     = ""
}

variable "remediation_configuration_target_rule_name" {
  description = "Name of the config rule to attach remediation (use created rule name if empty)"
  type        = string
  default     = ""
}

variable "remediation_configuration_resource_type" {
  description = "Resource type for remediation (optional)"
  type        = string
  default     = ""
}

variable "remediation_configuration_automatic" {
  description = "Automatic remediation execution"
  type        = bool
  default     = false
}

variable "remediation_configuration_maximum_automatic_attempts" {
  description = "Maximum automatic attempts"
  type        = number
  default     = 5
}

variable "remediation_configuration_parameters" {
  description = "Parameters for remediation"
  type = map(object({
    resource_value = optional(string)
    static_value   = optional(string)
  }))
  default = {}
}

variable "remediation_configuration_execution_controls" {
  description = "Execution controls (SSM rate control)"
  type = object({
    ssm_controls = optional(object({
      concurrent_execution_rate_percentage = optional(string)
      error_percentage                     = optional(string)
    }))
  })
  default = null
}

# Lambda function inputs
variable "lambda_function_source_file" {
  description = "Path to the Lambda function source file"
  type        = string
  default     = "lambda_function.py"
}

variable "lambda_function_runtime" {
  description = "Runtime for Lambda function"
  type        = string
  default     = "python3.12"
}

variable "lambda_function_handler" {
  description = "Handler for Lambda function"
  type        = string
  default     = "lambda_function.lambda_handler"
}

# ---------------------------------------------------------------------------
# Data Sources
# ---------------------------------------------------------------------------

# Archive file for Lambda deployment
data "archive_file" "lambda_zip" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  type        = "zip"
  source_file = var.lambda_function_source_file
  output_path = "${path.module}/lambda_function_payload.zip"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  name_prefix = lower(var.prefix)
  env_suffix  = lower(var.environment)

  # Default region from variable, used as fallback
  default_region = var.region

  # Resource names
  config_recorder_name          = "${local.name_prefix}-${local.env_suffix}-config-recorder"
  delivery_channel_name         = "${local.name_prefix}-${local.env_suffix}-config-delivery-channel"
  delivery_bucket_name          = "${local.name_prefix}-${local.env_suffix}-config-delivery-bucket"
  config_rule_name              = "${local.name_prefix}-${local.env_suffix}-config-rule"
  organization_managed_rule_name = "${local.name_prefix}-${local.env_suffix}-org-managed-rule"
  organization_custom_rule_name = "${local.name_prefix}-${local.env_suffix}-org-custom-rule"
  sns_topic_name                = "${local.name_prefix}-${local.env_suffix}-config-sns-topic"
  aggregator_name               = "${local.name_prefix}-${local.env_suffix}-config-aggregator"
  lambda_function_name          = "${local.name_prefix}-${local.env_suffix}-config-custom-rule-lambda"

  # Determine SNS topic ARN to use for delivery channel
  delivery_sns_topic_arn = var.enable_config_delivery_channel && var.delivery_channel_sns_topic_arn == "" ? aws_sns_topic.config[0].arn : var.delivery_channel_sns_topic_arn

  # Aggregate authorization region: use provided value or fall back to var.region
  aggregate_auth_region = var.aggregate_authorization_region != "" ? var.aggregate_authorization_region : local.default_region
}

# ---------------------------------------------------------------------------
# IAM Roles
# ---------------------------------------------------------------------------

# IAM role for AWS Config configuration recorder
resource "aws_iam_role" "config_recorder" {
  count = var.enable_config_configuration_recorder ? 1 : 0

  name = "${local.name_prefix}-${local.env_suffix}-config-recorder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_recorder_managed" {
  count = var.enable_config_configuration_recorder ? 1 : 0

  role       = aws_iam_role.config_recorder[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSConfigRole"
}

# IAM role for Lambda custom rule
resource "aws_iam_role" "lambda_custom_rule" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  name = "${local.name_prefix}-${local.env_suffix}-config-custom-rule-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_custom_rule_basic_exec" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  role       = aws_iam_role.lambda_custom_rule[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_custom_rule_config" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  name = "${local.name_prefix}-${local.env_suffix}-config-custom-rule-lambda-policy"
  role = aws_iam_role.lambda_custom_rule[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "config:PutEvaluations",
          "config:Get*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# S3 Bucket for Delivery Channel
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "config_delivery" {
  count = var.enable_config_delivery_channel ? 1 : 0

  bucket        = local.delivery_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "config_delivery" {
  count = var.enable_config_delivery_channel ? 1 : 0

  bucket = aws_s3_bucket.config_delivery[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_delivery" {
  count = var.enable_config_delivery_channel ? 1 : 0

  bucket = aws_s3_bucket.config_delivery[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "config_delivery" {
  count = var.enable_config_delivery_channel ? 1 : 0

  bucket = aws_s3_bucket.config_delivery[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SNS Topic (optional, created only if no ARN provided)
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "config" {
  count = var.enable_config_delivery_channel && var.delivery_channel_sns_topic_arn == "" ? 1 : 0

  name = local.sns_topic_name
}

resource "aws_sns_topic_policy" "config" {
  count = var.enable_config_delivery_channel && var.delivery_channel_sns_topic_arn == "" ? 1 : 0

  arn = aws_sns_topic.config[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "SNS:Publish"
        Resource = aws_sns_topic.config[0].arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# AWS Config Resources
# ---------------------------------------------------------------------------

# Aggregate Authorization
resource "aws_config_aggregate_authorization" "this" {
  count = var.enable_config_aggregate_authorization ? 1 : 0

  account_id = var.aggregate_authorization_account_id
  region     = local.aggregate_auth_region
}

# Configuration Aggregator
resource "aws_config_configuration_aggregator" "this" {
  count = var.enable_config_configuration_aggregator ? 1 : 0

  name = local.aggregator_name

  dynamic "account_aggregation_source" {
    for_each = length(var.aggregator_account_sources) > 0 ? [1] : []
    content {
      account_ids = [for src in var.aggregator_account_sources : src.account_id]
      regions     = flatten([for src in var.aggregator_account_sources : src.regions])
    }
  }

  dynamic "organization_aggregation_source" {
    for_each = var.aggregator_organization_source != null ? [1] : []
    content {
      role_arn    = var.aggregator_organization_source.role_arn
      all_regions = var.aggregator_organization_source.all_regions
    }
  }
}

# Configuration Recorder
resource "aws_config_configuration_recorder" "this" {
  count = var.enable_config_configuration_recorder ? 1 : 0

  name     = local.config_recorder_name
  role_arn = aws_iam_role.config_recorder[0].arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# Configuration Recorder Status
resource "aws_config_configuration_recorder_status" "this" {
  count = var.enable_config_configuration_recorder_status && var.enable_config_configuration_recorder ? 1 : 0

  name       = aws_config_configuration_recorder.this[0].name
  is_enabled = true
}

# Delivery Channel
resource "aws_config_delivery_channel" "this" {
  count = var.enable_config_delivery_channel ? 1 : 0

  name           = local.delivery_channel_name
  s3_bucket_name = aws_s3_bucket.config_delivery[0].id
  s3_key_prefix  = var.delivery_channel_s3_key_prefix != "" ? var.delivery_channel_s3_key_prefix : null
  sns_topic_arn  = local.delivery_sns_topic_arn != "" ? local.delivery_sns_topic_arn : null

  dynamic "snapshot_delivery_properties" {
    for_each = var.delivery_channel_snapshot_delivery_properties != null ? [1] : []
    content {
      delivery_frequency = var.delivery_channel_snapshot_delivery_properties.delivery_frequency
    }
  }
}

# Config Rule (Managed)
resource "aws_config_config_rule" "this" {
  count = var.enable_config_config_rule ? 1 : 0

  name = local.config_rule_name

  source {
    owner             = "AWS"
    source_identifier = var.managed_rule_source_identifier
  }

  dynamic "scope" {
    for_each = var.managed_rule_scope != null ? [1] : []
    content {
      tag_key                   = var.managed_rule_scope.tag_key
      tag_value                 = var.managed_rule_scope.tag_value
      compliance_resource_id    = var.managed_rule_scope.compliance_resource_id
      compliance_resource_types = var.managed_rule_scope.compliance_resource_types
    }
  }
}

# Organization Managed Rule
resource "aws_config_organization_managed_rule" "this" {
  count = var.enable_config_organization_managed_rule && var.enable_organizations_organization ? 1 : 0

  name = local.organization_managed_rule_name

  rule_identifier = var.organization_managed_rule_identifier

  excluded_accounts = length(var.organization_managed_rule_excluded_accounts) > 0 ? var.organization_managed_rule_excluded_accounts : null
}

# Organization Custom Rule
resource "aws_config_organization_custom_rule" "this" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  name = local.organization_custom_rule_name

  lambda_function_arn = var.organization_custom_rule_lambda_function_arn != "" ? var.organization_custom_rule_lambda_function_arn : aws_lambda_function.custom_rule[0].arn

  trigger_types = var.organization_custom_rule_trigger_types

  excluded_accounts    = length(var.organization_custom_rule_excluded_accounts) > 0 ? var.organization_custom_rule_excluded_accounts : null
  resource_types_scope = length(var.organization_custom_rule_resource_types_scope) > 0 ? var.organization_custom_rule_resource_types_scope : null
}

# Remediation Configuration
resource "aws_config_remediation_configuration" "this" {
  count = var.enable_config_remediation_configuration && (var.remediation_configuration_target_rule_name != "" || var.enable_config_config_rule) ? 1 : 0

  config_rule_name = var.remediation_configuration_target_rule_name != "" ? var.remediation_configuration_target_rule_name : aws_config_config_rule.this[0].name

  target_type = var.remediation_configuration_target_type
  target_id   = var.remediation_configuration_target_id

  resource_type              = var.remediation_configuration_resource_type != "" ? var.remediation_configuration_resource_type : null
  automatic                  = var.remediation_configuration_automatic
  maximum_automatic_attempts = var.remediation_configuration_maximum_automatic_attempts

  dynamic "parameter" {
    for_each = var.remediation_configuration_parameters
    content {
      name           = parameter.key
      resource_value = parameter.value.resource_value
      static_value   = parameter.value.static_value
    }
  }

  dynamic "execution_controls" {
    for_each = var.remediation_configuration_execution_controls != null ? [1] : []
    content {
      ssm_controls {
        concurrent_execution_rate_percentage = var.remediation_configuration_execution_controls.ssm_controls.concurrent_execution_rate_percentage
        error_percentage                     = var.remediation_configuration_execution_controls.ssm_controls.error_percentage
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Lambda Function for Custom Rule
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "custom_rule" {
  count = var.enable_config_organization_custom_rule ? 1 : 0

  function_name = local.lambda_function_name
  role          = aws_iam_role.lambda_custom_rule[0].arn
  handler       = var.lambda_function_handler
  runtime       = var.lambda_function_runtime
  filename      = data.archive_file.lambda_zip[0].output_path
  source_code_hash = data.archive_file.lambda_zip[0].output_base64sha256

  environment {
    variables = {
      RULE_NAME = local.organization_custom_rule_name
    }
  }
}

# ---------------------------------------------------------------------------
# Placeholder resource to guarantee at least one resource is created
# ---------------------------------------------------------------------------

resource "null_resource" "placeholder" {
  count = 1
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Security group
resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP and HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Terraform_SG_HTTP_HTTPS_SSH = "true"
  }
}

# EC2 instances
resource "aws_instance" "private_instance" {
  count         = 3
  ami           = data.aws_ami.amazon_linux2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp2"
    delete_on_termination = true
    encrypted             = true

    tags = {
      Name = "Terraform_EBS_Volume1"
    }
  }

  tags = {
    Name = "Terraform_Instance"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# =====================================================
# Variables
# =====================================================
variable "name" {
  description = "Global name prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment label (e.g., STAGE, PROD)"
  type        = string
  default     = "STAGE"
}

# ----- Flags to enable/disable components -----
variable "enable_route53_zone" {
  description = "Create a Route53 hosted zone"
  type        = bool
  default     = false
}

variable "enable_route53_record" {
  description = "Create Route53 DNS records"
  type        = bool
  default     = false
}

variable "enable_route53_health_check" {
  description = "Create Route53 health checks"
  type        = bool
  default     = false
}

variable "enable_route53_delegation_set" {
  description = "Create a reusable delegation set"
  type        = bool
  default     = false
}

variable "enable_route53_zone_association" {
  description = "Associate a VPC with a private hosted zone"
  type        = bool
  default     = false
}

variable "enable_route53_query_log" {
  description = "Enable query logging for a hosted zone"
  type        = bool
  default     = false
}

variable "enable_route53_vpc_association_authorization" {
  description = "Authorize cross-account VPC association"
  type        = bool
  default     = false
}

variable "enable_route53_key_signing_key" {
  description = "Enable DNSSEC key signing key for a hosted zone"
  type        = bool
  default     = false
}

# ----- Hosted Zone variables -----
variable "zone_domain_name" {
  description = "Domain name for the hosted zone (default: domain.localdomain)"
  type        = string
  default     = "domain.localdomain"
}

variable "zone_comment" {
  description = "Optional comment for the hosted zone"
  type        = string
  default     = ""
}

variable "zone_force_destroy" {
  description = "Force destroy all records when destroying the zone"
  type        = bool
  default     = false
}

variable "zone_delegation_set_id" {
  description = "Delegation set ID to associate with the zone (if empty, will use created delegation set if enabled)"
  type        = string
  default     = ""
}

variable "zone_vpc_id" {
  description = "VPC ID for private hosted zone (provide both vpc_id and vpc_region to create a private zone)"
  type        = string
  default     = ""
}

variable "zone_vpc_region" {
  description = "VPC region for private hosted zone"
  type        = string
  default     = ""
}

# ----- Record variables -----
variable "record_type" {
  description = "DNS record type (default: A)"
  type        = string
  default     = "A"
}

variable "record_allow_overwrite" {
  description = "Allow overwrite of existing records"
  type        = bool
  default     = false
}

variable "record_zone_id" {
  description = "Zone ID for the record (if empty, will use created zone if enabled)"
  type        = string
  default     = ""
}

variable "record_health_check_id" {
  description = "Health check ID to associate with the record (if empty, will use created health check if enabled)"
  type        = string
  default     = ""
}

variable "record_name" {
  description = "Name of the DNS record"
  type        = string
  default     = ""
}

variable "record_ttl" {
  description = "TTL for the record"
  type        = number
  default     = 300
}

variable "record_values" {
  description = "List of record values (for simple records)"
  type        = list(string)
  default     = []
}

variable "record_set_identifier" {
  description = "Unique identifier for routing policy records"
  type        = string
  default     = ""
}

# Routing policies
variable "record_failover_routing_policy" {
  description = "Failover routing policy (type: PRIMARY or SECONDARY)"
  type = object({
    type = string
  })
  default = null
}

variable "record_geolocation_routing_policy" {
  description = "Geolocation routing policy"
  type = object({
    continent   = optional(string)
    country     = optional(string)
    subdivision = optional(string)
  })
  default = null
}

variable "record_latency_routing_policy" {
  description = "Latency routing policy (region)"
  type = object({
    region = string
  })
  default = null
}

variable "record_weighted_routing_policy" {
  description = "Weighted routing policy (weight)"
  type = object({
    weight = number
  })
  default = null
}

variable "record_multivalue_answer_routing_policy" {
  description = "Enable multivalue answer routing policy (boolean)"
  type        = bool
  default     = false
}

variable "record_alias" {
  description = "Alias configuration"
  type = object({
    name                   = string
    zone_id                = string
    evaluate_target_health = bool
  })
  default = null
}

# ----- Health Check variables -----
variable "health_check_type" {
  description = "Health check type (default: HTTP)"
  type        = string
  default     = "HTTP"
}

variable "health_check_ip_address" {
  description = "IP address for the health check endpoint"
  type        = string
  default     = ""
}

variable "health_check_fqdn" {
  description = "Fully qualified domain name for the health check"
  type        = string
  default     = ""
}

variable "health_check_port" {
  description = "Port for the health check"
  type        = number
  default     = 80
}

variable "health_check_resource_path" {
  description = "Resource path for HTTP/HTTPS health checks"
  type        = string
  default     = "/"
}

variable "health_check_measure_latency" {
  description = "Measure latency from multiple regions"
  type        = bool
  default     = false
}

variable "health_check_search_string" {
  description = "String to search for in the response body"
  type        = string
  default     = ""
}

variable "health_check_child_health_checks" {
  description = "List of health check IDs for calculated health check (child health checks)"
  type        = list(string)
  default     = []
}

variable "health_check_child_health_threshold" {
  description = "Threshold for calculated health check (number of healthy children required)"
  type        = number
  default     = 1
}

variable "health_check_request_interval" {
  description = "Request interval (10 or 30 seconds)"
  type        = number
  default     = 30
}

variable "health_check_failure_threshold" {
  description = "Failure threshold before marking unhealthy"
  type        = number
  default     = 3
}

# ----- Delegation Set variables -----
variable "delegation_set_reference_name" {
  description = "Reference name for the delegation set (optional)"
  type        = string
  default     = ""
}

# ----- Zone Association variables -----
variable "zone_association_vpc_id" {
  description = "VPC ID for zone association"
  type        = string
  default     = ""
}

variable "zone_association_vpc_region" {
  description = "VPC region for zone association"
  type        = string
  default     = ""
}

variable "zone_association_zone_id" {
  description = "Zone ID for association (if empty, will use created zone if enabled)"
  type        = string
  default     = ""
}

# ----- Query Log variables -----
variable "query_log_cloudwatch_log_group_arn" {
  description = "ARN of CloudWatch log group for query logging"
  type        = string
  default     = ""
}

variable "query_log_zone_id" {
  description = "Zone ID for query logging (if empty, will use created zone if enabled)"
  type        = string
  default     = ""
}

# ----- VPC Association Authorization variables -----
variable "vpc_association_authorization_vpc_id" {
  description = "VPC ID for cross-account association authorization"
  type        = string
  default     = ""
}

variable "vpc_association_authorization_vpc_region" {
  description = "VPC region for cross-account association authorization"
  type        = string
  default     = ""
}

variable "vpc_association_authorization_zone_id" {
  description = "Zone ID for authorization (if empty, will use created zone if enabled)"
  type        = string
  default     = ""
}

# ----- Key Signing Key variables -----
variable "key_signing_key_name" {
  description = "Name for the key signing key (default: <name_env>-ksk)"
  type        = string
  default     = ""
}

variable "key_signing_key_status" {
  description = "Status of the key signing key (default: ACTIVE, will be uppercased)"
  type        = string
  default     = "ACTIVE"
}

variable "key_signing_key_hosted_zone_id" {
  description = "Hosted zone ID for the key signing key (if empty, will use created zone if enabled)"
  type        = string
  default     = ""
}

variable "key_signing_key_arn" {
  description = "ARN of KMS key for DNSSEC signing (if empty, will use created KMS key)"
  type        = string
  default     = ""
}

# =====================================================
# Locals
# =====================================================
locals {
  name_prefix = lower("${var.name}-${var.environment}")

  # Dynamic zone ID: use explicit variable, or created zone if enabled, else empty
  zone_id = var.enable_route53_zone ? try(aws_route53_zone.main[0].id, "") : ""

  # Dynamic health check ID: use explicit variable, or created health check if enabled, else empty
  health_check_id = var.enable_route53_health_check ? try(aws_route53_health_check.main[0].id, "") : ""

  # Dynamic delegation set ID: use explicit variable, or created delegation set if enabled, else empty
  delegation_set_id = try(coalesce(var.zone_delegation_set_id, aws_route53_delegation_set.main[0].id), "")
}

# =====================================================
# Delegation Set (optional)
# =====================================================
resource "aws_route53_delegation_set" "main" {
  count = var.enable_route53_delegation_set ? 1 : 0

  reference_name = coalesce(var.delegation_set_reference_name, "ds-${local.name_prefix}")

  lifecycle {
    prevent_destroy = true
  }
}

# =====================================================
# Hosted Zone (optional)
# =====================================================
resource "aws_route53_zone" "main" {
  count = var.enable_route53_zone ? 1 : 0

  name          = var.zone_domain_name
  comment       = var.zone_comment
  force_destroy = var.zone_force_destroy

  delegation_set_id = local.delegation_set_id != "" ? local.delegation_set_id : null

  dynamic "vpc" {
    for_each = var.zone_vpc_id != "" && var.zone_vpc_region != "" ? [1] : []
    content {
      vpc_id     = var.zone_vpc_id
      vpc_region = var.zone_vpc_region
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# =====================================================
# Health Check (optional)
# =====================================================
resource "aws_route53_health_check" "main" {
  count = var.enable_route53_health_check ? 1 : 0

  type                = var.health_check_type
  ip_address          = var.health_check_ip_address != "" ? var.health_check_ip_address : null
  fqdn                = var.health_check_fqdn != "" ? var.health_check_fqdn : null
  port                = var.health_check_port
  resource_path       = var.health_check_resource_path
  measure_latency     = var.health_check_measure_latency
  search_string       = var.health_check_search_string != "" ? var.health_check_search_string : null
  request_interval    = var.health_check_request_interval
  failure_threshold   = var.health_check_failure_threshold

  child_healthchecks      = length(var.health_check_child_health_checks) > 0 ? var.health_check_child_health_checks : null
  child_health_threshold  = var.health_check_child_health_threshold
}

# =====================================================
# DNS Record (optional)
# =====================================================
resource "aws_route53_record" "main" {
  count = var.enable_route53_record ? 1 : 0

  zone_id = var.record_zone_id != "" ? var.record_zone_id : local.zone_id
  name    = var.record_name
  type    = var.record_type
  ttl     = var.record_ttl
  records = var.record_values
  set_identifier = var.record_set_identifier != "" ? var.record_set_identifier : null

  allow_overwrite = var.record_allow_overwrite

  health_check_id = var.record_health_check_id != "" ? var.record_health_check_id : (local.health_check_id != "" ? local.health_check_id : null)

  multivalue_answer_routing_policy = var.record_multivalue_answer_routing_policy

  dynamic "failover_routing_policy" {
    for_each = var.record_failover_routing_policy != null ? [var.record_failover_routing_policy] : []
    content {
      type = failover_routing_policy.value.type
    }
  }

  dynamic "geolocation_routing_policy" {
    for_each = var.record_geolocation_routing_policy != null ? [var.record_geolocation_routing_policy] : []
    content {
      continent   = geolocation_routing_policy.value.continent
      country     = geolocation_routing_policy.value.country
      subdivision = geolocation_routing_policy.value.subdivision
    }
  }

  dynamic "latency_routing_policy" {
    for_each = var.record_latency_routing_policy != null ? [var.record_latency_routing_policy] : []
    content {
      region = latency_routing_policy.value.region
    }
  }

  dynamic "weighted_routing_policy" {
    for_each = var.record_weighted_routing_policy != null ? [var.record_weighted_routing_policy] : []
    content {
      weight = weighted_routing_policy.value.weight
    }
  }

  dynamic "alias" {
    for_each = var.record_alias != null ? [var.record_alias] : []
    content {
      name                   = alias.value.name
      zone_id                = alias.value.zone_id
      evaluate_target_health = alias.value.evaluate_target_health
    }
  }
}

# =====================================================
# Zone Association (optional)
# =====================================================
resource "aws_route53_zone_association" "main" {
  count = var.enable_route53_zone_association ? 1 : 0

  zone_id = var.zone_association_zone_id != "" ? var.zone_association_zone_id : local.zone_id
  vpc_id  = var.zone_association_vpc_id
  vpc_region = var.zone_association_vpc_region
}

# =====================================================
# Query Logging (optional) — requires IAM role
# =====================================================
resource "aws_iam_role" "route53_query_log" {
  count = var.enable_route53_query_log ? 1 : 0

  name = "route53-query-log-${local.name_prefix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "route53_query_log" {
  count = var.enable_route53_query_log ? 1 : 0

  name = "route53-query-log-policy-${local.name_prefix}"
  role = aws_iam_role.route53_query_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = var.query_log_cloudwatch_log_group_arn
      }
    ]
  })
}

resource "aws_route53_query_log" "main" {
  count = var.enable_route53_query_log ? 1 : 0

  cloudwatch_log_group_arn = var.query_log_cloudwatch_log_group_arn
  zone_id                  = var.query_log_zone_id != "" ? var.query_log_zone_id : local.zone_id
}

# =====================================================
# VPC Association Authorization (optional)
# =====================================================
resource "aws_route53_vpc_association_authorization" "main" {
  count = var.enable_route53_vpc_association_authorization ? 1 : 0

  zone_id    = var.vpc_association_authorization_zone_id != "" ? var.vpc_association_authorization_zone_id : local.zone_id
  vpc_id     = var.vpc_association_authorization_vpc_id
  vpc_region = var.vpc_association_authorization_vpc_region
}

# =====================================================
# KMS Key for DNSSEC (always created, but only used if key signing key enabled)
# =====================================================
resource "aws_kms_key" "dnssec" {
  description             = "KMS key for Route53 DNSSEC signing - ${local.name_prefix}"
  key_usage               = "SIGN_VERIFY"
  customer_master_key_spec = "ECC_NIST_P256"
  deletion_window_in_days = 7
  enable_key_rotation     = false

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Route53 to use the key for DNSSEC"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign",
          "kms:Verify"
        ]
        Resource = "*"
      },
      {
        Sid    = "Enable IAM users to manage the key"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "dnssec" {
  name          = "alias/${local.name_prefix}-dnssec"
  target_key_id = aws_kms_key.dnssec.key_id
}

# Data source for current account ID (used in KMS key policy)
data "aws_caller_identity" "current" {}

# =====================================================
# Key Signing Key (optional)
# =====================================================
resource "aws_route53_key_signing_key" "main" {
  count = var.enable_route53_key_signing_key ? 1 : 0

  hosted_zone_id             = var.key_signing_key_hosted_zone_id != "" ? var.key_signing_key_hosted_zone_id : local.zone_id
  name                       = var.key_signing_key_name != "" ? var.key_signing_key_name : "${local.name_prefix}-ksk"
  status                     = upper(var.key_signing_key_status)
  key_management_service_arn = var.key_signing_key_arn != "" ? var.key_signing_key_arn : aws_kms_key.dnssec.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy" "codedeploy_managed" {
  name = "AWSCodeDeployRole"
}

# Dedicated S3 bucket for deployment artifacts
resource "aws_s3_bucket" "deployment_artifacts" {
  bucket = "ecs-deployment-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "aws_s3_bucket_public_access_block" "deployment_artifacts" {
  bucket = aws_s3_bucket.deployment_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "deployment_artifacts" {
  description             = "KMS CMK for ECS deployment artifact encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "deployment_artifacts" {
  bucket = aws_s3_bucket.deployment_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.deployment_artifacts.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ECS Service Role
resource "aws_iam_role" "ecs_service_role" {
  name               = "ecsServiceRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:Describe*",
          "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
          "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
          "ec2:DescribeInstances",
          "ec2:DescribeNetworkInterfaces",
          "ssm:GetParameters",
          "secretsmanager:GetSecretValue",
          "kms:Decrypt",
          "codedeploy:*",
          "sns:Publish",
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "lambda:InvokeFunction"
        ]
        Resource = "*"
      }
    ]
  })
}

# ECS Exec Task Role
resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "ecsExecTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecs:DescribeServices",
          "ecs:ListServices",
          "ecs:ListTaskDefinitions",
          "ecs:ListTasks",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "secretsmanager:GetSecretValue",
          "kms:Decrypt",
          "ssm:GetParameters",
          "ssm:GetParameter"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec_task_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:CreateService",
          "ecs:UpdateService",
          "ecs:DeleteService",
          "ecs:DescribeServices",
          "ecs:ListServices"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject"
        ]
        Resource = [
          aws_s3_bucket.deployment_artifacts.arn,
          "${aws_s3_bucket.deployment_artifacts.arn}/*"
        ]
      }
    ]
  })
}

# ECS Task Role
resource "aws_iam_role" "ecs_task_role" {
  name               = "ecsTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
