}

# ECS CodeDeploy Role
resource "aws_iam_role" "ecs_codedeploy_role" {
  name               = "ecs_codedeploy_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
