}

resource "aws_iam_role_policy_attachment" "codedeploy_managed_attach" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = data.aws_iam_policy.codedeploy_managed.arn
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:CreateTaskSet",
          "ecs:DeleteTaskSet",
          "ecs:DescribeTaskSets",
          "ecs:UpdateServicePrimaryTaskSet",
          "ecs:DescribeServices",
          "ecs:ListTaskSets"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:ModifyRule"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:GetFunctionConfiguration"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.deployment_artifacts.arn,
          "${aws_s3_bucket.deployment_artifacts.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_task_role.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_exec_task_role.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 4)
}

# External VPC
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# External VPC default security group
resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.external.cidr_block]
  }

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  tags = {
    Name        = "Production External Default SG"
    environment = "prod"
  }
}

# External subnets
resource "aws_subnet" "external" {
  count = 4

  vpc_id                  = aws_vpc.external.id
  cidr_block              = cidrsubnet("10.41.0.0/16", 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "Subnet${count.index}-1${substr(local.azs[count.index], -1, 1)}"
    environment = "prod"
  }
}

# External Internet Gateway
resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    environment = "prod"
  }
}

# External custom route table
resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name        = "Production External Route Table"
    environment = "prod"
  }
}

# Main route table association for external VPC
resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

# Associate external subnets with route table
resource "aws_route_table_association" "external" {
  count = 4

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

# External default network ACL
resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name        = "Production External Default NACL"
    environment = "prod"
  }
}

# Internal VPC
resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = false
  instance_tenancy     = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

# Internal VPC default security group – no rules
resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  # No ingress or egress rules
  tags = {
    Name        = "Production Internal Default SG"
    environment = "prod"
  }
}

# Internal subnets
resource "aws_subnet" "internal" {
  count = 4

  vpc_id            = aws_vpc.internal.id
  cidr_block        = cidrsubnet("10.40.0.0/16", 8, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name        = "Subnet${count.index}-1${substr(local.azs[count.index], -1, 1)}"
    environment = "prod"
  }
}

# Internal default network ACL
resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 150
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    from_port  = 0
    to_port    = 0
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name        = "Production Internal Default NACL"
    environment = "prod"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "resource_prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ARN of the ACM certificate for HTTPS listener"
  type        = string
  default     = null
}

variable "url" {
  description = "Override the webhook URL"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for n8n (use ECR URL for VPC Endpoint compatibility)"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type (FARGATE or FARGATE_SPOT)"
  type        = string
  default     = "FARGATE_SPOT"
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Locals
locals {
  vpc_cidr = "10.0.0.0/16"
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
  webhook_url = var.url != null ? var.url : "https://${aws_lb.this.dns_name}"
  log_group_name = "${var.resource_prefix}-logs"
  cluster_name   = "${var.resource_prefix}-cluster"
  task_family    = "${var.resource_prefix}-task"
  service_name   = "${var.resource_prefix}-service"
  container_name = "n8n"
}

# VPC
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.resource_prefix}-vpc"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.resource_prefix}-private-${count.index}"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.resource_prefix}-public-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "${var.resource_prefix}-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "${var.resource_prefix}-public-rt"
  }
}

resource "aws_route" "public_igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security groups
resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb-sg"
  description = "ALB security group"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "${var.resource_prefix}-ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-ecs-tasks-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-efs-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "this" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = false
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id

  tags = {
    Name = "${var.resource_prefix}-alb"
  }
}

resource "aws_lb_target_group" "this" {
  name        = "${var.resource_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.this.id

  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${var.resource_prefix}-tg"
  }
}

resource "aws_lb_listener" "http" {
  count = var.certificate_arn != null ? 1 : 0

  load_balancer_arn = aws_lb.this.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  count = var.certificate_arn != null ? 1 : 0

  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-0"
  certificate_arn   = var.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }
}

# EFS
resource "aws_efs_file_system" "this" {
  encrypted = true
  tags = {
    Name = "${var.resource_prefix}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_access_point" "this" {
  file_system_id = aws_efs_file_system.this.id

  root_directory {
    path = "/n8n"
    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "0777"
    }
  }

  tags = {
    Name = "${var.resource_prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "this" {
  count = 3

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

# VPC Endpoints for AWS services (eliminates need for internet egress)
resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.ecs_tasks.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.resource_prefix}-vpce-logs"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.ecs_tasks.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.resource_prefix}-vpce-ecr-api"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.ecs_tasks.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.resource_prefix}-vpce-ecr-dkr"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.resource_prefix}-vpce-s3"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "this" {
  name              = local.log_group_name
  retention_in_days = 1
}

# ECS Cluster
resource "aws_ecs_cluster" "this" {
  name = local.cluster_name

  setting {
    name  = "containerInsights"
    value = "disabled"
  }
}

# Fargate capacity providers are built-in; no resource block needed.
# The aws_ecs_cluster_capacity_providers resource references the managed provider.
resource "aws_ecs_cluster_capacity_providers" "this" {
  cluster_name = aws_ecs_cluster.this.name

  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

# IAM Roles and Policies
resource "aws_iam_role" "task_execution" {
  name = "${var.resource_prefix}-task-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_execution_logs" {
  name = "${var.resource_prefix}-task-execution-logs-policy"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role" "task" {
  name = "${var.resource_prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.resource_prefix}-task-logs-policy"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      }
    ]
  })
}

# ECS Task Definition
resource "aws_ecs_task_definition" "this" {
  family                   = local.task_family
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n_data"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.this.id
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.this.id
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = local.log_group_name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "ecs"
        }
      }
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "n8n_data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
    }
  ])
}

# ECS Service
resource "aws_ecs_service" "this" {
  name            = local.service_name
  cluster         = aws_ecs_cluster.this.id
  task_definition = aws_ecs_task_definition.this.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets         = aws_subnet.public[*].id
    assign_public_ip = true
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.this.arn
    container_name   = local.container_name
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.http,
    aws_lb_listener.https
  ]
}

# Outputs
output "alb_dns_name" {
  value = aws_lb.this.dns_name
}

output "webhook_url" {
  value = local.webhook_url
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.this.name
}

output "efs_file_system_id" {
  value = aws_efs_file_system.this.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variable declarations
variable "prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "STAGE"
}

variable "tgw_amazon_side_asn" {
  description = "Amazon side ASN for Transit Gateway"
  type        = number
  default     = 64512
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "peer_region" {
  description = "AWS region for the peering attachment"
  type        = string
  default     = "us-east-2"
}

variable "peer_transit_gateway_id" {
  description = "ID of the peer Transit Gateway (required for peering)"
  type        = string
  default     = ""
}

variable "peer_account_id" {
  description = "AWS account ID of the peer Transit Gateway owner (defaults to current account)"
  type        = string
  default     = ""
}

variable "peer_role_arn" {
  description = "IAM role ARN to assume in the peer account for cross-account peering"
  type        = string
  default     = ""
}

variable "destination_cidr_blocks" {
  description = "List of destination CIDR blocks for static routes"
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "blackhole" {
  description = "Whether to create blackhole routes"
  type        = bool
  default     = false
}

variable "propagation_attachment_ids" {
  description = "List of attachment IDs for route table propagation (defaults to the VPC attachment if created)"
  type        = list(string)
  default     = []
}

variable "association_attachment_id" {
  description = "Attachment ID for route table association (defaults to the VPC attachment if created)"
  type        = string
  default     = ""
}

# Boolean flags to enable/disable components
variable "enable_transit_gateway" {
  description = "Enable Transit Gateway creation"
  type        = bool
  default     = true
}

variable "enable_transit_gateway_vpc_attachment" {
  description = "Enable VPC attachment creation"
  type        = bool
  default     = true
}

variable "enable_transit_gateway_vpc_attachment_accepter" {
  description = "Enable VPC attachment accepter"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_route_table" {
  description = "Enable custom route table creation"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_route" {
  description = "Enable static route creation"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_route_table_propagation" {
  description = "Enable route table propagation"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_route_table_association" {
  description = "Enable route table association"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_peering_attachment" {
  description = "Enable peering attachment creation"
  type        = bool
  default     = false
}

variable "enable_transit_gateway_peering_attachment_accepter" {
  description = "Enable peering attachment accepter creation"
  type        = bool
  default     = false
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# Locals
locals {
  enable = {
    enable_transit_gateway                          = var.enable_transit_gateway
    enable_transit_gateway_vpc_attachment           = var.enable_transit_gateway_vpc_attachment
    enable_transit_gateway_vpc_attachment_accepter   = var.enable_transit_gateway_vpc_attachment_accepter
    enable_transit_gateway_route_table              = var.enable_transit_gateway_route_table
    enable_transit_gateway_route                    = var.enable_transit_gateway_route
    enable_transit_gateway_route_table_propagation  = var.enable_transit_gateway_route_table_propagation
    enable_transit_gateway_route_table_association  = var.enable_transit_gateway_route_table_association
    enable_transit_gateway_peering_attachment       = var.enable_transit_gateway_peering_attachment
    enable_transit_gateway_peering_attachment_accepter = var.enable_transit_gateway_peering_attachment_accepter
  }

  name_prefix = "${var.prefix}-${var.environment}"

  common_tags = {
    Environment = var.environment
    Prefix      = var.prefix
  }

  # Resolve attachment ID for propagation/association (use custom or fallback to VPC attachment)
  vpc_attachment_id = try(aws_ec2_transit_gateway_vpc_attachment.this[0].id, null)

  propagation_ids = length(var.propagation_attachment_ids) > 0 ? var.propagation_attachment_ids : (local.vpc_attachment_id != null ? [local.vpc_attachment_id] : [])
  association_id  = var.association_attachment_id != "" ? var.association_attachment_id : local.vpc_attachment_id
}

# Provider alias for peering (cross-region and cross-account)
provider "aws" {
  alias  = "peer"
  region = var.peer_region

  dynamic "assume_role" {
    for_each = var.peer_role_arn != "" && var.peer_account_id != "" && var.peer_account_id != data.aws_caller_identity.current.account_id ? [1] : []
    content {
      role_arn = var.peer_role_arn
    }
  }
}

# Main VPC
resource "aws_vpc" "this" {
  count = local.enable.enable_transit_gateway_vpc_attachment ? 1 : 0
  cidr_block = var.vpc_cidr
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Subnets (one per AZ in the region)
resource "aws_subnet" "this" {
  for_each = local.enable.enable_transit_gateway_vpc_attachment ? toset(slice(data.aws_availability_zones.available.names, 0, 3)) : []
  vpc_id            = aws_vpc.this[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, index(slice(data.aws_availability_zones.available.names, 0, 3), each.value))
  availability_zone = each.value
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-${each.value}"
  })
}

# Transit Gateway
resource "aws_ec2_transit_gateway" "this" {
  count = local.enable.enable_transit_gateway ? 1 : 0
  amazon_side_asn                 = var.tgw_amazon_side_asn
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"
  default_route_table_association  = "enable"
  default_route_table_propagation  = "enable"
  auto_accept_shared_attachments   = "disable"
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-transit-gateway"
  })
  lifecycle {
    prevent_destroy = true
  }
}

# VPC Attachment
resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  count = local.enable.enable_transit_gateway_vpc_attachment ? 1 : 0
  transit_gateway_id = aws_ec2_transit_gateway.this[0].id
  vpc_id             = aws_vpc.this[0].id
  subnet_ids         = [for s in aws_subnet.this : s.id]
  appliance_mode_support = "disable"
  ipv6_support            = "disable"
  dns_support             = "enable"
  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-vpc-attachment"
  })
  lifecycle {
    prevent_destroy = true
  }
}

# VPC Attachment Accepter (for cross-account acceptance)
resource "aws_ec2_transit_gateway_vpc_attachment_accepter" "this" {
  count = local.enable.enable_transit_gateway_vpc_attachment_accepter ? 1 : 0
  transit_gateway_attachment_id = aws_ec2_transit_gateway_vpc_attachment.this[0].id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-vpc-attachment-accepter"
  })
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

# Custom Route Table
resource "aws_ec2_transit_gateway_route_table" "custom" {
  count = local.enable.enable_transit_gateway_route_table ? 1 : 0
  transit_gateway_id = aws_ec2_transit_gateway.this[0].id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-route-table"
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Static Routes
resource "aws_ec2_transit_gateway_route" "static" {
  for_each = local.enable.enable_transit_gateway_route ? { for idx, cidr in var.destination_cidr_blocks : idx => cidr } : {}
  destination_cidr_block         = each.value
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.custom[0].id
  blackhole                      = var.blackhole
  transit_gateway_attachment_id  = var.blackhole ? null : (local.vpc_attachment_id != null ? local.vpc_attachment_id : null)
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [
    aws_ec2_transit_gateway_route_table.custom,
    aws_ec2_transit_gateway_vpc_attachment.this
  ]
}

# Route Table Propagation
resource "aws_ec2_transit_gateway_route_table_propagation" "custom" {
  count = local.enable.enable_transit_gateway_route_table_propagation && length(local.propagation_ids) > 0 ? 1 : 0
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.custom[0].id
  transit_gateway_attachment_id = local.propagation_ids[0]
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [
    aws_ec2_transit_gateway_route_table.custom,
    aws_ec2_transit_gateway_vpc_attachment.this
  ]
}

# Route Table Association
resource "aws_ec2_transit_gateway_route_table_association" "custom" {
  count = local.enable.enable_transit_gateway_route_table_association && local.association_id != null ? 1 : 0
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.custom[0].id
  transit_gateway_attachment_id = local.association_id
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [
    aws_ec2_transit_gateway_route_table.custom,
    aws_ec2_transit_gateway_vpc_attachment.this
  ]
}

# Peering Attachment
resource "aws_ec2_transit_gateway_peering_attachment" "peer" {
  count = local.enable.enable_transit_gateway_peering_attachment ? 1 : 0
  transit_gateway_id = aws_ec2_transit_gateway.this[0].id
  peer_region        = var.peer_region
  peer_transit_gateway_id = var.peer_transit_gateway_id
  peer_account_id         = var.peer_account_id != "" ? var.peer_account_id : data.aws_caller_identity.current.account_id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-peering-attachment"
  })
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [aws_ec2_transit_gateway.this]
}

# Peering Attachment Accepter (cross-region/cross-account acceptance)
resource "aws_ec2_transit_gateway_peering_attachment_accepter" "peer_accepter" {
  count = local.enable.enable_transit_gateway_peering_attachment_accepter && local.enable.enable_transit_gateway_peering_attachment ? 1 : 0
  provider = aws.peer
  transit_gateway_attachment_id = aws_ec2_transit_gateway_peering_attachment.peer[0].id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-peering-attachment-accepter"
  })
  lifecycle {
    prevent_destroy = true
  }
  depends_on = [aws_ec2_transit_gateway_peering_attachment.peer]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  primary_az   = data.aws_availability_zones.available.names[0]
  secondary_az = data.aws_availability_zones.available.names[1]
  vpc_cidr     = "10.32.0.0/20"
}

# VPC
resource "aws_vpc" "lambda_rds_dev" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  tags = {
    Name = "lambda-rds-dev"
  }
}

# Default Security Group
resource "aws_default_security_group" "lambda_rds_dev_default" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  ingress = []

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.lambda_rds_dev.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-default"
  }
}

# Default Network ACL
resource "aws_default_network_acl" "lambda_rds_dev_default_nacl" {
  default_network_acl_id = aws_vpc.lambda_rds_dev.default_network_acl_id
  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }

  ingress {
    rule_no   = 100
    protocol  = "-1"
    action    = "allow"
    cidr_block = "0.0.0.0/0"
    from_port = 0
    to_port   = 0
  }

  egress {
    rule_no   = 100
    protocol  = "-1"
    action    = "allow"
    cidr_block = "0.0.0.0/0"
    from_port = 0
    to_port   = 0
  }
}

# Subnets
resource "aws_subnet" "db_subnet_1" {
  vpc_id            = aws_vpc.lambda_rds_dev.id
  cidr_block        = "10.32.0.0/28"
  availability_zone = local.primary_az
  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda_subnet" {
  vpc_id            = aws_vpc.lambda_rds_dev.id
  cidr_block        = "10.32.1.0/24"
  availability_zone = local.primary_az
  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "db_subnet_2" {
  vpc_id            = aws_vpc.lambda_rds_dev.id
  cidr_block        = "10.32.0.16/28"
  availability_zone = local.secondary_az
  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "bastion_subnet" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false
  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

# Network ACL Associations
resource "aws_network_acl_association" "db_subnet_1" {
  network_acl_id = aws_default_network_acl.lambda_rds_dev_default_nacl.id
  subnet_id      = aws_subnet.db_subnet_1.id
}

resource "aws_network_acl_association" "lambda_subnet" {
  network_acl_id = aws_default_network_acl.lambda_rds_dev_default_nacl.id
  subnet_id      = aws_subnet.lambda_subnet.id
}

resource "aws_network_acl_association" "db_subnet_2" {
  network_acl_id = aws_default_network_acl.lambda_rds_dev_default_nacl.id
  subnet_id      = aws_subnet.db_subnet_2.id
}

resource "aws_network_acl_association" "bastion_subnet" {
  network_acl_id = aws_default_network_acl.lambda_rds_dev_default_nacl.id
  subnet_id      = aws_subnet.bastion_subnet.id
}

# Internet Gateway
resource "aws_internet_gateway" "lambda_rds_dev_igw" {
  vpc_id = aws_vpc.lambda_rds_dev.id
  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

# Public Route Table
resource "aws_route_table" "lambda_rds_public_subnet" {
  vpc_id = aws_vpc.lambda_rds_dev.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.lambda_rds_dev_igw.id
  }
  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

# Route Table Association for Bastion Subnet
resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion_subnet.id
  route_table_id = aws_route_table.lambda_rds_public_subnet.id
}

# Security Groups
resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "PostgreSQL database security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.lambda_rds_dev.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Lambda functions security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.lambda_rds_dev.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.lambda_rds_dev.cidr_block]
  }

  egress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.postgres_db.id]
  }

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# Ingress rules for database security group
resource "aws_security_group_rule" "postgres_db_ingress_bastion" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.postgres_db.id
  source_security_group_id = aws_security_group.bastion_host.id
}

resource "aws_security_group_rule" "postgres_db_ingress_lambda" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.postgres_db.id
  source_security_group_id = aws_security_group.lambda_functions.id
}

terraform {
