resource "aws_network_acl_rule" "sandbox_inbound_101" {
  network_acl_id = aws_network_acl.sandbox.id
  rule_number    = 101
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
