# Security Groups
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from specified CIDRs and self"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from allowed CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_allowed_cidrs
  }

  ingress {
    description = "Self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = merge(local.common_tags, { Name = "Home SSH" })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from specified CIDRs and self"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from specified CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    description = "Self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = merge(local.common_tags, { Name = "Packer SSH" })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "env" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  env_prefix = var.env != "" ? "${var.env}-" : ""
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${local.env_prefix}vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.env_prefix}igw"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${local.env_prefix}eip-nat-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.env_prefix}nat-gw-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.env_prefix}public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.env_prefix}public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private_app" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.env_prefix}private-app-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private_app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.env_prefix}private-app-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_app" {
  count          = 3
  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

resource "aws_subnet" "private_db" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.env_prefix}private-db-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.env_prefix}private-db-rt"
  }
}

resource "aws_route_table_association" "private_db" {
  count          = 3
  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.private_db.id
}

# Terraform configuration for production-grade S3 bucket

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Random suffix
resource "random_id" "suffix" {
  count = var.use_random_suffix ? 1 : 0
  byte_length = 4
  prefix      = ""
}

# Locals
locals {
  account_alias_prefix = var.use_account_alias_prefix ? "${data.aws_caller_identity.current.account_id}-" : ""
  random_suffix        = var.use_random_suffix ? "-${random_id.suffix[0].hex}" : ""
  bucket_name          = "${local.account_alias_prefix}${var.bucket_name}${local.random_suffix}"

  # Default encryption algorithm
  sse_algorithm = var.kms_master_key_id != "" ? "aws:kms" : "AES256"
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

# Optional public access block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  # Rule: abort incomplete multipart uploads after 14 days
  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  # Rule: transition noncurrent versions to STANDARD_IA after 30 days, expire after 365 days
  rule {
    id     = "noncurrent-version-lifecycle"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  # Rule: expire analytics data after 30 days
  rule {
    id     = "analytics-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  # Rule: expire inventory data after 14 days
  rule {
    id     = "inventory-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }
}

# Analytics configuration
resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "AnalyticsExport"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = "_AWSBucketAnalytics/"
          format     = "CSV"
        }
      }
    }
  }
}

# Optional inventory configuration
resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "Inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  filter {
    prefix = "_AWSBucketInventory/"
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectLockRetainUntilDate",
    "ObjectLockMode",
    "ObjectLockLegalHoldStatus",
    "IntelligentTieringAccessTier",
    "BucketKeyStatus"
  ]

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
      encryption {
        sse_s3 {}
      }
    }
  }
}

# Bucket policy
data "aws_iam_policy_document" "bucket_policy" {
  # Deny non-TLS requests
  statement {
    sid       = "DenyNonTLS"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }

  # Allow S3 service principal to write analytics data
  statement {
    sid       = "AllowS3AnalyticsWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  # Allow S3 service principal to write inventory data
  statement {
    sid       = "AllowS3InventoryWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/_AWSBucketInventory/*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  # Merge custom policy if provided
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# Optional logging
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# Optional transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# Optional ACL
resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

# CORS configuration (only created when CORS rules are provided)
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prepend the AWS account ID to the bucket name (uses account ID as prefix since IAM account alias may not exist in greenfield accounts)"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random suffix to the bucket name"
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block settings"
  type        = bool
  default     = true
}

variable "enable_analytics" {
  description = "Enable storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE-KMS encryption. If empty, AES256 is used."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if non-empty"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket for server access logs. Leave empty to disable logging."
  type        = string
  default     = ""
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status ('Enabled' or 'Suspended'). Set to null to disable."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket. Leave empty to skip ACL (ownership controls enforced)."
  type        = string
  default     = ""
}

variable "cors_rules" {
  description = "List of CORS rules. Each rule must have allowed_headers, allowed_methods, allowed_origins."
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "custom_bucket_policy" {
  description = "JSON string of a custom bucket policy to merge with the default policy."
  type        = string
  default     = ""
}

# Outputs
output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  value = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

# Terraform required providers
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources
data "aws_canonical_user_id" "current" {}

data "aws_caller_identity" "current" {}

# Variables
variable "bucket_name" {
  description = "Prefix for the main S3 bucket name (a unique suffix will be appended)"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "Additional tags for resources"
  type        = map(string)
  default = {
    ServiceProvider = "Rackspace"
  }
}

variable "public_access_block_enabled" {
  description = "Enable public access block settings on the main bucket"
  type        = bool
  default     = true
}

variable "encryption_algorithm" {
  description = "Server-side encryption algorithm: 'AES256', 'aws:kms', or 'none'"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms", "none"], var.encryption_algorithm)
    error_message = "Valid values: AES256, aws:kms, none."
  }
}

variable "kms_key_id" {
  description = "Existing KMS key ID for encryption. If empty, a new key is created."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for KMS encryption"
  type        = bool
  default     = false
}

variable "control_object_ownership" {
  description = "Enable object ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting when control_object_ownership is true"
  type        = string
  default     = "ObjectWriter"
}

variable "canned_acl" {
  description = "Canned ACL to apply to the bucket (e.g., 'private', 'public-read')"
  type        = string
  default     = ""
}

variable "grants_json" {
  description = "JSON-encoded list of grant objects (e.g., [{\"type\":\"Group\",\"uri\":\"http://acs.amazonaws.com/groups/global/AllUsers\",\"permissions\":[\"READ\"]}])"
  type        = string
  default     = ""
}

variable "versioning_status" {
  description = "Versioning status: 'Enabled' or 'Suspended'"
  type        = string
  default     = "Suspended"
}

variable "mfa_delete" {
  description = "MFA delete status: 'Enabled' or 'Disabled'"
  type        = string
  default     = "Disabled"
}

variable "bucket_logging" {
  description = "Enable bucket logging"
  type        = bool
  default     = false
}

variable "log_bucket_name" {
  description = "Name of the logging bucket (created if bucket_logging is true)"
  type        = string
  default     = "benchmark-access-logs-bkt-logs"
}

variable "log_prefix" {
  description = "Prefix for log objects in the logging bucket"
  type        = string
  default     = ""
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock (forces bucket creation with object lock enabled)"
  type        = bool
  default     = false
}

variable "website_config" {
  description = "Map of website configuration settings: index_document, error_document, redirect_all_requests_to, routing_rules"
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "Map of intelligent tiering configuration"
  type        = any
  default     = {}
}

variable "cloudwatch_metrics" {
  description = "Map of CloudWatch metrics configurations"
  type        = any
  default     = {}
}

variable "cors_rules" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

# Locals
locals {
  merged_tags = merge(
    { Environment = var.environment },
    var.tags
  )

  # Parse grants JSON if provided
  grants_list = var.grants_json != "" ? jsondecode(var.grants_json) : []

  # Determine if we need to create a KMS key
  create_kms_key = var.encryption_algorithm == "aws:kms" && var.kms_key_id == ""

  # KMS key ID to use
  kms_key_id_final = local.create_kms_key ? aws_kms_key.main[0].arn : var.kms_key_id
}

# Main S3 bucket (uses bucket_prefix for uniqueness)
resource "aws_s3_bucket" "main" {
  bucket_prefix = var.bucket_name

  # Object Lock requires bucket creation with object_lock_enabled = true
  object_lock_enabled = var.object_lock_enabled

  tags = local.merged_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block (conditional)
resource "aws_s3_bucket_public_access_block" "main" {
  count = var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key (created only if encryption is aws:kms and no existing key ID provided)
data "aws_iam_policy_document" "kms_key" {
  count = local.create_kms_key ? 1 : 0

  statement {
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "main" {
  count = local.create_kms_key ? 1 : 0

  description             = "S3 bucket encryption key for ${var.bucket_name}"
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_key[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# Encryption configuration (conditional)
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.encryption_algorithm != "none" ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_algorithm == "aws:kms" ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption_algorithm == "aws:kms" ? local.kms_key_id_final : null
    }
    bucket_key_enabled = var.encryption_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

# Ownership controls (conditional)
resource "aws_s3_bucket_ownership_controls" "main" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    object_ownership = var.object_ownership
  }
}

# Bucket ACL with canned ACL or grants (skipped when public access block is enabled)
resource "aws_s3_bucket_acl" "main" {
  count = (var.canned_acl != "" || length(local.grants_list) > 0) && !var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  # Use canned ACL if provided (mutually exclusive with access_control_policy)
  acl = var.canned_acl != "" ? var.canned_acl : null

  # Use access_control_policy if grants are provided
  dynamic "access_control_policy" {
    for_each = length(local.grants_list) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants_list

        content {
          grantee {
            type = grant.value.type
            uri  = try(grant.value.uri, null)
            id   = try(grant.value.id, null)
          }
          permission = grant.value.permissions[0]
        }
      }
      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }
}

# Fallback ACL granting full control to canonical user (skipped when public access block is enabled)
resource "aws_s3_bucket_acl" "fallback" {
  count = (var.canned_acl == "" && length(local.grants_list) == 0) && !var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  depends_on = [aws_s3_bucket_ownership_controls.main]

  access_control_policy {
    grant {
      grantee {
        type = "CanonicalUser"
        id   = data.aws_canonical_user_id.current.id
      }
      permission = "FULL_CONTROL"
    }
    owner {
      id = data.aws_canonical_user_id.current.id
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.bucket

  versioning_configuration {
    status    = var.versioning_status
    mfa_delete = var.mfa_delete
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Logging bucket (conditional)
resource "aws_s3_bucket" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = var.log_bucket_name

  tags = merge(local.merged_tags, { Name = var.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Bucket logging (conditional)
resource "aws_s3_bucket_logging" "main" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.log_prefix
}

# Object Lock configuration (conditional)
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 365
    }
  }
}

# Website configuration (conditional)
resource "aws_s3_bucket_website_configuration" "main" {
  count = length(var.website_config) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  index_document {
    suffix = try(var.website_config.index_document, "index.html")
  }

  error_document {
    key = try(var.website_config.error_document, "error.html")
  }

  dynamic "redirect_all_requests_to" {
    for_each = can(var.website_config.redirect_all_requests_to) ? [var.website_config.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value
    }
  }

  dynamic "routing_rule" {
    for_each = can(var.website_config.routing_rules) ? var.website_config.routing_rules : []

    content {
      redirect {
        host_name = routing_rule.value.redirect.host_name
        protocol  = routing_rule.value.redirect.protocol
      }
    }
  }
}

# Intelligent Tiering (conditional)
resource "aws_s3_bucket_intelligent_tiering_configuration" "main" {
  count = length(var.intelligent_tiering) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket
  name   = try(var.intelligent_tiering.name, "Default")

  dynamic "tiering" {
    for_each = try(var.intelligent_tiering.tiering, [])

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# CloudWatch Metrics (conditional)
resource "aws_s3_bucket_metric" "main" {
  count = length(var.cloudwatch_metrics) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket
  name   = try(var.cloudwatch_metrics.name, "Default")

  filter {
    prefix = try(var.cloudwatch_metrics.filter.prefix, null)
    tags   = try(var.cloudwatch_metrics.filter.tags, null)
  }
}

# CORS configuration (conditional)
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Lifecycle configuration (conditional)
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = try(rule.value.status, "Enabled")

      dynamic "abort_incomplete_multipart_upload" {
        for_each = can(rule.value.abort_incomplete_multipart_upload) ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = can(rule.value.expiration) ? [rule.value.expiration] : []

        content {
          date = try(expiration.value.date, null)
          days = try(expiration.value.days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = can(rule.value.noncurrent_version_transition) ? rule.value.noncurrent_version_transition : []

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket (max 63 characters)"
  type        = string
  default     = null
  validation {
    condition     = var.bucket_name == null || length(var.bucket_name) <= 63
    error_message = "Bucket name must be at most 63 characters."
  }
}

variable "name_prefix" {
  description = "Prefix for bucket name (max 37 characters)"
  type        = string
  default     = null
  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "Name prefix must be at most 37 characters."
  }
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if not empty"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership control: BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter"
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "Object ownership must be one of: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "If provided, used for SSE-KMS encryption. If null, a default KMS key is created."
  type        = string
  default     = null
}

variable "enable_versioning" {
  description = "Enable bucket versioning"
  type        = bool
  default     = false
}

variable "custom_policy_json" {
  description = "Optional custom JSON policy to attach to the bucket"
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs that will log to this bucket (for logging permissions)"
  type        = list(string)
  default     = []
}

variable "eventbridge_enabled" {
  description = "Enable Amazon EventBridge notifications"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Object lock retention mode (GOVERNANCE or COMPLIANCE). Set to enable object lock."
  type        = string
  default     = null
  validation {
    condition     = var.object_lock_mode == null ? true : contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "Object lock mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Number of days for object lock retention"
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Number of years for object lock retention"
  type        = number
  default     = null
}

variable "replication_rules" {
  description = "List of replication rule configurations"
  type = list(object({
    priority          = number
    destination_bucket_arn = string
    filter_prefix     = optional(string)
    filter_tags       = optional(map(string))
    delete_marker_replication = optional(bool, false)
    status            = optional(string, "Enabled")
  }))
  default = []
}

variable "inventory_config" {
  description = "Inventory configuration (optional)"
  type = object({
    enabled          = optional(bool, true)
    schedule_frequency = string
    destination_bucket_arn = string
    format           = optional(string, "Parquet")
    optional_fields  = optional(list(string), [])
    include_object_versions = optional(string, "All")
    sse_s3_enabled   = optional(bool, false)
    sse_kms_key_arn  = optional(string, null)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id                                     = string
    enabled                                = bool
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    expiration_days                        = optional(number)
    expiration_date                        = optional(string)
    expiration_date_after_days             = optional(number)
    transition_days                        = optional(number)
    transition_storage_class               = optional(string)
    noncurrent_version_expiration_days     = optional(number)
    noncurrent_version_transition_days     = optional(number)
    noncurrent_version_transition_storage_class = optional(string)
    abort_incomplete_multipart_upload_days = optional(number)
  }))
  default = []
}

# Provider for the secondary region (cross-region replication)
provider "aws" {
  alias  = "replication_destination"
  region = "us-west-2"
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# KMS key for encryption (always created)
resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-bucket-key"
  target_key_id = aws_kms_key.s3.key_id
}

# Primary S3 bucket
resource "aws_s3_bucket" "primary" {
  bucket        = var.bucket_name
  bucket_prefix = var.bucket_name == null ? var.name_prefix : null
  force_destroy = var.force_destroy
  object_lock_enabled = var.object_lock_mode != null ? true : false

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = var.kms_key_arn != null ? var.kms_key_arn : aws_kms_key.s3.arn
      }
      bucket_key_enabled = true
    }
  }

  replication_configuration {
    role = length(var.replication_rules) > 0 ? aws_iam_role.replication[0].arn : ""
    rules {
      id       = "replication-rule"
      priority = 1
      status   = length(var.replication_rules) > 0 ? var.replication_rules[0].status : "Disabled"
      filter {
        prefix = length(var.replication_rules) > 0 ? (var.replication_rules[0].filter_prefix != null ? var.replication_rules[0].filter_prefix : "") : ""
      }
      destination {
        bucket        = length(var.replication_rules) > 0 ? var.replication_rules[0].destination_bucket_arn : ""
        storage_class = "STANDARD"
      }
      delete_marker_replication_status = length(var.replication_rules) > 0 ? (var.replication_rules[0].delete_marker_replication ? "Enabled" : "Disabled") : "Disabled"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    object_ownership = var.object_ownership
  }
}

# ACL (only if ObjectWriter)
resource "aws_s3_bucket_acl" "primary" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.primary.id
  acl    = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

# Public access block
resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# Versioning
resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# Bucket policy document
data "aws_iam_policy_document" "bucket_policy" {
  # SSL-only policy
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Logging permissions (if source buckets are specified)
  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []
    content {
      sid       = "S3ServerAccessLogs"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.primary.arn}/*"]
      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }
      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }

  # Custom policy (if provided)
  dynamic "statement" {
    for_each = var.custom_policy_json != null ? [1] : []
    content {
      # Custom policy is merged using a separate statement; in practice use
      # source_policy_documents to merge policies properly.
    }
  }
}

# Apply bucket policy
resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# EventBridge notification
resource "aws_s3_bucket_notification" "primary" {
  count  = var.eventbridge_enabled ? 1 : 0
  bucket = aws_s3_bucket.primary.id
  eventbridge = true
}

# Server access logging
resource "aws_s3_bucket_logging" "primary" {
  count = var.object_lock_mode == null ? 1 : 0
  bucket = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "logs/"
  depends_on = [aws_s3_bucket.logging[0]]
}

# Logging destination bucket (created only if logging is enabled)
resource "aws_s3_bucket" "logging" {
  count = var.object_lock_mode == null ? 1 : 0
  bucket = "s3-logging-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.object_lock_mode == null ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Object lock configuration (with precondition)
resource "aws_s3_bucket_object_lock_configuration" "primary" {
  count = var.object_lock_mode != null ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
      years = var.object_lock_years
    }
  }

  lifecycle {
    precondition {
      condition     = length(var.logging_source_bucket_arns) == 0
      error_message = "Object lock cannot be combined with source bucket logging."
    }
  }
}

# Cross-region replication
# IAM role for replication (static name to avoid cycle)
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name = "s3-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# Replication policy
data "aws_iam_policy_document" "replication_policy" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.primary.arn]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersionAcl"
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [for rule in var.replication_rules : "${rule.destination_bucket_arn}/*"]
  }
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name   = "s3-replication-policy"
  policy = data.aws_iam_policy_document.replication_policy[0].json
}

# Destination bucket in secondary region
resource "aws_s3_bucket" "replication_destination" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  provider = aws.replication_destination
  bucket = "s3-replication-destination-${data.aws_caller_identity.current.account_id}-us-west-2"
  force_destroy = false

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.replication[0].arn
      }
      bucket_key_enabled = true
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  provider = aws.replication_destination
  bucket = aws_s3_bucket.replication_destination[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# KMS key for replication destination in us-west-2
resource "aws_kms_key" "replication" {
  count    = length(var.replication_rules) > 0 ? 1 : 0
  provider = aws.replication_destination
  description             = "KMS key for S3 replication destination bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

# Inventory configuration
resource "aws_s3_bucket_inventory" "primary" {
  count = var.inventory_config != null ? 1 : 0
  bucket = aws_s3_bucket.primary.id
  name   = "Inventory"
  enabled = var.inventory_config.enabled
  included_object_versions = var.inventory_config.include_object_versions
  optional_fields = var.inventory_config.optional_fields

  destination {
    bucket {
      format     = var.inventory_config.format
      bucket_arn = var.inventory_config.destination_bucket_arn
      prefix     = "inventory/"
      dynamic "encryption" {
        for_each = var.inventory_config.sse_s3_enabled ? [1] : []
        content {
          sse_s3 {}
        }
      }
      dynamic "encryption" {
        for_each = var.inventory_config.sse_kms_key_arn != null ? [1] : []
        content {
          sse_kms {
            key_id = var.inventory_config.sse_kms_key_arn
          }
        }
      }
    }
  }

  schedule {
    frequency = var.inventory_config.schedule_frequency
  }
}

# Inventory destination bucket (created if inventory is configured)
resource "aws_s3_bucket" "inventory_destination" {
  count = var.inventory_config != null ? 1 : 0
  bucket = "s3-inventory-destination-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  force_destroy = false

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = var.kms_key_arn != null ? var.kms_key_arn : aws_kms_key.s3.arn
      }
      bucket_key_enabled = true
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "primary" {
  count = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "primary" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || length(rule.value.tags) > 0 ? [1] : []
        content {
          prefix = rule.value.prefix
          dynamic "tag" {
            for_each = rule.value.tags != null ? rule.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [1] : []
        content {
          days = rule.value.expiration_days
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_date != null ? [1] : []
        content {
          date = rule.value.expiration_date
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition_days != null ? [1] : []
        content {
          days          = rule.value.transition_days
          storage_class = rule.value.transition_storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_transition_days
          storage_class   = rule.value.noncurrent_version_transition_storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "designated_region" {
  description = "AWS region allowed for s3:CreateBucket"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket" {
  description = "Name of the remote state S3 bucket to deny access to"
  type        = string
  default     = "remote-state-bucket"
}

data "aws_caller_identity" "current" {}

# IAM Account Password Policy
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length      = 12
  require_uppercase_characters = true
  require_lowercase_characters = true
  require_numbers              = true
  require_symbols              = true
  allow_users_to_change_password = true
  hard_expiry                  = false
  max_password_age             = 0
  password_reuse_prevention    = 0
}

# S3 Account Public Access Block
resource "aws_s3_account_public_access_block" "global" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Groups
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
  path = "/"
}

# Attach AWS-managed policies to developer group
resource "aws_iam_group_policy_attachment" "developer_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# Custom policy: Developer personal access key management
resource "aws_iam_policy" "developer_access_keys" {
  name        = "${var.group_name_prefix}_developer_access_keys"
  description = "Manage personal access keys"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_access_keys_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_access_keys.arn
}

# Custom policy: Virtual MFA device management
resource "aws_iam_policy" "developer_mfa_devices" {
  name        = "${var.group_name_prefix}_developer_mfa_devices"
  description = "Manage virtual MFA devices"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Effect   = "Allow"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_mfa_devices_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_devices.arn
}

# Custom policy: MFA-gated S3 access
resource "aws_iam_policy" "developer_s3_mfa" {
  name        = "${var.group_name_prefix}_developer_s3_mfa"
  description = "MFA-gated S3 access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "s3:CreateBucket"
        Resource = "arn:aws:s3:::*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.designated_region
          }
        }
      },
      {
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.remote_state_bucket}",
          "arn:aws:s3:::${var.remote_state_bucket}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

# Custom policy: MFA-gated EC2, ELB, CloudWatch, AutoScaling, service-linked roles
resource "aws_iam_policy" "developer_ec2_mfa" {
  name        = "${var.group_name_prefix}_developer_ec2_mfa"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling, and service-linked roles"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_ec2_mfa_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_ec2_mfa.arn
}

# Admin role
resource "aws_iam_role" "admin" {
  name = "admin"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action    = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Admin role policy: full admin with MFA
resource "aws_iam_policy" "admin_role_policy" {
  name        = "admin_role_full_admin_mfa"
  description = "Full admin access with MFA requirement"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_role_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_role_policy.arn
}

# Admin group policy: allow sts:AssumeRole to admin role with MFA
resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_admin_assume_admin_role"
  description = "Allow assuming admin role with MFA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "subnets" {
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24",  availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24",  availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24",  availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24",  availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24",  availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24",  availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24",  availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24",  availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24",  availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24",  availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.main[0].id
  depends_on    = [aws_internet_gateway.main]
  tags = {
    Name = "deployme-natgw"
  }
}

resource "aws_subnet" "main" {
  for_each = { for idx, subnet in var.subnets : idx => subnet }

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false
  tags = {
    Name = each.value.name
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  for_each = { for idx in range(0, 8) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }
  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  for_each = { for idx in range(8, 12) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }
  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  for_each = { for idx in range(12, 16) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.spare.id
}

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound HTTP, HTTPS, and SSH traffic from VPC and web from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

output "server_public_ip" {
  value = aws_eip.nat.public_ip
}

# ------------------------------------------------------------------------------
# Terraform configuration
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "enabled" {
  description = "Boolean to enable/disable the entire backup stack (vaults, IAM roles, selections, notifications)"
  type        = bool
  default     = true
}

variable "vault_name" {
  description = "Name of the AWS Backup Vault to create"
  type        = string
  default     = null
}

variable "vault_kms_key_arn" {
  description = "ARN of the KMS key to encrypt the vault; defaults to AWS managed key"
  type        = string
  default     = null
}

variable "notifications" {
  description = "Map containing 'sns_topic_arn' to enable vault notifications"
  type        = map(string)
  default     = {}
}

variable "iam_role_arn" {
  description = "ARN of an existing IAM role for backup; if not provided, a new role is created"
  type        = string
  default     = null
}

variable "iam_role_name" {
  description = "Name for the IAM role created; defaults to 'aws-backup-plan-<plan_name>-role'"
  type        = string
  default     = null
}

variable "plan_name" {
  description = "Name of the AWS Backup Plan"
  type        = string
  default     = "default-backup-plan"
}

variable "windows_vss_backup" {
  description = "Global flag to enable Windows VSS backups on the single rule"
  type        = bool
  default     = false
}

# Single rule parameters
variable "rule_name" {
  description = "Name for the single backup rule"
  type        = string
  default     = null
}

variable "rule_schedule" {
  description = "Cron or rate expression for the single rule"
  type        = string
  default     = null
}

variable "rule_start_window" {
  description = "Start window in minutes for the single rule"
  type        = number
  default     = null
}

variable "rule_completion_window" {
  description = "Completion window in minutes for the single rule"
  type        = number
  default     = null
}

variable "rule_enable_continuous_backup" {
  description = "Enable continuous backup for the single rule"
  type        = bool
  default     = null
}

variable "rule_recovery_point_tags" {
  description = "Tags to apply to recovery points for the single rule"
  type        = map(string)
  default     = null
}

variable "rules" {
  description = "List of additional backup rule configurations (each map must contain 'rule_name')"
  type        = list(map(any))
  default     = []
}

# Single selection parameters
variable "selection_name" {
  description = "Name for the single backup selection"
  type        = string
  default     = null
}

variable "selection_resources" {
  description = "ARNs of resources to include in the single selection"
  type        = list(string)
  default     = null
}

variable "selection_not_resources" {
  description = "ARNs of resources to exclude in the single selection"
  type        = list(string)
  default     = null
}

variable "selection_conditions" {
  description = "Tag-based conditions for the single selection; keys: string_equals, string_like, string_not_equals, string_not_like. Each value is a map of tag key to value."
  type        = map(any)
  default     = {}
}

variable "selection_tags" {
  description = "Legacy tag-based selection (map of tag key to value) for the single selection"
  type        = map(string)
  default     = {}
}

variable "selections" {
  description = "List of additional selection configurations (each map supports the same keys as single selection variables)"
  type        = list(map(any))
  default     = []
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Conditional creation flags
  create_vault         = var.enabled && var.vault_name != null
  create_notifications = var.enabled && var.vault_name != null && try(var.notifications.sns_topic_arn, null) != null
  create_iam_role      = var.enabled && var.iam_role_arn == null

  # IAM role name
  iam_role_name = var.iam_role_name != null ? var.iam_role_name : "aws-backup-plan-${var.plan_name}-role"

  # Merge single rule (if provided) with the rules list
  single_rule = var.rule_name != null ? {
    rule_name                 = var.rule_name
    rule_schedule             = var.rule_schedule
    rule_start_window         = var.rule_start_window
    rule_completion_window    = var.rule_completion_window
    rule_enable_continuous_backup = var.rule_enable_continuous_backup
    rule_recovery_point_tags  = var.rule_recovery_point_tags
    windows_vss_backup        = var.windows_vss_backup
  } : null

  # Normalize each rule map: ensure lifecycle defaults and windows_vss_backup flag
  normalize_rule = { for k, r in toset(concat(
    local.single_rule != null ? [local.single_rule] : [],
    var.rules
  )) : k => merge(
    {
      rule_name                 = ""
      rule_schedule             = null
      rule_start_window         = null
      rule_completion_window    = null
      rule_enable_continuous_backup = null
      rule_recovery_point_tags  = null
      windows_vss_backup        = false
      lifecycle = {
        cold_storage_after = 30
        delete_after       = 180
      }
    },
    r,
    {
      lifecycle = merge(
        {
          cold_storage_after = 30
          delete_after       = 180
        },
        try(r.lifecycle, {})
      )
    }
  ) }

  merged_rules = [for k, r in local.normalize_rule : r]

  # Check if any rule requires Windows VSS backup
  enable_advanced_backup = length([for r in local.merged_rules : r if try(r.windows_vss_backup, false)]) > 0

  # Merge single selection (if provided) with the selections list
  single_selection = var.selection_name != null ? {
    selection_name        = var.selection_name
    selection_resources   = var.selection_resources
    selection_not_resources = var.selection_not_resources
    selection_conditions  = var.selection_conditions
    selection_tags        = var.selection_tags
  } : null

  merged_selections = concat(
    local.single_selection != null ? [local.single_selection] : [],
    var.selections
  )
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Backup Vault
# ------------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  count = local.create_vault ? 1 : 0

  name        = var.vault_name
  kms_key_arn = var.vault_kms_key_arn != null ? var.vault_kms_key_arn : null

  tags = {
    Name = var.vault_name
  }
}

# ------------------------------------------------------------------------------
# SNS Topic Policy and Vault Notifications
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "sns_topic_policy" {
  count = local.create_notifications ? 1 : 0

  statement {
    sid    = "AllowBackupToPublishToTopic"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = [
      "SNS:Publish"
    ]

    resources = [
      var.notifications["sns_topic_arn"]
    ]
  }
}

resource "aws_sns_topic_policy" "main" {
  count = local.create_notifications ? 1 : 0

  arn    = var.notifications["sns_topic_arn"]
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_backup_vault_notifications" "main" {
  count = local.create_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main[0].name
  sns_topic_arn       = var.notifications["sns_topic_arn"]
  backup_vault_events = ["BACKUP_JOB_STARTED", "BACKUP_JOB_COMPLETED", "RESTORE_JOB_STARTED", "RESTORE_JOB_COMPLETED", "RECOVERY_POINT_MODIFIED"]
}

# ------------------------------------------------------------------------------
# IAM Role for Backup (if not supplied)
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "assume_role_backup" {
  count = local.create_iam_role ? 1 : 0

  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  count = local.create_iam_role ? 1 : 0

  name               = local.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role_backup[0].json
}

# Attach AWS-managed policies
resource "aws_iam_role_policy_attachment" "backup" {
  count = local.create_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  count = local.create_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# Custom IAM policy for S3 backup permissions
data "aws_iam_policy_document" "s3_backup" {
  count = local.create_iam_role ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "s3:Get*",
      "s3:List*",
      "s3:PutObject*",
      "s3:DeleteObject*",
      "s3:GetBucket*",
      "s3:ListBucket*",
      "s3:PutLifecycleConfiguration",
      "s3:GetAccelerateConfiguration",
      "s3:PutAccelerateConfiguration",
      "s3:RestoreObject"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "s3_backup" {
  count = local.create_iam_role ? 1 : 0

  name        = "${local.iam_role_name}-s3-backup"
  description = "Custom policy for AWS Backup S3 backup operations"
  policy      = data.aws_iam_policy_document.s3_backup[0].json
}

resource "aws_iam_role_policy_attachment" "s3_backup" {
  count = local.create_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = aws_iam_policy.s3_backup[0].arn
}

# Custom IAM policy for S3 restore permissions
data "aws_iam_policy_document" "s3_restore" {
  count = local.create_iam_role ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:ListAllMyBuckets",
      "s3:RestoreObject",
      "s3:GetObjectTagging",
      "s3:PutObjectTagging"
    ]

    resources = ["*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "s3_restore" {
  count = local.create_iam_role ? 1 : 0

  name        = "${local.iam_role_name}-s3-restore"
  description = "Custom policy for AWS Backup S3 restore operations"
  policy      = data.aws_iam_policy_document.s3_restore[0].json
}

resource "aws_iam_role_policy_attachment" "s3_restore" {
  count = local.create_iam_role ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = aws_iam_policy.s3_restore[0].arn
}

# Inline policy for tagging
data "aws_iam_policy_document" "inline_tagging" {
  count = local.create_iam_role ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "backup:TagResource",
      "backup:UntagResource",
      "backup:GetResources"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "tagging" {
  count = local.create_iam_role ? 1 : 0

  name   = "backup-tagging"
  role   = aws_iam_role.backup[0].name
  policy = data.aws_iam_policy_document.inline_tagging[0].json
}

# ------------------------------------------------------------------------------
# Backup Plan
# ------------------------------------------------------------------------------

resource "aws_backup_plan" "main" {
  count = var.enabled && length(local.merged_rules) > 0 ? 1 : 0

  name = var.plan_name

  dynamic "rule" {
    for_each = local.merged_rules

    content {
      rule_name                = rule.value.rule_name
      target_vault_name        = local.create_vault ? aws_backup_vault.main[0].name : null
      schedule                 = rule.value.rule_schedule
      start_window             = rule.value.rule_start_window
      completion_window        = rule.value.rule_completion_window
      enable_continuous_backup = rule.value.rule_enable_continuous_backup
      recovery_point_tags      = rule.value.rule_recovery_point_tags

      lifecycle {
        cold_storage_after = rule.value.lifecycle.cold_storage_after
        delete_after       = rule.value.lifecycle.delete_after
      }

      dynamic "copy_action" {
        for_each = try(rule.value.copy_action, null) != null ? [rule.value.copy_action] : []

        content {
          destination_vault_arn = copy_action.value.destination_vault_arn

          lifecycle {
            cold_storage_after = try(copy_action.value.lifecycle.cold_storage_after, null)
            delete_after       = try(copy_action.value.lifecycle.delete_after, null)
          }
        }
      }
    }
  }

  dynamic "advanced_backup_setting" {
    for_each = local.enable_advanced_backup ? [1] : []

    content {
      resource_type = "EC2"
      backup_options = {
        WindowsVSS = "enabled"
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Backup Selections
# ------------------------------------------------------------------------------

resource "aws_backup_selection" "main" {
  for_each = var.enabled && length(local.merged_rules) > 0 ? { for idx, sel in local.merged_selections : idx => sel } : {}

  iam_role_arn = local.create_iam_role ? aws_iam_role.backup[0].arn : var.iam_role_arn
  name         = each.value.selection_name
  plan_id      = aws_backup_plan.main[0].id

  resources         = try(each.value.selection_resources, null)
  not_resources     = try(each.value.selection_not_resources, null)

  # Legacy tag-based selection via selection_tag blocks
  dynamic "selection_tag" {
    for_each = try(each.value.selection_tags, {})
    content {
      type  = "STRING_EQUALS"
      key   = selection_tag.key
      value = selection_tag.value
    }
  }

  # Condition block(s) for tag-based conditions
  dynamic "condition" {
    for_each = try(each.value.selection_conditions, {}) != {} ? [1] : []

    content {
      dynamic "string_equals" {
        for_each = try(each.value.selection_conditions.string_equals, {}) != {} ? [each.value.selection_conditions.string_equals] : []

        content {
          key   = string_equals.value.key
          value = string_equals.value.value
        }
      }

      dynamic "string_like" {
        for_each = try(each.value.selection_conditions.string_like, {}) != {} ? [each.value.selection_conditions.string_like] : []

        content {
          key   = string_like.value.key
          value = string_like.value.value
        }
      }

      dynamic "string_not_equals" {
        for_each = try(each.value.selection_conditions.string_not_equals, {}) != {} ? [each.value.selection_conditions.string_not_equals] : []

        content {
          key   = string_not_equals.value.key
          value = string_not_equals.value.value
        }
      }

      dynamic "string_not_like" {
        for_each = try(each.value.selection_conditions.string_not_like, {}) != {} ? [each.value.selection_conditions.string_not_like] : []

        content {
          key   = string_not_like.value.key
          value = string_not_like.value.value
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  description = "Name component of the standard label"
  type        = string
  default     = "my-security-group"
}

variable "environment" {
  description = "Environment component of the standard label"
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "ManagedBy tag value"
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of label components"
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for the source code"
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "enabled" {
  description = "Master switch to enable or disable all module resources"
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "When true, create a new security group; when false, use existing_sg_id"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID in which to create the security group. If null and new_sg is true, a VPC will be created automatically."
  type        = string
  default     = null
}

variable "existing_sg_id" {
  description = "Existing security group ID to apply rules to (required when new_sg = false)"
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Flag to enable creation or use of managed prefix lists"
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list IDs; when empty and prefix_list_enabled is true, a new prefix list is created"
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries in the managed prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list"
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []
}

variable "ingress_rules" {
  description = "List of ingress security group rules"
  type = list(object({
    description              = string
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress security group rules"
  type = list(object({
    description              = string
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

locals {
  label_id         = try(module.labels[0].id, "")
  label_tags       = try(module.labels[0].tags, {})
  sg_name          = format("%s-sg", local.label_id)
  prefix_name      = format("%s-prefix-list", local.label_id)
  effective_vpc_id = var.vpc_id != null ? var.vpc_id : (var.enabled && var.new_sg ? aws_vpc.this[0].id : null)
  sg_id            = var.enabled ? (var.new_sg ? aws_security_group.this[0].id : var.existing_sg_id) : null
  prefix_list_id   = var.enabled && (var.prefix_list_enabled || length(var.prefix_list_ids) > 0) ? (
    length(var.prefix_list_ids) > 0 ? var.prefix_list_ids[0] : aws_ec2_managed_prefix_list.this[0].id
  ) : null
}

module "labels" {
  source      = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"
  count       = var.enabled ? 1 : 0
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

resource "aws_vpc" "this" {
  count                = var.enabled && var.new_sg && var.vpc_id == null ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.label_tags, { Name = format("%s-vpc", local.label_id) })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group" "this" {
  count       = var.enabled && var.new_sg ? 1 : 0
  name        = local.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.effective_vpc_id

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.label_tags, { Name = local.sg_name })
}

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0
  name           = local.prefix_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(local.label_tags, { Name = local.prefix_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group_rule" "ingress" {
  for_each = var.enabled ? { for idx, rule in var.ingress_rules : idx => rule } : {}

  type              = "ingress"
  security_group_id = local.sg_id
  description       = each.value.description
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self                     = each.value.self ? true : null
  source_security_group_id = try(each.value.source_security_group_id, null) != null && try(each.value.source_security_group_id, "") != "" ? each.value.source_security_group_id : null
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null && try(each.value.prefix_list_id, "") != "" ? [each.value.prefix_list_id] : (local.prefix_list_id != null ? [local.prefix_list_id] : [])
}

resource "aws_security_group_rule" "egress" {
  for_each = var.enabled ? { for idx, rule in var.egress_rules : idx => rule } : {}

  type              = "egress"
  security_group_id = local.sg_id
  description       = each.value.description
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self                     = each.value.self ? true : null
  source_security_group_id = try(each.value.source_security_group_id, null) != null && try(each.value.source_security_group_id, "") != "" ? each.value.source_security_group_id : null
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null && try(each.value.prefix_list_id, "") != "" ? [each.value.prefix_list_id] : (local.prefix_list_id != null ? [local.prefix_list_id] : [])
}

output "security_group_id" {
  description = "The ID of the security group (new or existing)"
  value       = local.sg_id
}

output "prefix_list_id" {
  description = "The ID of the managed prefix list (if created or provided)"
  value       = local.prefix_list_id
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_name" {
  type        = string
  default     = "dev"
  description = "Environment name used to construct IAM role names"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# 1. Account Password Policy
# ---------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length      = 14
  require_lowercase_characters = true
  require_uppercase_characters = true
  require_numbers              = true
  require_symbols              = false
  allow_users_to_change_password = true
  max_password_age             = 90
  password_reuse_prevention    = 3
}

# ---------------------------------------------------------------------------
# 2. ECS Task Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secretsmanager" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy" "ecs_task_s3_custom" {
  name = "ecs-task-s3-custom"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObjectVersion",
          "s3:PutObjectAcl",
          "s3:GetBucketAcl",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name = "ecs-task-ssm-messages"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. ECS Execution Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_ecstask" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_ec2container" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_execution_inline" {
  name = "ecs-execution-secrets-kms"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:secret:*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = "arn:aws:kms:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:key/*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 4. ECS Events Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_events" {
  name = "ecs_events_role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_events_ecstask" {
  role       = aws_iam_role.ecs_events.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_ec2container" {
  role       = aws_iam_role.ecs_events.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# ---------------------------------------------------------------------------
# 5. Public Lambda Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "public_lambda" {
  name = "public-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "public_lambda_logging" {
  name = "public-lambda-cloudwatch"
  role = aws_iam_role.public_lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 6. VPC Lambda Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "vpc_lambda" {
  name = "vpc-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_lambda_inline" {
  name = "vpc-lambda-policy"
  role = aws_iam_role.vpc_lambda.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "secretsmanager:GetSecretValue"
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:secret:*"
      },
      {
        Effect = "Allow"
        Action = "lambda:InvokeFunction"
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 7. Step Functions Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "step_functions" {
  name = "step-functions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_inline" {
  name = "step-functions-policy"
  role = aws_iam_role.step_functions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogDelivery",
          "logs:GetLogDelivery",
          "logs:ListLogDeliveries"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "states:StartExecution",
          "states:DescribeExecution",
          "states:StopExecution"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "lambda:InvokeFunction"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "cloudwatch:DescribeAlarms"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 8. EventBridge Execution Role (for Step Functions)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_stepfunctions" {
  name = "eventbridge-stepfunctions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge_stepfunctions_inline" {
  name = "eventbridge-stepfunctions-policy"
  role = aws_iam_role.eventbridge_stepfunctions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "states:StartExecution"
        Resource = "arn:aws:states:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:stateMachine:*"
        Condition = {
          StringEquals = {
            "aws:ResourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 9. Developer Policy (MFA-limited)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer access with MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObjectVersion",
          "s3:PutObjectAcl",
          "s3:GetBucketAcl",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "CloudWatchAndECSReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "ecs:Describe*",
          "ecs:List*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
          "iam:UpdateAccessKey",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "ExplicitDenyWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
          "iam:UpdateAccessKey",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 10. Billing Policy (MFA-limited)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing access with MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingAccessWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:*",
          "budgets:*",
          "ce:*",
          "payments:*",
          "tax:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
      },
      {
        Sid    = "ExplicitDenyWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "config" {
  type        = string
  description = "YAML configuration for pipelines"
  default     = <<YAML
pipelines:
  - name: pipeline-one
    source:
      provider: CodeCommit
      repository_name: my-repo
      branch: main
    role_arn: null
    stages:
      - name: Source
        actions:
          - name: Source
            category: Source
            owner: AWS
            provider: CodeCommit
            version: 1
            configuration:
              RepositoryName: my-repo
              BranchName: main
      - name: Build
        actions:
          - name: Build
            category: Build
            owner: AWS
            provider: CodeBuild
            version: 1
            configuration:
              ProjectName: pipeline-one-build
              EnvironmentType: LINUX_CONTAINER
              ComputeType: BUILD_GENERAL1_SMALL
              Image: aws/codebuild/standard:6.0
      - name: Approval
        actions:
          - name: Approve
            category: Approval
            owner: AWS
            provider: Manual
            version: 1
            configuration: {}
      - name: Deploy
        actions:
          - name: InvokeLambda
            category: Invoke
            owner: AWS
            provider: Lambda
            version: 1
            configuration:
              FunctionName: pipeline-one-function
              UserParameters: "{}"
    triggers:
      - type: branch
        branch: main
      - type: cron
        expression: "cron(0 0 * * ? *)"
  - name: pipeline-two
    source:
      provider: GitHub
      repository_owner: myorg
      repository_name: my-repo
      branch: develop
    role_arn: null
    stages:
      - name: Source
        actions:
          - name: Source
            category: Source
            owner: AWS
            provider: CodeStarSourceConnection
            version: 1
            configuration:
              ConnectionArn: placeholder
              FullRepositoryId: myorg/my-repo
              BranchName: develop
      - name: Build
        actions:
          - name: Build
            category: Build
            owner: AWS
            provider: CodeBuild
            version: 1
            configuration:
              ProjectName: pipeline-two-build
              EnvironmentType: LINUX_CONTAINER
              ComputeType: BUILD_GENERAL1_SMALL
              Image: aws/codebuild/standard:6.0
    triggers:
      - type: cron
        expression: "cron(0 12 * * ? *)"
      - type: custom
        pattern: '{"source": ["aws.codecommit"], "detail-type": ["CodeCommit Repository State Change"]}'
YAML
}

locals {
  parsed_config = yamldecode(var.config)
  pipelines     = { for p in local.parsed_config.pipelines : p.name => p }

  # Extract CodeBuild configuration for pipelines that have a CodeBuild stage
  codebuild_projects = {
    for pname, pipeline in local.pipelines :
    pname => {
      name       = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.ProjectName, null)
      env_type   = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.EnvironmentType, "LINUX_CONTAINER")
      compute    = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.ComputeType, "BUILD_GENERAL1_SMALL")
      image      = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.Image, "aws/codebuild/standard:6.0")
    }
    if try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0], null) != null
  }

  # Extract Lambda configuration for pipelines that have a Lambda action
  lambda_functions = {
    for pname, pipeline in local.pipelines :
    pname => {
      name = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "Lambda"][0].configuration.FunctionName, null)
    }
    if try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "Lambda"][0], null) != null
  }

  # Determine if a default CodePipeline IAM role is needed
  default_role_needed = length([for p in local.pipelines : p if p.role_arn == null]) > 0

  # Map from trigger key to pipeline name
  trigger_to_pipeline = {
    for pair in flatten([
      for pname, pipeline in local.pipelines : [
        for idx, trigger in pipeline.triggers : {
          key   = "${pname}-${idx}"
          pname = pname
        }
      ]
    ]) : pair.key => pair.pname
  }
}

# KMS customer managed key for S3 bucket encryption
resource "aws_kms_key" "s3" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# KMS alias uses name_prefix to avoid collisions with previously created aliases
resource "aws_kms_alias" "s3" {
  name_prefix   = "alias/s3-bucket-cmk-"
  target_key_id = aws_kms_key.s3.key_id
}

# Random suffix for bucket names
resource "random_id" "bucket_suffix" {
  for_each    = local.pipelines
  byte_length = 4
}

# S3 artifact buckets
resource "aws_s3_bucket" "artifact" {
  for_each      = local.pipelines
  bucket        = "artifacts-${each.key}-${random_id.bucket_suffix[each.key].hex}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  for_each                = local.pipelines
  bucket                  = aws_s3_bucket.artifact[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.artifact[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.artifact[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 build cache buckets
resource "aws_s3_bucket" "cache" {
  for_each      = local.pipelines
  bucket        = "cache-${each.key}-${random_id.bucket_suffix[each.key].hex}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  for_each                = local.pipelines
  bucket                  = aws_s3_bucket.cache[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.cache[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "cache" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.cache[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

# CodeStar connections for GitHub, Bitbucket, or GitHub Enterprise Server sources
resource "aws_codestarconnections_connection" "github" {
  for_each = {
    for name, pipeline in local.pipelines :
    name => pipeline
    if pipeline.source.provider == "GitHub" || pipeline.source.provider == "Bitbucket" || pipeline.source.provider == "GitHubEnterpriseServer"
  }
  name          = "${each.key}-connection"
  provider_type = each.value.source.provider == "GitHubEnterpriseServer" ? "GitHubEnterpriseServer" : each.value.source.provider
  lifecycle {
    prevent_destroy = true
  }
}

# CodeStar host for GitHub Enterprise Server
resource "aws_codestarconnections_host" "ghes" {
  for_each = {
    for name, pipeline in local.pipelines :
    name => pipeline
    if pipeline.source.provider == "GitHubEnterpriseServer"
  }
  name              = "${each.key}-host"
  provider_endpoint = try(each.value.source.endpoint, "https://github.example.com")
  provider_type     = "GitHubEnterpriseServer"
  lifecycle {
    prevent_destroy = true
  }
}

# Default CodePipeline IAM role (if any pipeline does not specify a role_arn)
# name_prefix is used to avoid EntityAlreadyExists in shared/provisioned environments
resource "aws_iam_role" "codepipeline_default" {
  count = local.default_role_needed ? 1 : 0
  name_prefix = "codepipeline-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# IAM policy for default CodePipeline role
resource "aws_iam_policy" "codepipeline_default" {
  count = local.default_role_needed ? 1 : 0
  name_prefix = "codepipeline-default-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codepipeline:*",
          "codecommit:*",
          "codebuild:*",
          "ecr:*"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = concat(
          [for b in aws_s3_bucket.artifact : b.arn],
          [for b in aws_s3_bucket.cache : b.arn],
          flatten([for b in aws_s3_bucket.artifact : ["${b.arn}/*"]]),
          flatten([for b in aws_s3_bucket.cache : ["${b.arn}/*"]])
        )
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "codepipeline_default" {
  count      = local.default_role_needed ? 1 : 0
  role       = aws_iam_role.codepipeline_default[0].name
  policy_arn = aws_iam_policy.codepipeline_default[0].arn
}

# Dedicated IAM role for CodeBuild
resource "aws_iam_role" "codebuild_default" {
  count = length(local.codebuild_projects) > 0 ? 1 : 0
  name_prefix = "codebuild-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "codebuild_default" {
  count = length(local.codebuild_projects) > 0 ? 1 : 0
  name_prefix = "codebuild-default-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = concat(
          [for b in aws_s3_bucket.artifact : b.arn],
          [for b in aws_s3_bucket.cache : b.arn],
          flatten([for b in aws_s3_bucket.artifact : ["${b.arn}/*"]]),
          flatten([for b in aws_s3_bucket.cache : ["${b.arn}/*"]])
        )
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "codebuild_default" {
  count      = length(local.codebuild_projects) > 0 ? 1 : 0
  role       = aws_iam_role.codebuild_default[0].name
  policy_arn = aws_iam_policy.codebuild_default[0].arn
}

# Dedicated IAM role for Lambda
resource "aws_iam_role" "lambda_default" {
  count = length(local.lambda_functions) > 0 ? 1 : 0
  name_prefix = "lambda-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "lambda_default" {
  count      = length(local.lambda_functions) > 0 ? 1 : 0
  role       = aws_iam_role.lambda_default[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Inline CodeBuild projects
resource "aws_codebuild_project" "pipeline" {
  for_each     = local.codebuild_projects
  name         = each.value.name
  service_role = aws_iam_role.codebuild_default[0].arn

  source {
    type     = "CODEPIPELINE"
    buildspec = ""
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type               = each.value.compute
    image                      = each.value.image
    type                       = each.value.env_type
    image_pull_credentials_type = "CODEBUILD"
  }

  lifecycle {
    ignore_changes = [
      source[0].buildspec,
    ]
  }
}

# Import existing CodeBuild projects to prevent ResourceAlreadyExistsException
import {
  for_each = local.codebuild_projects
  to       = aws_codebuild_project.pipeline[each.key]
  id       = each.value.name
}

# Archive file for Lambda placeholder code
data "archive_file" "lambda" {
  for_each    = local.lambda_functions
  type        = "zip"
  output_path = "${path.module}/lambda-${each.key}.zip"
  source {
    content  = "def handler(event, context):\n    return {'statusCode': 200}"
    filename = "index.py"
  }
}

# Inline Lambda functions
resource "aws_lambda_function" "pipeline" {
  for_each         = local.lambda_functions
  function_name    = each.value.name
  handler          = "index.handler"
  runtime          = "python3.9"
  role             = aws_iam_role.lambda_default[0].arn
  filename         = data.archive_file.lambda[each.key].output_path
  source_code_hash = data.archive_file.lambda[each.key].output_base64sha256
  lifecycle {
    prevent_destroy = true
    ignore_changes = [
      source_code_hash,
      filename,
    ]
  }
}

# Import existing Lambda function to prevent ResourceConflictException
import {
  for_each = local.lambda_functions
  to       = aws_lambda_function.pipeline[each.key]
  id       = each.value.name
}

# CodePipeline resources
resource "aws_codepipeline" "pipeline" {
  for_each = local.pipelines
  name     = each.key
  role_arn = coalesce(each.value.role_arn, try(aws_iam_role.codepipeline_default[0].arn, null))

  artifact_store {
    location = aws_s3_bucket.artifact[each.key].id
    type     = "S3"
  }

  dynamic "stage" {
    for_each = each.value.stages
    content {
      name = stage.value.name
      dynamic "action" {
        for_each = stage.value.actions
        content {
          name     = action.value.name
          category = action.value.category
          owner    = action.value.owner
          provider = action.value.provider
          version  = action.value.version
          configuration = merge(
            action.value.provider == "CodeBuild" ? {} : action.value.configuration,
            action.value.provider == "CodeStarSourceConnection" ? {
              ConnectionArn = aws_codestarconnections_connection.github[each.key].arn
            } : {},
            action.value.provider == "CodeBuild" ? {
              ProjectName = aws_codebuild_project.pipeline[each.key].name
            } : {},
            action.value.provider == "Lambda" ? {
              FunctionName = aws_lambda_function.pipeline[each.key].function_name
            } : {}
          )
          output_artifacts = action.value.category == "Source" ? ["source_output"] : null
          input_artifacts  = action.value.provider == "CodeBuild" ? ["source_output"] : null
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# EventBridge IAM roles for each pipeline
resource "aws_iam_role" "eventbridge_pipeline" {
  for_each = local.pipelines
  name_prefix = "terrabits-${each.key}-"
  path        = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "eventbridge_pipeline" {
  for_each = local.pipelines
  name_prefix = "terrabits-${each.key}-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.pipeline[each.key].arn
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "eventbridge_pipeline" {
  for_each = local.pipelines
  role       = aws_iam_role.eventbridge_pipeline[each.key].name
  policy_arn = aws_iam_policy.eventbridge_pipeline[each.key].arn
}

# EventBridge rules – one per trigger
resource "aws_cloudwatch_event_rule" "pipeline" {
  for_each = {
    for pair in flatten([
      for pname, pipeline in local.pipelines : [
        for idx, trigger in pipeline.triggers : {
          key      = "${pname}-${idx}"
          pname    = pname
          trigger  = trigger
        }
      ]
    ]) : pair.key => pair
  }
  name        = "${each.value.pname}-trigger-${index([for t in local.pipelines[each.value.pname].triggers : t], each.value.trigger)}"
  description = "EventBridge rule for pipeline ${each.value.pname} trigger"

  event_pattern = each.value.trigger.type == "branch" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    detail = {
      referenceType = ["branch"]
      referenceName = [each.value.trigger.branch]
    }
  }) : each.value.trigger.type == "tag" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    detail = {
      referenceType = ["tag"]
      referenceName = [each.value.trigger.tag]
    }
  }) : each.value.trigger.type == "custom" ? each.value.trigger.pattern : null

  schedule_expression = each.value.trigger.type == "cron" ? each.value.trigger.expression : null
}

# EventBridge targets – one per rule
resource "aws_cloudwatch_event_target" "pipeline" {
  for_each = aws_cloudwatch_event_rule.pipeline
  rule     = each.value.name
  target_id = "target-${each.key}"
  arn       = aws_codepipeline.pipeline[local.trigger_to_pipeline[each.key]].arn
  role_arn  = aws_iam_role.eventbridge_pipeline[local.trigger_to_pipeline[each.key]].arn
}

# Data sources for KMS key policy and account root
data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "server_name" {
  description = "Name used for the Transfer Family server and related resources"
  type        = string
  default     = "sftp-server"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for the public subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "is_public" {
  description = "Whether the SFTP server endpoint is public (PUBLIC) or VPC-based"
  type        = bool
  default     = false
}

variable "performance_mode" {
  description = "EFS performance mode (generalPurpose or maxIO)"
  type        = string
  default     = "generalPurpose"
}

variable "logging_enabled" {
  description = "Enable CloudWatch logging for the Transfer server"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "Optional KMS key ID for EFS encryption. If not provided, a default key is created."
  type        = string
  default     = null
}

variable "sftp_users" {
  description = "Map of SFTP users. Each key is the username, value is an object with properties."
  type = map(object({
    user_name      = string
    uid            = number
    gid            = number
    ssh_public_key = string
    home_directory = string
    restricted     = bool
  }))
  default = {}
}

variable "additional_access_points" {
  description = "Map of additional EFS access points (not user-specific). Each key is the name, value is an object."
  type = map(object({
    name           = string
    directory_path = string
    uid            = number
    gid            = number
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  efs_kms_key_id = var.kms_key_id != null ? var.kms_key_id : aws_kms_key.efs[0].arn

  allowed_ssh_cidr = var.is_public ? "0.0.0.0/0" : var.vpc_cidr

  subnet_count = length(var.subnet_cidrs)
}

# ------------------------------------------------------------------------------
# VPC and Networking
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.server_name}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.server_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security Groups (no inline cross-references to avoid cycles)
# ------------------------------------------------------------------------------
resource "aws_security_group" "sftp_sg" {
  name        = "${var.server_name}-sftp-sg"
  description = "Security group for Transfer Family SFTP server"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.allowed_ssh_cidr]
  }

  tags = {
    Name = "${var.server_name}-sftp-sg"
  }
}

resource "aws_security_group" "efs_sg" {
  name        = "${var.server_name}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  # No egress rules needed; security groups are stateful, so reply traffic
  # for inbound NFS connections is automatically allowed.
  # Ingress from SFTP is added via aws_security_group_rule to avoid circular dependency.

  tags = {
    Name = "${var.server_name}-efs-sg"
  }
}

# ------------------------------------------------------------------------------
# Security Group Rules (cross-group references)
# ------------------------------------------------------------------------------
resource "aws_security_group_rule" "sftp_egress_efs" {
  type                     = "egress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.efs_sg.id
  security_group_id        = aws_security_group.sftp_sg.id

  description = "Outbound from SFTP to EFS on NFS"
}

resource "aws_security_group_rule" "efs_ingress_sftp" {
  type                     = "ingress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.sftp_sg.id
  security_group_id        = aws_security_group.efs_sg.id

  description = "Inbound to EFS from SFTP on NFS"
}

# ------------------------------------------------------------------------------
# KMS Key (default creation if no user-provided key)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "efs" {
  count = var.kms_key_id == null ? 1 : 0

  description             = "KMS key for EFS encryption - ${var.server_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "${var.server_name}-efs-key"
  }
}

resource "aws_kms_alias" "efs" {
  count = var.kms_key_id == null ? 1 : 0

  name          = "alias/${var.server_name}-efs"
  target_key_id = aws_kms_key.efs[0].key_id
}

# ------------------------------------------------------------------------------
# EFS File System and Mount Targets
# ------------------------------------------------------------------------------
resource "aws_efs_file_system" "main" {
  creation_token   = "${var.server_name}-efs"
  performance_mode = var.performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = local.efs_kms_key_id

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.server_name}-efs"
  }
}

resource "aws_efs_mount_target" "main" {
  count = local.subnet_count

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public[count.index].id
  security_groups = [aws_security_group.efs_sg.id]
}

# ------------------------------------------------------------------------------
# Transfer Family Server
# ------------------------------------------------------------------------------
resource "aws_eip" "transfer" {
  count = var.is_public ? local.subnet_count : 0

  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip-${count.index + 1}"
  }
}

resource "aws_transfer_server" "main" {
  domain                 = "EFS"
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = var.is_public ? "PUBLIC" : "VPC"

  dynamic "endpoint_details" {
    for_each = [1]
    content {
      vpc_id             = var.is_public ? null : aws_vpc.main.id
      subnet_ids         = var.is_public ? null : aws_subnet.public[*].id
      security_group_ids = var.is_public ? null : [aws_security_group.sftp_sg.id]
      address_allocation_ids = var.is_public ? aws_eip.transfer[*].id : null
    }
  }

  logging_role = var.logging_enabled ? aws_iam_role.logging_role[0].arn : null

  tags = {
    Name = var.server_name
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Logging (Conditional)
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "transfer" {
  count = var.logging_enabled ? 1 : 0

  name              = "/aws/transfer/${var.server_name}"
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.server_name}-logs"
  }
}

resource "aws_iam_role" "logging_role" {
  count = var.logging_enabled ? 1 : 0

  name = "${var.server_name}-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-logging-role"
  }
}

resource "aws_iam_policy" "logging_policy" {
  count = var.logging_enabled ? 1 : 0

  name        = "${var.server_name}-logging-policy"
  description = "Policy for Transfer Family CloudWatch logging"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.transfer[0].arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = var.logging_enabled ? 1 : 0

  role       = aws_iam_role.logging_role[0].name
  policy_arn = aws_iam_policy.logging_policy[0].arn
}

# ------------------------------------------------------------------------------
# IAM Role for SFTP Users
# ------------------------------------------------------------------------------
resource "aws_iam_role" "sftp_user_role" {
  name = "${var.server_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.server_name}-sftp-user-role"
  }
}

resource "aws_iam_policy" "sftp_user_policy" {
  name        = "${var.server_name}-sftp-user-policy"
  description = "Policy for SFTP users to access EFS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess",
          "elasticfilesystem:DescribeMountTargets"
        ]
        Resource = aws_efs_file_system.main.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  role       = aws_iam_role.sftp_user_role.name
  policy_arn = aws_iam_policy.sftp_user_policy.arn
}

# ------------------------------------------------------------------------------
# EFS Access Points for Restricted Users
# ------------------------------------------------------------------------------
resource "aws_efs_access_point" "user" {
  for_each = { for k, v in var.sftp_users : k => v if v.restricted }

  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = "/${each.value.user_name}"
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${var.server_name}-user-${each.value.user_name}"
  }
}

# ------------------------------------------------------------------------------
# SFTP Users (from sftp_users variable)
# ------------------------------------------------------------------------------
resource "aws_transfer_user" "main" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.main.id
  user_name = each.value.user_name
  role      = aws_iam_role.sftp_user_role.arn

  # For restricted users, use the EFS access point ARN; otherwise use the provided home directory path
  home_directory = each.value.restricted ? aws_efs_access_point.user[each.key].arn : each.value.home_directory

  tags = {
    Name = "${var.server_name}-user-${each.value.user_name}"
  }
}

# ------------------------------------------------------------------------------
# SSH Keys for SFTP Users
# ------------------------------------------------------------------------------
resource "aws_transfer_ssh_key" "user" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.main.id
  user_name = aws_transfer_user.main[each.key].user_name
  body      = each.value.ssh_public_key
}

# ------------------------------------------------------------------------------
# Additional EFS Access Points (from additional_access_points variable)
# ------------------------------------------------------------------------------
resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.directory_path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${var.server_name}-additional-${each.value.name}"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "org" {
  type = object({
    organization_name   = optional(string, "benchmark-org")
    organization_unit   = optional(string, "benchmark-ou")
    environment_type    = optional(string, "dev")
    environment_name    = optional(string, "benchmark")
  })
  default = {}
}

variable "spoke_def" {
  type    = string
  default = "001"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "zones" {
  type = map(object({
    zone_name           = string
    type                = string
    vpc_id              = optional(string)
    dns_vpc             = optional(object({
      vpc_id = string
    }))
    association_zone_ids = optional(list(string), [])
    custom_resolver_rules = optional(list(object({
      domain_name = string
      target_ips  = list(string)
    })), [])
  }))
  default = {}
}

variable "is_hub" {
  type    = bool
  default = false
}

variable "ram" {
  type = object({
    enabled                = optional(bool, false)
    allow_external_principals = optional(bool, false)
    principals             = optional(list(string), [])
  })
  default = {}
}

variable "shared" {
  type = object({
    resolver_rules = optional(list(string), [])
  })
  default = {}
}

# Data sources
data "aws_region" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

# Locals for tags
locals {
  tags = {
    Organization       = var.org.organization_name
    OrganizationUnit   = var.org.organization_unit
    EnvironmentType    = var.org.environment_type
    EnvironmentName    = var.org.environment_name
    SpokeDef           = var.spoke_def
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.tags, {
    Name = "hub-spoke-vpc"
  })
}

# Subnets (public)
resource "aws_subnet" "public" {
  count                   = length(data.aws_availability_zones.available.names)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.tags, {
    Name = "public-subnet-${count.index + 1}"
  })
}

# Route 53 Zones
resource "aws_route53_zone" "this" {
  for_each = var.zones
  name     = each.value.zone_name
  comment  = each.value.type == "private" ? "Private hosted zone" : "Public hosted zone"
  force_destroy = each.value.type == "public" ? true : false
  tags = merge(local.tags, {
    ZoneType = each.value.type
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Private zone: attach primary VPC
resource "aws_route53_zone_association" "primary_vpc" {
  for_each = {
    for k, v in var.zones : k => v if v.type == "private"
  }
  zone_id = aws_route53_zone.this[each.key].id
  vpc_id  = aws_vpc.main.id
  vpc_region = data.aws_region.current.id
}

# Cross-VPC authorization for private zones (if dns_vpc provided)
resource "aws_route53_vpc_association_authorization" "cross_vpc" {
  for_each = {
    for k, v in var.zones : k => v if v.type == "private" && v.dns_vpc != null
  }
  zone_id = aws_route53_zone.this[each.key].id
  vpc_id  = each.value.dns_vpc.vpc_id
}

# Additional zone associations for association_zone_ids
resource "aws_route53_zone_association" "additional" {
  for_each = {
    for pair in flatten([
      for k, v in var.zones : [
        for zid in v.association_zone_ids : {
          key    = "${k}-${zid}"
          zone   = k
          zone_id = zid
        }
      ]
    ]) : pair.key => pair
  }
  zone_id = each.value.zone_id
  vpc_id  = aws_vpc.main.id
  vpc_region = data.aws_region.current.id
}

# Security Group for Resolver Endpoints (only if hub)
resource "aws_security_group" "resolver" {
  count       = var.is_hub ? 1 : 0
  name        = "resolver-endpoints-sg"
  description = "Security group for Route 53 Resolver endpoints"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.tags, {
    Name = "resolver-endpoints-sg"
  })
}

resource "aws_security_group_rule" "resolver_ingress_udp" {
  count             = var.is_hub ? 1 : 0
  type              = "ingress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.resolver[0].id
}

resource "aws_security_group_rule" "resolver_ingress_tcp" {
  count             = var.is_hub ? 1 : 0
  type              = "ingress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.resolver[0].id
}

resource "aws_security_group_rule" "resolver_egress_udp" {
  count             = var.is_hub ? 1 : 0
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.resolver[0].id
}

resource "aws_security_group_rule" "resolver_egress_tcp" {
  count             = var.is_hub ? 1 : 0
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.resolver[0].id
}

# Resolver Endpoints (Hub only) - direct resources
resource "aws_route53_resolver_endpoint" "inbound" {
  count  = var.is_hub ? 1 : 0
  name   = "inbound"
  direction = "INBOUND"

  security_group_ids = [aws_security_group.resolver[0].id]

  dynamic "ip_address" {
    for_each = aws_subnet.public[*].id
    content {
      subnet_id = ip_address.value
    }
  }

  protocols = ["DoH", "Do53"]
  tags = local.tags
}

resource "aws_route53_resolver_endpoint" "outbound" {
  count  = var.is_hub ? 1 : 0
  name   = "outbound"
  direction = "OUTBOUND"

  security_group_ids = [aws_security_group.resolver[0].id]

  dynamic "ip_address" {
    for_each = aws_subnet.public[*].id
    content {
      subnet_id = ip_address.value
    }
  }

  protocols = ["DoH", "Do53"]
  tags = local.tags
}

# Resolver Rules for private zones (Hub only)
resource "aws_route53_resolver_rule" "private_zones" {
  for_each = {
    for k, v in var.zones : k => v if v.type == "private" && var.is_hub
  }
  domain_name          = each.value.zone_name
  rule_type            = "FORWARD"
  resolver_endpoint_id = aws_route53_resolver_endpoint.outbound[0].id
  target_ip {
    ip   = tolist(aws_route53_resolver_endpoint.inbound[0].ip_address)[0].ip
    port = 53
  }
  depends_on = [aws_route53_resolver_endpoint.inbound, aws_route53_resolver_endpoint.outbound]
  tags = merge(local.tags, {
    ZoneName = each.value.zone_name
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Custom Resolver Rules (Hub only)
resource "aws_route53_resolver_rule" "custom" {
  for_each = {
    for pair in flatten([
      for k, v in var.zones : [
        for idx, rule in v.custom_resolver_rules : {
          key          = "${k}-${idx}"
          domain_name  = rule.domain_name
          target_ips   = rule.target_ips
        }
      ]
    ]) : pair.key => pair
    if var.is_hub
  }
  domain_name          = each.value.domain_name
  rule_type            = "FORWARD"
  resolver_endpoint_id = aws_route53_resolver_endpoint.outbound[0].id
  dynamic "target_ip" {
    for_each = each.value.target_ips
    content {
      ip   = target_ip.value
      port = 53
    }
  }
  depends_on = [aws_route53_resolver_endpoint.outbound]
  tags = local.tags
  lifecycle {
    prevent_destroy = true
  }
}

# RAM Resource Shares (Hub only)
resource "aws_ram_resource_share" "resolver_rule" {
  for_each = {
    for k, v in var.zones : k => v if v.type == "private" && var.is_hub && var.ram.enabled
  }
  name                      = "resolver-rule-share-${each.key}"
  allow_external_principals = var.ram.allow_external_principals
  tags = local.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_association" "resolver_rule" {
  for_each = {
    for k, v in var.zones : k => v if v.type == "private" && var.is_hub && var.ram.enabled
  }
  resource_share_arn = aws_ram_resource_share.resolver_rule[each.key].arn
  resource_arn       = aws_route53_resolver_rule.private_zones[each.key].arn
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_principal_association" "resolver_rule" {
  for_each = {
    for pair in flatten([
      for k, v in var.zones : [
        for principal in var.ram.principals : {
          key       = "${k}-${principal}"
          zone_key  = k
          principal = principal
        }
      ]
    ]) : pair.key => pair
    if var.is_hub && var.ram.enabled
  }
  resource_share_arn = aws_ram_resource_share.resolver_rule[each.value.zone_key].arn
  principal          = each.value.principal
  lifecycle {
    prevent_destroy = true
  }
}

# Spoke: Accept RAM shares and associate rules
resource "aws_ram_resource_share_accepter" "shared" {
  count = var.is_hub ? 0 : length(var.shared.resolver_rules)
  share_arn = var.shared.resolver_rules[count.index]
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_resolver_rule_association" "shared" {
  count = var.is_hub ? 0 : length(var.shared.resolver_rules)
  resolver_rule_id = aws_ram_resource_share_accepter.shared[count.index].resources[0]
  vpc_id = aws_vpc.main.id
  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-west-1"
}

provider "aws" {
  alias  = "destination"
  region = var.replication_destination_region
}

data "aws_partition" "current" {}
data "aws_canonical_user_id" "current" {}

resource "random_pet" "bucket" {}

locals {
  bucket_name         = var.bucket_name != null ? var.bucket_name : (var.bucket_prefix != null ? var.bucket_prefix : random_pet.bucket.id)
  create_bucket       = var.create_bucket && var.putin_khuylo
  logging_bucket_name = var.logging_bucket_name != null ? var.logging_bucket_name : "${local.bucket_name}-logs"
  has_policy_statements = var.elb_log_delivery_policy || var.alb_nlb_log_delivery_policy || var.deny_non_ssl_transport || var.deny_outdated_tls || var.custom_bucket_policy != null
}

variable "create_bucket" {
  description = "Whether to create the S3 bucket."
  type        = bool
  default     = true
}

variable "putin_khuylo" {
  description = "Boolean flag to conditionally create the bucket (default true)."
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "Name of the bucket. If not set, bucket_prefix will be used."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for the bucket name. Only used if bucket_name is not set."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Allow deletion of all objects in the bucket when destroying."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Whether to enable object lock on the bucket."
  type        = bool
  default     = false
}

variable "block_public_acls" {
  description = "Block public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership control rule."
  type        = string
  default     = "ObjectWriter"
}

variable "acl" {
  description = "Canned ACL to apply to the bucket. Use 'null' if using grants."
  type        = string
  default     = "private"
}

variable "grant" {
  description = "JSON-encoded grant configuration. Only used if acl is null."
  type        = string
  default     = null
}

variable "payer" {
  description = "Request payment configuration: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"
}

variable "acceleration_status" {
  description = "Acceleration status: Enabled or Suspended."
  type        = string
  default     = "Suspended"
}

variable "versioning_enabled" {
  description = "Enable versioning on the bucket."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete for versioning."
  type        = bool
  default     = false
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm (e.g., AES256, aws:kms)."
  type        = string
  default     = "aws:kms"
}

variable "kms_master_key_id" {
  description = "KMS key ID for SSE-KMS. Required if sse_algorithm is aws:kms."
  type        = string
  default     = null
}

variable "object_lock_retention_mode" {
  description = "Object lock retention mode (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = null
}

variable "object_lock_retention_days" {
  description = "Number of days for object lock retention."
  type        = number
  default     = null
}

variable "object_lock_retention_years" {
  description = "Number of years for object lock retention."
  type        = number
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules."
  type = list(object({
    id     = string
    status = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    noncurrent_version_transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "logging_bucket_name" {
  description = "Name of the logging bucket. If not set, defaults to <main_bucket>-logs."
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Prefix for log objects in the logging bucket."
  type        = string
  default     = ""
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = []
}

variable "intelligent_tiering_configurations" {
  description = "List of intelligent tiering configurations."
  type = list(object({
    name = string
    tiering = list(object({
      access_tier = string
      days        = number
    }))
  }))
  default = []
}

variable "replication_configuration" {
  description = "Configuration for cross-region replication. If null, replication is not configured."
  type = object({
    rules = list(object({
      id     = string
      status = string
      filter = optional(object({
        prefix = optional(string)
        tags   = optional(map(string))
      }))
      destination = object({
        bucket_arn               = optional(string)
        storage_class            = optional(string)
        replica_kms_key_id       = optional(string)
        access_control_translation = optional(object({
          owner = string
        }))
        account_id               = optional(string)
      })
      source_selection_criteria = optional(object({
        sse_kms_encrypted_objects = optional(bool)
      }))
      delete_marker_replication = optional(bool, false)
    }))
  })
  default = null
}

variable "replication_destination_region" {
  description = "AWS region for the replication destination bucket."
  type        = string
  default     = "us-west-2"
}

variable "elb_log_delivery_policy" {
  description = "Enable ELB log delivery policy statement."
  type        = bool
  default     = false
}

variable "alb_nlb_log_delivery_policy" {
  description = "Enable ALB/NLB log delivery policy statement."
  type        = bool
  default     = false
}

variable "deny_non_ssl_transport" {
  description = "Enable policy to deny non-SSL transport."
  type        = bool
  default     = false
}

variable "deny_outdated_tls" {
  description = "Enable policy to deny outdated TLS versions."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "JSON-encoded custom bucket policy."
  type        = string
  default     = null
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

# Main bucket
resource "aws_s3_bucket" "main" {
  count = local.create_bucket ? 1 : 0

  bucket             = var.bucket_name != null ? var.bucket_name : (var.bucket_prefix != null ? null : local.bucket_name)
  bucket_prefix      = var.bucket_name == null && var.bucket_prefix != null ? var.bucket_prefix : null
  force_destroy      = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = {
    Name = local.bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block for main bucket
resource "aws_s3_bucket_public_access_block" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets

  depends_on = [aws_s3_bucket_policy.main]
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.main]
}

# ACL
resource "aws_s3_bucket_acl" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = var.acl != null || var.grant == null ? [] : [1]
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      grant {
        grantee {
          type = jsondecode(var.grant).grantee.type
          id   = try(jsondecode(var.grant).grantee.id, null)
          uri  = try(jsondecode(var.grant).grantee.uri, null)
        }
        permission = jsondecode(var.grant).permission
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

# Request payment configuration
resource "aws_s3_bucket_request_payment_configuration" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id
  payer  = var.payer
}

# Accelerate configuration
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id
  status = var.acceleration_status
}

# Versioning
resource "aws_s3_bucket_versioning" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  versioning_configuration {
    status    = var.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? coalesce(var.kms_master_key_id, aws_kms_key.s3.arn) : null
    }
  }
}

# Object lock configuration (only if enabled)
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = local.create_bucket && var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  rule {
    default_retention {
      mode  = var.object_lock_retention_mode
      days  = var.object_lock_retention_days
      years = var.object_lock_retention_years
    }
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = local.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          dynamic "and" {
            for_each = filter.value.prefix != null && length(lookup(filter.value, "tags", {})) > 0 ? [1] : []
            content {
              prefix = filter.value.prefix
              tags   = filter.value.tags
            }
          }

          prefix = (filter.value.prefix != null && length(lookup(filter.value, "tags", {})) == 0) ? filter.value.prefix : null

          dynamic "tag" {
            for_each = filter.value.prefix == null ? lookup(filter.value, "tags", {}) : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# Logging bucket
resource "aws_s3_bucket" "logging" {
  count = local.create_bucket ? 1 : 0

  bucket        = local.logging_bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block for logging bucket
resource "aws_s3_bucket_public_access_block" "logging" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Logging bucket policy to allow S3 logging service to write objects
data "aws_iam_policy_document" "logging_bucket_policy" {
  count = local.create_bucket ? 1 : 0

  statement {
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.logging[0].id}/*"]
  }
}

resource "aws_s3_bucket_policy" "logging" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id
  policy = data.aws_iam_policy_document.logging_bucket_policy[0].json
}

# Bucket logging configuration
resource "aws_s3_bucket_logging" "main" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.logging_prefix
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "main" {
  count = local.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Intelligent tiering configuration
resource "aws_s3_bucket_intelligent_tiering_configuration" "main" {
  count = local.create_bucket ? length(var.intelligent_tiering_configurations) : 0

  bucket = aws_s3_bucket.main[0].id
  name   = var.intelligent_tiering_configurations[count.index].name

  dynamic "tiering" {
    for_each = var.intelligent_tiering_configurations[count.index].tiering
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Replication resources (if replication_configuration is provided)
locals {
  enable_replication = var.replication_configuration != null
}

# Destination bucket for replication
resource "aws_s3_bucket" "destination" {
  count = local.enable_replication ? 1 : 0
  provider = aws.destination

  bucket = "${local.bucket_name}-replica"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block for destination bucket
resource "aws_s3_bucket_public_access_block" "destination" {
  count = local.enable_replication ? 1 : 0
  provider = aws.destination

  bucket = aws_s3_bucket.destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key for destination bucket encryption
resource "aws_kms_key" "destination" {
  count = local.enable_replication ? 1 : 0
  provider = aws.destination

  description             = "KMS key for S3 replication destination bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

# SSE-KMS encryption for destination bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "destination" {
  count = local.enable_replication ? 1 : 0
  provider = aws.destination

  bucket = aws_s3_bucket.destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.destination[0].arn
    }
  }
}

resource "aws_s3_bucket_versioning" "destination" {
  count = local.enable_replication ? 1 : 0
  provider = aws.destination

  bucket = aws_s3_bucket.destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = local.enable_replication ? 1 : 0

  name = "s3-replication-role-${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy for replication
data "aws_iam_policy_document" "replication" {
  count = local.enable_replication ? 1 : 0

  statement {
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersionAcl"
    ]
    resources = [
      "${aws_s3_bucket.main[0].arn}/*"
    ]
  }

  statement {
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [
      "${aws_s3_bucket.destination[0].arn}/*"
    ]
  }
}

resource "aws_iam_policy" "replication" {
  count = local.enable_replication ? 1 : 0

  name   = "s3-replication-policy-${local.bucket_name}"
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.enable_replication ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Replication configuration
resource "aws_s3_bucket_replication_configuration" "main" {
  count = local.enable_replication ? 1 : 0

  bucket = aws_s3_bucket.main[0].id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          dynamic "and" {
            for_each = filter.value.prefix != null && length(lookup(filter.value, "tags", {})) > 0 ? [1] : []
            content {
              prefix = filter.value.prefix
              tags   = filter.value.tags
            }
          }

          prefix = (filter.value.prefix != null && length(lookup(filter.value, "tags", {})) == 0) ? filter.value.prefix : null

          dynamic "tag" {
            for_each = filter.value.prefix == null ? lookup(filter.value, "tags", {}) : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket        = coalesce(rule.value.destination.bucket_arn, aws_s3_bucket.destination[0].arn)
        storage_class = rule.value.destination.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [rule.value.destination.replica_kms_key_id] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = rule.value.destination.access_control_translation != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        account = rule.value.destination.account_id
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value ? "Enabled" : "Disabled"
            }
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }
    }
  }
}

# Combined bucket policy
data "aws_iam_policy_document" "combined" {
  count = local.create_bucket && local.has_policy_statements ? 1 : 0

  # ELB log delivery
  dynamic "statement" {
    for_each = var.elb_log_delivery_policy ? [1] : []
    content {
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.main[0].arn}/*"]
      principals {
        type        = "Service"
        identifiers = ["elasticloadbalancing.amazonaws.com"]
      }
      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = ["arn:${data.aws_partition.current.partition}:elasticloadbalancing:*:*:loadbalancer/*"]
      }
    }
  }

  # ALB/NLB log delivery
  dynamic "statement" {
    for_each = var.alb_nlb_log_delivery_policy ? [1] : []
    content {
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.main[0].arn}/*"]
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  # Deny non-SSL transport
  dynamic "statement" {
    for_each = var.deny_non_ssl_transport ? [1] : []
    content {
      effect = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.main[0].arn,
        "${aws_s3_bucket.main[0].arn}/*"
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
      principals {
        type        = "*"
        identifiers = ["*"]
      }
    }
  }

  # Deny outdated TLS versions
  dynamic "statement" {
    for_each = var.deny_outdated_tls ? [1] : []
    content {
      effect = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.main[0].arn,
        "${aws_s3_bucket.main[0].arn}/*"
      ]
      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
      principals {
        type        = "*"
        identifiers = ["*"]
      }
    }
  }

  # Custom user-defined policy
  dynamic "statement" {
    for_each = var.custom_bucket_policy != null ? [1] : []
    content {
      actions   = jsondecode(var.custom_bucket_policy).Action
      resources = jsondecode(var.custom_bucket_policy).Resource
      effect    = jsondecode(var.custom_bucket_policy).Effect
      principals {
        type        = jsondecode(var.custom_bucket_policy).Principal.Type
        identifiers = [jsondecode(var.custom_bucket_policy).Principal.Identifiers]
      }
      condition {
        test     = jsondecode(var.custom_bucket_policy).Condition.Test
        variable = jsondecode(var.custom_bucket_policy).Condition.Variable
        values   = jsondecode(var.custom_bucket_policy).Condition.Values
      }
    }
  }
}

# Bucket policy
resource "aws_s3_bucket_policy" "main" {
  count = local.create_bucket && local.has_policy_statements ? 1 : 0

  bucket = aws_s3_bucket.main[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Input variables
variable "target_stack" {
  description = "Target stack name"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Short git hash for the stack"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Long git hash (32 hex characters)"
  type        = string
  default     = "0123456789abcdef0123456789abcdef"
}

variable "stack_s3_bucket" {
  description = "S3 bucket for deployment artifacts"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "S3 object key for the dataset"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "S3 object key for the destigmatized dataset"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "S3 object key for the genomic dataset"
  type        = string
  default     = "genomic_dataset.csv"
}

# Data source for current account ID (static provider metadata)
data "aws_caller_identity" "current" {}

# Local values
locals {
  # Map of role identifier to the full prefix used in the role name
  role_prefixes = {
    wildfly    = "wildfly-deployment-s3"
    httpd      = "httpd-deployment-s3"
    auth_hpds  = "auth-hpds-deployment-s3"
    open_hpds  = "open-hpds-deployment-s3"
    dictionary = "dictionary-deployment-s3"
  }

  # Datasets assigned per role
  role_dataset_keys = {
    wildfly    = []
    httpd      = []
    auth_hpds  = [var.destigmatized_dataset_s3_object_key]
    open_hpds  = [var.genomic_dataset_s3_object_key]
    dictionary = [var.dataset_s3_object_key]
  }

  # Prefixes (folders) each role needs access to (excluding exact dataset keys)
  role_list_prefixes = {
    for k, v in local.role_prefixes : k => concat(
      ["artifacts/${k}/", "configs/${k}/", "ssl/${k}/", "common-security-tools/"]
    )
  }

  # For ListBucket we use StringLike with wildcard
  role_list_bucket_prefixes = {
    for k, v in local.role_prefixes : k => [for p in local.role_list_prefixes[k] : "${p}*"]
  }

  # Object ARNs for GetObject (prefixes + exact dataset keys)
  role_object_arns = {
    for k, v in local.role_prefixes : k => concat(
      [for p in local.role_list_prefixes[k] : "arn:aws:s3:::${var.stack_s3_bucket}/${p}*"],
      [for key in local.role_dataset_keys[k] : "arn:aws:s3:::${var.stack_s3_bucket}/${key}"]
    )
  }
}

# KMS customer managed key for S3 bucket encryption
resource "aws_kms_key" "s3_cmk" {
  description             = "Customer managed key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# S3 bucket for deployment artifacts
resource "aws_s3_bucket" "deployment" {
  bucket = var.stack_s3_bucket

  tags = {
    StackGitHashLong = var.stack_githash_long
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "deployment" {
  bucket = aws_s3_bucket.deployment.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "deployment" {
  bucket = aws_s3_bucket.deployment.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "deployment" {
  bucket = aws_s3_bucket.deployment.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
  }
}

# IAM roles and instance profiles
resource "aws_iam_role" "this" {
  for_each = local.role_prefixes

  name = "${each.value}-${var.target_stack}-${var.stack_githash}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "this" {
  for_each = local.role_prefixes

  name = "${each.value}-${var.target_stack}-${var.stack_githash}"
  role = aws_iam_role.this[each.key].name
}

# Attach managed policies
resource "aws_iam_role_policy_attachment" "cloudwatch_agent" {
  for_each = local.role_prefixes

  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance" {
  for_each = local.role_prefixes

  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Inline policies for each role
resource "aws_iam_role_policy" "inline" {
  for_each = local.role_prefixes

  name = "inline-policy"
  role = aws_iam_role.this[each.key].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      # ec2:CreateTags on instances
      [
        {
          Action   = "ec2:CreateTags"
          Effect   = "Allow"
          Resource = "arn:aws:ec2:*:*:instance/*"
        }
      ],
      # cloudwatch:PutMetricData globally
      [
        {
          Action   = "cloudwatch:PutMetricData"
          Effect   = "Allow"
          Resource = "*"
        }
      ],
      # s3:ListBucket on the deployment bucket with prefix conditions
      [
        {
          Action   = "s3:ListBucket"
          Effect   = "Allow"
          Resource = aws_s3_bucket.deployment.arn
          Condition = {
            StringLike = {
              "s3:prefix" = local.role_list_bucket_prefixes[each.key]
            }
          }
        }
      ],
      # s3:GetObject on the specific object paths
      [
        {
          Action   = "s3:GetObject"
          Effect   = "Allow"
          Resource = local.role_object_arns[each.key]
        }
      ]
    )
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "create_module" {
  description = "Toggle to create all resources in this module"
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "Whether to create a new security group (true) or use an existing one (false)"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID where the security group will reside. If null and a new security group is created, a VPC will be auto-created."
  type        = string
  default     = null
}

variable "vpc_cidr_block" {
  description = "CIDR block for the auto-created VPC (only used when vpc_id is null and a new security group is created)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_sg_id" {
  description = "Existing security group ID when create_new_sg is false"
  type        = string
  default     = ""

  validation {
    condition     = var.create_new_sg || (var.create_module && length(var.existing_sg_id) > 0)
    error_message = "existing_sg_id must be provided when create_new_sg is false and create_module is true."
  }
}

variable "sg_name" {
  description = "Name of the security group"
  type        = string
  default     = "terraform-sg"
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke rules on security group delete"
  type        = bool
  default     = true
}

variable "create_before_destroy" {
  description = "Whether to use create_before_destroy lifecycle on the security group"
  type        = bool
  default     = true
}

variable "ingress_rules_new" {
  description = "Ingress rules for the newly created security group"
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules_new : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_new" {
  description = <<-EOT
    Egress rules for the newly created security group.
    IMPORTANT: No default egress rule is created. If this list is empty, outbound traffic
    will be blocked by default. You must provide at least one egress rule to allow
    outbound traffic (e.g., [{ protocol = "-1", from_port = 0, to_port = 0, cidr_ipv4 = "0.0.0.0/0" }]).
  EOT
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules_new : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "ingress_rules_existing" {
  description = "Ingress rules for the existing security group"
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules_existing : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_existing" {
  description = <<-EOT
    Egress rules for the existing security group.
    IMPORTANT: No default egress rule is created. If this list is empty, outbound traffic
    will be blocked by default. You must provide at least one egress rule to allow
    outbound traffic (e.g., [{ protocol = "-1", from_port = 0, to_port = 0, cidr_ipv4 = "0.0.0.0/0" }]).
  EOT
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules_existing : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create an AWS-managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the managed prefix list"
  type        = string
  default     = ""
}

variable "address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "List of entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "existing_prefix_list_ids" {
  description = "List of existing prefix list IDs to use instead of creating a new one"
  type        = list(string)
  default     = []
}

# Locals
locals {
  # Auto-create a VPC only when: module is enabled, a new SG is created, and no vpc_id is supplied
  create_vpc = var.create_module && var.create_new_sg && var.vpc_id == null

  # Select the VPC ID: use user-supplied value, or the auto-created VPC, or null (for existing-group-only paths)
  vpc_id = var.create_module && var.create_new_sg ? (
    var.vpc_id != null ? var.vpc_id : aws_vpc.this[0].id
  ) : null

  # SG ID for the new security group
  sg_id = var.create_module && var.create_new_sg ? (
    var.create_before_destroy ? aws_security_group.this_cbd_true[0].id : aws_security_group.this_cbd_false[0].id
  ) : null
}

# Auto-created VPC for greenfield deployments
resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.sg_name != "" ? "${var.sg_name}-vpc" : "terraform-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Security Group (new) - with create_before_destroy = true
resource "aws_security_group" "this_cbd_true" {
  count = var.create_module && var.create_new_sg && var.create_before_destroy ? 1 : 0

  name        = var.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id

  tags = {
    Name = var.sg_name
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = [description, name]
  }

  revoke_rules_on_delete = var.revoke_rules_on_delete
}

# Security Group (new) - with create_before_destroy = false
resource "aws_security_group" "this_cbd_false" {
  count = var.create_module && var.create_new_sg && !var.create_before_destroy ? 1 : 0

  name        = var.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id

  tags = {
    Name = var.sg_name
  }

  lifecycle {
    create_before_destroy = false
    ignore_changes        = [description, name]
  }

  revoke_rules_on_delete = var.revoke_rules_on_delete
}

# Ingress rules for new SG
resource "aws_security_group_rule" "ingress_new" {
  count = var.create_module && var.create_new_sg ? length(var.ingress_rules_new) : 0

  security_group_id = local.sg_id
  type              = "ingress"
  protocol          = var.ingress_rules_new[count.index].protocol
  from_port         = var.ingress_rules_new[count.index].from_port
  to_port           = var.ingress_rules_new[count.index].to_port
  description       = var.ingress_rules_new[count.index].description

  cidr_blocks              = var.ingress_rules_new[count.index].cidr_ipv4 != null ? [var.ingress_rules_new[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.ingress_rules_new[count.index].cidr_ipv6 != null ? [var.ingress_rules_new[count.index].cidr_ipv6] : null
  source_security_group_id = var.ingress_rules_new[count.index].source_security_group_id
  prefix_list_ids          = var.ingress_rules_new[count.index].prefix_list_id != null ? [var.ingress_rules_new[count.index].prefix_list_id] : null
}

# Egress rules for new SG
resource "aws_security_group_rule" "egress_new" {
  count = var.create_module && var.create_new_sg ? length(var.egress_rules_new) : 0

  security_group_id = local.sg_id
  type              = "egress"
  protocol          = var.egress_rules_new[count.index].protocol
  from_port         = var.egress_rules_new[count.index].from_port
  to_port           = var.egress_rules_new[count.index].to_port
  description       = var.egress_rules_new[count.index].description

  cidr_blocks              = var.egress_rules_new[count.index].cidr_ipv4 != null ? [var.egress_rules_new[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.egress_rules_new[count.index].cidr_ipv6 != null ? [var.egress_rules_new[count.index].cidr_ipv6] : null
  source_security_group_id = var.egress_rules_new[count.index].source_security_group_id
  prefix_list_ids          = var.egress_rules_new[count.index].prefix_list_id != null ? [var.egress_rules_new[count.index].prefix_list_id] : null
}

# Ingress rules for existing SG
resource "aws_security_group_rule" "ingress_existing" {
  count = var.create_module && !var.create_new_sg ? length(var.ingress_rules_existing) : 0

  security_group_id = var.existing_sg_id
  type              = "ingress"
  protocol          = var.ingress_rules_existing[count.index].protocol
  from_port         = var.ingress_rules_existing[count.index].from_port
  to_port           = var.ingress_rules_existing[count.index].to_port
  description       = var.ingress_rules_existing[count.index].description

  cidr_blocks              = var.ingress_rules_existing[count.index].cidr_ipv4 != null ? [var.ingress_rules_existing[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.ingress_rules_existing[count.index].cidr_ipv6 != null ? [var.ingress_rules_existing[count.index].cidr_ipv6] : null
  source_security_group_id = var.ingress_rules_existing[count.index].source_security_group_id
  prefix_list_ids          = var.ingress_rules_existing[count.index].prefix_list_id != null ? [var.ingress_rules_existing[count.index].prefix_list_id] : null
}

# Egress rules for existing SG
resource "aws_security_group_rule" "egress_existing" {
  count = var.create_module && !var.create_new_sg ? length(var.egress_rules_existing) : 0

  security_group_id = var.existing_sg_id
  type              = "egress"
  protocol          = var.egress_rules_existing[count.index].protocol
  from_port         = var.egress_rules_existing[count.index].from_port
  to_port           = var.egress_rules_existing[count.index].to_port
  description       = var.egress_rules_existing[count.index].description

  cidr_blocks              = var.egress_rules_existing[count.index].cidr_ipv4 != null ? [var.egress_rules_existing[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.egress_rules_existing[count.index].cidr_ipv6 != null ? [var.egress_rules_existing[count.index].cidr_ipv6] : null
  source_security_group_id = var.egress_rules_existing[count.index].source_security_group_id
  prefix_list_ids          = var.egress_rules_existing[count.index].prefix_list_id != null ? [var.egress_rules_existing[count.index].prefix_list_id] : null
}

# Managed Prefix List
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }
}

# Outputs
output "sg_id" {
  description = "ID of the security group (created or existing)"
  value = var.create_module ? (
    var.create_new_sg ? local.sg_id : var.existing_sg_id
  ) : null
}

output "vpc_id" {
  description = "VPC ID (auto-created or user-supplied) used by the security group"
  value = var.create_module && var.create_new_sg ? local.vpc_id : null
}

output "prefix_list_id" {
  description = "ID of the created prefix list, if any"
  value = var.create_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? (
    aws_ec2_managed_prefix_list.this[0].id
  ) : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------
variable "service_prefix" {
  description = "Prefix for resource naming"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "STAGE"
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Domain identity
variable "domain_identity_domain" {
  description = "Domain for SES domain identity"
  type        = string
  default     = "example.com"
}

# Email identity
variable "email_identity_email" {
  description = "Email address for SES email identity"
  type        = string
  default     = "admin@example.com"
}

# Identity policy
variable "identity_policy_name" {
  description = "Custom name for the identity policy (overrides default naming)"
  type        = string
  default     = ""
}

variable "identity_policy_principal" {
  description = "Principal for the identity policy statement"
  type        = string
  default     = "AWS"
}

variable "identity_policy_actions" {
  description = "Allowed SES actions for the identity"
  type        = list(string)
  default     = ["ses:SendEmail", "ses:SendRawEmail"]
}

# Configuration set
variable "configuration_set_name" {
  description = "Custom name for the configuration set (overrides default naming)"
  type        = string
  default     = ""
}

variable "configuration_set_reputation_metrics_enabled" {
  description = "Enable reputation metrics for the configuration set"
  type        = bool
  default     = true
}

variable "configuration_set_sending_enabled" {
  description = "Enable sending for the configuration set"
  type        = bool
  default     = true
}

variable "configuration_set_tls_policy" {
  description = "TLS policy for the configuration set. Valid values: REQUIRE or OPTIONAL."
  type        = string
  default     = "REQUIRE"

  validation {
    condition     = contains(["REQUIRE", "OPTIONAL"], var.configuration_set_tls_policy)
    error_message = "Valid values for tls_policy are REQUIRE or OPTIONAL."
  }
}

# Event destination
variable "event_destination_name" {
  description = "Custom name for the event destination (overrides default naming)"
  type        = string
  default     = ""
}

variable "event_destination_types" {
  description = "List of event types to send to the destination"
  type        = list(string)
  default     = ["bounce", "complaint", "delivery"]
}

variable "event_destination_cloudwatch_log_group_name" {
  description = "Custom log group name for CloudWatch destination (defaults to naming convention)"
  type        = string
  default     = ""
}

variable "event_destination_cloudwatch_log_retention" {
  description = "Retention days for CloudWatch log group"
  type        = number
  default     = 14
}

variable "event_destination_kinesis_firehose_stream_name" {
  description = "Custom Firehose stream name for event destination (defaults to naming convention)"
  type        = string
  default     = ""
}

variable "event_destination_sns_topic_name" {
  description = "Custom SNS topic name for event destination (defaults to naming convention)"
  type        = string
  default     = ""
}

variable "event_destination_destination_type" {
  description = "Destination type: cloudwatch, kinesis_firehose, or sns"
  type        = string
  default     = "sns"
}

# MAIL FROM domain
variable "mail_from_domain_prefix" {
  description = "Prefix for MAIL FROM domain (e.g., 'bounce.')"
  type        = string
  default     = "bounce."
}

variable "mail_from_domain_custom" {
  description = "Custom MAIL FROM domain (overrides the default prefix concatenation)"
  type        = string
  default     = ""
}

variable "mail_from_behavior_on_mx_failure" {
  description = "Behavior on MX failure: UseDefaultValue or RejectMessage"
  type        = string
  default     = "UseDefaultValue"
}

# Receipt rule set
variable "receipt_rule_set_name" {
  description = "Custom name for the receipt rule set (overrides default naming)"
  type        = string
  default     = ""
}

# Receipt rule
variable "receipt_rule_name" {
  description = "Custom name for the receipt rule (overrides default naming)"
  type        = string
  default     = ""
}

variable "receipt_rule_recipients" {
  description = "List of recipients for the receipt rule"
  type        = list(string)
  default     = []
}

variable "receipt_rule_enabled" {
  description = "Enable the receipt rule"
  type        = bool
  default     = true
}

variable "receipt_rule_scan_enabled" {
  description = "Enable scanning of incoming emails"
  type        = bool
  default     = true
}

variable "receipt_rule_tls_policy" {
  description = "TLS policy for the receipt rule: Require or Optional"
  type        = string
  default     = "Optional"
}

variable "receipt_rule_actions" {
  description = "List of actions for the receipt rule. Each action is an object with type and corresponding attributes."
  type = list(object({
    type = string # add_header, bounce, lambda, s3, sns, stop, workmail
    # add_header
    header_name  = optional(string)
    header_value = optional(string)
    # bounce
    bounce_message        = optional(string)
    bounce_sender         = optional(string)
    bounce_smtp_reply_code = optional(string)
    bounce_status_code    = optional(string)
    topic_arn             = optional(string)
    # lambda
    function_arn    = optional(string)
    invocation_type = optional(string)
    # s3
    bucket_name       = optional(string)
    object_key_prefix = optional(string)
    kms_key_arn       = optional(string)
    # sns
    sns_topic_arn = optional(string)
    encoding      = optional(string)
    # stop
    stop_scope = optional(string)
    # workmail
    organization_arn = optional(string)
  }))
  default = []
}

# Receipt filter
variable "receipt_filter_name" {
  description = "Custom name for the receipt filter (overrides default naming)"
  type        = string
  default     = ""
}

variable "receipt_filter_cidr" {
  description = "CIDR block for the receipt filter"
  type        = string
  default     = "0.0.0.0/0"
}

variable "receipt_filter_policy" {
  description = "Policy for the receipt filter: Allow or Block"
  type        = string
  default     = "Block"
}

# Active rule set
variable "active_rule_set_name" {
  description = "Custom name for the active rule set (overrides default naming, but must match a rule set name)"
  type        = string
  default     = ""
}

# Email template
variable "email_template_name" {
  description = "Custom name for the email template (overrides default naming)"
  type        = string
  default     = ""
}

variable "email_template_subject" {
  description = "Subject line of the email template"
  type        = string
  default     = "Hello from SES"
}

variable "email_template_html" {
  description = "HTML body of the email template"
  type        = string
  default     = "<h1>Hello</h1>"
}

variable "email_template_text" {
  description = "Text body of the email template"
  type        = string
  default     = "Hello"
}

# Notification topics
variable "notification_topic_bounce_name" {
  description = "Custom name for the bounce notification SNS topic (overrides default naming)"
  type        = string
  default     = ""
}

variable "notification_topic_complaint_name" {
  description = "Custom name for the complaint notification SNS topic (overrides default naming)"
  type        = string
  default     = ""
}

variable "notification_topic_delivery_name" {
  description = "Custom name for the delivery notification SNS topic (overrides default naming)"
  type        = string
  default     = ""
}

# Boolean toggles
variable "create_domain_identity" {
  description = "Create SES domain identity"
  type        = bool
  default     = true
}

variable "create_email_identity" {
  description = "Create SES email identity"
  type        = bool
  default     = false
}

variable "create_identity_policy" {
  description = "Create SES identity policy"
  type        = bool
  default     = false
}

variable "create_domain_dkim" {
  description = "Create SES domain DKIM"
  type        = bool
  default     = false
}

variable "create_domain_identity_verification" {
  description = "Create SES domain identity verification"
  type        = bool
  default     = false
}

variable "create_configuration_set" {
  description = "Create SES configuration set"
  type        = bool
  default     = true
}

variable "create_event_destination" {
  description = "Create SES configuration set event destination"
  type        = bool
  default     = false
}

variable "create_mail_from_domain" {
  description = "Create SES MAIL FROM domain"
  type        = bool
  default     = false
}

variable "create_receipt_rule_set" {
  description = "Create SES receipt rule set"
  type        = bool
  default     = false
}

variable "create_receipt_rule" {
  description = "Create SES receipt rule"
  type        = bool
  default     = false
}

variable "create_receipt_filter" {
  description = "Create SES receipt filter"
  type        = bool
  default     = false
}

variable "create_active_rule_set" {
  description = "Create SES active receipt rule set"
  type        = bool
  default     = false
}

variable "create_email_template" {
  description = "Create SES email template"
  type        = bool
  default     = false
}

variable "create_notification_topic" {
  description = "Create SNS topics for bounce, complaint, delivery notifications"
  type        = bool
  default     = false
}

# --------------------------------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------------------------------
locals {
  prefix = lower(var.service_prefix)
  env    = lower(var.environment)

  # Default naming conventions
  identity_policy_name      = var.identity_policy_name != "" ? var.identity_policy_name : "${local.prefix}-ses-identity-policy-${local.env}"
  configuration_set_name    = var.configuration_set_name != "" ? var.configuration_set_name : "${local.prefix}-ses-configuration-set-${local.env}"
  event_destination_name    = var.event_destination_name != "" ? var.event_destination_name : "${local.prefix}-ses-event-destination-${local.env}"
  receipt_rule_set_name     = var.receipt_rule_set_name != "" ? var.receipt_rule_set_name : "${local.prefix}-ses-receipt-rule-set-${local.env}"
  receipt_rule_name         = var.receipt_rule_name != "" ? var.receipt_rule_name : "${local.prefix}-ses-receipt-rule-${local.env}"
  receipt_filter_name       = var.receipt_filter_name != "" ? var.receipt_filter_name : "${local.prefix}-ses-receipt-filter-${local.env}"
  active_rule_set_name      = var.active_rule_set_name != "" ? var.active_rule_set_name : local.receipt_rule_set_name
  email_template_name       = var.email_template_name != "" ? var.email_template_name : "${local.prefix}-ses-template-${local.env}"
  bounce_topic_name         = var.notification_topic_bounce_name != "" ? var.notification_topic_bounce_name : "${local.prefix}-ses-bounce-${local.env}"
  complaint_topic_name      = var.notification_topic_complaint_name != "" ? var.notification_topic_complaint_name : "${local.prefix}-ses-complaint-${local.env}"
  delivery_topic_name       = var.notification_topic_delivery_name != "" ? var.notification_topic_delivery_name : "${local.prefix}-ses-delivery-${local.env}"
  cloudwatch_log_group_name = var.event_destination_cloudwatch_log_group_name != "" ? var.event_destination_cloudwatch_log_group_name : "${local.prefix}-ses-event-destination-logs-${local.env}"
  firehose_stream_name      = var.event_destination_kinesis_firehose_stream_name != "" ? var.event_destination_kinesis_firehose_stream_name : "${local.prefix}-ses-firehose-${local.env}"
  sns_topic_name            = var.event_destination_sns_topic_name != "" ? var.event_destination_sns_topic_name : "${local.prefix}-ses-event-destination-sns-${local.env}"

  # Mail from domain
  mail_from_domain = var.mail_from_domain_custom != "" ? var.mail_from_domain_custom : "${var.mail_from_domain_prefix}${var.domain_identity_domain}"

  # Common tags
  common_tags = merge(var.tags, {
    ServicePrefix = var.service_prefix
    Environment   = var.environment
  })
}

# --------------------------------------------------------------------------------------------------
# Data Sources
# --------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# --------------------------------------------------------------------------------------------------
# SES Domain Identity
# --------------------------------------------------------------------------------------------------
resource "aws_ses_domain_identity" "main" {
  count  = var.create_domain_identity ? 1 : 0
  domain = var.domain_identity_domain
}

# --------------------------------------------------------------------------------------------------
# SES Email Identity
# --------------------------------------------------------------------------------------------------
resource "aws_ses_email_identity" "main" {
  count = var.create_email_identity ? 1 : 0
  email = var.email_identity_email
}

# --------------------------------------------------------------------------------------------------
# SES Identity Policy
# Attach to either domain or email identity based on which is created.
# Prefer domain identity if both exist.
# --------------------------------------------------------------------------------------------------
resource "aws_ses_identity_policy" "main" {
  count = var.create_identity_policy ? 1 : 0

  identity = try(
    aws_ses_domain_identity.main[0].arn,
    aws_ses_email_identity.main[0].arn,
    ""
  )
  name    = local.identity_policy_name
  policy  = data.aws_iam_policy_document.identity_policy[0].json
}

data "aws_iam_policy_document" "identity_policy" {
  count = var.create_identity_policy ? 1 : 0

  statement {
    sid    = "SESIdentityPolicy"
    effect = "Allow"
    principals {
      identifiers = [var.identity_policy_principal]
      type        = "AWS"
    }
    actions   = var.identity_policy_actions
    resources = [
      try(
        aws_ses_domain_identity.main[0].arn,
        aws_ses_email_identity.main[0].arn,
        "arn:${data.aws_partition.current.partition}:ses:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identity/*"
      )
    ]
  }
}

# --------------------------------------------------------------------------------------------------
# SES Domain DKIM
# --------------------------------------------------------------------------------------------------
resource "aws_ses_domain_dkim" "main" {
  count = var.create_domain_dkim ? 1 : 0
  domain = aws_ses_domain_identity.main[0].domain
}

# --------------------------------------------------------------------------------------------------
# SES Domain Identity Verification
# --------------------------------------------------------------------------------------------------
resource "aws_ses_domain_identity_verification" "main" {
  count = var.create_domain_identity_verification ? 1 : 0
  domain = aws_ses_domain_identity.main[0].domain
  depends_on = [
    aws_ses_domain_dkim.main
  ]
}

# --------------------------------------------------------------------------------------------------
# SES Configuration Set (v2)
# --------------------------------------------------------------------------------------------------
resource "aws_sesv2_configuration_set" "main" {
  count = var.create_configuration_set ? 1 : 0
  configuration_set_name = local.configuration_set_name

  delivery_options {
    tls_policy = var.configuration_set_tls_policy
  }

  reputation_options {
    reputation_metrics_enabled = var.configuration_set_reputation_metrics_enabled
  }

  sending_options {
    sending_enabled = var.configuration_set_sending_enabled
  }
}

# --------------------------------------------------------------------------------------------------
# SES Configuration Set Event Destination (v2)
# --------------------------------------------------------------------------------------------------
resource "aws_sesv2_configuration_set_event_destination" "main" {
  count = var.create_event_destination ? 1 : 0

  configuration_set_name = aws_sesv2_configuration_set.main[0].configuration_set_name
  event_destination_name = local.event_destination_name

  event_destination {
    enabled              = true
    matching_event_types = var.event_destination_types

    dynamic "cloud_watch_destination" {
      for_each = var.event_destination_destination_type == "cloudwatch" ? [1] : []
      content {
        dimension_configuration {
          default_dimension_value = "default"
          dimension_name          = "ses"
          dimension_value_source  = "messageTag"
        }
      }
    }

    dynamic "kinesis_firehose_destination" {
      for_each = var.event_destination_destination_type == "kinesis_firehose" ? [1] : []
      content {
        delivery_stream_arn = aws_kinesis_firehose_delivery_stream.main[0].arn
        iam_role_arn        = aws_iam_role.firehose_event_destination[0].arn
      }
    }

    dynamic "sns_destination" {
      for_each = var.event_destination_destination_type == "sns" ? [1] : []
      content {
        topic_arn = aws_sns_topic.event_destination[0].arn
      }
    }
  }
}

# CloudWatch Log Group for event destination
resource "aws_cloudwatch_log_group" "event_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "cloudwatch" ? 1 : 0
  name  = local.cloudwatch_log_group_name
  retention_in_days = var.event_destination_cloudwatch_log_retention
  tags = merge(local.common_tags, { Name = local.cloudwatch_log_group_name })
}

# Kinesis Firehose Delivery Stream for event destination
resource "aws_kinesis_firehose_delivery_stream" "main" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  name        = local.firehose_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_event_destination[0].arn
    bucket_arn = aws_s3_bucket.firehose_destination[0].arn
    buffering_size     = 10
    buffering_interval = 60
    compression_format = "GZIP"
  }
}

# S3 bucket for Firehose destination
resource "aws_s3_bucket" "firehose_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  bucket = "${local.firehose_stream_name}-bucket"

  lifecycle {
    prevent_destroy = true
  }
  tags = merge(local.common_tags, { Name = "${local.firehose_stream_name}-bucket" })
}

resource "aws_s3_bucket_public_access_block" "firehose_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  bucket = aws_s3_bucket.firehose_destination[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  bucket = aws_s3_bucket.firehose_destination[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  bucket = aws_s3_bucket.firehose_destination[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for Firehose event destination
resource "aws_iam_role" "firehose_event_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  name  = "${local.firehose_stream_name}-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role[0].json
  tags = merge(local.common_tags, { Name = "${local.firehose_stream_name}-role" })
}

data "aws_iam_policy_document" "firehose_assume_role" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  statement {
    effect = "Allow"
    principals {
      identifiers = ["firehose.amazonaws.com"]
      type        = "Service"
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy" "firehose_event_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  name   = "${local.firehose_stream_name}-policy"
  role   = aws_iam_role.firehose_event_destination[0].id
  policy = data.aws_iam_policy_document.firehose_event_destination[0].json
}

data "aws_iam_policy_document" "firehose_event_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "kinesis_firehose" ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject"
    ]
    resources = [
      aws_s3_bucket.firehose_destination[0].arn,
      "${aws_s3_bucket.firehose_destination[0].arn}/*"
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }
}

# SNS topic for event destination
resource "aws_sns_topic" "event_destination" {
  count = var.create_event_destination && var.event_destination_destination_type == "sns" ? 1 : 0
  name  = local.sns_topic_name
  tags = merge(local.common_tags, { Name = local.sns_topic_name })
}

# --------------------------------------------------------------------------------------------------
# SES MAIL FROM Domain (classic)
# --------------------------------------------------------------------------------------------------
resource "aws_ses_domain_mail_from" "main" {
  count = var.create_mail_from_domain ? 1 : 0
  domain           = aws_ses_domain_identity.main[0].domain
  mail_from_domain = local.mail_from_domain
  behavior_on_mx_failure = var.mail_from_behavior_on_mx_failure
}

# --------------------------------------------------------------------------------------------------
# SES Receipt Rule Set
# --------------------------------------------------------------------------------------------------
resource "aws_ses_receipt_rule_set" "main" {
  count = var.create_receipt_rule_set ? 1 : 0
  rule_set_name = local.receipt_rule_set_name
}

# --------------------------------------------------------------------------------------------------
# SES Receipt Rule
# --------------------------------------------------------------------------------------------------
resource "aws_ses_receipt_rule" "main" {
  count = var.create_receipt_rule ? 1 : 0
  name          = local.receipt_rule_name
  rule_set_name = aws_ses_receipt_rule_set.main[0].rule_set_name
  recipients    = var.receipt_rule_recipients
  enabled       = var.receipt_rule_enabled
  scan_enabled  = var.receipt_rule_scan_enabled
  tls_policy    = var.receipt_rule_tls_policy

  dynamic "add_header_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "add_header"]
    content {
      header_name  = add_header_action.value.header_name
      header_value = add_header_action.value.header_value
      position     = index(var.receipt_rule_actions, add_header_action.value) + 1
    }
  }

  dynamic "bounce_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "bounce"]
    content {
      message          = bounce_action.value.bounce_message
      sender           = bounce_action.value.bounce_sender
      smtp_reply_code  = bounce_action.value.bounce_smtp_reply_code
      status_code      = bounce_action.value.bounce_status_code
      topic_arn        = bounce_action.value.topic_arn
      position         = index(var.receipt_rule_actions, bounce_action.value) + 1
    }
  }

  dynamic "lambda_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "lambda"]
    content {
      function_arn    = lambda_action.value.function_arn
      invocation_type = lambda_action.value.invocation_type
      topic_arn       = lambda_action.value.topic_arn
      position        = index(var.receipt_rule_actions, lambda_action.value) + 1
    }
  }

  dynamic "s3_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "s3"]
    content {
      bucket_name       = s3_action.value.bucket_name
      object_key_prefix = s3_action.value.object_key_prefix
      topic_arn         = s3_action.value.topic_arn
      kms_key_arn       = s3_action.value.kms_key_arn
      position          = index(var.receipt_rule_actions, s3_action.value) + 1
    }
  }

  dynamic "sns_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "sns"]
    content {
      topic_arn = sns_action.value.sns_topic_arn
      encoding  = sns_action.value.encoding
      position  = index(var.receipt_rule_actions, sns_action.value) + 1
    }
  }

  dynamic "stop_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "stop"]
    content {
      scope     = stop_action.value.stop_scope
      topic_arn = stop_action.value.topic_arn
      position  = index(var.receipt_rule_actions, stop_action.value) + 1
    }
  }

  dynamic "workmail_action" {
    for_each = [for a in var.receipt_rule_actions : a if a.type == "workmail"]
    content {
      organization_arn = workmail_action.value.organization_arn
      topic_arn        = workmail_action.value.topic_arn
      position         = index(var.receipt_rule_actions, workmail_action.value) + 1
    }
  }
}

# --------------------------------------------------------------------------------------------------
# SES Receipt Filter
# --------------------------------------------------------------------------------------------------
resource "aws_ses_receipt_filter" "main" {
  count = var.create_receipt_filter ? 1 : 0
  name   = local.receipt_filter_name
  cidr   = var.receipt_filter_cidr
  policy = var.receipt_filter_policy
}

# --------------------------------------------------------------------------------------------------
# SES Active Receipt Rule Set
# --------------------------------------------------------------------------------------------------
resource "aws_ses_active_receipt_rule_set" "main" {
  count = var.create_active_rule_set ? 1 : 0
  rule_set_name = local.active_rule_set_name
}

# --------------------------------------------------------------------------------------------------
# SES Email Template
# --------------------------------------------------------------------------------------------------
resource "aws_ses_template" "main" {
  count = var.create_email_template ? 1 : 0
  name = local.email_template_name
  subject = var.email_template_subject
  html    = var.email_template_html
  text    = var.email_template_text
}

# --------------------------------------------------------------------------------------------------
# SNS Topics for Bounce, Complaint, Delivery Notifications
# --------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "bounce" {
  count = var.create_notification_topic ? 1 : 0
  name  = local.bounce_topic_name
  tags  = merge(local.common_tags, { Name = local.bounce_topic_name })
}

resource "aws_sns_topic" "complaint" {
  count = var.create_notification_topic ? 1 : 0
  name  = local.complaint_topic_name
  tags  = merge(local.common_tags, { Name = local.complaint_topic_name })
}

resource "aws_sns_topic" "delivery" {
  count = var.create_notification_topic ? 1 : 0
  name  = local.delivery_topic_name
  tags  = merge(local.common_tags, { Name = local.delivery_topic_name })
}

# --------------------------------------------------------------------------------------------------
# SES Identity Notification Topic Associations
# --------------------------------------------------------------------------------------------------
resource "aws_ses_identity_notification_topic" "bounce" {
  count = var.create_notification_topic ? 1 : 0

  identity          = try(aws_ses_domain_identity.main[0].arn, aws_ses_email_identity.main[0].arn, "")
  notification_type = "Bounce"
  topic_arn         = aws_sns_topic.bounce[0].arn

  depends_on = [aws_sns_topic.bounce]
}

resource "aws_ses_identity_notification_topic" "complaint" {
  count = var.create_notification_topic ? 1 : 0

  identity          = try(aws_ses_domain_identity.main[0].arn, aws_ses_email_identity.main[0].arn, "")
  notification_type = "Complaint"
  topic_arn         = aws_sns_topic.complaint[0].arn

  depends_on = [aws_sns_topic.complaint]
}

resource "aws_ses_identity_notification_topic" "delivery" {
  count = var.create_notification_topic ? 1 : 0

  identity          = try(aws_ses_domain_identity.main[0].arn, aws_ses_email_identity.main[0].arn, "")
  notification_type = "Delivery"
  topic_arn         = aws_sns_topic.delivery[0].arn

  depends_on = [aws_sns_topic.delivery]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Variables
variable "container_image" {
  description = "Default container image name"
  type        = string
  default     = "nginx"
}

variable "workload_name" {
  description = "Base name for all resources, defaults to container_image"
  type        = string
  default     = null
}

variable "secrets" {
  description = "Map of secret names to values to be stored in SSM Parameter Store"
  type        = map(string)
  default     = {}
}

variable "env_vars" {
  description = "List of environment variable objects for the container"
  type = list(object({
    name  = string
    value = string
  }))
  default = []
}

variable "container_insights" {
  description = "Enable Container Insights for the ECS cluster"
  type        = bool
  default     = true
}

variable "log_retention_days" {
  description = "CloudWatch Log Group retention in days"
  type        = number
  default     = 365
}

variable "cpu" {
  description = "Task CPU units (256, 512, 1024, 2048, 4096)"
  type        = number
  default     = 256
}

variable "memory" {
  description = "Task memory in MiB (512, 1024, 2048, 3072, 4096, etc.)"
  type        = number
  default     = 512
}

variable "enable_load_balancing" {
  description = "Toggle ALB integration"
  type        = bool
  default     = true
}

variable "health_check_path" {
  description = "Health check path for ALB target group"
  type        = string
  default     = "/"
}

variable "health_check_matcher" {
  description = "HTTP codes to use when checking for a successful response from a target"
  type        = string
  default     = "200,301,302"
}

variable "health_check_timeout" {
  description = "Amount of time to wait for a health check response"
  type        = number
  default     = 5
}

variable "health_check_interval" {
  description = "Approximate amount of time between health checks"
  type        = number
  default     = 30
}

variable "deregistration_delay" {
  description = "Amount time for targets to drain connections"
  type        = number
  default     = 300
}

variable "stickiness_type" {
  description = "Stickiness type (lb_cookie, app_cookie)"
  type        = string
  default     = "lb_cookie"
}

variable "stickiness_cookie_duration" {
  description = "Cookie duration in seconds"
  type        = number
  default     = 86400
}

variable "host_header" {
  description = "Host header condition for the listener rule"
  type        = list(string)
  default     = ["*"]
}

variable "min_capacity" {
  description = "Minimum number of tasks"
  type        = number
  default     = 1
}

variable "max_capacity" {
  description = "Maximum number of tasks"
  type        = number
  default     = 1
}

variable "scale_in_cooldown" {
  description = "Cooldown for scale-in in seconds"
  type        = number
  default     = 60
}

variable "scale_out_cooldown" {
  description = "Cooldown for scale-out in seconds"
  type        = number
  default     = 60
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Random suffix
resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

# TLS private key and self-signed certificate for ALB HTTPS
resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.main.private_key_pem
  subject {
    common_name = "fargate.local"
  }
  is_ca_certificate     = false
  validity_period_hours = 87600
  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

# ACM certificate for ALB HTTPS listener
resource "aws_acm_certificate" "main" {
  count = var.enable_load_balancing ? 1 : 0
  private_key      = tls_private_key.main.private_key_pem
  certificate_body = tls_self_signed_cert.main.cert_pem
  tags = {
    Name = "acm-${local.name_prefix}"
  }
}

# Locals
locals {
  workload_name   = var.workload_name != null ? var.workload_name : var.container_image
  name_prefix     = "${local.workload_name}-${random_string.suffix.result}"
  container_port  = 80
  subnet_ids      = [aws_subnet.private[0].id, aws_subnet.private[1].id]
  vpc_id          = aws_vpc.main.id
  container_secrets = [
    for key in keys(var.secrets) : {
      name      = key
      valueFrom = aws_ssm_parameter.secret[key].arn
    }
  ]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "vega-${local.name_prefix}"
    type = "vega"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "igw-${local.name_prefix}"
  }
}

# Route table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "rt-${local.name_prefix}"
  }
}

# Subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "subnet-${local.name_prefix}-${count.index}"
    type = "vega-private"
  }
}

# Route table associations
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

# KMS key for SSM encryption
resource "aws_kms_key" "ssm" {
  description             = "KMS key for encrypting SSM parameters under /fargate/${random_string.suffix.result}/"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  tags = {
    Name = "kms-ssm-${local.name_prefix}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ssm" {
  name          = "alias/fargate-ssm-key-${random_string.suffix.result}"
  target_key_id = aws_kms_key.ssm.key_id
}

# SSM Parameters for secrets
resource "aws_ssm_parameter" "secret" {
  for_each = var.secrets
  name     = "/fargate/${random_string.suffix.result}/${each.key}"
  type     = "SecureString"
  value    = each.value
  key_id   = aws_kms_key.ssm.key_id
  tier     = "Standard"
  lifecycle {
    prevent_destroy = true
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/${local.name_prefix}"
  retention_in_days = var.log_retention_days
  tags = {
    Name = "log-${local.name_prefix}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = local.name_prefix
  setting {
    name  = "containerInsights"
    value = var.container_insights ? "enabled" : "disabled"
  }
  tags = {
    Name = "cluster-${local.name_prefix}"
  }
}

# Capacity provider strategy for Fargate
resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE"]
  default_capacity_provider_strategy {
    base              = 1
    weight            = 100
    capacity_provider = "FARGATE"
  }
}

# IAM role for ECS tasks (execution and task role)
resource "aws_iam_role" "ecs_task" {
  name = "ecs_task_role_${random_string.suffix.result}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Name = "iam-ecs-task-${local.name_prefix}"
  }
}

# Managed policy attachments
resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ssm_read_only" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "ecr_read_only" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "ses_full_access" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSESFullAccess"
}

resource "aws_iam_role_policy_attachment" "s3_full_access" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy_attachment" "lambda_full_access" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AWSLambda_FullAccess"
}

resource "aws_iam_role_policy_attachment" "textract_full_access" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonTextractFullAccess"
}

# Inline policy for SSM messaging
resource "aws_iam_role_policy" "ssm_messaging" {
  name = "ssm-messaging-${random_string.suffix.result}"
  role = aws_iam_role.ecs_task.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:SendCommand",
          "ssm:GetCommandInvocation",
          "ssm:ListCommands",
          "ssm:ListCommandInvocations",
          "ssm:CancelCommand",
          "ssm:DescribeInstanceInformation"
        ]
        Resource = "*"
      }
    ]
  })
}

# Security group for ECS tasks
resource "aws_security_group" "ecs_tasks" {
  name        = "sg-ecs-${local.name_prefix}"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/1", "128.0.0.0/1"]
  }
  tags = {
    Name = "sg-ecs-${local.name_prefix}"
  }
}

# Security group for ALB (if load balancing enabled)
resource "aws_security_group" "alb" {
  count = var.enable_load_balancing ? 1 : 0
  name        = "sg-alb-${local.name_prefix}"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "sg-alb-${local.name_prefix}"
  }
}

# Ingress rule from ALB to ECS tasks on container port (conditional)
resource "aws_security_group_rule" "ecs_alb_ingress" {
  count                    = var.enable_load_balancing ? 1 : 0
  type                     = "ingress"
  from_port                = local.container_port
  to_port                  = local.container_port
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb[0].id
  security_group_id        = aws_security_group.ecs_tasks.id
}

# ALB (created when load balancing enabled)
resource "aws_lb" "main" {
  count              = var.enable_load_balancing ? 1 : 0
  name               = "alb-${random_string.suffix.result}"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = local.subnet_ids
  enable_deletion_protection = false
  drop_invalid_header_fields = true
  tags = {
    Name = "alb-${local.name_prefix}"
  }
}

# Target group
resource "aws_lb_target_group" "main" {
  count = var.enable_load_balancing ? 1 : 0
  name        = "tg-${local.name_prefix}"
  port        = local.container_port
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = local.vpc_id
  health_check {
    enabled             = true
    path                = var.health_check_path
    matcher             = var.health_check_matcher
    timeout             = var.health_check_timeout
    interval            = var.health_check_interval
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }
  deregistration_delay = var.deregistration_delay
  stickiness {
    type            = var.stickiness_type
    cookie_duration = var.stickiness_cookie_duration
    enabled         = true
  }
  tags = {
    Name = "tg-${local.name_prefix}"
  }
}

# HTTP listener (redirect to HTTPS)
resource "aws_lb_listener" "http" {
  count = var.enable_load_balancing ? 1 : 0
  load_balancer_arn = aws_lb.main[0].arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# HTTPS listener (forward to target group)
resource "aws_lb_listener" "https" {
  count = var.enable_load_balancing ? 1 : 0
  load_balancer_arn = aws_lb.main[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.main[0].arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main[0].arn
  }
}

# Listener rule (attached to HTTPS listener)
resource "aws_lb_listener_rule" "main" {
  count = var.enable_load_balancing ? 1 : 0
  listener_arn = aws_lb_listener.https[0].arn
  priority     = 100
  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main[0].arn
  }
  condition {
    host_header {
      values = var.host_header
    }
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "main" {
  family                   = local.name_prefix
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.cpu
  memory                   = var.memory
  execution_role_arn       = aws_iam_role.ecs_task.arn
  task_role_arn            = aws_iam_role.ecs_task.arn
  container_definitions = jsonencode([
    {
      name         = local.workload_name
      image        = var.container_image
      essential    = true
      portMappings = [
        {
          containerPort = local.container_port
          hostPort      = local.container_port
          protocol      = "tcp"
        }
      ]
      environment  = var.env_vars
      secrets      = local.container_secrets
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
  tags = {
    Name = "taskdef-${local.name_prefix}"
  }
}

# ECS Service
resource "aws_ecs_service" "main" {
  name            = local.name_prefix
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  launch_type     = "FARGATE"
  desired_count   = var.min_capacity
  network_configuration {
    subnets         = local.subnet_ids
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }
  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    base              = 1
    weight            = 100
  }
  dynamic "load_balancer" {
    for_each = var.enable_load_balancing ? [1] : []
    content {
      target_group_arn = aws_lb_target_group.main[0].arn
      container_name   = local.workload_name
      container_port   = local.container_port
    }
  }
  depends_on = [
    aws_lb_listener.http,
    aws_lb_listener.https,
    aws_iam_role_policy_attachment.ecs_task_execution
  ]
  tags = {
    Name = "service-${local.name_prefix}"
  }
}

# Application Auto Scaling target
resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = var.max_capacity
  min_capacity       = var.min_capacity
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.main.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

# Target tracking scaling policy
resource "aws_appautoscaling_policy" "cpu" {
  name               = "cpu-target-tracking-${local.name_prefix}"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace
  target_tracking_scaling_policy_configuration {
    target_value = 70.0
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    scale_in_cooldown  = var.scale_in_cooldown
    scale_out_cooldown = var.scale_out_cooldown
    disable_scale_in   = false
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project_name" {
  description = "Prefix for all IAM roles, instance profiles, and bucket names"
  type        = string
  default     = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# KMS Key for S3 bucket encryption
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "Allow S3 to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "artifacts" {
  description             = "KMS key for S3 artifacts bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

# ---------------------------------------------------------------------------------------------------------------------
# EC2 CodeDeploy Role and Instance Profile
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_codedeploy_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_codedeploy" {
  name               = "${var.project_name}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_codedeploy_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy" {
  name = aws_iam_role.ec2_codedeploy.name
  role = aws_iam_role.ec2_codedeploy.name
}

# ---------------------------------------------------------------------------------------------------------------------
# CodeDeploy Service Role
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  name               = "${var.project_name}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json
}

resource "aws_iam_role_policy_attachment" "codedeploy_codedeploy_role" {
  role       = aws_iam_role.codedeploy.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

# ---------------------------------------------------------------------------------------------------------------------
# EC2 CloudWatch Agent Role and Instance Profile
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_cloudwatch_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_cloudwatch" {
  name               = "${var.project_name}_ec2_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_cloudwatch_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_agent_policy" {
  role       = aws_iam_role.ec2_cloudwatch.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_instance_profile" "ec2_cloudwatch" {
  name = aws_iam_role.ec2_cloudwatch.name
  role = aws_iam_role.ec2_cloudwatch.name
}

# ---------------------------------------------------------------------------------------------------------------------
# Restrictive S3 policy for artifact bucket
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "s3_artifacts_access" {
  statement {
    sid    = "RestrictiveS3Access"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetObjectVersion"
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*"
    ]
  }
}

resource "aws_iam_policy" "s3_artifacts" {
  name        = "${var.project_name}-s3-artifacts-policy"
  description = "Restrictive S3 access policy for artifact bucket"
  policy      = data.aws_iam_policy_document.s3_artifacts_access.json
}

# ---------------------------------------------------------------------------------------------------------------------
# Attach restrictive S3 policy to roles
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = aws_iam_policy.s3_artifacts.arn
}

resource "aws_iam_role_policy_attachment" "codedeploy_s3" {
  role       = aws_iam_role.codedeploy.name
  policy_arn = aws_iam_policy.s3_artifacts.arn
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_s3" {
  role       = aws_iam_role.ec2_cloudwatch.name
  policy_arn = aws_iam_policy.s3_artifacts.arn
}

resource "aws_iam_role_policy_attachment" "codebuild_s3" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.s3_artifacts.arn
}

# ---------------------------------------------------------------------------------------------------------------------
# CodeBuild Role with Inline Policy
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild" {
  name               = "${var.project_name}_CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name = "${var.project_name}_CodeBuildInlinePolicy"
  role = aws_iam_role.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
      },
      {
        Sid    = "CodeBuildReports"
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestCases"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 Artifacts Bucket
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket = "${lower(var.project_name)}-artifacts-bucket-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CodePipeline Role with Inline Policy
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com"
      ]
    }
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "codepipeline" {
  name               = "${var.project_name}_CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name = "${var.project_name}_CodePipelineInlinePolicy"
  role = aws_iam_role.codepipeline.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullPipelineAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:*",
          "codecommit:*",
          "codedeploy:*",
          "lambda:InvokeFunction",
          "lambda:UpdateFunctionCode",
          "codebuild:*",
          "cloudformation:CreateStack",
          "cloudformation:UpdateStack",
          "cloudformation:DeleteStack",
          "cloudformation:DescribeStacks",
          "cloudformation:DescribeStackEvents",
          "cloudformation:GetTemplate",
          "cloudformation:ValidateTemplate"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3BucketSpecific"
        Effect = "Allow"
        Action = [
          "s3:GetBucketVersioning",
          "s3:ListBucket",
          "s3:GetObjectVersion",
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
      },
      {
        Sid    = "PassRole"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_role.ec2_codedeploy.arn,
          aws_iam_role.codedeploy.arn,
          aws_iam_role.ec2_cloudwatch.arn,
          aws_iam_role.codebuild.arn,
          aws_iam_role.codepipeline.arn
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
