  }

  global_secondary_index {
    name            = "OwnerIdIndex"
    hash_key        = "OwnerId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-collections"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

