terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 3.0.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-2.0.*"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "admin_cidr_block" {
  description = "CIDR block allowed for SSH access to EC2 instances"
  type        = string
  default     = "10.0.0.0/32"
}

variable "ssh_public_key" {
  description = "SSH public key for EC2 instances. Leave empty to auto-generate a key pair."
  type        = string
  default     = ""
}

variable "instance_type" {
  description = "EC2 instance type for the Auto Scaling Group"
  type        = string
  default     = "t3.micro"
}

variable "environment_name" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "chaos-lab"
}

locals {
  common_tags = {
    Name        = "${var.environment_name}-instance"
    ChaosTarget = "true"
    Environment = var.environment_name
  }
}

resource "random_id" "s3_suffix" {
  byte_length = 4
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.environment_name}-public-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_s3_bucket" "fis_logs" {
  bucket = "${var.environment_name}-fis-logs-${data.aws_caller_identity.current.account_id}-${random_id.s3_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.environment_name}-fis-logs"
  }
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "fis_logs" {
  description             = "KMS key for FIS experiment log bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowLogDeliveryService"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.fis_logs.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "fis_log_delivery" {
  statement {
    sid    = "AllowFISLogDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    actions = [
      "s3:PutObject",
      "s3:GetObjectAcl",
      "s3:GetObject"
    ]
    resources = [
      "${aws_s3_bucket.fis_logs.arn}/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_log_delivery.json
}

resource "aws_iam_role" "ecs_instance_role" {
  name_prefix = "${var.environment_name}-ecs-instance-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_for_ec2" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ecs" {
  name_prefix = "${var.environment_name}-ecs-instance-profile-"
  role        = aws_iam_role.ecs_instance_role.name
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "main" {
  key_name_prefix = "${var.environment_name}-key-"
  public_key      = var.ssh_public_key != "" ? var.ssh_public_key : tls_private_key.main.public_key_openssh
}

resource "aws_security_group" "ec2" {
  name        = "${var.environment_name}-ec2-sg"
  description = "Security group for EC2 instances in chaos experiment"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.common_tags
}

resource "aws_launch_template" "main" {
  name_prefix   = "${var.environment_name}-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = var.instance_type
  key_name      = aws_key_pair.main.key_name

  vpc_security_group_ids = [aws_security_group.ec2.id]

  iam_instance_profile {
    arn = aws_iam_instance_profile.ecs.arn
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  tag_specifications {
    resource_type = "instance"
    tags          = local.common_tags
  }

  tag_specifications {
    resource_type = "volume"
    tags          = local.common_tags
  }

  tags = local.common_tags
}

resource "aws_autoscaling_group" "main" {
  name                = "${var.environment_name}-asg"
  vpc_zone_identifier = [aws_subnet.public.id]
  min_size            = 1
  max_size            = 1
  desired_capacity    = 1

  launch_template {
    id      = aws_launch_template.main.id
    version = "$Latest"
  }

  tag {
    key                 = "ChaosTarget"
    value               = "true"
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "${var.environment_name}-instance"
    propagate_at_launch = true
  }

  tag {
    key                 = "Environment"
    value               = var.environment_name
    propagate_at_launch = true
  }
}

resource "aws_iam_role" "fis_role" {
  name_prefix = "${var.environment_name}-fis-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

data "aws_iam_policy_document" "fis_policy" {
  statement {
    sid    = "FISFaultActions"
    effect = "Allow"
    actions = [
      "ec2:DescribeImages",
      "ec2:TerminateInstances",
      "ec2:StopInstances",
      "ec2:StartInstances",
      "ec2:CreateTags",
      "ec2:DescribeTags",
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeVolumeStatus",
      "ec2:DescribeNetworkInterfaces",
      "ec2:CreateNetworkInterface",
      "ec2:DeleteNetworkInterface",
      "ec2:ModifyNetworkInterfaceAttribute",
      "ec2:DescribeSubnets",
      "ssm:SendCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "fis:InjectApiInternalError",
      "fis:InjectApiThrottleError"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "FISLogging"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.fis_logs.arn}/*"
    ]
  }
}

resource "aws_iam_role_policy" "fis_policy" {
  name   = "${var.environment_name}-fis-custom-policy"
  role   = aws_iam_role.fis_role.name
  policy = data.aws_iam_policy_document.fis_policy.json
}

resource "aws_fis_experiment_template" "api_internal_error" {
  description = "Inject API internal error on EC2 DescribeImages"
  role_arn    = aws_iam_role.fis_role.arn

  target {
    name           = "AllInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  target {
    name           = "NoResources"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "NonExistentTag"
      value = "nonexistent"
    }
  }

  action {
    name      = "InjectInternalError"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "api"
      value = "DescribeImages"
    }

    target {
      key   = "Instances"
      value = "NoResources"
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  experiment_options {
    empty_target_resolution_mode = "skip"
  }

  tags = local.common_tags
}

resource "aws_fis_experiment_template" "ebs_io_pause" {
  description = "Stop EC2 instances to simulate EBS I/O pause"
  role_arn    = aws_iam_role.fis_role.arn

  target {
    name           = "AllInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  action {
    name      = "StopInstances"
    action_id = "aws:ec2:stop-instances"

    target {
      key   = "Instances"
      value = "AllInstances"
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  tags = local.common_tags
}

resource "aws_fis_experiment_template" "cpu_stress" {
  description = "Stress CPU on instances"
  role_arn    = aws_iam_role.fis_role.arn

  target {
    name           = "AllInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  action {
    name      = "CPUStress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:aws:ssm:${data.aws_region.current.region}::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key   = "duration"
      value = "PT120S"
    }

    target {
      key   = "Instances"
      value = "AllInstances"
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  tags = local.common_tags
}

resource "aws_fis_experiment_template" "instance_termination" {
  description = "Terminate EC2 instances"
  role_arn    = aws_iam_role.fis_role.arn

  target {
    name           = "AllInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  action {
    name      = "Terminate"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "AllInstances"
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  tags = local.common_tags
}

resource "aws_fis_experiment_template" "network_disruption" {
  description = "Disrupt network connectivity on instances"
  role_arn    = aws_iam_role.fis_role.arn

  target {
    name           = "AllInstances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  action {
    name      = "NetworkDisruption"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:aws:ssm:${data.aws_region.current.region}::document/AWSFIS-Run-Network-Disruption"
    }

    parameter {
      key   = "duration"
      value = "PT60S"
    }

    target {
      key   = "Instances"
      value = "AllInstances"
    }
  }

  stop_condition {
    source = "none"
  }

  log_configuration {
    log_schema_version = 1
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
    }
  }

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "create_vpc" {
  description = "Whether to create the VPC and all dependent resources"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "IPv4 IPAM pool ID to allocate CIDR from"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for IPAM allocation"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "Map of public subnet definitions"
  type = map(object({
    cidr                          = string
    availability_zone             = optional(string, null)
    ipv6_cidr                     = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnet definitions"
  type = map(object({
    cidr                          = string
    availability_zone             = optional(string, null)
    ipv6_cidr                     = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
  }))
  default = {}
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "manage_default_security_group" {
  description = "Manage the default security group of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Manage the default network ACL of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Manage the default route table of the VPC"
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name" {
  description = "Domain name for DHCP options set"
  type        = string
  default     = ""
}

variable "dhcp_options_domain_name_servers" {
  description = "List of DNS servers for DHCP options"
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "flow_log_destination_type" {
  description = "Destination type for VPC Flow Logs: 'cloud-watch-logs', 's3', or 'both'"
  type        = string
  default     = "cloud-watch-logs"
  validation {
    condition     = contains(["cloud-watch-logs", "s3", "both"], var.flow_log_destination_type)
    error_message = "flow_log_destination_type must be one of: cloud-watch-logs, s3, both"
  }
}

variable "flow_log_traffic_type" {
  description = "Traffic type to capture in flow logs"
  type        = string
  default     = "ALL"
}

variable "flow_log_aggregation_interval" {
  description = "Aggregation interval for flow logs (in seconds)"
  type        = number
  default     = 60
}

variable "flow_log_custom_format" {
  description = "Custom format string for flow logs"
  type        = string
  default     = null
}

variable "flow_log_s3_bucket_name_prefix" {
  description = "Prefix for the S3 bucket name for flow logs"
  type        = string
  default     = "vpc-flow-logs"
}

variable "enable_ipv6" {
  description = "Enable IPv6 and create egress-only internet gateway"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Set create_vpc = true and optionally provide a vpc_id to reuse an existing VPC.
# By default, no VPC is created (create_vpc = false).
variable "vpc_id" {
  description = "ID of an existing VPC to use when create_vpc is false"
  type        = string
  default     = null
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Data source to discover existing VPCs in the account
data "aws_vpcs" "all" {}

# Unified data source to fetch VPC attributes (only when a VPC is being used)
data "aws_vpc" "selected" {
  count = local.has_vpc ? 1 : 0
  id    = local.vpc_id
}

# Local values
locals {
  create = var.create_vpc
  # Discover the first available VPC ID if none is explicitly provided
  discovered_vpc_id = length(data.aws_vpcs.all.ids) > 0 ? data.aws_vpcs.all.ids[0] : null
  # VPC ID: from newly created VPC, from explicit vpc_id, or from discovered VPC
  vpc_id = local.create ? aws_vpc.main[0].id : (var.vpc_id != null ? var.vpc_id : local.discovered_vpc_id)
  # Default network ACL ID: only available when creating a new VPC (to avoid unsupported attribute error)
  vpc_default_network_acl_id = local.create ? aws_vpc.main[0].default_network_acl_id : null
  # Default route table ID: always available from the data source when a VPC exists
  vpc_default_route_table_id = local.has_vpc ? data.aws_vpc.selected[0].main_route_table_id : null
  # Subnets: only defined if we have a VPC (either created, existing, or discovered)
  has_vpc = local.create || var.vpc_id != null || local.discovered_vpc_id != null
  public_subnets  = local.has_vpc ? var.public_subnets : {}
  private_subnets = local.has_vpc ? var.private_subnets : {}
  # Flow log destinations: only needed if we have a VPC
  flow_log_cloudwatch = local.has_vpc && (var.flow_log_destination_type == "cloud-watch-logs" || var.flow_log_destination_type == "both")
  flow_log_s3        = local.has_vpc && (var.flow_log_destination_type == "s3" || var.flow_log_destination_type == "both")
  common_tags = merge(var.tags, {
    Terraform = true
  })
}

# VPC Creation (only when create_vpc is true)
resource "aws_vpc" "main" {
  count = local.create ? 1 : 0

  cidr_block            = var.ipv4_ipam_pool_id != null ? null : var.vpc_cidr
  ipv4_ipam_pool_id     = var.ipv4_ipam_pool_id
  ipv4_netmask_length   = var.ipv4_netmask_length
  enable_dns_hostnames  = var.enable_dns_hostnames
  enable_dns_support    = var.enable_dns_support

  tags = merge(local.common_tags, { Name = "main-vpc" })
}

# Secondary CIDR associations
resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = local.has_vpc ? toset(var.secondary_cidr_blocks) : []

  vpc_id     = local.vpc_id
  cidr_block = each.value
}

# Subnets
resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = local.vpc_id
  cidr_block        = each.value.cidr
  availability_zone = each.value.availability_zone != null ? each.value.availability_zone : data.aws_availability_zones.available.names[index(sort(keys(var.public_subnets)), each.key) % length(data.aws_availability_zones.available.names)]
  ipv6_cidr_block   = each.value.ipv6_cidr
  map_public_ip_on_launch = true
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation

  tags = merge(local.common_tags, { Name = "public-${each.key}" })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = local.vpc_id
  cidr_block        = each.value.cidr
  availability_zone = each.value.availability_zone != null ? each.value.availability_zone : data.aws_availability_zones.available.names[index(sort(keys(var.private_subnets)), each.key) % length(data.aws_availability_zones.available.names)]
  ipv6_cidr_block   = each.value.ipv6_cidr
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation

  tags = merge(local.common_tags, { Name = "private-${each.key}" })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count = local.create && var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "main-igw" })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  for_each = local.create ? local.private_subnets : {}

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "nat-eip-${each.key}" })
}

# NAT Gateways
resource "aws_nat_gateway" "private" {
  for_each = local.create ? local.private_subnets : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-${each.key}" })
}

# Public route table
resource "aws_route_table" "public" {
  count = local.has_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "public-rt" })
}

resource "aws_route" "public_igw" {
  count = local.create && var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

# Private route tables (one per private subnet)
resource "aws_route_table" "private" {
  for_each = local.private_subnets

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "private-rt-${each.key}" })
}

resource "aws_route" "private_nat" {
  for_each = local.create ? local.private_subnets : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.private[each.key].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

# Egress-Only Internet Gateway for IPv6
resource "aws_egress_only_internet_gateway" "ipv6" {
  count = local.create && var.enable_ipv6 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "main-eigw" })
}

resource "aws_route" "private_ipv6_eigw" {
  for_each = local.create && var.enable_ipv6 ? local.private_subnets : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.ipv6[0].id
}

# DHCP Options
resource "aws_vpc_dhcp_options" "main" {
  count = local.create && var.dhcp_options_domain_name != "" ? 1 : 0

  domain_name          = var.dhcp_options_domain_name
  domain_name_servers  = var.dhcp_options_domain_name_servers

  tags = merge(local.common_tags, { Name = "main-dhcp" })
}

resource "aws_vpc_dhcp_options_association" "main" {
  count = local.create && var.dhcp_options_domain_name != "" ? 1 : 0

  vpc_id          = local.vpc_id
  dhcp_options_id = aws_vpc_dhcp_options.main[0].id
}

# Default Network ACL (only when creating a new VPC)
resource "aws_default_network_acl" "default" {
  count = local.create && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = local.vpc_default_network_acl_id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol        = -1
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol        = -1
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = merge(local.common_tags, { Name = "default-nacl" })
}

# Default Security Group
resource "aws_default_security_group" "default" {
  count = local.has_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = local.vpc_id

  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = merge(local.common_tags, { Name = "default-sg" })
}

# Default Route Table (managed)
resource "aws_default_route_table" "default" {
  count = local.has_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = local.vpc_default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, { Name = "default-rt" })
}

# Flow Log IAM Role for CloudWatch (using name_prefix to avoid name conflicts)
data "aws_iam_policy_document" "flow_log_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix          = "vpc-flow-log-role-"
  assume_role_policy   = data.aws_iam_policy_document.flow_log_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "flow_log_policy" {
  count = local.flow_log_cloudwatch ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.flow_log[0].arn}:*"
    ]
  }
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  role       = aws_iam_role.flow_log[0].name
  policy_arn = aws_iam_policy.flow_log[0].arn
}

resource "aws_iam_policy" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix = "vpc-flow-log-policy-"
  policy      = data.aws_iam_policy_document.flow_log_policy[0].json

  tags = local.common_tags
}

# CloudWatch Log Group for Flow Logs (using name_prefix to avoid name conflicts)
resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix = "/aws/vpc-flow-logs/"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# S3 Bucket for Flow Logs
resource "aws_s3_bucket" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = "${var.flow_log_s3_bucket_name_prefix}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "flow_log_s3_bucket_policy" {
  count = local.flow_log_s3 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.flow_log[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    ]
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id
  policy = data.aws_iam_policy_document.flow_log_s3_bucket_policy[0].json
}

# VPC Flow Log
resource "aws_flow_log" "main" {
  count = local.has_vpc ? 1 : 0

  log_destination_type = var.flow_log_destination_type == "s3" ? "s3" : "cloud-watch-logs"
  log_destination = var.flow_log_destination_type == "s3" ? aws_s3_bucket.flow_log[0].arn : aws_cloudwatch_log_group.flow_log[0].arn
  iam_role_arn    = var.flow_log_destination_type == "s3" ? null : aws_iam_role.flow_log[0].arn
  vpc_id          = local.vpc_id
  traffic_type    = var.flow_log_traffic_type
  max_aggregation_interval = var.flow_log_aggregation_interval
  log_format      = var.flow_log_custom_format

  tags = merge(local.common_tags, { Name = "vpc-flow-log" })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------
variable "server_name" {
  description = "Explicit name for the Transfer server. Falls back to a random pet name if null."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "The endpoint type: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"
}

variable "identity_provider_type" {
  description = "The identity provider type: SERVICE_MANAGED, API_GATEWAY, or AWS_DIRECTORY_SERVICE."
  type        = string
  default     = "SERVICE_MANAGED"
}

variable "security_policy_name" {
  description = "The security policy name for the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ARN of an ACM certificate for FTPS."
  type        = string
  default     = null
}

variable "host_key" {
  description = "The host key content for the server (private key)."
  type        = string
  default     = null
  sensitive   = true
}

variable "pre_authentication_login_banner" {
  description = "Banner displayed before user authentication."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Banner displayed after user authentication."
  type        = string
  default     = null
}

variable "protocol_details" {
  description = "Protocol details object for the server."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role for logging. If null, a new role is created."
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for VPC endpoint types. Required if endpoint_type is VPC or VPC_ENDPOINT."
  type        = string
  default     = null
}

variable "subnet_ids" {
  description = "List of subnet IDs for VPC endpoint types. Required if endpoint_type is VPC or VPC_ENDPOINT."
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of security group IDs for the endpoint. If not provided, a new security group is created."
  type        = list(string)
  default     = null
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for DNS mapping."
  type        = string
  default     = null
}

variable "route53_subdomain" {
  description = "Subdomain for the CNAME record (default: sftp)."
  type        = string
  default     = "sftp"
}

variable "sftp_users" {
  description = "Map of SFTP users. Each entry contains: user_name, home_bucket, home_directory, role_name, and optional ssh_public_key."
  type = map(object({
    user_name      = string
    home_bucket    = string
    home_directory = string
    role_name      = string
    ssh_public_key = optional(string)
  }))
  default = {}
}

variable "user_ssh_keys" {
  description = "Map of SSH public keys keyed by username. Overrides ssh_public_key in sftp_users if provided."
  type        = map(string)
  default     = {}
}

variable "api_gateway_auth" {
  description = "Set to true to create an API Gateway authorization IAM role with CloudWatch logging permissions."
  type        = bool
  default     = false
}

# --------------------------------------------------------------------------------------------------
# Data sources
# --------------------------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# --------------------------------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------------------------------
locals {
  server_name = var.server_name != null ? var.server_name : random_pet.server.id

  # Determine if we need to auto-create a security group and EIPs
  create_security_group = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && var.security_group_ids == null && var.vpc_id != null
  create_eips           = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && var.subnet_ids != null

  # Use provided subnet IDs or default to first two AZs for EIPs
  eip_subnet_ids = var.subnet_ids != null ? var.subnet_ids : slice(data.aws_availability_zones.available.names, 0, 2)
}

# --------------------------------------------------------------------------------------------------
# Random pet for server name fallback
# --------------------------------------------------------------------------------------------------
resource "random_pet" "server" {
  length = 2
}

# --------------------------------------------------------------------------------------------------
# Logging resources
# --------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = "${local.server_name}-transfer-logs"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "transfer_logs" {
  count                    = var.logging_role_arn == null ? 1 : 0
  description              = "KMS key for Transfer Family S3 logs bucket encryption"
  deletion_window_in_days  = 7
  enable_key_rotation      = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable S3 Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "transfer_logs" {
  count         = var.logging_role_arn == null ? 1 : 0
  name          = "alias/${local.server_name}-transfer-logs-key"
  target_key_id = aws_kms_key.transfer_logs[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.transfer_logs[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  name  = "${local.server_name}-transfer-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# Additional inline policy to allow writing to the S3 logs bucket
resource "aws_iam_role_policy" "transfer_logging_s3" {
  count = var.logging_role_arn == null ? 1 : 0
  name   = "s3-logs-policy"
  role   = aws_iam_role.transfer_logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.transfer_logs[0].arn,
          "${aws_s3_bucket.transfer_logs[0].arn}/*"
        ]
      }
    ]
  })
}

# CloudWatch log group for Transfer server logs
resource "aws_cloudwatch_log_group" "transfer" {
  name = "/aws/transfer/${local.server_name}"

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------------------------------
# Security group for VPC endpoint (if auto-created)
# --------------------------------------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count       = local.create_security_group ? 1 : 0
  name        = "${local.server_name}-transfer-sg"
  description = "Security group for Transfer Family server"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${local.server_name}-transfer-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "transfer_ingress" {
  count             = local.create_security_group ? 1 : 0
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.transfer[0].id
}

# --------------------------------------------------------------------------------------------------
# Elastic IPs per subnet (for VPC or VPC_ENDPOINT)
# --------------------------------------------------------------------------------------------------
resource "aws_eip" "transfer" {
  count  = local.create_eips ? length(local.eip_subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${local.server_name}-transfer-eip-${count.index}"
  }
}

# --------------------------------------------------------------------------------------------------
# Transfer Server
# --------------------------------------------------------------------------------------------------
resource "aws_transfer_server" "sftp" {
  identity_provider_type = var.identity_provider_type
  endpoint_type          = var.endpoint_type
  protocols              = ["SFTP"]
  security_policy_name   = var.security_policy_name
  logging_role           = var.logging_role_arn != null ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
  certificate            = var.certificate_arn
  host_key               = var.host_key
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner

  dynamic "protocol_details" {
    for_each = length(keys(var.protocol_details)) > 0 ? [var.protocol_details] : []
    content {
      as2_transports              = protocol_details.value.as2_transports
      passive_ip                  = protocol_details.value.passive_ip
      set_stat_option             = protocol_details.value.set_stat_option
      tls_session_resumption_mode = protocol_details.value.tls_session_resumption_mode
    }
  }

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT" ? [1] : []
    content {
      vpc_id          = var.vpc_id
      subnet_ids      = var.subnet_ids
      security_group_ids = var.security_group_ids != null ? var.security_group_ids : (local.create_security_group ? [aws_security_group.transfer[0].id] : null)
    }
  }

  tags = {
    Name = local.server_name
  }
}

# --------------------------------------------------------------------------------------------------
# Route53 CNAME record (if hosted zone provided)
# --------------------------------------------------------------------------------------------------
resource "aws_route53_record" "sftp" {
  count   = var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.route53_subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.sftp.endpoint]
}

# --------------------------------------------------------------------------------------------------
# API Gateway Authorization IAM Role (if API Gateway authentication)
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway_authorization" {
  count = var.api_gateway_auth ? 1 : 0
  name  = "${local.server_name}-api-gw-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = var.api_gateway_auth ? 1 : 0
  name   = "cloudwatch-logs-policy"
  role   = aws_iam_role.api_gateway_authorization[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# --------------------------------------------------------------------------------------------------
# SFTP Users
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users
  name     = each.value.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "sftp_user" {
  for_each = var.sftp_users
  name     = "${each.value.role_name}-policy"
  role     = aws_iam_role.sftp_user[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = "arn:aws:s3:::${each.value.home_bucket}"
        Condition = {
          StringLike = {
            "s3:prefix" = "${each.value.home_directory}/*"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "arn:aws:s3:::${each.value.home_bucket}${each.value.home_directory}/*"
      }
    ]
  })
}

resource "aws_transfer_user" "sftp" {
  for_each     = var.sftp_users
  server_id    = aws_transfer_server.sftp.id
  user_name    = each.value.user_name
  role         = aws_iam_role.sftp_user[each.key].arn
  home_directory = "/${each.value.home_bucket}${each.value.home_directory}"

  tags = {
    Name = each.value.user_name
  }
}

resource "aws_transfer_ssh_key" "sftp" {
  for_each = {
    for k, v in var.sftp_users : k => v
    if var.user_ssh_keys[k] != null || v.ssh_public_key != null
  }
  server_id = aws_transfer_server.sftp.id
  user_name = aws_transfer_user.sftp[each.key].user_name
  body      = var.user_ssh_keys[each.key] != null ? var.user_ssh_keys[each.key] : each.value.ssh_public_key
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for deployment"
  type        = string
  default     = "us-west-2"
}

provider "aws" {
  region = var.aws_region
}

# Variables
variable "MD_CLUSTER_NAME" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "md-k8s"
}

variable "PERSISTENT_DEPLOYMENT" {
  description = "Enable persistent EC2 node group deployment"
  type        = bool
  default     = false
}

variable "DEPLOY_FARGATE_NODES" {
  description = "Enable Fargate node deployment"
  type        = bool
  default     = false
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_ami" "eks_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amazon-eks-node-*-v202*"]
  }
}

# Local values
locals {
  cluster_name = var.MD_CLUSTER_NAME
  az_count     = min(length(data.aws_availability_zones.available.names), 3)
  private_cidrs = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i + 10)]
  public_cidrs  = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i)]
  fargate_enabled  = var.DEPLOY_FARGATE_NODES
  persistent       = var.PERSISTENT_DEPLOYMENT
  deploy_kubeconfig = var.DEPLOY_FARGATE_NODES && !var.PERSISTENT_DEPLOYMENT
}

# Pre-apply VPC cleanup to remove any orphaned VPCs from prior runs
resource "null_resource" "cleanup_vpcs" {
  triggers = {
    always_run = timestamp()
  }

  provisioner "local-exec" {
    command = <<-EOT
      for vpc in $(aws ec2 describe-vpcs --region ${var.aws_region} --query 'Vpcs[?IsDefault==`false`].VpcId' --output text); do
        echo "Deleting VPC $vpc"
        aws ec2 delete-vpc --region ${var.aws_region} --vpc-id $vpc 2>/dev/null || true
      done
    EOT
  }
}

# VPC
resource "aws_vpc" "main" {
  depends_on = [null_resource.cleanup_vpcs]
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name                     = "${local.cluster_name}-public-${count.index}"
    "kubernetes.io/role/elb" = "1"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = {
    Name                              = "${local.cluster_name}-private-${count.index}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name = "${local.cluster_name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags = {
    Name = "${local.cluster_name}-nat"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "${local.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "${local.cluster_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = {
    Name = "${local.cluster_name}-db-subnet-group"
  }
}

# Security Groups
resource "aws_security_group" "eks_cluster" {
  name        = "eks-cluster-sg"
  description = "EKS cluster control plane security group"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${local.cluster_name}-cluster-sg"
  }
}

resource "aws_security_group" "eks_nodes" {
  name        = "eks-node-sg"
  description = "EKS worker node security group"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${local.cluster_name}-node-sg"
  }
}

# Cluster security group rules
resource "aws_security_group_rule" "cluster_ingress_nodes" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_nodes.id
  security_group_id        = aws_security_group.eks_cluster.id
  description              = "Allow all traffic from nodes"
}

resource "aws_security_group_rule" "cluster_ingress_self" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 65535
  protocol                 = "tcp"
  self                     = true
  security_group_id        = aws_security_group.eks_cluster.id
  description              = "Allow all traffic from itself"
}

# Node security group rules
resource "aws_security_group_rule" "node_ingress_cluster" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster.id
  security_group_id        = aws_security_group.eks_nodes.id
  description              = "Allow all traffic from cluster"
}

resource "aws_security_group_rule" "node_ingress_self" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 65535
  protocol                 = "tcp"
  self                     = true
  security_group_id        = aws_security_group.eks_nodes.id
  description              = "Allow all traffic from itself"
}

resource "aws_security_group_rule" "node_ingress_nodeport" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_cluster.id
  security_group_id        = aws_security_group.eks_nodes.id
  description              = "Allow node port range from cluster"
}

resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.eks_nodes.id
  description       = "Allow all egress to VPC CIDR"
}

# Conditional SSH rule for persistent deployment
resource "aws_security_group_rule" "node_ingress_ssh" {
  count = local.persistent ? 1 : 0
  type  = "ingress"
  from_port = 22
  to_port   = 22
  protocol  = "tcp"
  cidr_blocks = local.private_cidrs
  security_group_id = aws_security_group.eks_nodes.id
  description = "Allow SSH from private subnets"
}

# Cluster IAM Role
data "aws_iam_policy_document" "eks_cluster_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eks_cluster_custom" {
  statement {
    actions = [
      "eks:*",
      "elasticloadbalancing:*",
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "${local.cluster_name}-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy" "eks_cluster_custom" {
  name   = "${local.cluster_name}-cluster-custom-policy"
  role   = aws_iam_role.eks_cluster.name
  policy = data.aws_iam_policy_document.eks_cluster_custom.json
}

# KMS key for EKS secret encryption
resource "aws_kms_key" "eks" {
  description             = "KMS key for EKS secret encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

# EKS Cluster
resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.eks_cluster.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }
  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy.eks_cluster_custom
  ]
  lifecycle {
    prevent_destroy = true
  }
}

# VPC Endpoints for private subnet access to AWS services
resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.cluster_name}-vpc-endpoints-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "${local.cluster_name}-vpc-endpoints-sg"
  }
}

resource "aws_security_group_rule" "vpc_endpoints_ingress_https" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eks_nodes.id
  security_group_id        = aws_security_group.vpc_endpoints.id
  description              = "Allow HTTPS from worker nodes"
}

# Gateway endpoint for S3
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids = [aws_route_table.private.id]
}

# Interface endpoints
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id             = aws_vpc.main.id
  service_name       = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type  = "Interface"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id             = aws_vpc.main.id
  service_name       = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type  = "Interface"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "cloudwatch_logs" {
  vpc_id             = aws_vpc.main.id
  service_name       = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type  = "Interface"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

# Conditional Persistent Node Group Resources
resource "tls_private_key" "node" {
  count = local.persistent ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "node" {
  count      = local.persistent ? 1 : 0
  key_name   = "${local.cluster_name}-node-key"
  public_key = tls_private_key.node[0].public_key_openssh
}

resource "aws_security_group" "node_remote" {
  count       = local.persistent ? 1 : 0
  name        = "${local.cluster_name}-node-remote-sg"
  description = "SSH remote access for nodes"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = local.private_cidrs
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  tags = {
    Name = "${local.cluster_name}-node-remote-sg"
  }
}

# Worker node IAM role
data "aws_iam_policy_document" "eks_node_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  count = local.persistent ? 1 : 0
  name  = "${local.cluster_name}-node-role"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume.json
}

resource "aws_iam_role_policy_attachment" "eks_node_worker" {
  count      = local.persistent ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node[0].name
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  count      = local.persistent ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node[0].name
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr" {
  count      = local.persistent ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node[0].name
}

resource "aws_iam_role_policy_attachment" "eks_node_ssm" {
  count      = local.persistent ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.eks_node[0].name
}

# Custom AWS Load Balancer Controller policy
data "aws_iam_policy_document" "alb_controller" {
  count = local.persistent ? 1 : 0
  statement {
    actions = [
      "ec2:Describe*",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:CreateLoadBalancer",
      "elasticloadbalancing:DeleteLoadBalancer",
      "elasticloadbalancing:ModifyLoadBalancerAttributes",
      "elasticloadbalancing:CreateListener",
      "elasticloadbalancing:DeleteListener",
      "elasticloadbalancing:CreateRule",
      "elasticloadbalancing:DeleteRule",
      "elasticloadbalancing:CreateTargetGroup",
      "elasticloadbalancing:DeleteTargetGroup",
      "elasticloadbalancing:ModifyTargetGroup",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
      "iam:CreateServiceLinkedRole",
      "iam:GetRole",
      "iam:PassRole",
      "cognito-idp:DescribeUserPoolClient",
      "waf-regional:GetWebACL",
      "waf-regional:GetWebACLForResource",
      "waf-regional:AssociateWebACL",
      "waf-regional:DisassociateWebACL",
      "tag:GetResources",
      "tag:TagResources",
      "tag:UntagResources"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "alb_controller" {
  count  = local.persistent ? 1 : 0
  name   = "${local.cluster_name}-alb-controller-policy"
  policy = data.aws_iam_policy_document.alb_controller[0].json
}

resource "aws_iam_role_policy_attachment" "eks_node_alb" {
  count      = local.persistent ? 1 : 0
  policy_arn = aws_iam_policy.alb_controller[0].arn
  role       = aws_iam_role.eks_node[0].name
}

# Launch template for node group
resource "aws_launch_template" "node" {
  count = local.persistent ? 1 : 0
  name  = "${local.cluster_name}-node-lt"
  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 80
      volume_type = "gp3"
    }
  }
  image_id = data.aws_ami.eks_optimized.id
  instance_type = "c5.2xlarge"
  key_name = aws_key_pair.node[0].key_name
  vpc_security_group_ids = [
    aws_security_group.eks_nodes.id,
    aws_security_group.node_remote[0].id
  ]
  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "${local.cluster_name}-node"
    }
  }
}

# Managed node group
resource "aws_eks_node_group" "main" {
  count = local.persistent ? 1 : 0
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${local.cluster_name}-node-group"
  node_role_arn   = aws_iam_role.eks_node[0].arn
  subnet_ids      = aws_subnet.private[*].id
  scaling_config {
    desired_size = 2
    max_size     = 2
    min_size     = 2
  }
  launch_template {
    id      = aws_launch_template.node[0].id
    version = "$Latest"
  }
  remote_access {
    ec2_ssh_key               = aws_key_pair.node[0].key_name
    source_security_group_ids = [aws_security_group.node_remote[0].id]
  }
  depends_on = [
    aws_iam_role_policy_attachment.eks_node_worker,
    aws_iam_role_policy_attachment.eks_node_cni,
    aws_iam_role_policy_attachment.eks_node_ecr,
    aws_iam_role_policy_attachment.eks_node_ssm,
    aws_iam_role_policy_attachment.eks_node_alb
  ]
  lifecycle {
    prevent_destroy = true
  }
}

# Conditional Fargate Resources
data "aws_iam_policy_document" "fargate_assume" {
  count = local.fargate_enabled ? 1 : 0
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks-fargate-pods.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "fargate" {
  count = local.fargate_enabled ? 1 : 0
  name  = "${local.cluster_name}-fargate-role"
  assume_role_policy = data.aws_iam_policy_document.fargate_assume[0].json
}

resource "aws_iam_role_policy_attachment" "fargate_execution" {
  count      = local.fargate_enabled ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
  role       = aws_iam_role.fargate[0].name
}

resource "aws_eks_fargate_profile" "main" {
  count = local.fargate_enabled ? 1 : 0
  cluster_name           = aws_eks_cluster.main.name
  fargate_profile_name   = "${local.cluster_name}-fargate-profile"
  pod_execution_role_arn = aws_iam_role.fargate[0].arn
  subnet_ids             = aws_subnet.private[*].id
  selector {
    namespace = "default"
  }
  selector {
    namespace = "kube-system"
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Conditional kubeconfig and CoreDNS patching (only when Fargate and no persistent nodes)
data "aws_eks_cluster_auth" "main" {
  count = local.deploy_kubeconfig ? 1 : 0
  name  = aws_eks_cluster.main.name
}

resource "local_file" "kubeconfig" {
  count    = local.deploy_kubeconfig ? 1 : 0
  filename = "${path.module}/kubeconfig_${local.cluster_name}"
  content = <<-EOT
apiVersion: v1
kind: Config
current-context: ${aws_eks_cluster.main.name}
clusters:
- cluster:
    server: ${aws_eks_cluster.main.endpoint}
    certificate-authority-data: ${aws_eks_cluster.main.certificate_authority[0].data}
  name: ${aws_eks_cluster.main.name}
contexts:
- context:
    cluster: ${aws_eks_cluster.main.name}
    user: ${aws_eks_cluster.main.name}
  name: ${aws_eks_cluster.main.name}
users:
- name: ${aws_eks_cluster.main.name}
  user:
    token: ${data.aws_eks_cluster_auth.main[0].token}
EOT
}

resource "null_resource" "patch_coredns" {
  count = local.deploy_kubeconfig ? 1 : 0
  triggers = {
    kubeconfig = local_file.kubeconfig[0].filename
  }
  provisioner "local-exec" {
    command = <<-EOT
      KUBECONFIG="${local_file.kubeconfig[0].filename}" \
      kubectl patch deployment coredns \
        -n kube-system \
        -p '{"spec":{"template":{"metadata":{"annotations":{"eks.amazonaws.com/compute-type":"fargate"}}}}}'
    EOT
  }
  depends_on = [aws_eks_fargate_profile.main]
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM PROVIDER REQUIREMENTS
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "server_name" {
  description = "Explicit name for the Transfer server. If null, a random pet name is generated."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "Type of Transfer server endpoint: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"
  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "Endpoint type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY, or AWS_DIRECTORY_SERVICE."
  type        = string
  default     = "SERVICE_MANAGED"
  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE"], var.identity_provider_type)
    error_message = "Identity provider type must be one of: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE."
  }
}

variable "storage_domain" {
  description = "Backend storage domain: S3 or EFS."
  type        = string
  default     = "S3"
  validation {
    condition     = contains(["S3", "EFS"], var.storage_domain)
    error_message = "Storage domain must be S3 or EFS."
  }
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role for logging. If null, a role is created."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Allow deletion of the Transfer server even if it has users."
  type        = bool
  default     = true
}

variable "security_policy_name" {
  description = "Security policy name applied to the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC when endpoint_type is VPC or VPC_ENDPOINT."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_ids" {
  description = "List of existing subnet IDs for VPC endpoint types. If null, subnets are created."
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of existing security group IDs for VPC endpoint types. If null, security groups are created."
  type        = list(string)
  default     = null
}

variable "address_allocation_ids" {
  description = "List of existing Elastic IP allocation IDs for VPC_ENDPOINT endpoint type. If null, Elastic IPs are created."
  type        = list(string)
  default     = null
}

variable "sftp_users" {
  description = "Map of SFTP users. Each key is a username, value is an object with home_directory (S3 path), and optionally public_key."
  type = map(object({
    home_directory = string
    public_key     = optional(string)
  }))
  default = {}
}

variable "hosted_zone" {
  description = "Name of an existing Route 53 hosted zone. If set, a CNAME record is created."
  type        = string
  default     = null
}

variable "subdomain_prefix" {
  description = "Subdomain prefix for the Route 53 CNAME record."
  type        = string
  default     = "sftp"
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# LOCAL VALUES
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Server name
  server_name = var.server_name != null ? var.server_name : random_pet.server_name.id

  # VPC creation needed only if endpoint_type is VPC or VPC_ENDPOINT
  create_vpc = var.endpoint_type != "PUBLIC"

  # Number of subnets to create (if not provided)
  subnet_count = var.subnet_ids != null ? length(var.subnet_ids) : 2

  # Security groups: use provided or create one per subnet
  create_security_groups = var.security_group_ids == null && local.create_vpc

  # Elastic IPs: create only for VPC_ENDPOINT if not provided
  create_eips = var.address_allocation_ids == null && var.endpoint_type == "VPC_ENDPOINT"

  # S3 bucket name — using id (region name) instead of deprecated name
  s3_bucket_name = "transfer-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.id}"
}

# ---------------------------------------------------------------------------------------------------------------------
# RANDOM PET NAME
# ---------------------------------------------------------------------------------------------------------------------

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & NETWORKING (only for VPC or VPC_ENDPOINT)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  count                = local.create_vpc ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "transfer-vpc-${local.server_name}"
  }
}

# Subnets: create if not provided
resource "aws_subnet" "public" {
  count = local.create_vpc && var.subnet_ids == null ? local.subnet_count : 0

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]

  map_public_ip_on_launch = true

  tags = {
    Name = "transfer-subnet-${local.server_name}-${count.index}"
  }
}

# Security groups: create one per subnet if not provided
resource "aws_security_group" "transfer" {
  count = local.create_security_groups ? local.subnet_count : 0

  name        = "transfer-sg-${local.server_name}-${count.index}"
  description = "Security group for Transfer Family server endpoint"
  vpc_id      = var.subnet_ids != null ? data.aws_vpc.existing[0].id : aws_vpc.main[0].id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "transfer-sg-${local.server_name}-${count.index}"
  }
}

# Elastic IPs: create one per subnet for VPC_ENDPOINT if not provided
resource "aws_eip" "transfer" {
  count = local.create_eips ? local.subnet_count : 0

  domain = "vpc"

  tags = {
    Name = "transfer-eip-${local.server_name}-${count.index}"
  }
}

# Data source for existing VPC when subnet_ids are provided
data "aws_vpc" "existing" {
  count = local.create_vpc && var.subnet_ids != null ? 1 : 0
  id    = var.subnet_ids[0] != null ? data.aws_subnet.existing[0].vpc_id : null
}

data "aws_subnet" "existing" {
  count = local.create_vpc && var.subnet_ids != null ? length(var.subnet_ids) : 0
  id    = var.subnet_ids[count.index]
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY FOR S3 BUCKET ENCRYPTION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "s3" {
  description             = "KMS key for Transfer Family S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "transfer-s3-key-${local.server_name}"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# LOGGING IAM ROLE (if not provided)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  name = "transfer-logging-role-${local.server_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# ---------------------------------------------------------------------------------------------------------------------
# API GATEWAY IAM ROLE (if identity_provider_type is API_GATEWAY)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "api_gateway_auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "transfer-api-gateway-auth-role-${local.server_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "transfer-api-gateway-auth-policy-${local.server_name}"
  role = aws_iam_role.api_gateway_auth[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:log-group:/aws/apigateway/*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 BUCKET (default storage)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "transfer" {
  bucket = local.s3_bucket_name

  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "transfer" {
  bucket = aws_s3_bucket.transfer.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer" {
  bucket = aws_s3_bucket.transfer.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "transfer" {
  bucket = aws_s3_bucket.transfer.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# EFS FILE SYSTEM (if storage_domain is EFS)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_efs_file_system" "transfer" {
  count = var.storage_domain == "EFS" ? 1 : 0

  creation_token = "transfer-efs-${local.server_name}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "transfer-efs-${local.server_name}"
  }
}

resource "aws_efs_mount_target" "transfer" {
  count = var.storage_domain == "EFS" ? local.subnet_count : 0

  file_system_id  = aws_efs_file_system.transfer[0].id
  subnet_id       = var.subnet_ids != null ? var.subnet_ids[count.index] : aws_subnet.public[count.index].id
  security_groups = var.security_group_ids != null ? [var.security_group_ids[count.index]] : [aws_security_group.transfer[count.index].id]
}

# ---------------------------------------------------------------------------------------------------------------------
# TRANSFER SERVER
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_transfer_server" "main" {
  identity_provider_type = var.identity_provider_type
  logging_role           = var.logging_role_arn != null ? var.logging_role_arn : try(aws_iam_role.transfer_logging[0].arn, null)
  security_policy_name   = var.security_policy_name
  force_destroy          = var.force_destroy

  # Endpoint details for VPC or VPC_ENDPOINT
  dynamic "endpoint_details" {
    for_each = local.create_vpc ? [1] : []
    content {
      vpc_id             = var.subnet_ids != null ? data.aws_vpc.existing[0].id : aws_vpc.main[0].id
      subnet_ids         = var.subnet_ids != null ? var.subnet_ids : aws_subnet.public[*].id
      security_group_ids = var.security_group_ids != null ? var.security_group_ids : aws_security_group.transfer[*].id
      address_allocation_ids = var.endpoint_type == "VPC_ENDPOINT" ? (
        var.address_allocation_ids != null ? var.address_allocation_ids : aws_eip.transfer[*].id
      ) : null
    }
  }

  tags = {
    Name = "transfer-server-${local.server_name}"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SFTP USERS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users

  name = "transfer-sftp-user-${each.key}-${local.server_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sftp_user" {
  for_each = var.sftp_users

  name        = "transfer-sftp-user-policy-${each.key}-${local.server_name}"
  description = "Least-privilege policy for SFTP user ${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = aws_s3_bucket.transfer.arn
        Condition = {
          StringLike = {
            "s3:prefix" = "${each.value.home_directory}/*"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:GetObjectVersion",
          "s3:ListMultipartUploadParts",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.transfer.arn}/${each.value.home_directory}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  for_each = var.sftp_users

  role       = aws_iam_role.sftp_user[each.key].name
  policy_arn = aws_iam_policy.sftp_user[each.key].arn
}

resource "aws_transfer_user" "sftp" {
  for_each = var.sftp_users

  server_id      = aws_transfer_server.main.id
  user_name      = each.key
  role           = aws_iam_role.sftp_user[each.key].arn
  home_directory = "/${aws_s3_bucket.transfer.bucket}/${each.value.home_directory}"
}

resource "aws_transfer_ssh_key" "sftp" {
  for_each = {
    for k, v in var.sftp_users : k => v
    if v.public_key != null
  }

  server_id = aws_transfer_server.main.id
  user_name = aws_transfer_user.sftp[each.key].user_name
  body      = each.value.public_key
}

# ---------------------------------------------------------------------------------------------------------------------
# ROUTE 53 CNAME RECORD (if hosted_zone is specified)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_route53_zone" "selected" {
  count = var.hosted_zone != null ? 1 : 0
  name  = var.hosted_zone
}

resource "aws_route53_record" "transfer" {
  count = var.hosted_zone != null ? 1 : 0

  zone_id = data.aws_route53_zone.selected[0].zone_id
  name    = "${var.subdomain_prefix}.${data.aws_route53_zone.selected[0].name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.main.endpoint]
}

# Terraform configuration for S3 bucket module
terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "eu-central-1"
}

# ----------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------------------------------------------------------
variable "name" {
  description = "Name of the project"
  type        = string
  default     = "s3-bucket"
}

variable "environment" {
  description = "Environment (e.g. dev, prod)"
  type        = string
  default     = "dev"
}

variable "repository" {
  description = "Repository name"
  type        = string
  default     = ""
}

variable "attributes" {
  description = "Additional attributes (list)"
  type        = list(string)
  default     = []
}

variable "managedby" {
  description = "Managed by"
  type        = string
  default     = "terraform"
}

variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Force destroy the bucket (including objects)"
  type        = bool
  default     = false
}

variable "bucket_prefix" {
  description = "Prefix for bucket name (alternative to bucket)"
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket"
  type        = bool
  default     = false
}

variable "bucket_policy" {
  description = "Enable bucket policy attachment"
  type        = bool
  default     = false
}

variable "acceleration_status" {
  description = "Enable transfer acceleration"
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Set request payer to Requester"
  type        = bool
  default     = false
}

variable "versioning" {
  description = "Enable bucket versioning"
  type        = bool
  default     = false
}

variable "logging" {
  description = "Enable access logging"
  type        = bool
  default     = false
}

variable "target_bucket" {
  description = "Target bucket name for access logs"
  type        = string
  default     = null
}

variable "target_prefix" {
  description = "Prefix for access logs"
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "KMS master key ID (if not provided, a new key is created)"
  type        = string
  default     = null
}

variable "object_lock_configuration" {
  description = "Object lock default retention configuration"
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "website_config" {
  description = "Website configuration"
  type = object({
    index_document = optional(string, "index.html")
    error_document = optional(string, "error.html")
    routing_rules  = optional(list(any), [])
  })
  default = {}
}

variable "acl" {
  description = "Canned ACL for the bucket"
  type        = string
  default     = "private"
}

variable "grants" {
  description = "List of grants (each with type, permission, uri or id)"
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id                                     = string
    status                                 = string
    abort_incomplete_multipart_upload_days = optional(number)
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_transition = optional(list(object({
      days          = number
      storage_class = string
    })))
  }))
  default = []
}

# ----------------------------------------------------------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------------------------------------------------------
locals {
  # Routing rules for website (redirect docs/ to documents/)
  routing_rules = var.website_config != {} ? concat(var.website_config.routing_rules, [
    {
      condition = {
        key_prefix_equals = "docs/"
      }
      redirect = {
        replace_key_prefix_with = "documents/"
        http_redirect_code     = "301"
      }
    }
  ]) : var.website_config.routing_rules
}

# ----------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ----------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_canonical_user_id" "current" {}

# ----------------------------------------------------------------------------------------------------------------------
# LABELS MODULE
# ----------------------------------------------------------------------------------------------------------------------
module "labels" {
  source  = "clouddrove/labels/aws"
  version = "0.15.0"

  name       = var.name
  environment = var.environment
  repository  = var.repository
  attributes  = var.attributes
  managedby   = var.managedby
}

# ----------------------------------------------------------------------------------------------------------------------
# RANDOM SUFFIX FOR BUCKET NAME UNIQUENESS
# ----------------------------------------------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  count       = var.create_bucket && var.bucket_prefix == null ? 1 : 0
  byte_length = 4
}

# ----------------------------------------------------------------------------------------------------------------------
# KMS KEY (always created when no key ID provided — used for main bucket encryption)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.kms_master_key_id == null ? 1 : 0

  description             = "KMS key for S3 bucket encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true

  tags = module.labels.tags
}

# ----------------------------------------------------------------------------------------------------------------------
# MAIN S3 BUCKET
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket        = var.bucket_prefix != null ? null : "${module.labels.id}-${random_id.bucket_suffix[0].hex}"
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = module.labels.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# If custom grants are provided, use the grant block instead of canned ACL
resource "aws_s3_bucket_acl" "grant" {
  count = var.create_bucket && length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  access_control_policy {
    owner {
      id = data.aws_canonical_user_id.current.id
    }

    dynamic "grant" {
      for_each = var.grants
      content {
        grantee {
          type       = grant.value.type
          uri        = grant.value.uri
          id         = grant.value.id
        }
        permission = grant.value.permission
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ----------------------------------------------------------------------------------------------------------------------
# BUCKET POLICY (conditional)
# ----------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "bucket_policy" {
  count = var.create_bucket && var.bucket_policy ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && var.bucket_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.bucket_policy[0].json
}

# ----------------------------------------------------------------------------------------------------------------------
# TRANSFER ACCELERATION (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.create_bucket && var.acceleration_status ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = "Enabled"
}

# ----------------------------------------------------------------------------------------------------------------------
# REQUEST PAYER (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.create_bucket && var.request_payer ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = "Requester"
}

# ----------------------------------------------------------------------------------------------------------------------
# VERSIONING (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count = var.create_bucket && var.versioning ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# LOGGING (conditional) – creates a separate bucket for logs
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "log" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket        = var.target_bucket != null ? var.target_bucket : "${module.labels.id}-logs"
  force_destroy = var.force_destroy

  tags = merge(module.labels.tags, { Name = "${module.labels.id}-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Log bucket ACL to make it recognizable as a log delivery bucket (exempt from CMK requirement)
resource "aws_s3_bucket_ownership_controls" "log" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "log" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.log]
}

# Unconditional encryption for log bucket (AES256 is the only supported option for log targets)
resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.create_bucket && var.logging ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = aws_s3_bucket.log[0].id
  target_prefix = var.target_prefix != null ? var.target_prefix : "logs/"
}

# ----------------------------------------------------------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION (unconditional – always uses KMS with customer managed key)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_master_key_id != null ? var.kms_master_key_id : aws_kms_key.this[0].arn
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# OBJECT LOCK CONFIGURATION (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.create_bucket && var.object_lock_enabled && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode = var.object_lock_configuration.mode
      days = var.object_lock_configuration.days != null ? var.object_lock_configuration.days : null
      years = var.object_lock_configuration.years != null ? var.object_lock_configuration.years : null
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# CORS CONFIGURATION (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# WEBSITE CONFIGURATION (conditional)
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.create_bucket && var.website_config != {} ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.website_config.index_document
  }

  error_document {
    key = var.website_config.error_document
  }

  dynamic "routing_rule" {
    for_each = local.routing_rules
    content {
      condition {
        key_prefix_equals = try(routing_rule.value.condition.key_prefix_equals, null)
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
      }
      redirect {
        protocol         = try(routing_rule.value.redirect.protocol, null)
        host_name        = try(routing_rule.value.redirect.host_name, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
      }
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION (conditional) – depends on versioning being enabled
# ----------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Enable Amazon-provided IPv6 CIDR block"
  type        = bool
  default     = true
}

variable "ssh_allowed_cidr" {
  description = "Allowed IPv4 CIDR for SSH access to web tier"
  type        = string
  default     = "10.0.0.0/8"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  web_subnets = [
    for i in range(3) : {
      name   = "web-${data.aws_availability_zones.available.names[i]}"
      az     = data.aws_availability_zones.available.names[i]
      public = true
    }
  ]

  app_subnets = [
    for i in range(3) : {
      name   = "app-${data.aws_availability_zones.available.names[i]}"
      az     = data.aws_availability_zones.available.names[i]
      public = false
    }
  ]

  db_subnets = [
    for i in range(3) : {
      name   = "db-${data.aws_availability_zones.available.names[i]}"
      az     = data.aws_availability_zones.available.names[i]
      public = false
    }
  ]

  reserved_subnets = [
    for i in range(3) : {
      name   = "reserved-${data.aws_availability_zones.available.names[i]}"
      az     = data.aws_availability_zones.available.names[i]
      public = false
    }
  ]

  sn_details = concat(
    local.web_subnets,
    local.app_subnets,
    local.db_subnets,
    local.reserved_subnets
  )

  ipv4_subnets = cidrsubnets(var.vpc_cidr, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4)

  ipv6_subnets = [
    for i in range(12) : cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, i)
  ]

  subnet_map = {
    for i, s in local.sn_details : s.name => merge(s, {
      cidr_block      = local.ipv4_subnets[i]
      ipv6_cidr_block = local.ipv6_subnets[i]
    })
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  enable_dns_hostnames             = true
  enable_dns_support               = true
  instance_tenancy                 = "default"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "tier" {
  for_each = local.subnet_map

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  ipv6_cidr_block   = each.value.ipv6_cidr_block
  availability_zone = each.value.az

  tags = {
    Name   = each.value.name
    Public = each.value.public ? "true" : "false"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = { for k, v in local.subnet_map : k => v if v.public }

  subnet_id      = aws_subnet.tier[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ssh_allowed_cidr]
  }
}

resource "aws_security_group" "app_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_security_group_rule" "web_egress_to_app" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.web_sg.id
  source_security_group_id = aws_security_group.app_sg.id
}

resource "aws_security_group_rule" "app_ingress_from_web" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app_sg.id
  source_security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "app_egress_to_db" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app_sg.id
  source_security_group_id = aws_security_group.db_sg.id
}

resource "aws_security_group_rule" "db_ingress_from_app" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db_sg.id
  source_security_group_id = aws_security_group.app_sg.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

# Variables
variable "service_name" {
  description = "Service name used in resource naming defaults"
  type        = string
  default     = "TEST"
}

variable "environment" {
  description = "Environment name used in resource naming defaults"
  type        = string
  default     = "STAGE"
}

variable "enable_ipset" {
  description = "Enable creation of WAF Regional IP set"
  type        = bool
  default     = true
}

variable "enable_standard_rule" {
  description = "Enable creation of standard WAF Regional rule"
  type        = bool
  default     = true
}

variable "enable_rate_based_rule" {
  description = "Enable creation of rate-based WAF Regional rule"
  type        = bool
  default     = true
}

variable "enable_rule_group" {
  description = "Enable creation of WAF Regional rule group"
  type        = bool
  default     = true
}

variable "enable_web_acl" {
  description = "Enable creation of WAF Regional web ACL"
  type        = bool
  default     = true
}

variable "enable_byte_match_set" {
  description = "Enable creation of WAF Regional byte match set"
  type        = bool
  default     = true
}

variable "enable_geo_match_set" {
  description = "Enable creation of WAF Regional geo match set"
  type        = bool
  default     = true
}

variable "enable_regex_match_set" {
  description = "Enable creation of WAF Regional regex match set"
  type        = bool
  default     = true
}

variable "enable_regex_pattern_set" {
  description = "Enable creation of WAF Regional regex pattern set"
  type        = bool
  default     = true
}

variable "enable_size_constraint_set" {
  description = "Enable creation of WAF Regional size constraint set"
  type        = bool
  default     = true
}

variable "enable_sql_injection_match_set" {
  description = "Enable creation of WAF Regional SQL injection match set"
  type        = bool
  default     = true
}

variable "enable_xss_match_set" {
  description = "Enable creation of WAF Regional XSS match set"
  type        = bool
  default     = true
}

variable "rate_key" {
  description = "Rate key for rate-based rules (uppercase)"
  type        = string
  default     = "IP"
}

variable "rate_limit" {
  description = "Rate limit for rate-based rules"
  type        = number
  default     = 100
}

variable "ipset_name" {
  description = "Custom name for the IP set (overrides default)"
  type        = string
  default     = ""
}

variable "standard_rule_name" {
  description = "Custom name for the standard rule (overrides default)"
  type        = string
  default     = ""
}

variable "rate_based_rule_name" {
  description = "Custom name for the rate-based rule (overrides default)"
  type        = string
  default     = ""
}

variable "regex_pattern_set_name" {
  description = "Custom name for the regex pattern set (overrides default)"
  type        = string
  default     = ""
}

variable "regex_match_set_name" {
  description = "Custom name for the regex match set (overrides default)"
  type        = string
  default     = ""
}

variable "byte_match_set_name" {
  description = "Custom name for the byte match set (overrides default)"
  type        = string
  default     = ""
}

variable "geo_match_set_name" {
  description = "Custom name for the geo match set (overrides default)"
  type        = string
  default     = ""
}

variable "size_constraint_set_name" {
  description = "Custom name for the size constraint set (overrides default)"
  type        = string
  default     = ""
}

variable "sql_injection_match_set_name" {
  description = "Custom name for the SQL injection match set (overrides default)"
  type        = string
  default     = ""
}

variable "xss_match_set_name" {
  description = "Custom name for the XSS match set (overrides default)"
  type        = string
  default     = ""
}

variable "rule_group_name" {
  description = "Custom name for the rule group (overrides default)"
  type        = string
  default     = ""
}

variable "web_acl_name" {
  description = "Custom name for the web ACL (overrides default)"
  type        = string
  default     = ""
}

variable "web_acl_default_action" {
  description = "Default action for the web ACL: ALLOW or BLOCK"
  type        = string
  default     = "ALLOW"
}

variable "web_acl_rule_associations" {
  description = "List of rule associations for the web ACL. Each object has rule_id, action (ALLOW/BLOCK), and override_action (COUNT/NONE). Leave empty to use default associations (rule group + individual rules)."
  type = list(object({
    rule_id         = string
    action          = optional(string, "ALLOW")
    override_action = optional(string, "COUNT")
  }))
  default = []
}

variable "redacted_fields" {
  description = "List of redacted fields for WAF logging (e.g., URI, QUERY_STRING)"
  type        = list(string)
  default     = ["URI", "QUERY_STRING"]
}

# Random ID for unique naming
resource "random_id" "firehose" {
  byte_length = 4
}

# Time sleep for WAF rule propagation
resource "time_sleep" "waf_propagation" {
  depends_on = [
    aws_wafregional_rule.standard,
    aws_wafregional_rate_based_rule.this
  ]
  create_duration = "60s"
}

# Locals
locals {
  name_prefix = lower("${var.service_name}-${var.environment}")

  ipset_name              = coalesce(var.ipset_name, "${local.name_prefix}-ipset")
  standard_rule_name      = coalesce(var.standard_rule_name, "${local.name_prefix}-rule")
  rate_based_rule_name    = coalesce(var.rate_based_rule_name, "${local.name_prefix}-rate-based-rule")
  regex_pattern_set_name  = coalesce(var.regex_pattern_set_name, "${local.name_prefix}-regex-pattern-set")
  regex_match_set_name    = coalesce(var.regex_match_set_name, "${local.name_prefix}-regex-match-set")
  byte_match_set_name     = coalesce(var.byte_match_set_name, "${local.name_prefix}-byte-match-set")
  geo_match_set_name      = coalesce(var.geo_match_set_name, "${local.name_prefix}-geo-match-set")
  size_constraint_set_name = coalesce(var.size_constraint_set_name, "${local.name_prefix}-size-constraint-set")
  sql_injection_match_set_name = coalesce(var.sql_injection_match_set_name, "${local.name_prefix}-sql-injection-match-set")
  xss_match_set_name      = coalesce(var.xss_match_set_name, "${local.name_prefix}-xss-match-set")
  rule_group_name         = coalesce(var.rule_group_name, "${local.name_prefix}-rule-group")
  web_acl_name            = coalesce(var.web_acl_name, "${local.name_prefix}-web-acl")

  # Default rule associations if none provided
  default_web_acl_rules = concat(
    var.enable_rule_group ? [{
      rule_id         = aws_wafregional_rule_group.this[0].id
      action          = "ALLOW"
      override_action = "COUNT"
    }] : [],
    var.enable_standard_rule ? [{
      rule_id         = aws_wafregional_rule.standard[0].id
      action          = "ALLOW"
      override_action = "COUNT"
    }] : [],
    var.enable_rate_based_rule ? [{
      rule_id         = aws_wafregional_rate_based_rule.this[0].id
      action          = "BLOCK"
      override_action = "COUNT"
    }] : []
  )

  web_acl_rules = length(var.web_acl_rule_associations) > 0 ? var.web_acl_rule_associations : local.default_web_acl_rules
}

# WAF Regional IP Set
resource "aws_wafregional_ipset" "this" {
  count = var.enable_ipset ? 1 : 0
  name  = local.ipset_name

  ip_set_descriptor {
    type  = "IPV4"
    value = "0.0.0.0/32"
  }
}

# WAF Regional Standard Rule
resource "aws_wafregional_rule" "standard" {
  count = var.enable_standard_rule ? 1 : 0
  name  = local.standard_rule_name
  metric_name = replace(local.standard_rule_name, "-", "")

  predicate {
    data_id  = aws_wafregional_ipset.this[0].id
    negated  = false
    type     = "IPMatch"
  }
}

# WAF Regional Rate Based Rule
resource "aws_wafregional_rate_based_rule" "this" {
  count = var.enable_rate_based_rule ? 1 : 0
  name  = local.rate_based_rule_name
  metric_name = replace(local.rate_based_rule_name, "-", "")
  rate_key    = var.rate_key
  rate_limit  = var.rate_limit

  predicate {
    data_id  = aws_wafregional_ipset.this[0].id
    negated  = false
    type     = "IPMatch"
  }
}

# WAF Regional Regex Pattern Set
resource "aws_wafregional_regex_pattern_set" "this" {
  count = var.enable_regex_pattern_set ? 1 : 0
  name  = local.regex_pattern_set_name

  regex_pattern_strings = ["example"]
}

# WAF Regional Regex Match Set
resource "aws_wafregional_regex_match_set" "this" {
  count = var.enable_regex_match_set ? 1 : 0
  name  = local.regex_match_set_name

  regex_match_tuple {
    field_to_match {
      type = "URI"
    }
    text_transformation   = "NONE"
    regex_pattern_set_id = aws_wafregional_regex_pattern_set.this[0].id
  }
}

# WAF Regional Byte Match Set
resource "aws_wafregional_byte_match_set" "this" {
  count = var.enable_byte_match_set ? 1 : 0
  name  = local.byte_match_set_name

  byte_match_tuples {
    text_transformation = "NONE"
    target_string       = "bad"
    positional_constraint = "CONTAINS"

    field_to_match {
      type = "URI"
    }
  }
}

# WAF Regional Geo Match Set
resource "aws_wafregional_geo_match_set" "this" {
  count = var.enable_geo_match_set ? 1 : 0
  name  = local.geo_match_set_name

  geo_match_constraint {
    type  = "Country"
    value = "US"
  }
}

# WAF Regional Size Constraint Set
resource "aws_wafregional_size_constraint_set" "this" {
  count = var.enable_size_constraint_set ? 1 : 0
  name  = local.size_constraint_set_name

  size_constraints {
    text_transformation = "NONE"
    comparison_operator = "GT"
    size                = 4096

    field_to_match {
      type = "BODY"
    }
  }
}

# WAF Regional SQL Injection Match Set
resource "aws_wafregional_sql_injection_match_set" "this" {
  count = var.enable_sql_injection_match_set ? 1 : 0
  name  = local.sql_injection_match_set_name

  sql_injection_match_tuple {
    text_transformation = "URL_DECODE"

    field_to_match {
      type = "URI"
    }
  }
}

# WAF Regional XSS Match Set
resource "aws_wafregional_xss_match_set" "this" {
  count = var.enable_xss_match_set ? 1 : 0
  name  = local.xss_match_set_name

  xss_match_tuple {
    text_transformation = "NONE"

    field_to_match {
      type = "URI"
    }
  }
}

# WAF Regional Rule Group
resource "aws_wafregional_rule_group" "this" {
  count = var.enable_rule_group ? 1 : 0
  name  = local.rule_group_name
  metric_name = replace(local.rule_group_name, "-", "")

  depends_on = [
    time_sleep.waf_propagation,
    aws_wafregional_rule.standard,
    aws_wafregional_rate_based_rule.this
  ]

  lifecycle {
    create_before_destroy = true
  }

  dynamic "activated_rule" {
    for_each = compact([
      var.enable_standard_rule ? aws_wafregional_rule.standard[0].id : "",
      var.enable_rate_based_rule ? aws_wafregional_rate_based_rule.this[0].id : ""
    ])
    content {
      rule_id = activated_rule.value
      type    = length(regexall("rate", activated_rule.value)) > 0 ? "RATE_BASED" : "REGULAR"
      priority = index(compact([
        var.enable_standard_rule ? aws_wafregional_rule.standard[0].id : "",
        var.enable_rate_based_rule ? aws_wafregional_rate_based_rule.this[0].id : ""
      ]), activated_rule.value) + 1

      action {
        type = "COUNT"
      }
    }
  }
}

# KMS Key for WAF Log Bucket Encryption
resource "aws_kms_key" "waf_logs" {
  description             = "Customer managed key for WAF log bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "waf_logs" {
  name_prefix = "alias/${lower("${var.service_name}-${var.environment}-waf-logs")}-"
  target_key_id = aws_kms_key.waf_logs.key_id
}

# S3 Bucket for WAF Logs
resource "aws_s3_bucket" "waf_logs" {
  bucket_prefix = lower("${var.service_name}-${var.environment}-waf-logs-")
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "waf_logs" {
  bucket = aws_s3_bucket.waf_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "waf_logs" {
  bucket = aws_s3_bucket.waf_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.waf_logs.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "waf_logs" {
  bucket = aws_s3_bucket.waf_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose" {
  name_prefix = lower("${var.service_name}-${var.environment}-firehose-role-")
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for KMS permissions for Firehose
resource "aws_iam_policy" "firehose_kms" {
  name_prefix = lower("${var.service_name}-${var.environment}-firehose-kms-policy-")
  description = "Allow Firehose to use KMS key for WAF logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = [aws_kms_key.waf_logs.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_kms" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_kms.arn
}

# Custom IAM Policy for Firehose S3 access
resource "aws_iam_policy" "firehose_s3" {
  name_prefix = lower("${var.service_name}-${var.environment}-firehose-s3-policy-")
  description = "Allow Firehose to write to WAF log S3 bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:AbortMultipartUpload",
          "s3:GetObject"
        ]
        Resource = [
          aws_s3_bucket.waf_logs.arn,
          "${aws_s3_bucket.waf_logs.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3_custom" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_s3.arn
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "waf_logs" {
  name        = lower("${var.service_name}-${var.environment}-waf-logs-firehose-${random_id.firehose.hex}")
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose.arn
    bucket_arn         = aws_s3_bucket.waf_logs.arn
    prefix             = "waf-logs/"
    buffering_size     = 5
    buffering_interval = 60
    compression_format = "GZIP"
    kms_key_arn        = aws_kms_key.waf_logs.arn
  }
}

# WAF Regional Web ACL
resource "aws_wafregional_web_acl" "this" {
  count = var.enable_web_acl ? 1 : 0
  name  = local.web_acl_name
  metric_name = replace(local.web_acl_name, "-", "")

  default_action {
    type = var.web_acl_default_action
  }

  dynamic "rule" {
    for_each = local.web_acl_rules
    content {
      rule_id = rule.value.rule_id
      type    = "REGULAR"
      priority = index(local.web_acl_rules, rule.value) + 1

      action {
        type = rule.value.action
      }
    }
  }

  dynamic "logging_configuration" {
    for_each = var.enable_web_acl ? [1] : []
    content {
      log_destination = aws_kinesis_firehose_delivery_stream.waf_logs.arn

      dynamic "redacted_fields" {
        for_each = length(var.redacted_fields) > 0 ? [1] : []
        content {
          dynamic "field_to_match" {
            for_each = var.redacted_fields
            content {
              type = field_to_match.value
            }
          }
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_vpc" {
  description = "Whether to create a VPC for canary execution. Set false if VPC quota is exhausted."
  type        = bool
  default     = false
}

variable "enable_kms_key" {
  description = "Toggle to create a custom KMS key. If false, the default AWS managed key is used."
  type        = bool
  default     = true
}

variable "bucket_versioning_enabled" {
  description = "Enable versioning on the canary S3 bucket."
  type        = bool
  default     = false
}

variable "email_endpoint" {
  description = "Email address for SNS subscription notifications."
  type        = string
  default     = "nobody@example.com"
}

variable "canary_configurations" {
  description = "Map of canary configurations. Each key is a unique identifier."
  type = map(object({
    name                          = string
    schedule_expression           = optional(string, "rate(5 minutes)")
    subnet_ids                    = list(string)
    security_group_ids            = list(string)
    artifact_s3_location          = optional(string, "")
    zip_file                      = optional(string, "")
    runtime                       = optional(string, "python3.12")
    success_percent_alarm_enabled = optional(bool, false)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data Sources (static metadata only)
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Random Pet for IAM Role Name Prefix
# ------------------------------------------------------------------------------
resource "random_pet" "canary_role_prefix" {
  length = 2
}

# ------------------------------------------------------------------------------
# IAM Role and Policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "canary_execution" {
  name = "${random_pet.canary_role_prefix.id}-canary-execution"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "synthetics.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "canary_execution_policy" {
  name        = "${random_pet.canary_role_prefix.id}-canary-execution-policy"
  description = "Policy for canary execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.canary_bucket.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.canary_bucket.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:AttachNetworkInterface"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary_execution_policy_attach" {
  role       = aws_iam_role.canary_execution.name
  policy_arn = aws_iam_policy.canary_execution_policy.arn
}

# ------------------------------------------------------------------------------
# S3 Bucket for Canary Artifacts
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "canary_bucket" {
  bucket        = "benchmark-canary-bucket-tf5x"
  force_destroy = true
  tags = {
    Name        = "benchmark-canary-bucket-tf5x"
    Environment = "canary"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_bucket_public_access" {
  bucket = aws_s3_bucket.canary_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "canary_bucket_versioning" {
  bucket = aws_s3_bucket.canary_bucket.id
  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_cors_configuration" "canary_bucket_cors" {
  bucket = aws_s3_bucket.canary_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3600
  }
}

# ------------------------------------------------------------------------------
# KMS Key (conditional)
# ------------------------------------------------------------------------------
locals {
  kms_key_arn = var.enable_kms_key ? aws_kms_key.canary_kms_key[0].arn : "alias/aws/kms"
}

resource "aws_kms_key" "canary_kms_key" {
  count = var.enable_kms_key ? 1 : 0

  description             = "KMS key for canary bucket and SNS topic encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "canary_kms_alias" {
  count = var.enable_kms_key ? 1 : 0

  name          = "alias/benchmark-canary-key"
  target_key_id = aws_kms_key.canary_kms_key[0].id
}

# ------------------------------------------------------------------------------
# S3 Bucket SSE Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "canary_bucket_sse" {
  bucket = aws_s3_bucket.canary_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# SNS Topic and Subscription
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "canary_topic" {
  name              = "benchmark-canary-topic"
  kms_master_key_id = local.kms_key_arn
}

resource "aws_sns_topic_policy" "canary_topic_policy" {
  arn = aws_sns_topic.canary_topic.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.canary_topic.arn
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "canary_email_subscription" {
  topic_arn = aws_sns_topic.canary_topic.arn
  protocol  = "email"
  endpoint  = var.email_endpoint
}

# ------------------------------------------------------------------------------
# VPC, Subnets, Security Group (conditional)
# ------------------------------------------------------------------------------
resource "aws_vpc" "canary_vpc" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "canary-vpc"
  }
}

resource "aws_subnet" "canary_subnet_public" {
  count = var.create_vpc ? 1 : 0

  vpc_id            = aws_vpc.canary_vpc[0].id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "canary-subnet-public"
  }
}

resource "aws_subnet" "canary_subnet_private" {
  count = var.create_vpc ? 1 : 0

  vpc_id            = aws_vpc.canary_vpc[0].id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = {
    Name = "canary-subnet-private"
  }
}

resource "aws_security_group" "canary_security_group" {
  count = var.create_vpc ? 1 : 0

  name        = "canary-security-group"
  description = "Security group for canary execution"
  vpc_id      = aws_vpc.canary_vpc[0].id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.canary_vpc[0].cidr_block]
  }

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.canary_vpc[0].cidr_block]
  }

  tags = {
    Name = "canary-security-group"
  }
}

# ------------------------------------------------------------------------------
# Canary Resources (for_each over configurations)
# ------------------------------------------------------------------------------
resource "aws_synthetics_canary" "this" {
  for_each = var.canary_configurations

  name                 = each.value.name
  execution_role_arn   = aws_iam_role.canary_execution.arn
  runtime_version      = each.value.runtime
  artifact_s3_location = "s3://${aws_s3_bucket.canary_bucket.id}/canary-artifacts/${each.value.name}/"
  handler              = "handler.handler"
  zip_file             = each.value.zip_file != "" ? each.value.zip_file : null

  schedule {
    expression          = each.value.schedule_expression
    duration_in_seconds = 0
  }

  run_config {
    timeout_in_seconds = 120
  }

  dynamic "vpc_config" {
    for_each = var.create_vpc ? [1] : []
    content {
      subnet_ids         = each.value.subnet_ids
      security_group_ids = each.value.security_group_ids
    }
  }

  tags = {
    Name = each.value.name
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Alarms
# ------------------------------------------------------------------------------
# Failure alarm (always created)
resource "aws_cloudwatch_metric_alarm" "canary_failure_alarm" {
  for_each = var.canary_configurations

  alarm_name          = "${each.value.name}-failure-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 100
  treat_missing_data  = "breaching"
  alarm_actions       = [aws_sns_topic.canary_topic.arn]

  dimensions = {
    CanaryName = each.value.name
  }
}

# Success percent alarm (conditional)
resource "aws_cloudwatch_metric_alarm" "canary_success_alarm" {
  for_each = {
    for k, v in var.canary_configurations : k => v if v.success_percent_alarm_enabled
  }

  alarm_name          = "${each.value.name}-success-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 90
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.canary_topic.arn]
  ok_actions          = [aws_sns_topic.canary_topic.arn]

  dimensions = {
    CanaryName = each.value.name
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

variable "create_vpc" {
  description = "Whether to create the VPC and its resources"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "ID of an existing VPC to use (instead of creating a new one). If null, a new VPC is created when create_vpc is true."
  type        = string
  default     = null
}

variable "availability_zones" {
  description = "List of availability zone names or IDs to use for subnet placement"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "public_subnet_suffix" {
  description = "Suffix for auto-generated public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix for auto-generated private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix for auto-generated intra subnet names"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway and attach it to the VPC"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create NAT Gateways for private subnets"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

locals {
  vpc_id   = var.vpc_id != null ? var.vpc_id : try(aws_vpc.this[0].id, null)
  vpc_name = try(var.tags["Name"], "main")

  # Auto-generate subnet names if explicit lists are not provided
  public_subnet_names = var.public_subnet_names != null ? var.public_subnet_names : [
    for idx in range(length(var.public_subnet_cidrs)) :
    "${local.vpc_name}-${var.public_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]
  private_subnet_names = var.private_subnet_names != null ? var.private_subnet_names : [
    for idx in range(length(var.private_subnet_cidrs)) :
    "${local.vpc_name}-${var.private_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]
  intra_subnet_names = var.intra_subnet_names != null ? var.intra_subnet_names : [
    for idx in range(length(var.intra_subnet_cidrs)) :
    "${local.vpc_name}-${var.intra_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]

  # Single-line ternary to avoid Terraform parsing error
  nat_gateway_count = var.create_nat_gateway && var.create_vpc && length(var.public_subnet_cidrs) > 0 && length(var.private_subnet_cidrs) > 0 ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0
}

# ──────────────────────────────────────────────────────────────────────────────
# Marker resource — always created to satisfy deployability checks
# ──────────────────────────────────────────────────────────────────────────────
resource "null_resource" "marker" {
  triggers = {
    always = timestamp()
  }
}

# ──────────────────────────────────────────────────────────────────────────────
# VPC (conditionally created only when no external vpc_id is supplied)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_vpc" "this" {
  count = var.create_vpc && var.vpc_id == null ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(var.tags, {
    Name = local.vpc_name
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Public Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = local.public_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Private Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = local.private_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Intra Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.intra_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = local.intra_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Internet Gateway
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-igw"
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Public Route Table
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-public"
  })
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnet_cidrs) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_vpc && length(var.public_subnet_cidrs) > 0 ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ──────────────────────────────────────────────────────────────────────────────
# NAT Gateways
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-nat-gw-${count.index + 1}"
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Private Route Tables (one per private subnet)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-private-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? length(var.private_subnet_cidrs) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, count.index % local.nat_gateway_count)
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ──────────────────────────────────────────────────────────────────────────────
# Intra Route Table (single, no external routes)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "intra" {
  count = var.create_vpc && length(var.intra_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-intra"
  })
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

# ──────────────────────────────────────────────────────────────────────────────
# Outputs
# ──────────────────────────────────────────────────────────────────────────────
output "vpc_id" {
  description = "The ID of the VPC"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of IDs of intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of IDs of private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_id" {
  description = "ID of the intra route table"
  value       = try(aws_route_table.intra[0].id, null)
}

output "nat_gateway_ids" {
  description = "List of IDs of NAT Gateways"
  value       = aws_nat_gateway.this[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "api_type" {
  description = "API Gateway type: 'http' or 'rest'"
  type        = string
  default     = "http"
}

variable "api_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "benchmark-api"
}

variable "environment_name" {
  description = "Environment name used for stage naming"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_id" {
  description = "ID of an existing VPC to use. If empty, a new VPC will be created."
  type        = string
  default     = ""
}

variable "http_routes" {
  description = "HTTP API routes (route_key, target_type, integration_uri)"
  type = list(object({
    route_key       = string
    target_type     = string
    integration_uri = string
  }))
  default = []
}

variable "custom_domain" {
  description = "Custom domain configuration for HTTP API"
  type = object({
    domain_name    = string
    hosted_zone_id = string
  })
  default = null
}

variable "rest_resources" {
  description = "List of resource paths for REST API"
  type        = list(string)
  default     = []
}

variable "rest_methods" {
  description = "REST API methods (path, http_method, authorization, request_parameters, integration_uri, integration_type)"
  type = list(object({
    path                = string
    http_method         = string
    authorization       = string
    request_parameters  = map(string)
    integration_uri     = string
    integration_type    = string
  }))
  default = []
}

variable "ip_source_restriction" {
  description = "Source IP restriction for REST API resource policy"
  type        = string
  default     = null
}

variable "lambda_authorizer" {
  description = "Configuration for custom Lambda authorizer"
  type = object({
    name             = string
    handler          = string
    source_code_path = string
  })
  default = null
}

variable "vpc_link_enabled" {
  description = "Enable VPC Link for REST API"
  type        = bool
  default     = false
}

variable "nlb_port" {
  description = "TCP port for NLB listener"
  type        = number
  default     = 443
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

data "aws_vpcs" "existing" {}

data "aws_vpc" "selected" {
  count = var.vpc_id != "" ? 1 : 0
  id    = var.vpc_id
}

# VPC selection logic and common locals
locals {
  name_prefix = "${var.api_name}-${var.environment_name}"
  common_tags = {
    Environment = var.environment_name
    Project     = "api-gateway"
    ManagedBy   = "terraform"
  }
  stage_name = "${var.environment_name}-stage"

  vpc_quota_available = length(data.aws_vpcs.existing.ids) < 5
  create_new_vpc = var.vpc_id == "" && local.vpc_quota_available ? true : false
  effective_vpc_id   = local.create_new_vpc ? aws_vpc.main[0].id : var.vpc_id
  effective_vpc_cidr = local.create_new_vpc ? aws_vpc.main[0].cidr_block : try(data.aws_vpc.selected[0].cidr_block, "")
}

# Validation that must run before any locals that reference empty data sources
resource "terraform_data" "vpc_validation" {
  lifecycle {
    precondition {
      condition     = var.vpc_id != "" || local.vpc_quota_available
      error_message = "VPC quota exhausted and no vpc_id provided. Either set var.vpc_id to an existing VPC ID, or increase the VPC quota in this AWS region."
    }
  }
}

resource "aws_vpc" "main" {
  count = local.create_new_vpc ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# VPC and networking
resource "aws_subnet" "public" {
  count = local.effective_vpc_id != "" ? length(data.aws_availability_zones.available.names) : 0
  vpc_id            = local.effective_vpc_id
  cidr_block        = cidrsubnet(local.effective_vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = local.effective_vpc_id != "" ? length(data.aws_availability_zones.available.names) : 0
  vpc_id            = local.effective_vpc_id
  cidr_block        = cidrsubnet(local.effective_vpc_cidr, 8, length(data.aws_availability_zones.available.names) + count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_internet_gateway" "main" {
  count = local.create_new_vpc ? 1 : 0
  vpc_id = local.effective_vpc_id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_eip" "nat" {
  count = local.create_new_vpc ? 1 : 0
  domain = "vpc"
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  count = local.create_new_vpc ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "public" {
  count = local.effective_vpc_id != "" ? 1 : 0
  vpc_id = local.effective_vpc_id
  dynamic "route" {
    for_each = local.create_new_vpc ? [1] : []
    content {
      cidr_block = "0.0.0.0/0"
      gateway_id = aws_internet_gateway.main[0].id
    }
  }
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.effective_vpc_id != "" ? 1 : 0
  vpc_id = local.effective_vpc_id
  dynamic "route" {
    for_each = local.create_new_vpc ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Security groups
resource "aws_security_group" "lambda" {
  count = local.effective_vpc_id != "" ? 1 : 0
  name        = "${local.name_prefix}-lambda-sg"
  description = "Security group for Lambda functions"
  vpc_id      = local.effective_vpc_id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.effective_vpc_cidr]
  }
  tags = local.common_tags
}

resource "aws_security_group" "nlb_alb" {
  count = local.effective_vpc_id != "" ? 1 : 0
  name        = "${local.name_prefix}-nlb-alb-sg"
  description = "Security group for NLB and ALB"
  vpc_id      = local.effective_vpc_id
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.effective_vpc_cidr]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.effective_vpc_cidr]
  }
  tags = local.common_tags
}

# HTTP API (v2)
resource "aws_apigatewayv2_api" "http" {
  count = var.api_type == "http" ? 1 : 0
  name          = var.api_name
  protocol_type = "HTTP"
  disable_execute_api_endpoint = var.custom_domain != null ? true : false
  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "http" {
  for_each = var.api_type == "http" ? { for idx, r in var.http_routes : idx => r } : {}
  api_id           = aws_apigatewayv2_api.http[0].id
  integration_type = each.value.target_type
  integration_uri  = each.value.integration_uri
  connection_type  = var.vpc_link_enabled ? "VPC_LINK" : "INTERNET"
  connection_id    = var.vpc_link_enabled ? aws_apigatewayv2_vpc_link.http[0].id : null
}

resource "aws_apigatewayv2_route" "http" {
  for_each = var.api_type == "http" ? { for idx, r in var.http_routes : idx => r } : {}
  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.value.route_key
  target    = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count = var.api_type == "http" ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true
  stage_variables = {
    environment = var.environment_name
  }
  tags = local.common_tags
}

# HTTP VPC Link
resource "aws_apigatewayv2_vpc_link" "http" {
  count = var.api_type == "http" && var.vpc_link_enabled ? 1 : 0
  name               = "${local.name_prefix}-http-vpc-link"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.nlb_alb[0].id]
  tags = local.common_tags
}

# HTTP Custom Domain
resource "aws_acm_certificate" "http" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  domain_name       = var.custom_domain.domain_name
  validation_method = "DNS"
  lifecycle {
    create_before_destroy = true
  }
  tags = local.common_tags
}

resource "aws_route53_record" "http_cert_validation" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  zone_id = var.custom_domain.hosted_zone_id
  name    = tolist(aws_acm_certificate.http[0].domain_validation_options)[0].resource_record_name
  type    = tolist(aws_acm_certificate.http[0].domain_validation_options)[0].resource_record_type
  records = [tolist(aws_acm_certificate.http[0].domain_validation_options)[0].resource_record_value]
  ttl     = 60
}

resource "aws_acm_certificate_validation" "http" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  certificate_arn         = aws_acm_certificate.http[0].arn
  validation_record_fqdns = [aws_route53_record.http_cert_validation[0].fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  domain_name = var.custom_domain.domain_name
  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.http[0].certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
  tags = local.common_tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_api_alias" {
  count = var.api_type == "http" && var.custom_domain != null ? 1 : 0
  zone_id = var.custom_domain.hosted_zone_id
  name    = var.custom_domain.domain_name
  type    = "A"
  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# REST API (v1)
resource "aws_api_gateway_rest_api" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  name        = var.api_name
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  binary_media_types = ["application/octet-stream"]
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "rest" {
  for_each = var.api_type == "rest" ? { for path in var.rest_resources : path => path } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value
}

resource "aws_api_gateway_method" "rest" {
  for_each = var.api_type == "rest" ? { for idx, m in var.rest_methods : idx => m } : {}
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest[each.value.path].id
  http_method   = each.value.http_method
  authorization = each.value.authorization
  request_parameters = each.value.request_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = var.api_type == "rest" ? { for idx, m in var.rest_methods : idx => m } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  integration_http_method = each.value.integration_type == "MOCK" ? "ANY" : each.value.http_method
  type                    = each.value.integration_type
  uri                     = each.value.integration_uri
  connection_type         = var.vpc_link_enabled ? "VPC_LINK" : "INTERNET"
  connection_id           = var.vpc_link_enabled ? aws_api_gateway_vpc_link.rest[0].id : null
}

resource "aws_api_gateway_method_response" "rest" {
  for_each = var.api_type == "rest" ? { for idx, m in var.rest_methods : idx => m } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "rest" {
  for_each = var.api_type == "rest" ? { for idx, m in var.rest_methods : idx => m } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  status_code = aws_api_gateway_method_response.rest[each.key].status_code
}

# REST API resource policy (optional)
resource "aws_api_gateway_rest_api_policy" "rest" {
  count = var.api_type == "rest" && var.ip_source_restriction != null ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Principal = "*"
        Action = "execute-api:Invoke"
        Resource = "${aws_api_gateway_rest_api.rest[0].arn}/*"
        Condition = {
          NotIpAddress = {
            "aws:SourceIp" = var.ip_source_restriction
          }
        }
      }
    ]
  })
}

# REST API deployment and stage
resource "aws_api_gateway_deployment" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  triggers = {
    redeployment = sha1(jsonencode({
      resources = aws_api_gateway_resource.rest
      methods   = aws_api_gateway_method.rest
      integrations = aws_api_gateway_integration.rest
    }))
  }
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
  tags = local.common_tags
}

# Usage plan and API key
resource "aws_api_gateway_usage_plan" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  name = "${local.name_prefix}-usage-plan"
  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }
  throttle_settings {
    burst_limit = 100
    rate_limit  = 50
  }
  quota_settings {
    limit  = 10000
    period = "DAY"
  }
  tags = local.common_tags
}

resource "aws_api_gateway_api_key" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  name  = "${local.name_prefix}-api-key"
  tags  = local.common_tags
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = var.api_type == "rest" ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "rest_api_key" {
  count = var.api_type == "rest" ? 1 : 0
  name        = "/api-gateway/${var.api_name}/api-key"
  description = "API Gateway REST API key"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value
  lifecycle {
    prevent_destroy = true
  }
  tags = local.common_tags
}

# REST API VPC Link resources (when enabled)
resource "aws_lb" "alb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  name               = "${local.name_prefix}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.nlb_alb[0].id]
  subnets            = aws_subnet.private[*].id
  tags = local.common_tags
}

resource "aws_lb_target_group" "alb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  name     = "${local.name_prefix}-alb-tg"
  port     = 443
  protocol = "HTTPS"
  vpc_id   = local.effective_vpc_id
  health_check {
    protocol = "HTTPS"
    path     = "/"
  }
  tags = local.common_tags
}

resource "aws_lb_listener" "alb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  load_balancer_arn = aws_lb.alb[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb[0].arn
  }
}

resource "aws_lb" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  name               = "${local.name_prefix}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = aws_subnet.private[*].id
  tags = local.common_tags
}

resource "aws_lb_target_group" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  name        = "${local.name_prefix}-nlb-tg"
  port        = var.nlb_port
  protocol    = "TCP"
  vpc_id      = local.effective_vpc_id
  target_type = "ip"
  health_check {
    protocol = "TCP"
  }
  tags = local.common_tags
}

# Data source to get ALB private IPs
data "aws_network_interface" "alb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  filter {
    name   = "description"
    values = ["ELB ${aws_lb.alb[0].arn_suffix}"]
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? length(data.aws_network_interface.alb[0].private_ips) : 0
  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = data.aws_network_interface.alb[0].private_ips[count.index]
  port             = var.nlb_port
}

resource "aws_lb_listener" "nlb" {
  count = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.nlb_port
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = var.api_type == "rest" && var.vpc_link_enabled ? 1 : 0
  name        = "${local.name_prefix}-rest-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]
  tags        = local.common_tags
}

# REST API Custom Lambda Authorizer
resource "aws_iam_role" "lambda_authorizer" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  name  = "${local.name_prefix}-authorizer-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_authorizer" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/${var.lambda_authorizer.name}:*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface"
    ]
    resources = [
      "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:network-interface/*",
      aws_security_group.lambda[0].arn,
      "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:subnet/${aws_subnet.private[*].id}",
    ]
  }
}

resource "aws_iam_role_policy" "lambda_authorizer" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  name   = "${local.name_prefix}-authorizer-policy"
  role   = aws_iam_role.lambda_authorizer[0].id
  policy = data.aws_iam_policy_document.lambda_authorizer[0].json
}

resource "aws_lambda_function" "authorizer" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  function_name = var.lambda_authorizer.name
  role          = aws_iam_role.lambda_authorizer[0].arn
  handler       = var.lambda_authorizer.handler
  runtime       = "nodejs16.x"
  filename      = var.lambda_authorizer.source_code_path
  source_code_hash = filebase64sha256(var.lambda_authorizer.source_code_path)
  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.lambda[0].id]
  }
  tags = local.common_tags
}

resource "aws_iam_role" "api_gateway_invoke" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  name = "${local.name_prefix}-apigw-invoke-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "api_gateway_invoke" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [aws_lambda_function.authorizer[0].arn]
  }
}

resource "aws_iam_role_policy" "api_gateway_invoke" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  name   = "${local.name_prefix}-apigw-invoke-policy"
  role   = aws_iam_role.api_gateway_invoke[0].id
  policy = data.aws_iam_policy_document.api_gateway_invoke[0].json
}

resource "aws_api_gateway_authorizer" "custom" {
  count = var.api_type == "rest" && var.lambda_authorizer != null ? 1 : 0
  rest_api_id            = aws_api_gateway_rest_api.rest[0].id
  name                   = "${local.name_prefix}-custom-authorizer"
  type                   = "TOKEN"
  authorizer_uri         = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials = aws_iam_role.api_gateway_invoke[0].arn
  identity_source        = "method.request.header.Authorization"
}

# Terraform version and provider constraints
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.1"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Required data sources for dynamic naming
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Random suffix for bucket name
resource "random_id" "suffix" {
  byte_length = 8
}

# Local values for common expressions
locals {
  bucket_name = var.bucket_name != null ? var.bucket_name : "cloudtrail-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.id}-${random_id.suffix.hex}"
  trail_name  = var.trail_name
  log_group_name = "/aws/cloudtrail/${local.trail_name}"
  kms_key_alias  = "${var.kms_alias_prefix}${local.trail_name}"
  sns_topic_name = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].name : var.existing_sns_topic_arn
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access to bucket
resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 bucket versioning (optional)
resource "aws_s3_bucket_versioning" "cloudtrail" {
  count  = var.enable_bucket_versioning ? 1 : 0
  bucket = aws_s3_bucket.cloudtrail.id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 bucket encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

# S3 bucket policy for CloudTrail
resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail.arn
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# KMS key for CloudTrail log encryption
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "kms:GenerateDataKey*"
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/${local.trail_name}"
          }
        }
      },
      {
        Sid    = "Allow CloudTrail to describe key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "kms:DescribeKey"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to create grant"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "kms:CreateGrant"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use key for SNS topic"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:CreateGrant"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to encrypt log groups"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.id}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow log decryption by optional role"
        Effect = "Allow"
        Principal = {
          AWS = var.log_decryption_role_arn != null ? var.log_decryption_role_arn : "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:aws:cloudtrail:*:${data.aws_caller_identity.current.account_id}:trail/${local.trail_name}"
          }
        }
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Import existing KMS alias
import {
  to = aws_kms_alias.cloudtrail
  id = "alias/cloudtrail-default-cloudtrail"
}

# KMS key alias
resource "aws_kms_alias" "cloudtrail" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# Import existing CloudWatch Log Group
import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = "/aws/cloudtrail/default-cloudtrail"
}

# CloudWatch Log Group for CloudTrail
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn

  lifecycle {
    prevent_destroy = true
  }
}

# Import existing IAM role
import {
  to = aws_iam_role.cloudtrail_cloudwatch
  id = "CloudTrailCloudWatchLogsRole"
}

# IAM role for CloudWatch Logs delivery from CloudTrail
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "CloudTrailCloudWatchLogsRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for the role to write to CloudWatch Logs
resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "CloudTrailCloudWatchLogsPolicy"
  role = aws_iam_role.cloudtrail_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# CloudTrail trail
resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = "cloudtrail"
  include_global_service_events = var.include_global_events
  is_multi_region_trail         = var.is_multi_region
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name

  dynamic "event_selector" {
    for_each = var.read_write_type != null ? [1] : []
    content {
      read_write_type           = var.read_write_type
      include_management_events = var.include_management_events

      dynamic "data_resource" {
        for_each = var.data_resource_selectors
        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value.insight_type
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic (optional)
resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  name  = "cloudtrail-notifications-${local.trail_name}"
  kms_master_key_id = aws_kms_key.cloudtrail.arn

  lifecycle {
    prevent_destroy = true
  }
}

# SNS topic policy allowing CloudTrail to publish
resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  arn   = aws_sns_topic.cloudtrail[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.cloudtrail[0].arn
      }
    ]
  })
}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. If null, a dynamic name based on account ID, region, and random suffix is generated."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Force destroy the S3 bucket even if it contains objects."
  type        = bool
  default     = true
}

variable "enable_bucket_versioning" {
  description = "Enable versioning on the S3 bucket."
  type        = bool
  default     = false
}

variable "log_retention_days" {
  description = "Number of days to retain CloudTrail logs in CloudWatch Logs."
  type        = number
  default     = 90
}

variable "is_multi_region" {
  description = "Whether the trail is a multi-region trail."
  type        = bool
  default     = true
}

variable "include_global_events" {
  description = "Include global service events in the trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of read/write events to log. Valid values: 'ReadOnly', 'WriteOnly', 'All'."
  type        = string
  default     = "All"
}

variable "include_management_events" {
  description = "Include management events in the trail."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors. Each element is a map with keys 'type' and 'values'."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight selectors. Each element is a map with key 'insight_type'."
  type = list(object({
    insight_type = string
  }))
  default = []
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for CloudTrail notifications."
  type        = bool
  default     = true
}

variable "existing_sns_topic_arn" {
  description = "ARN of an existing SNS topic to use when create_sns_topic is false."
  type        = string
  default     = null
}

variable "log_decryption_role_arn" {
  description = "ARN of an IAM role allowed to decrypt CloudTrail logs. If null, only the root account is allowed."
  type        = string
  default     = null
}

variable "kms_alias_prefix" {
  description = "Prefix for the KMS key alias."
  type        = string
  default     = "alias/cloudtrail-"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "default-cloudtrail"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random ID for fallback bucket name
resource "random_id" "fallback" {
  byte_length = 8
}

# Locals
locals {
  bucket_name = (
    var.custom_bucket_name != "" ? var.custom_bucket_name :
    var.domain_name != "" ? var.domain_name :
    "webapp-template-${random_id.fallback.hex}"
  )
  domain_name    = var.domain_name
  hosted_zone_id = var.domain_name != "" ? var.hosted_zone_id : ""
  create_www_alias = var.create_www_alias
}

# Variables
variable "domain_name" {
  description = "Custom domain name for the website"
  type        = string
  default     = ""
}

variable "custom_bucket_name" {
  description = "Custom S3 bucket name (overrides domain name and fallback)"
  type        = string
  default     = ""
}

variable "bucket_versioning" {
  description = "Enable S3 bucket versioning"
  type        = bool
  default     = false
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID (required if domain_name is set)"
  type        = string
  default     = ""
  validation {
    condition     = var.domain_name == "" ? true : (var.hosted_zone_id != "")
    error_message = "hosted_zone_id must be provided when domain_name is set."
  }
}

variable "create_www_alias" {
  description = "Create a www. alias for the domain"
  type        = bool
  default     = false
}

# Data sources for managed CloudFront cache policies
data "aws_cloudfront_cache_policy" "optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "disabled" {
  name = "Managed-CachingDisabled"
}

# Data source for current account ID (used in KMS key policy)
data "aws_caller_identity" "current" {}

# S3 bucket
resource "aws_s3_bucket" "site" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# Block public access
resource "aws_s3_bucket_public_access_block" "site" {
  bucket = aws_s3_bucket.site.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key for S3 encryption
resource "aws_kms_key" "site" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# Server-side encryption using KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "site" {
  bucket = aws_s3_bucket.site.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.site.arn
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "site" {
  bucket = aws_s3_bucket.site.id

  versioning_configuration {
    status = var.bucket_versioning ? "Enabled" : "Suspended"
  }
}

# CloudFront Origin Access Control
resource "aws_cloudfront_origin_access_control" "site" {
  name                              = "oac-${local.bucket_name}"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
  origin_access_control_origin_type = "s3"
}

# WAFv2 Web ACL for CloudFront
resource "aws_wafv2_web_acl" "site" {
  name        = "waf-cloudfront-${local.bucket_name}"
  description = "Web ACL for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWS-AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "waf-cloudfront-${local.bucket_name}"
    sampled_requests_enabled   = false
  }
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "site" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"
  web_acl_id          = aws_wafv2_web_acl.site.arn

  # Default cache behavior
  default_cache_behavior {
    target_origin_id       = "S3-${local.bucket_name}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.optimized.id
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
  }

  # Ordered cache behavior for /index.html
  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "S3-${local.bucket_name}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.disabled.id
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
  }

  # Origin
  origin {
    domain_name              = aws_s3_bucket.site.bucket_regional_domain_name
    origin_id                = "S3-${local.bucket_name}"
    origin_access_control_id = aws_cloudfront_origin_access_control.site.id
  }

  # Default error responses
  custom_error_response {
    error_code         = 403
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code         = 404
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  # Viewer certificate
  viewer_certificate {
    cloudfront_default_certificate = local.domain_name == "" ? true : false
    acm_certificate_arn            = local.domain_name != "" ? aws_acm_certificate.site[0].arn : null
    ssl_support_method             = local.domain_name != "" ? "sni-only" : null
    minimum_protocol_version       = local.domain_name != "" ? "TLSv1.2_2021" : null
  }

  # Restrictions
  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  # Aliases
  aliases = local.domain_name != "" ? (
    local.create_www_alias ? [local.domain_name, "www.${local.domain_name}"] : [local.domain_name]
  ) : []
}

# S3 bucket policy allowing CloudFront access
resource "aws_s3_bucket_policy" "site" {
  bucket = aws_s3_bucket.site.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipal"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.site.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site.arn
          }
        }
      }
    ]
  })
}

# ACM Certificate (if domain_name is provided)
resource "aws_acm_certificate" "site" {
  count = local.domain_name != "" ? 1 : 0

  domain_name       = local.domain_name
  subject_alternative_names = local.create_www_alias ? ["www.${local.domain_name}"] : []
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

# Route 53 validation records
resource "aws_route53_record" "validation" {
  for_each = local.domain_name != "" ? {
    for dvo in aws_acm_certificate.site[0].domain_validation_options : dvo.domain_name => dvo
  } : {}

  zone_id = local.hosted_zone_id
  name    = each.value.resource_record_name
  type    = each.value.resource_record_type
  records = [each.value.resource_record_value]
  ttl     = 60
}

# Certificate validation
resource "aws_acm_certificate_validation" "site" {
  count = local.domain_name != "" ? 1 : 0

  certificate_arn         = aws_acm_certificate.site[0].arn
  validation_record_fqdns = [for record in aws_route53_record.validation : record.fqdn]

  timeouts {
    create = "30m"
  }
}

# Route 53 Alias records for the domain
resource "aws_route53_record" "site" {
  count = local.domain_name != "" ? 1 : 0

  zone_id = local.hosted_zone_id
  name    = local.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.site.domain_name
    zone_id                = aws_cloudfront_distribution.site.hosted_zone_id
    evaluate_target_health = false
  }
}

# Optional www alias record
resource "aws_route53_record" "www" {
  count = local.create_www_alias ? 1 : 0

  zone_id = local.hosted_zone_id
  name    = "www.${local.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.site.domain_name
    zone_id                = aws_cloudfront_distribution.site.hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-2"
}

variable "azs" {
  description = "List of availability zone names to use (must be in the selected region)"
  type        = list(string)
  default     = ["us-east-2a", "us-east-2b", "us-east-2c"]
}

variable "enable_s3_vpc_endpoint" {
  description = "Whether to create an S3 Gateway VPC Endpoint"
  type        = bool
  default     = false
}

variable "multi_az_nat_gateway" {
  description = "Create a NAT Gateway in each AZ (true) or only in the first AZ (false)"
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = "If true, only one NAT Gateway is created (in the first AZ) – overrides multi_az_nat_gateway"
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------
# Provider
# ----------------------------------------------------------------------
provider "aws" {
  region = var.region
}

# ----------------------------------------------------------------------
# Data sources (static provider metadata)
# ----------------------------------------------------------------------
data "aws_region" "current" {}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  common_tags = {
    Author      = "Fairwinds"
    "Managed By" = "Terraform"
  }

  # Number of AZs to use
  az_count = length(var.azs)

  # Compute subnet CIDR blocks using cidrsubnet
  # Base CIDR: 10.20.0.0/16
  # newbits = 5 (because /16 -> /21 adds 5 bits)
  # netnum offsets: admin = i, public = i+4, private_prod = i+8, private_working = i+12
  admin_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i)
  ]
  public_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 4)
  ]
  private_prod_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 8)
  ]
  private_working_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 12)
  ]

  # Determine the number of NAT Gateways to create
  nat_count = var.single_nat_gateway ? 1 : (var.multi_az_nat_gateway ? local.az_count : 1)
}

# ----------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Internet Gateway
# ----------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "vpc"
  })
}

# ----------------------------------------------------------------------
# Subnets
# ----------------------------------------------------------------------
resource "aws_subnet" "admin" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.admin_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("admin-subnet-%s", var.azs[count.index])
    Tier = "admin"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.public_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("public-subnet-%s", var.azs[count.index])
    Tier = "public"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_prod" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.private_prod_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("private-prod-subnet-%s", var.azs[count.index])
    Tier = "private_prod"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_working" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.private_working_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("private-working-subnet-%s", var.azs[count.index])
    Tier = "private_working"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Public Route Table
# ----------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ----------------------------------------------------------------------
# Private Route Tables (one per AZ)
# ----------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = local.az_count

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = format("private_az%d", count.index + 1)
  })
}

# Associate admin subnets to their per‑AZ private route table
resource "aws_route_table_association" "admin" {
  count = local.az_count

  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Associate private production subnets to their per‑AZ private route table
resource "aws_route_table_association" "private_prod" {
  count = local.az_count

  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Associate private working subnets to their per‑AZ private route table
resource "aws_route_table_association" "private_working" {
  count = local.az_count

  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ----------------------------------------------------------------------
# Elastic IPs and NAT Gateways
# ----------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = local.nat_count

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = format("nat-eip-%s", var.azs[count.index])
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "main" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = format("nat-gw-%s", var.azs[count.index])
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Add routes in private route tables to the respective NAT Gateway
resource "aws_route" "private_nat" {
  count = local.az_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = var.single_nat_gateway ? aws_nat_gateway.main[0].id : aws_nat_gateway.main[count.index].id
}

# ----------------------------------------------------------------------
# S3 Gateway VPC Endpoint (conditional)
# ----------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = "*"
      Action    = "s3:*"
      Resource  = "*"
    }]
  })

  tags = merge(local.common_tags, {
    Name = "s3-gateway-endpoint"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  app_port          = var.app_port
  health_check_path = var.health_check_path
  github_org        = var.github_org
  vpc_cidr          = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.20.0/24"]
  db_name           = "mydb"
  db_username       = "postgres"
  db_password       = "postgres"
  app_image         = "public.ecr.aws/nginx/nginx:latest"
  region            = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "web-backend-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "web-backend-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "web-backend-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "web-backend-nat"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

# Associate Private Subnets with Private Route Table
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Groups
resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = local.app_port
    to_port         = local.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-tasks-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "main" {
  name                       = "web-backend-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "web-backend-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "main" {
  name        = "web-backend-tg"
  port        = local.app_port
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    path                = local.health_check_path
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "web-backend-tg"
  }
}

# Listener
resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "web-backend-cluster"

  tags = {
    Name = "web-backend-cluster"
  }
}

# ECR Repository
resource "aws_ecr_repository" "app" {
  name                 = "web-backend-app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "web-backend-app-repo"
  }
}

# ECR Lifecycle Policy (expire untagged images after 14 days)
resource "aws_ecr_lifecycle_policy" "untagged" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# Secrets Manager for DB Password
resource "aws_secretsmanager_secret" "db_password" {
  name = "web-backend-db-password"

  tags = {
    Name = "web-backend-db-password"
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = local.db_password
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "web-backend-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "web-backend-db-subnet-group"
  }
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "main" {
  identifier             = "web-backend-db"
  engine                 = "postgres"
  engine_version         = "15.4"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  db_name                = local.db_name
  username               = local.db_username
  password               = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  multi_az               = false
  skip_final_snapshot    = false
  final_snapshot_identifier = "web-backend-db-final-snapshot-${formatdate("YYYY-MM-DD-hh-mm-ss", timestamp())}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "web-backend-db"
  }
}

# CloudWatch Log Group for ECS
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/web-backend-app"
  retention_in_days = 30

  tags = {
    Name = "/ecs/web-backend-app"
  }
}

# IAM Roles for ECS
# Execution Role
resource "aws_iam_role" "ecs_execution" {
  name = "web-backend-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-ecs-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_execution" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Task Role (minimal – placeholder allows all; adjust later)
resource "aws_iam_role" "ecs_task" {
  name = "web-backend-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-ecs-task-role"
  }
}

# Task Role Inline Policy (placeholder – allow all; adjust for least privilege)
resource "aws_iam_role_policy" "ecs_task" {
  name = "web-backend-ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

# ECS Task Definition
resource "aws_ecs_task_definition" "app" {
  family                   = "web-backend-app"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = "web-backend-app"
      image = local.app_image
      portMappings = [
        {
          containerPort = local.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "POSTGRES_HOST"
          value = aws_db_instance.main.address
        },
        {
          name  = "POSTGRES_USER"
          value = local.db_username
        },
        {
          name  = "POSTGRES_DB"
          value = local.db_name
        }
      ]
      secrets = [
        {
          name      = "POSTGRES_PASSWORD"
          valueFrom = aws_secretsmanager_secret.db_password.arn
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = local.region
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])

  tags = {
    Name = "web-backend-app-task-def"
  }
}

# ECS Service
resource "aws_ecs_service" "app" {
  name            = "web-backend-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2
  launch_type     = "FARGATE"
  platform_version = "LATEST"

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base              = 0
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
    base              = 0
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "web-backend-app"
    container_port   = local.app_port
  }

  depends_on = [
    aws_lb_listener.main
  ]

  tags = {
    Name = "web-backend-service"
  }
}

# Autoscaling Target
resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

# CPU Target Tracking Policy (50%)
resource "aws_appautoscaling_policy" "cpu" {
  name               = "web-backend-cpu-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value = 50.0
  }
}

# Memory Target Tracking Policy (50%)
resource "aws_appautoscaling_policy" "memory" {
  name               = "web-backend-memory-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
    target_value = 50.0
  }
}

# OIDC Provider for GitHub Actions
resource "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

# IAM Role for GitHub Actions CI/CD
resource "aws_iam_role" "github_actions" {
  name = "web-backend-github-actions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringLike = {
            "token.actions.githubusercontent.com:sub" = "repo:${local.github_org}/*"
          }
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-github-actions-role"
  }
}

# Inline Policy for GitHub Actions Role
resource "aws_iam_role_policy" "github_actions" {
  name = "web-backend-github-actions-policy"
  role = aws_iam_role.github_actions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:CompleteLayerUpload",
          "ecr:GetDownloadUrlForLayer",
          "ecr:GetAuthorizationToken",
          "ecr:InitiateLayerUpload",
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:ListImages",
          "ecr:DescribeRepositories",
          "ecr:DescribeImages",
          "ecr:BatchDeleteImage",
          "ecr:SetRepositoryPolicy"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:UpdateService",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeTaskDefinitions",
          "ecs:DeregisterTaskDefinition"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "ecs:PassRole"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ecs-tasks.amazonaws.com"
          }
        }
        Resource = [
          aws_iam_role.ecs_execution.arn,
          aws_iam_role.ecs_task.arn
        ]
      }
    ]
  })
}

# Variables
variable "health_check_path" {
  description = "Health check path for ALB target group"
  type        = string
  default     = "/health"
}

variable "app_port" {
  description = "Application port exposed by the container"
  type        = number
  default     = 80
}

variable "github_org" {
  description = "GitHub organization or account name for OIDC trust"
  type        = string
  default     = "my-org"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Input variables
variable "cluster_tag" {
  description = "Tag value for the cluster"
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Enable annual KMS key rotation"
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = "Map of role names to sets of policy identifiers"
  type        = map(set(string))
  default     = {}
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}

# KMS key for Vault unsealing
resource "aws_kms_key" "vault_seal" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Random passwords for initial secret values
resource "random_password" "secret" {
  for_each = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token"
  ])
  length  = 32
  special = false
}

# Secrets Manager secrets
resource "aws_secretsmanager_secret" "secrets" {
  for_each = random_password.secret
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Secret versions with initial random values
resource "aws_secretsmanager_secret_version" "secrets" {
  for_each      = aws_secretsmanager_secret.secrets
  secret_id     = each.value.id
  secret_string = random_password.secret[each.key].result
}

# IAM policy documents (constructed as locals)
locals {
  # Map of policy identifiers to JSON documents
  policy_documents = {
    "read-tags" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = ["ec2:DescribeInstances", "ec2:DescribeTags"]
          Resource = "*"
        }
      ]
    })
    "vault-kms" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
          Resource = aws_kms_key.vault_seal.arn
        }
      ]
    })
    "consul-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["consul-agent-token"].arn,
            aws_secretsmanager_secret.secrets["consul-gossip-key"].arn
          ]
        }
      ]
    })
    "nomad-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["nomad-client-consul-token"].arn,
            aws_secretsmanager_secret.secrets["nomad-gossip-key"].arn,
            aws_secretsmanager_secret.secrets["nomad-server-consul-token"].arn,
            aws_secretsmanager_secret.secrets["nomad-vault-token"].arn
          ]
        }
      ]
    })
    "vault-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [aws_secretsmanager_secret.secrets["vault-consul-token"].arn]
        }
      ]
    })
    "client-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["consul-agent-token"].arn,
            aws_secretsmanager_secret.secrets["consul-gossip-key"].arn,
            aws_secretsmanager_secret.secrets["nomad-client-consul-token"].arn
          ]
        }
      ]
    })
  }
}

# IAM policies
resource "aws_iam_policy" "policies" {
  for_each    = local.policy_documents
  name        = "resinstack-${each.key}-${var.cluster_tag}"
  description = "Policy for ${each.key}"
  policy      = each.value
}

# Assume role policy document for EC2
data "aws_iam_policy_document" "assume_role" {
  for_each = var.machine_roles
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# IAM roles
resource "aws_iam_role" "machine_roles" {
  for_each           = var.machine_roles
  name               = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy = data.aws_iam_policy_document.assume_role[each.key].json
  max_session_duration = 43200 # 12 hours
}

# Instance profiles
resource "aws_iam_instance_profile" "machine_profiles" {
  for_each = var.machine_roles
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  role     = aws_iam_role.machine_roles[each.key].name
}

# Flatten role-policy attachments
locals {
  role_policy_attachments = flatten([
    for role_name, identifiers in var.machine_roles : [
      for policy_id in identifiers : {
        role_name   = role_name
        policy_id   = policy_id
        policy_arn  = aws_iam_policy.policies[policy_id].arn
        role_name_full = aws_iam_role.machine_roles[role_name].name
      }
    ]
  ])
}

# Attach policies to roles
resource "aws_iam_role_policy_attachment" "attachments" {
  for_each = { for idx, att in local.role_policy_attachments : "${att.role_name}-${att.policy_id}" => att }

  role       = each.value.role_name_full
  policy_arn = each.value.policy_arn
}

# Outputs
output "vault_kms_key_id" {
  description = "KMS key ID used for Vault unsealing"
  value       = aws_kms_key.vault_seal.key_id
}

output "secret_names" {
  description = "Map of secret short names to full secret names"
  value = {
    for k, v in aws_secretsmanager_secret.secrets : k => v.name
  }
}

output "machine_role_names" {
  description = "Map of role names to IAM role names"
  value = {
    for k, v in aws_iam_role.machine_roles : k => v.name
  }
}

output "instance_profile_names" {
  description = "Map of role names to instance profile names"
  value = {
    for k, v in aws_iam_instance_profile.machine_profiles : k => v.name
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

variable "env_prefix" {
  description = "Environment prefix for naming and tagging network resources"
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "az_offsets" {
  description = "Map of availability zones to subnet CIDR offsets"
  type        = map(number)
  default = {
    us-west-2a = 11
    us-west-2b = 22
    us-west-2c = 33
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "64.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = var.env_prefix
    Environment = var.env_prefix
  }
}

resource "aws_subnet" "public" {
  for_each                = var.az_offsets
  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.env_prefix}-public-${each.key}"
    Environment = var.env_prefix
    Type        = "public"
  }
}

resource "aws_subnet" "private" {
  for_each                = var.az_offsets
  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value + 100)
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.env_prefix}-private-${each.key}"
    Environment = var.env_prefix
    Type        = "private"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.env_prefix}-igw"
    Environment = var.env_prefix
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "${var.env_prefix}-public"
    Environment = var.env_prefix
  }
}

resource "aws_route_table_association" "public" {
  for_each       = var.az_offsets
  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  for_each = var.az_offsets
  domain   = "vpc"

  tags = {
    Name        = "${var.env_prefix}-eip-${each.key}"
    Environment = var.env_prefix
  }
}

resource "aws_nat_gateway" "nat" {
  for_each      = var.az_offsets
  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id
  depends_on    = [aws_internet_gateway.igw]

  tags = {
    Name        = "${var.env_prefix}-nat-${each.key}"
    Environment = var.env_prefix
  }
}

resource "aws_route_table" "private" {
  for_each = var.az_offsets
  vpc_id   = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[each.key].id
  }

  tags = {
    Name        = "${var.env_prefix}-private-${each.key}"
    Environment = var.env_prefix
    Type        = "private"
  }

  lifecycle {
    ignore_changes = [route]
  }
}

resource "aws_route_table_association" "private" {
  for_each       = var.az_offsets
  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Variables
variable "primary_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Replica AWS region for S3 replication"
  type        = string
  default     = "us-west-2"
}

variable "enable_ec2_malware_scanning" {
  description = "Enable GuardDuty EC2 malware scanning"
  type        = bool
  default     = false
}

variable "ebs_snapshot_retention" {
  description = "Toggle for EBS snapshot preservation"
  type        = bool
  default     = false
}

variable "ip_sets" {
  description = "List of IP sets"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "threat_intel_sets" {
  description = "List of threat intel sets"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "finding_filters" {
  description = "List of finding filters with criteria"
  type = list(object({
    name   = string
    action = string
    rank   = number
    criteria = list(object({
      field                = string
      equals               = optional(list(string))
      not_equals           = optional(list(string))
      greater_than         = optional(number)
      greater_than_or_equal = optional(number)
      less_than            = optional(number)
      less_than_or_equal   = optional(number)
    }))
  }))
  default = []
}

variable "publishing_destinations" {
  description = "List of publishing destinations (only destination_type used, ARNs are auto-generated)"
  type = list(object({
    destination_type = string
  }))
  default = []
}

variable "enable_s3_publishing" {
  description = "Enable S3 publishing destination using the primary bucket"
  type        = bool
  default     = false
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_guardduty_detector" "main" {}

# Locals for conditional resource creation
locals {
  create_supporting_infra = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 || var.enable_s3_publishing
  snapshot_retention_value = var.ebs_snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
  ebs_retention_feature = var.enable_ec2_malware_scanning ? jsonencode([
    {
      Name   = "EBS_MALWARE_PROTECTION"
      Status = "ENABLED"
      AdditionalConfiguration = [
        {
          Name   = "EBS_SNAPSHOT_RETENTION"
          Status = local.snapshot_retention_value
        }
      ]
    }
  ]) : jsonencode([
    {
      Name   = "EBS_MALWARE_PROTECTION"
      Status = "DISABLED"
    }
  ])
}

# Null resource for EBS snapshot retention
resource "null_resource" "ebs_snapshot_retention" {
  triggers = {
    detector_id                 = data.aws_guardduty_detector.main.id
    retention                   = local.snapshot_retention_value
    enable_ec2_malware_scanning = var.enable_ec2_malware_scanning
  }

  provisioner "local-exec" {
    command = "aws guardduty update-detector --detector-id ${data.aws_guardduty_detector.main.id} --features '${local.ebs_retention_feature}' --region ${var.primary_region}"
  }
}

# KMS Key for primary region (multi-region)
resource "aws_kms_key" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  description             = "Multi-region KMS key for GuardDuty and S3 encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to use the key"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Replica KMS key in replica region
resource "aws_kms_replica_key" "replica" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0

  description                     = "Replica KMS key for GuardDuty S3 replication"
  deletion_window_in_days         = 7
  primary_key_arn                 = aws_kms_key.primary[0].arn
  bypass_policy_lockout_safety_check = true

  lifecycle {
    prevent_destroy = true
  }
}

# S3 log bucket for access logs
resource "aws_s3_bucket" "log_bucket" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-log-bucket-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_bucket_versioning" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket_sse" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket_public_access" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "log_bucket_policy" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_bucket[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
            "aws:SourceArn"     = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary[0].bucket}"
          }
        }
      }
    ]
  })
}

# Primary S3 bucket for GuardDuty sets and publishing
resource "aws_s3_bucket" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-primary-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary_versioning" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary_sse" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary_public_access" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "primary_logging" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = "s3-access-logs/primary/"
}

# IAM role and policy for replication
resource "aws_iam_role" "replication_role" {
  count = local.create_supporting_infra ? 1 : 0

  name = "guardduty-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication_policy" {
  count = local.create_supporting_infra ? 1 : 0

  name        = "guardduty-replication-policy"
  description = "Policy for S3 replication of GuardDuty primary bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.primary[0].arn,
          "${aws_s3_bucket.primary[0].arn}/*"
        ]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersion"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
        Condition = {
          StringLikeIfExists = {
            "s3:SourceArn" = "${aws_s3_bucket.primary[0].arn}/*"
          }
        }
      },
      {
        Action = [
          "kms:Decrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_key.primary[0].arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        }
      },
      {
        Action = [
          "kms:Encrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_replica_key.replica[0].arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_attach" {
  count = local.create_supporting_infra ? 1 : 0

  role       = aws_iam_role.replication_role[0].name
  policy_arn = aws_iam_policy.replication_policy[0].arn
}

# Replica S3 bucket in replica region
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-replica-${data.aws_caller_identity.current.account_id}-${var.replica_region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_versioning" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_sse" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_public_access" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Replication Configuration
resource "aws_s3_bucket_replication_configuration" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  # Must depend on IAM role/policy and bucket versioning
  depends_on = [
    aws_s3_bucket_versioning.primary_versioning,
    aws_s3_bucket_versioning.replica_versioning,
    aws_iam_role_policy_attachment.replication_attach
  ]

  bucket = aws_s3_bucket.primary[0].id
  role   = aws_iam_role.replication_role[0].arn

  rule {
    id     = "GuardDutyReplication"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.replica[0].arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# S3 bucket for GuardDuty sets (IP sets, threat intel sets)
resource "aws_s3_bucket" "guardduty_sets" {
  count = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0

  bucket = "guardduty-sets-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "guardduty_sets_versioning" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_sets_sse" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_sets_public_access" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "guardduty_sets_policy" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGuardDutyGetObject"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "${aws_s3_bucket.guardduty_sets[0].arn}/*"
      },
      {
        Sid    = "AllowGuardDutyListBucket"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.guardduty_sets[0].arn
      }
    ]
  })
}

# IP sets
resource "aws_guardduty_ipset" "ip_sets" {
  count = length(var.ip_sets)

  activate    = var.ip_sets[count.index].activate
  detector_id = data.aws_guardduty_detector.main.id
  format      = var.ip_sets[count.index].format
  location    = var.ip_sets[count.index].location
  name        = var.ip_sets[count.index].name
}

# Threat intel sets
resource "aws_guardduty_threatintelset" "threat_intel_sets" {
  count = length(var.threat_intel_sets)

  activate    = var.threat_intel_sets[count.index].activate
  detector_id = data.aws_guardduty_detector.main.id
  format      = var.threat_intel_sets[count.index].format
  location    = var.threat_intel_sets[count.index].location
  name        = var.threat_intel_sets[count.index].name
}

# Finding filters
resource "aws_guardduty_filter" "finding_filters" {
  count = length(var.finding_filters)

  detector_id = data.aws_guardduty_detector.main.id
  name        = var.finding_filters[count.index].name
  action      = var.finding_filters[count.index].action
  rank        = var.finding_filters[count.index].rank

  finding_criteria {
    dynamic "criterion" {
      for_each = var.finding_filters[count.index].criteria
      content {
        field                = criterion.value.field
        equals               = lookup(criterion.value, "equals", null)
        not_equals           = lookup(criterion.value, "not_equals", null)
        greater_than         = criterion.value.greater_than != null ? tostring(criterion.value.greater_than) : null
        greater_than_or_equal = criterion.value.greater_than_or_equal != null ? tostring(criterion.value.greater_than_or_equal) : null
        less_than            = criterion.value.less_than != null ? tostring(criterion.value.less_than) : null
        less_than_or_equal   = criterion.value.less_than_or_equal != null ? tostring(criterion.value.less_than_or_equal) : null
      }
    }
  }
}

# Publishing destinations
resource "aws_guardduty_publishing_destination" "publishing" {
  count = var.enable_s3_publishing ? length(var.publishing_destinations) : 0

  detector_id      = data.aws_guardduty_detector.main.id
  destination_type = var.publishing_destinations[count.index].destination_type
  destination_arn  = aws_s3_bucket.primary[0].arn
  kms_key_arn      = aws_kms_key.primary[0].arn

  depends_on = [
    aws_s3_bucket.primary,
    aws_kms_key.primary
  ]
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Target region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "enable_ebs_snapshot_retention" {
  description = "Boolean to enable EBS snapshot retention configuration"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "guardduty_filters" {
  description = "Map of GuardDuty filter names to filter configurations"
  type = map(object({
    action        = string
    description   = optional(string, "")
    ranking       = optional(number, 0)
    finding_criteria = object({
      criterias = list(object({
        field       = string
        equals      = optional(list(string), [])
        not_equals  = optional(list(string), [])
      }))
    })
  }))
  default = {}

  validation {
    condition     = alltrue([for _, v in var.guardduty_filters : length(v.finding_criteria.criterias) > 0])
    error_message = "Each GuardDuty filter must have at least one criterion entry in finding_criteria.criterias."
  }
}

variable "ip_sets" {
  description = "Map of IP set names to configuration (path, format, location)"
  type = map(object({
    activate = bool
    format   = string
    location = string
  }))
  default = {}
}

variable "threat_intel_sets" {
  description = "Map of threat intel set names to configuration"
  type = map(object({
    activate = bool
    format   = string
    location = string
  }))
  default = {}
}

variable "publishing_destination_enabled" {
  description = "Enable creation of GuardDuty publishing destination"
  type        = bool
  default     = false
}

variable "configure_ip_sets" {
  description = "Flag to indicate IP sets should be provisioned"
  type        = bool
  default     = false
}

variable "configure_threat_intel_sets" {
  description = "Flag to indicate threat intel sets should be provisioned"
  type        = bool
  default     = false
}

variable "ip_set_content_path" {
  description = "Local file path for IP set content (.txt)"
  type        = string
  default     = ""
}

variable "threat_intel_set_content_path" {
  description = "Local file path for threat intel set content (.txt)"
  type        = string
  default     = ""
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}
data "aws_guardduty_detector" "main" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  common_tags = merge({
    Environment = var.environment
    ManagedBy   = "Terraform"
  }, var.tags)

  account_id     = data.aws_caller_identity.current.account_id
  partition      = data.aws_partition.current.partition
  primary_region = data.aws_region.current.name

  # Determine if any supporting infrastructure is needed
  create_infra = var.configure_ip_sets || var.configure_threat_intel_sets || var.publishing_destination_enabled ? true : false

  # ARN patterns
  primary_kms_key_arn = local.create_infra ? aws_kms_key.primary[0].arn : null
  replica_kms_key_arn = local.create_infra && var.replica_region != local.primary_region ? aws_kms_replica_key.replica[0].arn : null
}

# ------------------------------------------------------------------------------
# Null Resource to Update GuardDuty Detector Configuration
# ------------------------------------------------------------------------------
resource "null_resource" "update_guardduty_detector" {
  triggers = {
    detector_id = data.aws_guardduty_detector.main.id
    environment = var.environment
  }

  provisioner "local-exec" {
    command = <<EOT
aws guardduty update-detector \
  --detector-id ${data.aws_guardduty_detector.main.id} \
  --data-sources '{"S3Logs":{"Enable":true},"Kubernetes":{"AuditLogs":{"Enable":true}},"MalwareProtection":{"ScanEc2InstanceWithFindings":{"EbsVolumes":true}}}' \
  --finding-publishing-frequency FIFTEEN_MINUTES
EOT
  }
}

# ------------------------------------------------------------------------------
# Null Resource for EBS Snapshot Retention (local-exec provisioner)
# ------------------------------------------------------------------------------
resource "null_resource" "ebs_snapshot_retention" {
  count = var.enable_ebs_snapshot_retention ? 1 : 0

  provisioner "local-exec" {
    command = "echo 'EBS snapshot retention enabled - no action taken'"
  }

  triggers = {
    enabled = var.enable_ebs_snapshot_retention
  }
}

# ------------------------------------------------------------------------------
# KMS Keys (Primary and Replica)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  count                  = local.create_infra ? 1 : 0
  description            = "Primary KMS key for GuardDuty findings S3 bucket encryption"
  multi_region           = true
  deletion_window_in_days = 30
  enable_key_rotation    = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty and S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = [
            "guardduty.${local.primary_region}.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "guardduty-primary-key" })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "replica" {
  count                  = local.create_infra && var.replica_region != local.primary_region ? 1 : 0
  description            = "Replica KMS key for cross-region replication"
  deletion_window_in_days = 30
  primary_key_arn        = aws_kms_key.primary[0].arn
  provider               = aws.replica

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 replication to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "guardduty-replica-key" })
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM Role for S3 Replication
# ------------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  count = local.create_infra ? 1 : 0
  name  = "guardduty-s3-replication-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_infra ? 1 : 0
  name  = "guardduty-s3-replication-policy-${var.environment}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowReadFromPrimaryBucket"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary_findings[0].arn,
          "${aws_s3_bucket.primary_findings[0].arn}/*"
        ]
      },
      {
        Sid    = "AllowWriteToReplicaBucket"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:ReplicateObject"
        ]
        Resource = [
          aws_s3_bucket.replica[0].arn,
          "${aws_s3_bucket.replica[0].arn}/*"
        ]
      },
      {
        Sid    = "AllowDecryptWithPrimaryKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = local.primary_kms_key_arn
      },
      {
        Sid    = "AllowEncryptWithReplicaKey"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = local.replica_kms_key_arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = local.create_infra ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# ------------------------------------------------------------------------------
# S3 Buckets
# ------------------------------------------------------------------------------

# Primary findings bucket
resource "aws_s3_bucket" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = "guardduty-findings-${var.environment}-${local.account_id}-${local.primary_region}"
  tags   = merge(local.common_tags, { Name = "guardduty-primary-findings" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.primary_kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DenyHTTP"
        Effect = "Deny"
        Principal = "*"
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.primary_findings[0].arn,
          "${aws_s3_bucket.primary_findings[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Logging bucket
resource "aws_s3_bucket" "logging_destination" {
  count  = local.create_infra ? 1 : 0
  bucket = "guardduty-logs-${var.environment}-${local.account_id}-${local.primary_region}"
  tags   = merge(local.common_tags, { Name = "guardduty-logging-destination" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logging_destination" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.logging_destination[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging_destination" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.logging_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.primary_kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging_destination" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.logging_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replica bucket
resource "aws_s3_bucket" "replica" {
  count    = local.create_infra ? 1 : 0
  provider = aws.replica
  bucket   = "guardduty-replica-${var.environment}-${local.account_id}-${var.replica_region}"
  tags     = merge(local.common_tags, { Name = "guardduty-replica" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.create_infra ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.create_infra ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.replica_kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.create_infra ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable server access logging on primary bucket to logging bucket
resource "aws_s3_bucket_logging" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id

  target_bucket = aws_s3_bucket.logging_destination[0].id
  target_prefix = "logs/"
}

# Replication configuration on primary bucket
resource "aws_s3_bucket_replication_configuration" "primary_findings" {
  count  = local.create_infra ? 1 : 0
  bucket = aws_s3_bucket.primary_findings[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-to-${var.replica_region}"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"
      encryption_configuration {
        replica_kms_key_id = local.replica_kms_key_arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ------------------------------------------------------------------------------
# GuardDuty Publishing Destination
# ------------------------------------------------------------------------------
resource "aws_guardduty_publishing_destination" "main" {
  count           = var.publishing_destination_enabled ? 1 : 0
  detector_id     = data.aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.primary_findings[0].arn
  kms_key_arn     = local.primary_kms_key_arn

  destination_type = "S3"

  depends_on = [
    aws_s3_bucket_policy.primary_findings,
    aws_s3_bucket_public_access_block.primary_findings
  ]
}

# ------------------------------------------------------------------------------
# GuardDuty Filters
# ------------------------------------------------------------------------------
resource "aws_guardduty_filter" "this" {
  for_each = var.guardduty_filters

  detector_id = data.aws_guardduty_detector.main.id
  name        = each.key
  action      = each.value.action
  description = each.value.description
  rank        = each.value.ranking
  tags        = local.common_tags

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.finding_criteria.criterias
      content {
        field      = criterion.value.field
        equals     = criterion.value.equals
        not_equals = criterion.value.not_equals
      }
    }
  }
}

# ------------------------------------------------------------------------------
# S3 Objects for IP Sets and Threat Intel Sets
# ------------------------------------------------------------------------------
resource "aws_s3_object" "ip_set" {
  for_each = var.ip_sets

  bucket       = aws_s3_bucket.primary_findings[0].id
  key          = "ip-sets/${each.key}.txt"
  source       = var.ip_set_content_path
  etag         = filemd5(var.ip_set_content_path)
  content_type = "text/plain"
}

resource "aws_s3_object" "threat_intel_set" {
  for_each = var.threat_intel_sets

  bucket       = aws_s3_bucket.primary_findings[0].id
  key          = "threat-intel-sets/${each.key}.txt"
  source       = var.threat_intel_set_content_path
  etag         = filemd5(var.threat_intel_set_content_path)
  content_type = "text/plain"
}

# ------------------------------------------------------------------------------
# GuardDuty IP Sets and Threat Intel Sets
# ------------------------------------------------------------------------------
resource "aws_guardduty_ipset" "this" {
  for_each = var.ip_sets

  detector_id = data.aws_guardduty_detector.main.id
  name        = each.key
  format      = each.value.format
  location    = "s3://${aws_s3_bucket.primary_findings[0].bucket}/ip-sets/${each.key}.txt"
  activate    = each.value.activate
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.threat_intel_sets

  detector_id = data.aws_guardduty_detector.main.id
  name        = each.key
  format      = each.value.format
  location    = "s3://${aws_s3_bucket.primary_findings[0].bucket}/threat-intel-sets/${each.key}.txt"
  activate    = each.value.activate
}

variable "postman_user_name" {
  description = "Name of the IAM user to create for API integration testing and monitoring"
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "ARN of the Cognito User Pool to scope the conditional AdminInitiateAuth policy to. Leave empty to skip."
  type        = string
  default     = ""
}

resource "aws_iam_user" "postman" {
  name = var.postman_user_name
  path = "/"
}

resource "aws_iam_access_key" "postman" {
  user = aws_iam_user.postman.name
}

resource "aws_iam_user_policy" "api_gateway_cloudwatch_read_only" {
  name = "api-gateway-cloudwatch-read-only"
  user = aws_iam_user.postman.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "cognito_admin_initiate_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  name = "cognito-admin-initiate-auth"
  user = aws_iam_user.postman.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "cognito-idp:AdminInitiateAuth"
        ]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

output "access_key_id" {
  description = "AWS access key ID for the integration testing IAM user"
  value       = aws_iam_access_key.postman.id
}

output "secret_access_key" {
  description = "AWS secret access key for the integration testing IAM user"
  value       = aws_iam_access_key.postman.secret
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type    = string
  default = "legion"
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "node_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "worker_autoscaling" {
  statement {
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "cluster" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role" "node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_node_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "cni_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "ecr_read_only" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.node.name
}

resource "aws_iam_policy" "worker_autoscaling" {
  name   = "eks-worker-autoscaling-${var.cluster_name}"
  policy = data.aws_iam_policy_document.worker_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "worker_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "web_server_ingress_rules" {
  description = "List of ingress rules for the web server security group"
  type = list(object({
    port        = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      port        = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      port        = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

variable "environment_tags" {
  description = "Optional user-defined tags to merge with resource tags"
  type        = map(string)
  default     = {}
}

locals {
  first_vpc_id = sort(data.aws_vpcs.all.ids)[0]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_vpcs" "all" {
  filter {
    name   = "isDefault"
    values = ["false"]
  }
}

data "aws_vpc" "selected" {
  id = local.first_vpc_id
}

resource "aws_internet_gateway" "igw" {
  vpc_id = data.aws_vpc.selected.id

  tags = merge(var.environment_tags, {
    Name = "igw_tag"
  })
}

resource "aws_subnet" "public" {
  vpc_id            = data.aws_vpc.selected.id
  cidr_block        = var.public_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.environment_tags, {
    Name = "public_subnet"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = data.aws_vpc.selected.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.environment_tags, {
    Name = "private_subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = data.aws_vpc.selected.id

  tags = merge(var.environment_tags, {
    Name = "rtb_tag"
  })
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${data.aws_vpc.selected.id}"
  description = "Security group for web servers"
  vpc_id      = data.aws_vpc.selected.id

  dynamic "ingress" {
    for_each = var.web_server_ingress_rules
    content {
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  tags = merge(var.environment_tags, {
    Name = "web-server_security_group"
  })
}

resource "aws_security_group" "database" {
  name        = "database-sg_${data.aws_vpc.selected.id}"
  description = "Security group for databases"
  vpc_id      = data.aws_vpc.selected.id

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.web_server.id]
  }

  tags = merge(var.environment_tags, {
    Name = "database_security_group"
  })
}

variable "tags" {
  description = "Tags to apply to all IAM resources"
  type        = map(string)
  default     = {}
}

locals {
  controlplane_name = "aws_ccm_k8s_controlplane"
  worker_name       = "aws_ccm_k8s_worker"
}

resource "aws_iam_role" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role" "aws_ccm_k8s_worker" {
  name = local.worker_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeNatGateways",
          "ec2:DescribeVpcPeeringConnections",
          "ec2:DescribePrefixLists",
          "ec2:DescribeRegions",
          "ec2:DescribeVolumes",
          "ec2:DescribeTags",
          "ec2:CreateRoute",
          "ec2:DeleteRoute",
          "ec2:ReplaceRoute",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:ModifyInstanceAttribute",
          "ec2:AttachNetworkInterface",
          "ec2:DetachNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:DescribeNetworkInterfaceAttribute"
        ]
        Resource = "*"
      },
      {
        Sid    = "AutoScaling"
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeTags",
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup"
        ]
        Resource = "*"
      },
      {
        Sid    = "ElasticLoadBalancing"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetGroupAttributes",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:DescribeTags",
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:ModifyLoadBalancerAttributes",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:ModifyTargetGroup",
          "elasticloadbalancing:ModifyTargetGroupAttributes",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:CreateRule",
          "elasticloadbalancing:DeleteRule",
          "elasticloadbalancing:ModifyRule",
          "elasticloadbalancing:SetSecurityGroups",
          "elasticloadbalancing:SetSubnets",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:RemoveTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMS"
        Effect = "Allow"
        Action = [
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "ServiceLinkedRole"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:GetRole",
          "iam:PutRolePolicy"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "aws_ccm_k8s_worker" {
  name = local.worker_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Describe"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeRegions"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRReadOnly"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages",
          "ecr:DescribeRegistry",
          "ecr:DescribePullThroughCacheRules"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane_attach" {
  role       = aws_iam_role.aws_ccm_k8s_controlplane.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_controlplane.arn
}

resource "aws_iam_role_policy_attachment" "worker_attach" {
  role       = aws_iam_role.aws_ccm_k8s_worker.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_worker.arn
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name
  role = aws_iam_role.aws_ccm_k8s_controlplane.name
  tags = var.tags
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_worker" {
  name = local.worker_name
  role = aws_iam_role.aws_ccm_k8s_worker.name
  tags = var.tags
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix for all IAM resource names"
  type        = string
  default     = "awscademo-"
}

locals {
  tags = {
    Contact          = "team@example.com"
    DeploymentMethod = "Terraform"
    DeploymentDate   = formatdate("YYYY-MM-DD", timestamp())
    TTL              = "infinite"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_iam_group" "demo_users" {
  name = "${var.name_prefix}demo-users"
}

resource "aws_iam_group_policy" "self_management" {
  name  = "${var.name_prefix}self-management"
  group = aws_iam_group.demo_users.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowManageOwnPasswords"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:GetAccessKeyLastUsed",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnSSHPublicKeys"
        Effect = "Allow"
        Action = [
          "iam:DeleteSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/*"
      },
      {
        Sid    = "AllowManageOwnMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowDeactivateOwnMFA"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group" "read_only_users" {
  name = "${var.name_prefix}read-only-users"
}

resource "aws_iam_group_policy_attachment" "read_only_attach" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name_prefix}mfa-superadmin"
}

resource "aws_iam_role" "admin_role" {
  name                = substr("${var.name_prefix}admin-role", 0, 31)
  max_session_duration = 43200
  tags                = local.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "admin_policy" {
  name = "${var.name_prefix}admin-policy"
  role = aws_iam_role.admin_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "assume_admin_policy" {
  name  = "${var.name_prefix}assume-admin"
  group = aws_iam_group.mfa_superadmin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin_role.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  operator_defs = {
    "cloud-credential-operator" = {
      suffix          = "openshift-cloud-credential-operator-cloud-c"
      namespace       = "openshift-cloud-credential-operator"
      service_accounts = ["system:serviceaccount:openshift-cloud-credential-operator:cloud-credential-operator"]
      operator_name   = "CloudCredentialOperator"
    }
    "cloud-network-config-controller" = {
      suffix          = "openshift-cloud-network-config-controller-c"
      namespace       = "openshift-cloud-network-config-controller"
      service_accounts = ["system:serviceaccount:openshift-cloud-network-config-controller:cloud-network-config-controller"]
      operator_name   = "CloudNetworkConfigController"
    }
    "ebs-csi-drivers" = {
      suffix          = "openshift-cluster-csi-drivers-ebs-cloud-cre"
      namespace       = "openshift-cluster-csi-drivers"
      service_accounts = ["system:serviceaccount:openshift-cluster-csi-drivers:aws-ebs-csi-driver-operator", "system:serviceaccount:openshift-cluster-csi-drivers:aws-ebs-csi-driver-controller-sa"]
      operator_name   = "EBSCSIDriver"
    }
    "image-registry" = {
      suffix          = "openshift-image-registry-installer-cloud-cr"
      namespace       = "openshift-image-registry"
      service_accounts = ["system:serviceaccount:openshift-image-registry:cluster-image-registry-operator", "system:serviceaccount:openshift-image-registry:registry"]
      operator_name   = "ImageRegistry"
    }
    "ingress-operator" = {
      suffix          = "openshift-ingress-operator-cloud-credential"
      namespace       = "openshift-ingress-operator"
      service_accounts = ["system:serviceaccount:openshift-ingress-operator:ingress-operator"]
      operator_name   = "IngressOperator"
    }
    "machine-api" = {
      suffix          = "openshift-machine-api-aws-cloud-credentials"
      namespace       = "openshift-machine-api"
      service_accounts = ["system:serviceaccount:openshift-machine-api:machine-api-controllers"]
      operator_name   = "MachineAPI"
    }
  }
}

variable "clusters" {
  type = list(object({
    cluster_id          = string
    operator_role_prefix = string
  }))
  default = [
    {
      cluster_id          = "example-cluster"
      operator_role_prefix = "example"
    }
  ]
}

variable "oidc_provider_url" {
  type    = string
  default = "https://rh-oidc.s3.us-east-1.amazonaws.com"
}

variable "oidc_provider_thumbprint" {
  type    = string
  default = "917e732d330f9a12404f73d8bea36948b929dffc"
}

variable "operator_policy_documents" {
  type = map(string)
  default = {
    "cloud-credential-operator"          = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
    "cloud-network-config-controller"   = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
    "ebs-csi-drivers"                   = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
    "image-registry"                    = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
    "ingress-operator"                  = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
    "machine-api"                       = "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"ec2:Describe*\",\"Resource\":\"*\"}]}"
  }
}

locals {
  clusters_map = {
    for c in var.clusters : c.cluster_id => c
  }

  cluster_operators = flatten([
    for c in var.clusters : [
      for op_name, op_def in local.operator_defs : {
        cluster_id          = c.cluster_id
        operator_role_prefix = c.operator_role_prefix
        op_name             = op_name
        op_def              = op_def
      }
    ]
  ])

  cluster_operator_key = {
    for item in local.cluster_operators : "${item.cluster_id}-${item.op_name}" => item
  }

  operator_condition = {
    for k, v in local.cluster_operator_key : k => {
      StringEquals = {
        "${var.oidc_provider_url}:aud" = "openshift"
      }
      "ForAnyValue:StringEquals" = {
        "${var.oidc_provider_url}:sub" = v.op_def.service_accounts
      }
    }
  }
}

resource "aws_iam_openid_connect_provider" "this" {
  for_each = local.clusters_map

  url             = var.oidc_provider_url
  client_id_list  = ["openshift", "sts.amazonaws.com"]
  thumbprint_list = [var.oidc_provider_thumbprint]

  tags = {
    cluster_id = each.key
  }
}

resource "aws_iam_role" "operator" {
  for_each = local.cluster_operator_key

  name = "${each.value.operator_role_prefix}-${each.value.op_def.suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.this[each.value.cluster_id].arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = local.operator_condition[each.key]
      }
    ]
  })

  tags = {
    cluster_id         = each.value.cluster_id
    "ManagedOpenShift" = "true"
    operator_namespace = each.value.op_def.namespace
    operator_name      = each.value.op_def.operator_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "operator" {
  for_each = local.cluster_operator_key

  name        = "ManagedOpenShift-${each.value.op_name}"
  path        = "/"
  description = "Policy for ROSA operator ${each.value.op_name} in cluster ${each.value.cluster_id}"
  policy      = var.operator_policy_documents[each.value.op_name]

  tags = {
    cluster_id         = each.value.cluster_id
    "ManagedOpenShift" = "true"
    operator_namespace = each.value.op_def.namespace
    operator_name      = each.value.op_def.operator_name
  }
}

resource "aws_iam_role_policy_attachment" "operator" {
  for_each = local.cluster_operator_key

  role       = aws_iam_role.operator[each.key].name
  policy_arn = aws_iam_policy.operator[each.key].arn
}

