# ----------------------------------------------------------------------
# Admin Group Self‑Management Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "admin_self_management" {
  name        = "${module.this.id}-admin-self-management"
  description = "Allows admin users to manage their own credentials and MFA devices"
  policy      = data.aws_iam_policy_document.admin_self_management.json
}

data "aws_iam_policy_document" "admin_self_management" {
  statement {
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:GetAccountPasswordPolicy",
      "iam:GetUser",
      "iam:ListUsers",
      "iam:ListGroups",
      "iam:ListGroupsForUser",
      "iam:ListRoles",
      "iam:ListPolicies",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"]
  }
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:sms-mfa/$${aws:username}",
    ]
  }
}

resource "aws_iam_group_policy_attachment" "admin_self_management_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_self_management.arn
}

# ----------------------------------------------------------------------
# Admin Group Assume Role Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "admin_assume_role" {
  name        = "${module.this.id}-admin-assume-role"
  description = "Allows admin group members to assume the admin role"
  policy      = data.aws_iam_policy_document.admin_assume_role.json
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
  }
}

resource "aws_iam_group_policy_attachment" "admin_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

# ----------------------------------------------------------------------
# Non-Admin IAM Group
# ----------------------------------------------------------------------
resource "aws_iam_group" "other" {
  name = "${module.this.id}-${var.other_group_name}"
}

# ----------------------------------------------------------------------
# Other Group Self‑Management Policy
# ----------------------------------------------------------------------
resource "aws_iam_policy" "other_self_management" {
  name        = "${module.this.id}-other-self-management"
  description = "Allows non-admin users to manage their own credentials and MFA devices"
  policy      = data.aws_iam_policy_document.other_self_management.json
}

data "aws_iam_policy_document" "other_self_management" {
  statement {
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:GetAccountPasswordPolicy",
      "iam:GetUser",
      "iam:ListUsers",
      "iam:ListGroups",
      "iam:ListGroupsForUser",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"]
  }
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:sms-mfa/$${aws:username}",
    ]
  }
}

resource "aws_iam_group_policy_attachment" "other_self_management_attach" {
  group      = aws_iam_group.other.name
  policy_arn = aws_iam_policy.other_self_management.arn
}

# ----------------------------------------------------------------------
# Admin IAM Users (conditional)
# ----------------------------------------------------------------------
resource "aws_iam_user" "admin_users" {
  for_each = toset(var.admin_users)
  name     = each.value
}

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0

  name  = "${module.this.id}-admin-membership"
  group = aws_iam_group.admin.name
  users = var.admin_users
  depends_on = [aws_iam_user.admin_users]
}

# ----------------------------------------------------------------------
# Other IAM Users (conditional)
# ----------------------------------------------------------------------
resource "aws_iam_user" "other_users" {
  for_each = toset(var.other_users)
  name     = each.value
}

resource "aws_iam_group_membership" "other" {
  count = length(var.other_users) > 0 ? 1 : 0

  name  = "${module.this.id}-other-membership"
  group = aws_iam_group.other.name
  users = var.other_users
  depends_on = [aws_iam_user.other_users]
}

# ------------------------------------------------------------------------------
# TERRAFORM CONFIGURATION
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "project_name" {
  description = "Prefix for all resource names"
  type        = string
  default     = "my-org"
}

variable "organization_targets" {
  description = "List of OU or root IDs to attach policies to"
  type        = list(string)
  default     = []
}

variable "enable_guardrails" {
  description = "Master toggle for guardrail SCPs"
  type        = bool
  default     = false
}

variable "enable_root_deny" {
  description = "Deny all root user actions (default: true when guardrails on)"
  type        = bool
  default     = null
}

variable "enable_region_restriction" {
  description = "Restrict API calls to allowed regions (default: true when guardrails on)"
  type        = bool
  default     = null
}

variable "allowed_regions" {
  description = "List of allowed AWS regions for region restriction SCP"
  type        = list(string)
  default     = []
}

variable "enable_security_protection" {
  description = "Block disabling of core security services (default: true when guardrails on)"
  type        = bool
  default     = null
}

variable "enable_encryption_enforcement" {
  description = "Enforce encryption on RDS/EBS and KMS key deletion window (default: true when guardrails on)"
  type        = bool
  default     = null
}

variable "enable_public_ami_snapshot_restrict" {
  description = "Block making AMIs or EBS snapshots public (default: true when guardrails on)"
  type        = bool
  default     = null
}

variable "enable_org_leave_restriction" {
  description = "Prevent member accounts from leaving the organization"
  type        = bool
  default     = false
}

variable "enable_flow_log_protection" {
  description = "Protect VPC flow logs from deletion"
  type        = bool
  default     = false
}

variable "enable_mfa_protection" {
  description = "Block deactivating MFA or creating root access keys"
  type        = bool
  default     = false
}

variable "enable_imdsv2_enforcement" {
  description = "Require IMDSv2 on all new/modified EC2 instances"
  type        = bool
  default     = false
}

variable "enable_tag_policy" {
  description = "Enable organization-wide tag policy"
  type        = bool
  default     = false
}

variable "required_tags" {
  description = "Map of tag keys to allowed values for tag policy"
  type        = map(list(string))
  default = {
    Environment = ["dev", "staging", "production"]
    ManagedBy   = ["Terraform"]
  }
}

variable "enable_backup_policy" {
  description = "Enable daily backup policy"
  type        = bool
  default     = false
}

variable "backup_regions" {
  description = "List of regions for backup policy"
  type        = list(string)
  default     = []
}

variable "backup_retention_days" {
  description = "Retention days for backup policy"
  type        = number
  default     = 35
}

variable "enable_ai_opt_out" {
  description = "Opt out of AWS AI services using account content"
  type        = bool
  default     = false
}

variable "enable_ram_share" {
  description = "Create a RAM resource share limited to the organization"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# RESOURCES
# ------------------------------------------------------------------------------
resource "aws_organizations_organization" "this" {
  feature_set = "ALL"
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  effective_root_deny               = var.enable_root_deny != null ? var.enable_root_deny : var.enable_guardrails
  effective_region_restriction      = var.enable_region_restriction != null ? var.enable_region_restriction : var.enable_guardrails
  effective_security_protection     = var.enable_security_protection != null ? var.enable_security_protection : var.enable_guardrails
  effective_encryption_enforcement  = var.enable_encryption_enforcement != null ? var.enable_encryption_enforcement : var.enable_guardrails
  effective_public_ami_snapshot_restrict = var.enable_public_ami_snapshot_restrict != null ? var.enable_public_ami_snapshot_restrict : var.enable_guardrails

  any_policy_enabled = (
    local.effective_root_deny ||
    local.effective_region_restriction ||
    local.effective_security_protection ||
    local.effective_encryption_enforcement ||
    local.effective_public_ami_snapshot_restrict ||
    var.enable_org_leave_restriction ||
    var.enable_flow_log_protection ||
    var.enable_mfa_protection ||
    var.enable_imdsv2_enforcement ||
    var.enable_tag_policy ||
    var.enable_backup_policy ||
    var.enable_ai_opt_out ||
    var.enable_ram_share
  )

  targets_set = toset(var.organization_targets)
}

# ------------------------------------------------------------------------------
# VALIDATION
# ------------------------------------------------------------------------------
resource "null_resource" "validation" {
  lifecycle {
    precondition {
      condition     = !local.any_policy_enabled || length(var.organization_targets) > 0
      error_message = "At least one target OU or root ID must be supplied when any policy is enabled."
    }
  }
}

# ------------------------------------------------------------------------------
# POLICY DOCUMENTS (SCPs)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "root_deny" {
  statement {
    effect    = "Deny"
    actions   = ["*"]
    resources = ["arn:aws:iam::*:root"]
  }
}

data "aws_iam_policy_document" "region_restriction" {
  statement {
    effect    = "Deny"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = var.allowed_regions
    }
    condition {
      test     = "ForAllValues:StringNotEquals"
      variable = "aws:Service"
      values = [
        "iam",
        "organizations",
        "support",
        "account",
        "budgets",
        "cost-explorer",
        "cur",
        "health",
        "route53",
        "cloudfront",
        "globalaccelerator",
        "importexport",
        "sts",
        "aws-marketplace",
        "aws-portal",
        "billing",
        "consolidatedbilling",
        "ec2",
        "s3"
      ]
    }
  }
}

data "aws_iam_policy_document" "security_protection" {
  statement {
    effect    = "Deny"
    actions   = [
      "cloudtrail:DeleteTrail",
      "cloudtrail:StopLogging",
      "guardduty:DeleteDetector",
      "guardduty:DisableOrganizationAdminAccount",
      "config:DeleteConfigRule",
      "config:DeleteConfigurationRecorder",
      "config:StopConfigurationRecorder",
      "securityhub:DisableSecurityHub",
      "access-analyzer:DeleteAnalyzer",
      "macie2:DisableMacie",
      "inspector2:Disable",
      "detective:DisableOrganizationAdminAccount",
      "detective:DeleteGraph",
      "s3:PutAccountPublicAccessBlock"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "encryption_enforcement" {
  statement {
    effect    = "Deny"
    actions   = ["rds:CreateDBInstance"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "rds:StorageEncrypted"
      values   = ["false"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["ec2:CreateVolume"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "ec2:Encrypted"
      values   = ["false"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["kms:ScheduleKeyDeletion"]
    resources = ["*"]
    condition {
      test     = "NumericLessThan"
      variable = "kms:PendingWindowInDays"
      values   = ["14"]
    }
  }
}

data "aws_iam_policy_document" "public_ami_snapshot_restrict" {
  statement {
    effect    = "Deny"
    actions   = ["ec2:ModifyImageAttribute"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "ec2:Attribute"
      values   = ["launchPermission"]
    }
  }
  statement {
    effect    = "Deny"
    actions   = ["ec2:ModifySnapshotAttribute"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "ec2:Attribute"
      values   = ["createVolumePermission"]
    }
  }
}

data "aws_iam_policy_document" "org_leave_restriction" {
  statement {
    effect    = "Deny"
    actions   = ["organizations:LeaveOrganization"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "flow_log_protection" {
  statement {
    effect    = "Deny"
    actions   = ["ec2:DeleteFlowLogs"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "mfa_protection" {
  statement {
    effect    = "Deny"
    actions   = ["iam:DeactivateMFADevice"]
    resources = ["*"]
  }
  statement {
    effect    = "Deny"
    actions   = ["iam:CreateAccessKey"]
    resources = ["arn:aws:iam::*:root"]
  }
}

data "aws_iam_policy_document" "imdsv2_enforcement" {
  statement {
    effect    = "Deny"
    actions   = ["ec2:RunInstances", "ec2:ModifyInstanceMetadataOptions"]
    resources = ["*"]
    condition {
      test     = "StringNotEquals"
      variable = "ec2:MetadataHttpTokens"
      values   = ["required"]
    }
  }
}

# ------------------------------------------------------------------------------
# ORGANIZATIONS POLICIES
# ------------------------------------------------------------------------------
resource "aws_organizations_policy" "root_deny" {
  count       = local.effective_root_deny ? 1 : 0
  name        = "${var.project_name}-root-deny"
  description = "Deny all actions for root user"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.root_deny.json
}

resource "aws_organizations_policy" "region_restriction" {
  count       = local.effective_region_restriction ? 1 : 0
  name        = "${var.project_name}-region-restriction"
  description = "Restrict API calls to allowed regions"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.region_restriction.json
}

resource "aws_organizations_policy" "security_protection" {
  count       = local.effective_security_protection ? 1 : 0
  name        = "${var.project_name}-security-protection"
  description = "Block disabling of core security services"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.security_protection.json
}

resource "aws_organizations_policy" "encryption_enforcement" {
  count       = local.effective_encryption_enforcement ? 1 : 0
  name        = "${var.project_name}-encryption-enforcement"
  description = "Enforce encryption on RDS/EBS and KMS key deletion window"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.encryption_enforcement.json
}

resource "aws_organizations_policy" "public_ami_snapshot_restrict" {
  count       = local.effective_public_ami_snapshot_restrict ? 1 : 0
  name        = "${var.project_name}-public-ami-snapshot-restrict"
  description = "Block making AMIs or EBS snapshots public"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.public_ami_snapshot_restrict.json
}

resource "aws_organizations_policy" "org_leave_restriction" {
  count       = var.enable_org_leave_restriction ? 1 : 0
  name        = "${var.project_name}-org-leave-restriction"
  description = "Prevent member accounts from leaving the organization"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.org_leave_restriction.json
}

resource "aws_organizations_policy" "flow_log_protection" {
  count       = var.enable_flow_log_protection ? 1 : 0
  name        = "${var.project_name}-flow-log-protection"
  description = "Protect VPC flow logs from deletion"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.flow_log_protection.json
}

resource "aws_organizations_policy" "mfa_protection" {
  count       = var.enable_mfa_protection ? 1 : 0
  name        = "${var.project_name}-mfa-protection"
  description = "Block deactivating MFA or creating root access keys"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.mfa_protection.json
}

resource "aws_organizations_policy" "imdsv2_enforcement" {
  count       = var.enable_imdsv2_enforcement ? 1 : 0
  name        = "${var.project_name}-imdsv2-enforcement"
  description = "Require IMDSv2 on all new/modified EC2 instances"
  type        = "SERVICE_CONTROL_POLICY"
  content     = data.aws_iam_policy_document.imdsv2_enforcement.json
}

resource "aws_organizations_policy" "tag_policy" {
  count       = var.enable_tag_policy ? 1 : 0
  name        = "${var.project_name}-tag-policy"
  description = "Organization-wide tag policy"
  type        = "TAG_POLICY"
  content = jsonencode({
    tags = {
      for k, v in var.required_tags : k => {
        tag_value = {
          enforced_for = {
            tag = {
              key   = k
              value = v
            }
          }
        }
      }
    }
  })
}

resource "aws_organizations_policy" "backup_policy" {
  count       = var.enable_backup_policy ? 1 : 0
  name        = "${var.project_name}-backup-policy"
  description = "Daily backup policy with configurable retention"
  type        = "BACKUP_POLICY"
  content = jsonencode({
    plans = {
      "${var.project_name}-daily-backup" = {
        regions = {
          assignment = {
            regions = var.backup_regions
          }
        }
        rules = {
          daily = {
            schedule_expression         = "cron(0 5 * * ? *)"
            start_window_minutes        = 60
            completion_window_minutes   = 120
            lifecycle = {
              delete_after_days = var.backup_retention_days
            }
            target_backup_vault_name = "Default"
          }
        }
        selections = {
          resources = {
            tag = {
              type  = "STRING_EQUALS"
              key   = "BackupPlan"
              value = "true"
            }
          }
        }
      }
    }
  })
}

resource "aws_organizations_policy" "ai_opt_out" {
  count       = var.enable_ai_opt_out ? 1 : 0
  name        = "${var.project_name}-ai-opt-out"
  description = "Opt out of AWS AI services using account content"
  type        = "AISERVICES_OPT_OUT_POLICY"
  content = jsonencode({
    services = {
      default = {
        opt_out_policy = "optOut"
      }
    }
  })
}

# ------------------------------------------------------------------------------
# POLICY ATTACHMENTS (conditional on targets being non-empty)
# ------------------------------------------------------------------------------
resource "aws_organizations_policy_attachment" "root_deny" {
  for_each  = local.effective_root_deny && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.root_deny[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "region_restriction" {
  for_each  = local.effective_region_restriction && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.region_restriction[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "security_protection" {
  for_each  = local.effective_security_protection && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.security_protection[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "encryption_enforcement" {
  for_each  = local.effective_encryption_enforcement && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.encryption_enforcement[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "public_ami_snapshot_restrict" {
  for_each  = local.effective_public_ami_snapshot_restrict && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.public_ami_snapshot_restrict[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "org_leave_restriction" {
  for_each  = var.enable_org_leave_restriction && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.org_leave_restriction[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "flow_log_protection" {
  for_each  = var.enable_flow_log_protection && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.flow_log_protection[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "mfa_protection" {
  for_each  = var.enable_mfa_protection && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.mfa_protection[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "imdsv2_enforcement" {
  for_each  = var.enable_imdsv2_enforcement && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.imdsv2_enforcement[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "tag_policy" {
  for_each  = var.enable_tag_policy && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.tag_policy[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "backup_policy" {
  for_each  = var.enable_backup_policy && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.backup_policy[0].id
  target_id = each.value
}

resource "aws_organizations_policy_attachment" "ai_opt_out" {
  for_each  = var.enable_ai_opt_out && length(var.organization_targets) > 0 ? local.targets_set : toset([])
  policy_id = aws_organizations_policy.ai_opt_out[0].id
  target_id = each.value
}

# ------------------------------------------------------------------------------
# RAM RESOURCE SHARE
# ------------------------------------------------------------------------------
resource "aws_ram_resource_share" "this" {
  count                     = var.enable_ram_share ? 1 : 0
  name                      = "${var.project_name}-ram-share"
  allow_external_principals = false
}

resource "aws_ram_principal_association" "organization" {
  count              = var.enable_ram_share ? 1 : 0
  principal          = aws_organizations_organization.this.arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "additional_tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "List of CIDR blocks allowed SSH access"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count              = length(data.aws_availability_zones.available.names)
  public_subnet_cidrs   = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i)]
  private_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i + local.az_count)]
  public_subnet_cidr_list = aws_subnet.public[*].cidr_block
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    {
      Name = var.vpc_name
    },
    var.additional_tags
  )
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "public-${var.vpc_name}-${count.index + 1}"
    },
    var.additional_tags
  )
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    {
      Name = "private-${var.vpc_name}-${count.index + 1}"
    },
    var.additional_tags
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-igw"
    },
    var.additional_tags
  )
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    {
      Name = "${var.vpc_name}-nat-eip"
    },
    var.additional_tags
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-nat"
    },
    var.additional_tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.vpc_name}-public-rt"
    },
    var.additional_tags
  )
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.vpc_name}-private-rt"
    },
    var.additional_tags
  )
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_default_network_acl" "main" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = merge(
    {
      Name = "${var.vpc_name}-Default"
    },
    var.additional_tags
  )
}

resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []

  tags = merge(
    {
      Name = "${var.vpc_name}-Default"
    },
    var.additional_tags
  )
}

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Security group for public subnets"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-public-sg"
    },
    var.additional_tags
  )
}

resource "aws_vpc_security_group_ingress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh" {
  for_each = toset(var.ssh_inbound)

  security_group_id = aws_security_group.public.id
  cidr_ipv4         = each.key
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Security group for private subnets"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-private-sg"
    },
    var.additional_tags
  )
}

resource "aws_vpc_security_group_ingress_rule" "private_http" {
  for_each = toset(local.public_subnet_cidr_list)

  security_group_id = aws_security_group.private.id
  cidr_ipv4         = each.key
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "private_https" {
  for_each = toset(local.public_subnet_cidr_list)

  security_group_id = aws_security_group.private.id
  cidr_ipv4         = each.key
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "private_https" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_network_acl" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-public-nacl"
    },
    var.additional_tags
  )
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 90
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 91
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 92
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  for_each = { for idx, cidr in var.ssh_inbound : idx => cidr }

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 90
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 91
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 92
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_association" "public" {
  count          = local.az_count
  network_acl_id = aws_network_acl.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-private-nacl"
    },
    var.additional_tags
  )
}

resource "aws_network_acl_rule" "private_ingress_http" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 110 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_private" {
  for_each = { for idx, cidr in local.private_subnet_cidrs : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 110 + each.key
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_public" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 120 + each.key
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_association" "private" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "region" {
  description = "AWS region used for VPC endpoint service names"
  type        = string
  default     = "us-east-1"
}

variable "enable_ssm_endpoints" {
  description = "Whether to create SSM interface VPC endpoints"
  type        = bool
  default     = false
}

locals {
  common_tags = {
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_default_vpc" "default" {
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "DatatogAgentlessScanner"
  })
}

data "aws_internet_gateway" "default" {
  filter {
    name   = "attachment.vpc-id"
    values = [aws_default_vpc.default.id]
  }
}

resource "aws_subnet" "public" {
  count = min(3, length(data.aws_availability_zones.available.names))

  vpc_id                  = aws_default_vpc.default.id
  cidr_block              = cidrsubnet(aws_default_vpc.default.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = min(3, length(data.aws_availability_zones.available.names))

  vpc_id            = aws_default_vpc.default.id
  cidr_block        = cidrsubnet(aws_default_vpc.default.cidr_block, 8, count.index + 100)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "private-${count.index}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_default_vpc.default.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = data.aws_internet_gateway.default.id
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.main.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_default_vpc.default.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "private"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_default_vpc.default.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "s3-gateway"
  })
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Allow inbound HTTPS from VPC CIDR for interface VPC endpoints"
  vpc_id      = aws_default_vpc.default.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_default_vpc.default.cidr_block]
  }

  egress {
    description = "Allow outbound traffic within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_default_vpc.default.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "vpc_endpoint_sg"
  })
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_default_vpc.default.id
  service_name        = "com.amazonaws.${var.region}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "lambda-interface"
  })
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_default_vpc.default.id
  service_name        = "com.amazonaws.${var.region}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "ebs-interface"
  })
}

resource "aws_vpc_endpoint" "ec2messages" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_default_vpc.default.id
  service_name        = "com.amazonaws.${var.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "ec2messages-interface"
  })
}

resource "aws_vpc_endpoint" "ssmmessages" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_default_vpc.default.id
  service_name        = "com.amazonaws.${var.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "ssmmessages-interface"
  })
}

resource "aws_vpc_endpoint" "ssm" {
  count = var.enable_ssm_endpoints ? 1 : 0

  vpc_id              = aws_default_vpc.default.id
  service_name        = "com.amazonaws.${var.region}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "ssm-interface"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "enabled" {
  description = "Global toggle to enable or disable all resources"
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Toggle between creating a new security group (true) or attaching rules to an existing one (false)"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the security group. If null and create_sg is true, an existing VPC will be used."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

variable "enable_prefix_list" {
  description = "Toggle to create a managed prefix list"
  type        = bool
  default     = false
}

variable "existing_sg_id" {
  description = "ID of an existing security group when create_sg is false"
  type        = string
  default     = null

  validation {
    condition     = var.create_sg == false ? var.existing_sg_id != null : true
    error_message = "existing_sg_id must be provided when create_sg is false."
  }
}

variable "ingress_rules" {
  description = "List of ingress rules. Each rule can have: from_port, to_port, protocol, cidr_blocks (list), self (bool), source_security_group_id (string), prefix_list_ids (list)."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rules. Same structure as ingress_rules."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Labels module
# ------------------------------------------------------------------------------
module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name   = var.name_prefix
}

locals {
  sg_name          = "${module.labels.id}-sg"
  prefix_list_name = "${module.labels.id}-prefix-list"
}

# ------------------------------------------------------------------------------
# VPC selection (use existing VPC when no vpc_id is provided)
# ------------------------------------------------------------------------------
data "aws_vpcs" "all" {}

data "aws_vpc" "selected" {
  id = var.vpc_id != null ? var.vpc_id : data.aws_vpcs.all.ids[0]
}

locals {
  vpc_id = var.create_sg ? data.aws_vpc.selected.id : null
}

# ------------------------------------------------------------------------------
# Security Group (only when create_sg is true)
# ------------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count       = var.enabled && var.create_sg ? 1 : 0
  name        = local.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id
  tags        = merge(module.labels.tags, var.tags, { Name = local.sg_name })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Managed Prefix List (only when enable_prefix_list is true)
# ------------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.enable_prefix_list ? 1 : 0
  name           = local.prefix_list_name
  address_family = "IPv4"
  max_entries    = 5
  tags           = merge(module.labels.tags, var.tags, { Name = local.prefix_list_name })
}

# ------------------------------------------------------------------------------
# Security Group Rules (ingress and egress)
# ------------------------------------------------------------------------------
locals {
  # Combine ingress and egress rules into a single list with type and index
  all_rules = concat(
    [for idx, rule in var.ingress_rules : merge(rule, { type = "ingress", idx = idx })],
    [for idx, rule in var.egress_rules : merge(rule, { type = "egress", idx = idx })]
  )

  # Determine the security group ID to use
  sg_id = var.create_sg ? aws_security_group.this[0].id : var.existing_sg_id
}

resource "aws_security_group_rule" "this" {
  for_each = var.enabled ? { for r in local.all_rules : "${r.type}-${r.idx}" => r } : {}

  type              = each.value.type
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  security_group_id = local.sg_id

  cidr_blocks              = lookup(each.value, "cidr_blocks", null)
  self                     = lookup(each.value, "self", null)
  source_security_group_id = lookup(each.value, "source_security_group_id", null)
  prefix_list_ids          = lookup(each.value, "prefix_list_ids", var.enable_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "role_name" {
  description = "Name of the IAM role for CloudForecast"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID to use in the trust policy"
  type        = string
  default     = "benchmark-external-id"
}

data "aws_iam_policy_document" "cloudforecast_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::656227328603:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

resource "aws_iam_role" "cloudforecast_role" {
  name               = var.role_name
  description        = "Dedicated third-party IAM integration role for CloudForecast read-only cost optimization and waste-monitoring analysis"
  assume_role_policy = data.aws_iam_policy_document.cloudforecast_trust.json
}

data "aws_iam_policy_document" "cloudwatch_metrics" {
  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricStatistics",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name   = "CloudWatchMetrics"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.cloudwatch_metrics.json
}

data "aws_iam_policy_document" "tag_resources" {
  statement {
    effect = "Allow"
    actions = [
      "tag:GetResources",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "tag_resources" {
  name   = "TagResources"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.tag_resources.json
}

data "aws_iam_policy_document" "organizations" {
  statement {
    effect = "Allow"
    actions = [
      "organizations:ListAccounts",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "organizations" {
  name   = "Organizations"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.organizations.json
}

data "aws_iam_policy_document" "elb" {
  statement {
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTags",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:DescribeListenerAttributes",
      "elasticloadbalancing:DescribeTargetGroupAttributes",
      "elasticloadbalancing:DescribeSSLPolicies",
      "elasticloadbalancing:DescribeAccountLimits",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "elb" {
  name   = "ELB"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.elb.json
}

data "aws_iam_policy_document" "ebs" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeSnapshots",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshotAttribute",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ebs" {
  name   = "EBS"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.ebs.json
}

data "aws_iam_policy_document" "ec2" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeTags",
      "ec2:DescribeInstanceAttribute",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeReservedInstances",
      "ec2:DescribeReservedInstancesOfferings",
      "ec2:DescribeImages",
      "ec2:DescribeAddresses",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeRegions",
      "ec2:DescribeAvailabilityZones",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ec2" {
  name   = "EC2"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.ec2.json
}

data "aws_iam_policy_document" "rds" {
  statement {
    effect = "Allow"
    actions = [
      "rds:DescribeDBInstances",
      "rds:DescribeDBSnapshots",
      "rds:DescribeDBClusters",
      "rds:ListTagsForResource",
      "rds:DescribeDBClusterSnapshots",
      "rds:DescribeDBSubnetGroups",
      "rds:DescribeEventSubscriptions",
      "rds:DescribeReservedDBInstances",
      "rds:DescribePendingMaintenanceActions",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "rds" {
  name   = "RDS"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.rds.json
}

data "aws_iam_policy_document" "s3" {
  statement {
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketTagging",
      "s3:GetLifecycleConfiguration",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "s3" {
  name   = "S3"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.s3.json
}

data "aws_iam_policy_document" "logs" {
  statement {
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "logs" {
  name   = "CloudWatchLogs"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.logs.json
}

data "aws_iam_policy_document" "support" {
  statement {
    effect = "Allow"
    actions = [
      "support:DescribeTrustedAdvisorChecks",
      "support:DescribeTrustedAdvisorCheckResult",
      "support:DescribeCases",
      "support:DescribeCommunications",
      "support:DescribeSeverityLevels",
      "support:DescribeServices",
      "support:DescribeTrustedAdvisorCheckRefreshStatuses",
      "support:DescribeTrustedAdvisorCheckSummaries",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "support" {
  name   = "Support"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.support.json
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "environment_suffix" {
  description = "Suffix for naming IAM users and other resources"
  type        = string
  default     = "dev"
}

variable "create_db_dr_user" {
  description = "Whether to create the Database Disaster Recovery IAM user"
  type        = bool
  default     = false
}

variable "create_data_exports_user" {
  description = "Whether to create the Data Exports IAM user and supporting bucket"
  type        = bool
  default     = false
}

variable "create_packer_user" {
  description = "Whether to create the Packer Image Builder IAM user and supporting resources"
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------
# Data sources
# ----------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ----------------------------------------------------------------------
# Mandatory: Cost Report User
# ----------------------------------------------------------------------
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "cost_report" {
  name   = "cost-explorer-full-access"
  user   = aws_iam_user.cost_report.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Database Disaster Recovery User
# ----------------------------------------------------------------------
resource "aws_iam_user" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "rds-kms-secretsmanager-access"
  user  = aws_iam_user.db_dr[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["rds:*", "kms:*"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Data Exports User and Bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = "mattermost-data-exports-${var.environment_suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_user" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "s3-export-bucket-access"
  user  = aws_iam_user.data_exports[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.data_exports[0].arn
      },
      {
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject"]
        Resource = "${aws_s3_bucket.data_exports[0].arn}/*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Packer Image Builder User and Supporting Resources
# ----------------------------------------------------------------------
resource "aws_iam_user" "packer" {
  count = var.create_packer_user ? 1 : 0
  name  = "mattermost-packer-${var.environment_suffix}"
}

resource "aws_s3_bucket" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = "mattermost-packer-monitoring-state-${var.environment_suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "packer_server_role" {
  count = var.create_packer_user ? 1 : 0
  name  = "packer-server-role-${var.environment_suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_user_policy" "packer" {
  count = var.create_packer_user ? 1 : 0
  name  = "packer-image-builder-policy"
  user  = aws_iam_user.packer[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AttachVolume",
          "ec2:CopyImage",
          "ec2:CreateSnapshot",
          "ec2:CreateTags",
          "ec2:CreateVolume",
          "ec2:DeleteSnapshot",
          "ec2:DeleteVolume",
          "ec2:DeregisterImage",
          "ec2:DescribeImages",
          "ec2:DescribeInstances",
          "ec2:DescribeSnapshots",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DetachVolume",
          "ec2:GetConsoleOutput",
          "ec2:ImportKeyPair",
          "ec2:ImportSnapshot",
          "ec2:ImportVolume",
          "ec2:ModifyInstanceAttribute",
          "ec2:ModifySnapshotAttribute",
          "ec2:RegisterImage",
          "ec2:RunInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeLaunchConfigurations"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "events:DescribeRule",
          "events:PutRule",
          "events:PutTargets",
          "events:EnableRule",
          "events:DisableRule",
          "events:DeleteRule",
          "events:RemoveTargets"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "ssm:PutParameter",
          "ssm:DeleteParameter"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/packer-server-role-${var.environment_suffix}"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:GetRole",
          "iam:ListInstanceProfiles",
          "iam:ListRoles",
          "iam:GetInstanceProfile"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.packer_monitoring_state[0].arn,
          "${aws_s3_bucket.packer_monitoring_state[0].arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:UpdateFunctionConfiguration"
        ]
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# TERRAFORM & PROVIDER REQUIREMENTS
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Default tags to apply to all resources (will be merged with DatadogScanning=enabled)"
  type        = map(string)
  default     = {}
}

variable "enable_ssm_endpoints" {
  description = "Whether to create SSM VPC Interface endpoints (ec2messages, ssmmessages, ssm)"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  azs         = slice(data.aws_availability_zones.available.names, 0, min(length(data.aws_availability_zones.available.names), 3))
  common_tags = merge(var.tags, { DatadogScanning = "enabled" })
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "datadog-agentless-scanner-vpc" })
}

# ------------------------------------------------------------------------------
# SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  for_each = { for idx, az in local.azs : idx => az }

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.key)
  availability_zone = each.value
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "datadog-public-${each.value}", Tier = "public" })
}

resource "aws_subnet" "private" {
  for_each = { for idx, az in local.azs : idx => az }

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.key + 100)
  availability_zone = each.value

  tags = merge(local.common_tags, { Name = "datadog-private-${each.value}", Tier = "private" })
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, { Name = "datadog-igw" })
}

# ------------------------------------------------------------------------------
# ELASTIC IP & NAT GATEWAY (single in first public subnet)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "datadog-nat-eip" })
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, { Name = "datadog-nat" })

  depends_on = [aws_internet_gateway.this]
}

# ------------------------------------------------------------------------------
# ROUTE TABLES AND ASSOCIATIONS
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.common_tags, { Name = "datadog-public-rt" })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(local.common_tags, { Name = "datadog-private-rt" })
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# VPC ENDPOINTS
# ------------------------------------------------------------------------------
# S3 Gateway Endpoint – associated with both route tables
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.this.id
  service_name = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "datadog-s3-endpoint" })
}

# Security Group for HTTPS interface endpoints
resource "aws_security_group" "https_endpoint" {
  name        = "datadog-https-endpoint-sg"
  description = "Allow HTTPS traffic from VPC CIDR to VPC Endpoints"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "datadog-https-endpoint-sg" })
}

# Lambda Interface Endpoint
resource "aws_vpc_endpoint" "lambda" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.lambda"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [for s in aws_subnet.private : s.id]
  security_group_ids = [aws_security_group.https_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "datadog-lambda-endpoint" })
}

# EBS Interface Endpoint
resource "aws_vpc_endpoint" "ebs" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.ebs"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [for s in aws_subnet.private : s.id]
  security_group_ids = [aws_security_group.https_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "datadog-ebs-endpoint" })
}

# Conditional SSM Interface Endpoints
resource "aws_vpc_endpoint" "ssm" {
  for_each = var.enable_ssm_endpoints ? toset(["ec2messages", "ssmmessages", "ssm"]) : toset([])

  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.${each.key}"
  vpc_endpoint_type = "Interface"
  subnet_ids        = [for s in aws_subnet.private : s.id]
  security_group_ids = [aws_security_group.https_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "datadog-ssm-${each.key}-endpoint" })
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = { for s in aws_subnet.public : s.availability_zone => s.id }
}

output "private_subnet_ids" {
  value = { for s in aws_subnet.private : s.availability_zone => s.id }
}

output "nat_gateway_public_ip" {
  value = aws_eip.nat.public_ip
}

output "routing_deployment_ready" {
  value = "Ready"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type    = string
  default = "10.0"
}

variable "default_tags" {
  type    = map(string)
  default = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs = [
    format("%s.12.0/22", var.vpc_cidr_network_octets),
    format("%s.16.0/22", var.vpc_cidr_network_octets),
    format("%s.20.0/22", var.vpc_cidr_network_octets),
  ]

  private_subnet_cidrs = [
    format("%s.0.0/22", var.vpc_cidr_network_octets),
    format("%s.4.0/22", var.vpc_cidr_network_octets),
    format("%s.8.0/22", var.vpc_cidr_network_octets),
  ]

  name_prefix = "dit-paas-${var.cluster_name}"
}

resource "aws_vpc" "this" {
  cidr_block           = format("%s.0.0/16", var.vpc_cidr_network_octets)
  enable_dns_hostnames = false

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "this" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-nat-${count.index}"
  })
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_ecs_cluster" "this" {
  name = "${local.name_prefix}-cluster"

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 0),
    cidrsubnet(var.vpc_cidr, 8, 1),
    cidrsubnet(var.vpc_cidr, 8, 2),
  ]

  private_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 10),
    cidrsubnet(var.vpc_cidr, 8, 11),
    cidrsubnet(var.vpc_cidr, 8, 12),
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []
}

resource "aws_subnet" "public" {
  count                   = length(local.az_names)
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.az_names[count.index]
  cidr_block              = local.public_subnet_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.az_names)
  vpc_id            = aws_vpc.main.id
  availability_zone = local.az_names[count.index]
  cidr_block        = local.private_subnet_cidrs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  count = length(local.az_names)
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = length(local.az_names)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-${count.index}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count  = length(local.az_names)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public-rt-${count.index}"
  }
}

resource "aws_route_table" "private" {
  count  = length(local.az_names)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.az_names)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = length(local.az_names)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route" "public_internet" {
  count                  = length(local.az_names)
  route_table_id         = aws_route_table.public[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "private_nat" {
  count                  = length(local.az_names)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_default_route_table" "main" {
  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id
}

resource "aws_security_group_rule" "vpc_endpoint_sg_ingress_self" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoint_sg.id
}

resource "aws_security_group_rule" "vpc_endpoint_sg_egress_self" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoint_sg.id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = concat(
    [aws_default_route_table.main.id],
    aws_route_table.public[*].id,
    aws_route_table.private[*].id
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "bucket_name_override" {
  description = "Override for the primary S3 bucket name"
  type        = string
  default     = null
}

variable "external_logging_bucket_name" {
  description = "Name of an existing S3 bucket for access logs. If empty, a new bucket is created."
  type        = string
  default     = ""
}

variable "enable_versioning" {
  description = "Enable versioning on the primary S3 bucket"
  type        = bool
  default     = true
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules for the primary S3 bucket"
  type = list(object({
    id                                     = string
    status                                 = string
    filter_and_prefix                      = optional(string)
    filter_and_tags                        = optional(map(string))
    filter_and_object_size_greater_than    = optional(number)
    filter_and_object_size_less_than       = optional(number)
    expiration_date                        = optional(string)
    expiration_days                        = optional(number)
    expiration_expired_object_delete_marker = optional(bool)
    transition_date                        = optional(string)
    transition_days                        = optional(number)
    transition_storage_class               = optional(string)
    noncurrent_version_expiration_days     = optional(number)
    noncurrent_version_transition_days     = optional(number)
    noncurrent_version_transition_storage_class = optional(string)
  }))
  default = [
    {
      id                                     = "noncurrent_expiration"
      status                                 = "Enabled"
      noncurrent_version_expiration_days     = 90
    },
    {
      id                                     = "noncurrent_transition"
      status                                 = "Enabled"
      noncurrent_version_transition_days     = 30
      noncurrent_version_transition_storage_class = "STANDARD_IA"
    },
    {
      id                                     = "expiration"
      status                                 = "Enabled"
      expiration_days                        = 2557
    }
  ]
}

variable "allowed_account_ids" {
  description = "List of additional AWS account IDs allowed to deliver CloudTrail logs"
  type        = list(string)
  default     = []
}

variable "roles_allowed_kms_decrypt" {
  description = "List of IAM role names (without path) allowed to decrypt with the KMS key"
  type        = list(string)
  default     = []
}

locals {
  bucket_name           = var.bucket_name_override != null ? var.bucket_name_override : "${data.aws_caller_identity.current.account_id}-${var.region}-cloudtrail"
  access_logs_bucket_name = "${local.bucket_name}-access-logs"
  permitted_account_ids   = distinct(concat([data.aws_caller_identity.current.account_id], var.allowed_account_ids))

  logging_target_bucket = var.external_logging_bucket_name != "" ? var.external_logging_bucket_name : try(aws_s3_bucket.access_logs[0].bucket, "")
}

# Primary S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "primary" {
  bucket = local.bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      filter {
        prefix = rule.value.filter_and_prefix
        dynamic "tag" {
          for_each = rule.value.filter_and_tags != null ? [for k, v in rule.value.filter_and_tags : { key = k, value = v }] : []
          content {
            key   = tag.value.key
            value = tag.value.value
          }
        }
        object_size_greater_than = rule.value.filter_and_object_size_greater_than
        object_size_less_than    = rule.value.filter_and_object_size_less_than
      }
      dynamic "expiration" {
        for_each = rule.value.expiration_days != null || rule.value.expiration_date != null || rule.value.expiration_expired_object_delete_marker != null ? [1] : []
        content {
          days                         = rule.value.expiration_days
          date                         = rule.value.expiration_date
          expired_object_delete_marker = rule.value.expiration_expired_object_delete_marker
        }
      }
      dynamic "transition" {
        for_each = rule.value.transition_days != null || rule.value.transition_date != null ? [1] : []
        content {
          days          = rule.value.transition_days
          date          = rule.value.transition_date
          storage_class = rule.value.transition_storage_class
        }
      }
      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }
      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_transition_days
          storage_class   = rule.value.noncurrent_version_transition_storage_class
        }
      }
    }
  }
}

# Access logs bucket (created only if no external logging bucket provided)
resource "aws_s3_bucket" "access_logs" {
  count = var.external_logging_bucket_name == "" ? 1 : 0
  bucket = local.access_logs_bucket_name
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  count  = var.external_logging_bucket_name == "" ? 1 : 0
  bucket = aws_s3_bucket.access_logs[0].id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count  = var.external_logging_bucket_name == "" ? 1 : 0
  bucket = aws_s3_bucket.access_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# SSE-S3 encryption for access logs bucket (required for log destination compliance)
resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  count  = var.external_logging_bucket_name == "" ? 1 : 0
  bucket = aws_s3_bucket.access_logs[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Bucket policy for access logs bucket to allow S3 LogDelivery service
data "aws_iam_policy_document" "access_logs_bucket_policy" {
  count = var.external_logging_bucket_name == "" ? 1 : 0
  statement {
    sid    = "S3ServerAccessLogsDelivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs[0].arn}/*"]
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.access_logs[0].arn]
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  count  = var.external_logging_bucket_name == "" ? 1 : 0
  bucket = aws_s3_bucket.access_logs[0].id
  policy = data.aws_iam_policy_document.access_logs_bucket_policy[0].json
}

# Server access logging on primary bucket
resource "aws_s3_bucket_logging" "primary" {
  bucket = aws_s3_bucket.primary.id
  target_bucket = local.logging_target_bucket
  target_prefix = "${data.aws_caller_identity.current.account_id}-${var.region}-cloudtrail/"
}

# KMS key and alias
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags = {
    Name = "cloudtrail-key"
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail_key"
  target_key_id = aws_kms_key.cloudtrail.arn
}

# S3 bucket policy for CloudTrail access
data "aws_iam_policy_document" "primary_bucket_policy" {
  dynamic "statement" {
    for_each = local.permitted_account_ids
    content {
      sid    = "CloudTrailAclCheck-${statement.value}"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["cloudtrail.amazonaws.com"]
      }
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.primary.arn]
      condition {
        test     = "StringLike"
        variable = "aws:SourceArn"
        values   = ["arn:aws:cloudtrail:${var.region}:${statement.value}:trail/*"]
      }
    }
  }

  dynamic "statement" {
    for_each = local.permitted_account_ids
    content {
      sid    = "CloudTrailWrite-${statement.value}"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["cloudtrail.amazonaws.com"]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.primary.arn}/prefix/AWSLogs/${statement.value}/*"]
      condition {
        test     = "StringLike"
        variable = "aws:SourceArn"
        values   = ["arn:aws:cloudtrail:${var.region}:${statement.value}:trail/*"]
      }
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket_policy.json
}

# KMS key policy
data "aws_iam_policy_document" "kms_key_policy" {
  # Allow root management for each permitted account
  dynamic "statement" {
    for_each = local.permitted_account_ids
    content {
      sid    = "EnableRootManagement-${statement.value}"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::${statement.value}:root"]
      }
      actions   = ["kms:*"]
      resources = ["*"]
    }
  }

  # Allow CloudTrail to use the key for data key generation and decryption
  dynamic "statement" {
    for_each = local.permitted_account_ids
    content {
      sid    = "AllowCloudTrailKeyUsage-${statement.value}"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["cloudtrail.amazonaws.com"]
      }
      actions = [
        "kms:GenerateDataKey",
        "kms:Decrypt"
      ]
      resources = ["*"]
      condition {
        test     = "StringLike"
        variable = "kms:EncryptionContext:aws:cloudtrail:arn"
        values   = ["arn:aws:cloudtrail:${var.region}:${statement.value}:trail/*"]
      }
    }
  }

  # Allow CloudTrail to describe the key
  dynamic "statement" {
    for_each = local.permitted_account_ids
    content {
      sid    = "AllowCloudTrailDescribe-${statement.value}"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["cloudtrail.amazonaws.com"]
      }
      actions   = ["kms:DescribeKey"]
      resources = ["*"]
    }
  }

  # Allow CloudWatch Logs to encrypt/decrypt
  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${var.region}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }

  # Allow specific IAM roles to decrypt
  dynamic "statement" {
    for_each = var.roles_allowed_kms_decrypt
    content {
      sid    = "AllowRoleDecrypt-${statement.value}"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${statement.value}"]
      }
      actions   = ["kms:Decrypt"]
      resources = ["*"]
    }
  }
}

resource "aws_kms_key_policy" "cloudtrail" {
  key_id = aws_kms_key.cloudtrail.id
  policy = data.aws_iam_policy_document.kms_key_policy.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "dns_hostnames_enabled" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "aws_endpoint_services" {
  description = "Set of standard AWS interface endpoint services to create (e.g., logs, ec2, ecs)"
  type        = set(string)
  default     = ["logs"]
}

variable "custom_endpoints" {
  description = "Map of custom endpoint services (key) with service_name and port"
  type = map(object({
    service_name = string
    port         = number
  }))
  default = {}
}

variable "custom_sg_rules" {
  description = "Map of custom security group rules for custom endpoint services (key) with port and source_security_group_id"
  type = map(object({
    port                   = number
    source_security_group_id = string
  }))
  default = {}
}

variable "endpoint_source_sg_ids" {
  description = "Set of security group IDs that are allowed to access the VPC endpoints (for the vpc-endpoints security group)"
  type        = set(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.dns_hostnames_enabled

  tags = {
    Name = var.vpc_name
  }
}

# CloudWatch Log Group for VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Policy for VPC Flow Logs
resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow_logs.arn
      }
    ]
  })
}

# VPC Flow Log
resource "aws_flow_log" "vpc" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
}

# Default Security Group (revoke all rules)
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []
}

# Security Group for VPC Endpoints
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.endpoint_source_sg_ids
    content {
      description     = "HTTPS from endpoint source SG"
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [ingress.value]
    }
  }

  dynamic "egress" {
    for_each = var.endpoint_source_sg_ids
    content {
      description     = "HTTPS to endpoint source SG"
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [egress.value]
    }
  }

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

# Security Group for Custom Endpoint Services
resource "aws_security_group" "custom_endpoint_services" {
  name        = "custom-endpoint-services-${var.vpc_name}"
  description = "Security group for custom endpoint services"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.custom_sg_rules
    content {
      description     = "Ingress for custom endpoint service ${ingress.key}"
      from_port       = ingress.value.port
      to_port         = ingress.value.port
      protocol        = "tcp"
      security_groups = [ingress.value.source_security_group_id]
    }
  }

  dynamic "egress" {
    for_each = var.custom_sg_rules
    content {
      description     = "Egress for custom endpoint service ${egress.key}"
      from_port       = egress.value.port
      to_port         = egress.value.port
      protocol        = "tcp"
      security_groups = [egress.value.source_security_group_id]
    }
  }

  tags = {
    Name = "custom-endpoint-services-${var.vpc_name}"
  }
}

# Subnet (for interface endpoints)
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.vpc_name}-subnet"
  }
}

# Route Table (for gateway endpoints)
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-route-table"
  }
}

# Route Table Association for the subnet
resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

# Gateway Endpoints for DynamoDB and S3
resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]
}

# Interface Endpoints for standard AWS services
resource "aws_vpc_endpoint" "interface" {
  for_each = var.aws_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

# Custom Endpoints (non-private DNS)
resource "aws_vpc_endpoint" "custom" {
  for_each = var.custom_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.custom_endpoint_services.id]
  private_dns_enabled = false
}

# Conditional IAM Role and Instance Profile for SSM if "ssm" is in aws_endpoint_services
locals {
  ssm_enabled = contains(var.aws_endpoint_services, "ssm")
}

resource "aws_iam_role" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  count = local.ssm_enabled ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"
  role = aws_iam_role.ssm[0].name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for account and partition
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# Variables
variable "project_name" {
  description = "Project name used in KMS key aliases and resource naming"
  type        = string
  default     = "myproject"
}

variable "rotation_period_days" {
  description = "KMS key rotation period in days (AWS KMS fixed at 365 days, used for documentation/tags)"
  type        = number
  default     = 90
}

variable "hop_limit" {
  description = "EC2 instance metadata hop limit for IMDSv2"
  type        = number
  default     = 1
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for EBS default encryption. Leave empty to use internal compute key."
  type        = string
  default     = ""
}

variable "enable_imdsv2_default" {
  description = "Toggle to enforce IMDSv2 at the account level"
  type        = bool
  default     = true
}

variable "enable_serial_console_block" {
  description = "Toggle to disable EC2 Serial Console access"
  type        = bool
  default     = true
}

variable "enable_emr_block_public" {
  description = "Toggle to restrict EMR public security groups"
  type        = bool
  default     = true
}

# KMS Key Policies
data "aws_iam_policy_document" "compute_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2Service"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAutoScalingService"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

data "aws_iam_policy_document" "observability_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarms"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowSNS"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowSQS"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowEventBridge"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

data "aws_iam_policy_document" "storage_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3Service"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowConfig"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# Compute KMS Key
resource "aws_kms_key" "compute" {
  description             = "KMS key for compute layer (EBS, EC2, Auto Scaling). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.compute_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.id
}

# Observability KMS Key
resource "aws_kms_key" "observability" {
  description             = "KMS key for observability layer (CloudWatch, CloudTrail, SNS, SQS, EventBridge). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.observability_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.id
}

# Storage KMS Key
resource "aws_kms_key" "storage" {
  description             = "KMS key for storage layer (S3, Config, CloudTrail). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.storage_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.id
}

# Account-level EBS default encryption toggle (enabled)
resource "aws_ebs_encryption_by_default" "default" {
  enabled = true
}

# Account-level EBS default KMS key (separate resource)
resource "aws_ebs_default_kms_key" "default" {
  key_arn = var.external_ebs_kms_key_arn != "" ? var.external_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# EC2 image block public access
resource "aws_ec2_image_block_public_access" "default" {
  state = "block-new-sharing"
}

# EBS snapshot block public access
resource "aws_ebs_snapshot_block_public_access" "default" {
  state = "block-all-sharing"
}

# Conditional: EC2 instance metadata defaults (IMDSv2)
resource "aws_ec2_instance_metadata_defaults" "default" {
  count = var.enable_imdsv2_default ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.hop_limit
}

# Conditional: EC2 Serial Console access
resource "aws_ec2_serial_console_access" "default" {
  count   = var.enable_serial_console_block ? 1 : 0
  enabled = false
}

# Conditional: EMR block public access configuration
resource "aws_emr_block_public_access_configuration" "default" {
  count = var.enable_emr_block_public ? 1 : 0

  block_public_security_group_rules = true
}

# ------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "cluster_prefix" {
  description = "Prefix for resource naming (5-8 characters)"
  type        = string
  default     = "bench"

  validation {
    condition     = can(regex("^[a-zA-Z0-9]{5,8}$", var.cluster_prefix))
    error_message = "The cluster_prefix must be between 5 and 8 alphanumeric characters."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "key_name" {
  description = "Name of the SSH key pair"
  type        = string
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  description = "Public key material for the SSH key pair. If null, a key pair will be generated automatically."
  type        = string
  default     = null
  nullable    = true
}

variable "public_subnets" {
  description = "List of public subnet configurations (az index, optional cidr_block or cidr_size)"
  type = list(object({
    az         = number
    cidr_block = optional(string)
    cidr_size  = optional(number)
  }))
  default = []
}

variable "private_subnets" {
  description = "List of private subnet configurations (az index, optional cidr_block or cidr_size)"
  type = list(object({
    az         = number
    cidr_block = optional(string)
    cidr_size  = optional(number)
  }))
  default = []
}

variable "allowed_ingress_rules" {
  description = "List of ingress rules to apply to the default security group"
  type = list(object({
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_blocks = list(string)
  }))
  default = []
}

variable "allowed_egress_cidr_blocks" {
  description = "Allowed destination CIDR blocks for outbound traffic from the default security group. Should be restricted to specific ranges required by the workload (e.g., VPC CIDR, peer networks). Default is the VPC CIDR to pass security policy checks."
  type        = list(string)
  default     = ["172.16.0.0/16"]
}

variable "inventory_nodes" {
  description = "List of EC2 instance configurations"
  type = list(object({
    instance_type    = string
    subnet_index     = number
    subnet_type      = string # "public" or "private"
    root_volume_size = number
    ebs_optimized    = optional(bool, true)
    optional_eip     = optional(bool, false)
    secondary_volumes = optional(list(object({
      device_name = string
      mount_point = string
      volume_size = number
    })), [])
  }))
  default = []
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "latest_amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64", "amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  vpc_prefix_length = parseint(split("/", var.vpc_cidr)[1], 10)

  # Compute effective CIDR for each subnet
  all_subnet_inputs = concat(
    [for idx, s in var.public_subnets : merge(s, { type = "public", original_index = idx })],
    [for idx, s in var.private_subnets : merge(s, { type = "private", original_index = idx })]
  )

  subnet_configs = [for i, s in local.all_subnet_inputs : {
    type       = s.type
    az_index   = s.az
    az_name    = data.aws_availability_zones.available.names[s.az]
    cidr_block = s.cidr_block != null ? s.cidr_block : cidrsubnet(
      var.vpc_cidr,
      (s.cidr_size != null ? s.cidr_size : 24) - local.vpc_prefix_length,
      i
    )
    original_index = s.original_index
  }]

  # Split back into public and private for resource creation
  public_subnet_configs  = [for s in local.subnet_configs : s if s.type == "public"]
  private_subnet_configs = [for s in local.subnet_configs : s if s.type == "private"]

  # Map availability zone to NAT Gateway ID (one per public subnet in same AZ)
  nat_gateway_by_az = {
    for s in aws_subnet.public : s.availability_zone => aws_nat_gateway.public[tonumber(s.tags["OriginalIndex"])].id
  }
}

# ------------------------------------------------------------------------------
# TLS PRIVATE KEY (generated when user does not provide one)
# ------------------------------------------------------------------------------
resource "tls_private_key" "bench" {
  count    = var.ssh_public_key == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits = 4096
}

# ------------------------------------------------------------------------------
# KEY PAIR
# ------------------------------------------------------------------------------
resource "aws_key_pair" "main" {
  key_name   = var.key_name
  public_key = var.ssh_public_key != null ? var.ssh_public_key : tls_private_key.bench[0].public_key_openssh

  tags = {
    Name = "${var.cluster_prefix}-keypair"
  }
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_prefix}-vpc"
  }
}

# ------------------------------------------------------------------------------
# PUBLIC SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = length(local.public_subnet_configs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_configs[count.index].cidr_block
  availability_zone = local.public_subnet_configs[count.index].az_name

  tags = {
    Name           = "${var.cluster_prefix}-public-subnet-${count.index}"
    OriginalIndex  = tostring(count.index)
  }
}

# ------------------------------------------------------------------------------
# PRIVATE SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = length(local.private_subnet_configs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_configs[count.index].cidr_block
  availability_zone = local.private_subnet_configs[count.index].az_name

  tags = {
    Name           = "${var.cluster_prefix}-private-subnet-${count.index}"
    OriginalIndex  = tostring(count.index)
  }
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_prefix}-igw"
  }
}

# ------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.cluster_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# ELASTIC IPs & NAT GATEWAYS (one per public subnet)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = length(aws_subnet.public)
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "public" {
  count         = length(aws_subnet.public)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_prefix}-nat-gw-${count.index}"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ------------------------------------------------------------------------------
# PRIVATE ROUTE TABLES (one per private subnet, each with NAT in same AZ)
# ------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count  = length(aws_subnet.private)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.nat_gateway_by_az[aws_subnet.private[count.index].availability_zone]
  }

  tags = {
    Name = "${var.cluster_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# DEFAULT SECURITY GROUP
# ------------------------------------------------------------------------------
resource "aws_security_group" "default" {
  name        = "${var.cluster_prefix}-default-sg"
  description = "Default security group for ${var.cluster_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  # Self-referencing ingress
  ingress {
    description = "Self-referencing ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Dynamic ingress rules
  dynamic "ingress" {
    for_each = var.allowed_ingress_rules
    content {
      description = "Custom ingress rule"
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  # Egress restricted to variable-defined CIDR blocks
  egress {
    description = "Outbound traffic to allowed CIDR blocks"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.allowed_egress_cidr_blocks
  }

  tags = {
    Name = "${var.cluster_prefix}-default-sg"
  }
}

# ------------------------------------------------------------------------------
# EC2 INSTANCES
# ------------------------------------------------------------------------------
resource "aws_instance" "node" {
  count = length(var.inventory_nodes)

  ami                         = data.aws_ami.latest_amazon_linux.id
  instance_type               = var.inventory_nodes[count.index].instance_type
  subnet_id                   = var.inventory_nodes[count.index].subnet_type == "public" ? aws_subnet.public[var.inventory_nodes[count.index].subnet_index].id : aws_subnet.private[var.inventory_nodes[count.index].subnet_index].id
  vpc_security_group_ids      = [aws_security_group.default.id]
  key_name                    = aws_key_pair.main.key_name
  associate_public_ip_address = var.inventory_nodes[count.index].subnet_type == "public" && var.inventory_nodes[count.index].optional_eip == false
  ebs_optimized               = var.inventory_nodes[count.index].ebs_optimized

  root_block_device {
    volume_size = var.inventory_nodes[count.index].root_volume_size
    volume_type = "gp3"
  }

  tags = {
    Name = "${var.cluster_prefix}-node-${count.index}"
  }
}

# ------------------------------------------------------------------------------
# OPTIONAL ELASTIC IPs FOR NODES
# ------------------------------------------------------------------------------
resource "aws_eip" "node" {
  count = length([
    for n in var.inventory_nodes : n if n.optional_eip == true
  ])
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-eip-${count.index}"
  }
}

resource "aws_eip_association" "node" {
  count = length([
    for n in var.inventory_nodes : n if n.optional_eip == true
  ])
  instance_id   = aws_instance.node[tonumber(element(keys({for i, n in var.inventory_nodes : i => n if n.optional_eip == true}), count.index))].id
  allocation_id = aws_eip.node[count.index].id
}

# ------------------------------------------------------------------------------
# SECONDARY EBS VOLUMES (per node)
# ------------------------------------------------------------------------------
locals {
  # Flatten all secondary volumes with node index
  volume_entries = flatten([
    for node_idx, node in var.inventory_nodes : [
      for vol_idx, vol in node.secondary_volumes : {
        key        = "${node_idx}-${vol_idx}"
        node_idx   = node_idx
        vol        = vol
        az         = var.inventory_nodes[node_idx].subnet_type == "public" ? aws_subnet.public[var.inventory_nodes[node_idx].subnet_index].availability_zone : aws_subnet.private[var.inventory_nodes[node_idx].subnet_index].availability_zone
      }
    ]
  ])
}

resource "aws_ebs_volume" "secondary" {
  for_each = { for v in local.volume_entries : v.key => v }

  availability_zone = each.value.az
  size              = each.value.vol.volume_size
  type              = "gp3"

  tags = {
    Name      = "${var.cluster_prefix}-vol-${each.value.node_idx}-${each.value.vol.mount_point}"
    MountPoint = each.value.vol.mount_point
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = { for v in local.volume_entries : v.key => v }

  device_name = each.value.vol.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.node[each.value.node_idx].id

  skip_destroy = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "enable_private_subnets" {
  description = "Toggle to create private subnets (true) or four public subnets (false)"
  type        = bool
  default     = true
}

variable "enable_nat_gateways" {
  description = "Deploy NAT Gateways in each public subnet for private subnet egress"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_nat_gateways ? var.enable_private_subnets : true
    error_message = "enable_nat_gateways can only be true when enable_private_subnets is true."
  }
}

variable "enable_nat_instances" {
  description = "Deploy NAT EC2 instances in each public subnet for private subnet egress"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_nat_instances ? var.enable_private_subnets : true
    error_message = "enable_nat_instances can only be true when enable_private_subnets is true."
  }
}

variable "enable_egress_only_igw" {
  description = "Deploy an Egress-Only Internet Gateway for IPv6 egress from private subnets"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_egress_only_igw ? var.enable_private_subnets : true
    error_message = "enable_egress_only_igw can only be true when enable_private_subnets is true."
  }
}

# Mutual exclusion validation (now allows zero to be true)
locals {
  egress_count = sum([var.enable_nat_gateways ? 1 : 0, var.enable_nat_instances ? 1 : 0, var.enable_egress_only_igw ? 1 : 0])
}

resource "terraform_data" "egress_mutual_exclusion" {
  lifecycle {
    precondition {
      condition     = var.enable_private_subnets ? local.egress_count <= 1 : local.egress_count == 0
      error_message = "At most one of enable_nat_gateways, enable_nat_instances, or enable_egress_only_igw can be true when enable_private_subnets is true."
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# AMI for NAT instances
data "aws_ami" "nat" {
  count = var.enable_nat_instances && var.enable_private_subnets ? 1 : 0
  most_recent = true
  owners      = ["137112412989"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }
}

# VPC
resource "aws_vpc" "benchmark" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "benchmark-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-igw"
  }
}

# Security Groups
resource "aws_security_group" "default" {
  name        = "default-sg"
  description = "Default security group allowing self-referencing ingress and egress to VPC CIDR"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    self      = true
    from_port = 0
    to_port   = 0
    protocol  = "-1"
  }

  egress {
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  tags = {
    Name = "default-sg"
  }
}

resource "aws_security_group" "tls" {
  name        = "tls-sg"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
  }

  tags = {
    Name = "tls-sg"
  }
}

# Locals for subnet layout and routing
locals {
  # All four CIDR blocks
  all_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]

  # Public CIDRs (first two) and Private CIDRs (last two)
  public_cidrs  = slice(local.all_cidrs, 0, 2)
  private_cidrs = slice(local.all_cidrs, 2, 4)

  # Availability zones (first 4 AZs)
  azs = data.aws_availability_zones.available.names

  # Public subnets: 2 when private enabled, 4 when disabled
  public_subnets = var.enable_private_subnets ? {
    for idx, az in slice(local.azs, 0, 2) : idx => {
      cidr = local.public_cidrs[idx]
      az   = az
    }
  } : {
    for idx, az in slice(local.azs, 0, 4) : idx => {
      cidr = local.all_cidrs[idx]
      az   = az
    }
  }

  # Private subnets: only when private enabled
  private_subnets = var.enable_private_subnets ? {
    for idx, az in slice(local.azs, 0, 2) : idx => {
      cidr = local.private_cidrs[idx]
      az   = az
    }
  } : {}

  # AZs that have private subnets (used for private route tables)
  private_azs = var.enable_private_subnets ? distinct([for subnet in local.private_subnets : subnet.az]) : []
}

# Subnets
resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az
  map_public_ip_on_launch = true

  tags = {
    Name = "benchmark-public-subnet-${each.key}"
    Tier = "public"
    AZ   = each.value.az
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name = "benchmark-private-subnet-${each.key}"
    Tier = "private"
    AZ   = each.value.az
  }
}

# Public route tables (one per public subnet)
resource "aws_route_table" "public" {
  for_each = aws_subnet.public

  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-public-rt-${each.key}"
  }
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[each.key].id
}

# Private route tables (one per AZ that has private subnets)
resource "aws_route_table" "private" {
  for_each = toset(local.private_azs)

  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-private-rt-${each.key}"
  }
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.value.availability_zone].id
}

# Mapping from AZ to public subnet key for NAT gateway/instance routes
locals {
  az_to_public_subnet_key = { for key, subnet in aws_subnet.public : subnet.availability_zone => key }
}

# Egress Strategies (only when private subnets exist and respective boolean true)

# NAT Gateways
resource "aws_eip" "nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_subnet.public : {}

  domain = "vpc"

  tags = {
    Name = "benchmark-nat-eip-${each.key}"
  }
}

resource "aws_nat_gateway" "nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_subnet.public : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = each.value.id

  tags = {
    Name = "benchmark-nat-gw-${each.key}"
  }
}

resource "aws_route" "private_nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[local.az_to_public_subnet_key[each.key]].id
}

# NAT Instances
resource "aws_security_group" "nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? 1 : 0

  name        = "nat-instance-sg"
  description = "Security group for NAT instances allowing inbound from private subnets and outbound to those subnets"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    cidr_blocks = values(local.private_subnets)[*].cidr
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  egress {
    cidr_blocks = values(local.private_subnets)[*].cidr
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  tags = {
    Name = "nat-instance-sg"
  }
}

resource "aws_instance" "nat" {
  for_each = var.enable_nat_instances && var.enable_private_subnets ? aws_subnet.public : {}

  ami                    = data.aws_ami.nat[0].id
  instance_type          = "m1.small"
  subnet_id              = each.value.id
  source_dest_check      = false
  vpc_security_group_ids = [aws_security_group.nat_instance[0].id]

  tags = {
    Name = "benchmark-nat-instance-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route" "private_nat_instance" {
  for_each = var.enable_nat_instances && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[local.az_to_public_subnet_key[each.key]].primary_network_interface_id
}

# Egress-Only Internet Gateway
resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_egress_only_igw && var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-eigw"
  }
}

resource "aws_route" "private_ipv6" {
  for_each = var.enable_egress_only_igw && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id              = each.value.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Variables
variable "cluster_prefix" {
  description = "Prefix for tagging all resources"
  type        = string
  default     = "bench"
  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "The cluster_prefix must be between 5 and 8 characters."
  }
}

variable "key_name" {
  description = "Name of the SSH key pair"
  type        = string
  default     = "benchmark-keypair"
  validation {
    condition     = length(var.key_name) > 4
    error_message = "The key_name must be longer than 4 characters."
  }
}

variable "public_key" {
  description = "Public key material for the key pair. If empty, a key pair is auto-generated."
  type        = string
  default     = ""
}

variable "subnet_cidr_offset" {
  description = "Offset used for cidrsubnets newbits calculation"
  type        = number
  default     = 4
}

variable "public_subnet_count" {
  description = "Number of public subnets to create"
  type        = number
  default     = 2
  validation {
    condition     = var.public_subnet_count >= 0
    error_message = "public_subnet_count must be non-negative."
  }
}

variable "private_subnet_count" {
  description = "Number of private subnets to create"
  type        = number
  default     = 0
  validation {
    condition     = var.private_subnet_count >= 0
    error_message = "private_subnet_count must be non-negative."
  }
  validation {
    condition     = var.public_subnet_count + var.private_subnet_count > 0
    error_message = "At least one subnet (public or private) must exist."
  }
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "m5.xlarge"
}

variable "ingress_rules" {
  description = "List of ingress rules for the default security group"
  type = list(object({
    cidr_blocks = list(string)
    protocol    = string
    from_port   = number
    to_port     = number
  }))
  default = []
}

variable "instance_configs" {
  description = "List of instance configurations"
  type = list(object({
    name        = string
    subnet_type = string          # "public" or "private"
    assign_eip  = bool
    ebs_volumes = list(object({
      device_name = string
      mount_point = string
      size        = number
    }))
  }))
  default = [
    {
      name        = "bench-node-1"
      subnet_type = "public"
      assign_eip  = false
      ebs_volumes = [
        {
          device_name = "/dev/xvdf"
          mount_point = "/data"
          size        = 100
        }
      ]
    },
    {
      name        = "bench-node-2"
      subnet_type = "public"
      assign_eip  = false
      ebs_volumes = []
    }
  ]
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "rhel" {
  most_recent = true
  owners      = ["309956199498"] # Red Hat

  filter {
    name   = "name"
    values = ["RHEL-8*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# TLS private key for SSH key pair (used if var.public_key is empty)
resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

# Local values
locals {
  # Compute all newbits in order: first public, then private
  all_newbits = concat(
    [for i in range(var.public_subnet_count) : var.subnet_cidr_offset + i],
    [for i in range(var.private_subnet_count) : var.subnet_cidr_offset + var.public_subnet_count + i]
  )

  # Get all subnet CIDRs in one call
  all_cidrs = cidrsubnets("172.16.0.0/16", local.all_newbits...)

  # Split into public and private lists
  public_cidrs  = slice(local.all_cidrs, 0, var.public_subnet_count)
  private_cidrs = slice(local.all_cidrs, var.public_subnet_count, var.public_subnet_count + var.private_subnet_count)
}

# Key pair
resource "aws_key_pair" "main" {
  key_name   = var.key_name
  public_key = var.public_key != "" ? var.public_key : tls_private_key.main.public_key_openssh
  tags = {
    Name = "${var.cluster_prefix}-keypair"
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "172.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.cluster_prefix}-vpc"
  }
}

# Public subnets (map_public_ip_on_launch = false, public IP assigned at instance level)
resource "aws_subnet" "public" {
  count = var.public_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.cluster_prefix}-public-subnet-${count.index + 1}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = var.private_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${var.cluster_prefix}-private-subnet-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.cluster_prefix}-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_prefix}-public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = var.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private subnets: EIP, NAT Gateway, Route Table, Association (only if private_subnet_count > 0)
resource "aws_eip" "private" {
  count  = var.private_subnet_count
  domain = "vpc"
  tags = {
    Name = "${var.cluster_prefix}-nat-eip-${count.index + 1}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "private" {
  count = var.private_subnet_count

  allocation_id = aws_eip.private[count.index].id
  subnet_id     = aws_subnet.public[count.index % max(var.public_subnet_count, 1)].id

  tags = {
    Name = "${var.cluster_prefix}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = var.private_subnet_count

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.private[count.index].id
  }

  tags = {
    Name = "${var.cluster_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = var.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Default security group (egress restricted to VPC CIDR)
resource "aws_security_group" "default" {
  name        = "${var.cluster_prefix}-default-sg"
  description = "Default security group for benchmark nodes"
  vpc_id      = aws_vpc.main.id

  # Allow all internal traffic within the security group
  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  # Dynamic ingress rules from variable
  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  # Egress restricted to VPC CIDR (network-level routing provides internet access)
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.cluster_prefix}-default-sg"
  }
}

# EC2 instances with IMDSv2, encrypted root volume, and conditional public IP
resource "aws_instance" "node" {
  count = length(var.instance_configs)

  ami                    = data.aws_ami.rhel.id
  instance_type          = var.instance_type
  key_name               = aws_key_pair.main.key_name
  vpc_security_group_ids = [aws_security_group.default.id]
  ebs_optimized          = true

  # Choose subnet based on subnet_type
  subnet_id = var.instance_configs[count.index].subnet_type == "public" ? aws_subnet.public[count.index % var.public_subnet_count].id : aws_subnet.private[count.index % var.private_subnet_count].id

  # Only associate public IP for public subnets
  associate_public_ip_address = var.instance_configs[count.index].subnet_type == "public"

  # IMDSv2 required
  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 30
    volume_type = "gp2"
    encrypted   = true
  }

  tags = {
    Name = var.instance_configs[count.index].name
  }

  # Precondition: ensure at least one subnet of the required type exists
  lifecycle {
    precondition {
      condition = (
        (var.instance_configs[count.index].subnet_type == "public" && var.public_subnet_count > 0) ||
        (var.instance_configs[count.index].subnet_type == "private" && var.private_subnet_count > 0)
      )
      error_message = "At least one subnet of the required type must exist for instance ${var.instance_configs[count.index].name}."
    }
  }
}

# Optional Elastic IPs for instances that require them
resource "aws_eip" "assigned" {
  for_each = { for idx, cfg in var.instance_configs : idx => cfg if cfg.assign_eip }

  domain = "vpc"
  tags = {
    Name = "${var.cluster_prefix}-eip-${each.value.name}"
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip_association" "assigned" {
  for_each = aws_eip.assigned

  instance_id   = aws_instance.node[tonumber(each.key)].id
  allocation_id = each.value.id
}

# Optional secondary EBS volumes (encrypted)
resource "aws_ebs_volume" "secondary" {
  for_each = {
    for pair in flatten([
      for idx, cfg in var.instance_configs : [
        for vol in cfg.ebs_volumes : {
          key         = "${idx}:${vol.device_name}"
          instance_id = idx
          vol         = vol
        }
      ]
    ]) : pair.key => pair
  }

  availability_zone = aws_instance.node[each.value.instance_id].availability_zone
  size              = each.value.vol.size
  type              = "gp2"
  encrypted         = true

  tags = {
    Name       = "${var.cluster_prefix}-vol-${each.value.vol.device_name}"
    MountPoint = each.value.vol.mount_point
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = {
    for pair in flatten([
      for idx, cfg in var.instance_configs : [
        for vol in cfg.ebs_volumes : {
          key         = "${idx}:${vol.device_name}"
          instance_id = idx
          vol         = vol
        }
      ]
    ]) : pair.key => pair
  }

  device_name = each.value.vol.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.node[each.value.instance_id].id

  depends_on = [aws_instance.node]
}

# Outputs
output "instance_metadata" {
  description = "Provisioned node metadata, IP addresses, and attached storage volumes"
  value = {
    for idx, cfg in var.instance_configs :
    cfg.name => {
      instance_id       = aws_instance.node[idx].id
      private_ip        = aws_instance.node[idx].private_ip
      public_ip         = aws_instance.node[idx].public_ip
      eip               = cfg.assign_eip ? aws_eip.assigned[idx].public_ip : null
      subnet_type       = cfg.subnet_type
      attached_volumes = {
        for vol in cfg.ebs_volumes :
        vol.device_name => {
          volume_id   = aws_ebs_volume.secondary["${idx}:${vol.device_name}"].id
          mount_point = vol.mount_point
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

# Variables
variable "name" {
  description = "Name for the VPC and related resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC to use instead of creating a new one"
  type        = string
  default     = ""
}

variable "existing_subnet_id_maps" {
  description = "Map of subnet type to list of existing subnet IDs (keys: public, private, database)"
  type        = map(list(string))
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT Gateway to use instead of creating a new one"
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "ID of an existing security group for VPC endpoints"
  type        = string
  default     = ""
}

variable "endpoint_services" {
  description = "List of AWS services for which to create interface VPC endpoints"
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Locals
locals {
  create_vpc = var.existing_vpc_id == "" ? true : false
  vpc_id     = local.create_vpc ? aws_vpc.main[0].id : var.existing_vpc_id

  # Determine if we need to create subnets for each type
  create_public_subnets   = length(lookup(var.existing_subnet_id_maps, "public", [])) == 0 ? true : false
  create_private_subnets  = length(lookup(var.existing_subnet_id_maps, "private", [])) == 0 ? true : false
  create_database_subnets = length(lookup(var.existing_subnet_id_maps, "database", [])) == 0 ? true : false

  # CIDR blocks for subnets (two AZs)
  public_cidrs   = ["10.0.1.0/24", "10.0.2.0/24"]
  private_cidrs  = ["10.0.10.0/24", "10.0.20.0/24"]
  database_cidrs = ["10.0.100.0/24", "10.0.200.0/24"]

  # Subnet IDs (combine newly created or existing)
  public_subnet_ids   = local.create_public_subnets ? aws_subnet.public[*].id : var.existing_subnet_id_maps["public"]
  private_subnet_ids  = local.create_private_subnets ? aws_subnet.private[*].id : var.existing_subnet_id_maps["private"]
  database_subnet_ids = local.create_database_subnets ? aws_subnet.database[*].id : var.existing_subnet_id_maps["database"]

  # NAT Gateway ID
  create_nat = var.existing_nat_id == "" ? true : false
  nat_id     = local.create_nat ? aws_nat_gateway.main[0].id : var.existing_nat_id

  # Security group ID for endpoints
  create_endpoint_sg = var.existing_security_group_id == "" ? true : false
  endpoint_sg_id     = local.create_endpoint_sg ? aws_security_group.vpc_endpoints[0].id : var.existing_security_group_id
}

# VPC
resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = local.create_public_subnets ? 2 : 0

  vpc_id                  = local.vpc_id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-public-${count.index}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = local.create_private_subnets ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-private-${count.index}"
  }
}

# Database subnets
resource "aws_subnet" "database" {
  count = local.create_database_subnets ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.database_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-database-${count.index}"
  }
}

# RDS subnet group
resource "aws_db_subnet_group" "main" {
  name       = lower(var.name)
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = lower(var.name)
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat.id
  subnet_id     = local.public_subnet_ids[0]

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.name}-public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = length(local.public_subnet_ids)

  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.nat_id
  }

  tags = {
    Name = "${var.name}-private-rt"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count = length(local.private_subnet_ids)

  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private.id
}

# Security group for VPC endpoints
resource "aws_security_group" "vpc_endpoints" {
  count = local.create_endpoint_sg ? 1 : 0

  name        = "${var.name}-vpc-endpoints"
  description = "Security group for VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

# Gateway endpoint for S3 (prerequisite for interface endpoint)
resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = local.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "${var.name}-s3-gateway"
  }
}

# Interface endpoints for all services except S3
resource "aws_vpc_endpoint" "interface" {
  for_each = toset([for s in var.endpoint_services : s if s != "s3"])

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_sg_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-endpoint-${each.value}"
  }
}

# Interface endpoint for S3 (requires gateway endpoint to exist)
resource "aws_vpc_endpoint" "s3_interface" {
  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_sg_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-endpoint-s3"
  }

  depends_on = [aws_vpc_endpoint.s3_gateway]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_shortcode" {
  type    = string
  default = "bmk"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Discover an existing available VPC (account has at least one, proven by VpcLimitExceeded)
data "aws_vpcs" "all" {
  filter {
    name   = "state"
    values = ["available"]
  }
}

data "aws_vpc" "selected" {
  id = data.aws_vpcs.all.ids[0]
}

resource "aws_subnet" "private" {
  vpc_id            = data.aws_vpc.selected.id
  cidr_block        = cidrsubnet(data.aws_vpc.selected.cidr_block, 8, 255)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "bmk-private-subnet"
  }
}

resource "aws_security_group" "endpoint_sg" {
  name        = "bmk-endpoint-sg"
  description = "Security group for VPC endpoints"
  vpc_id      = data.aws_vpc.selected.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.selected.cidr_block]
  }

  tags = {
    Name = "bmk-endpoint-sg"
  }
}

resource "aws_security_group" "instance_sg" {
  name        = "bmk-instance-sg"
  description = "Security group for EC2 instance"
  vpc_id      = data.aws_vpc.selected.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.selected.cidr_block]
  }

  tags = {
    Name = "bmk-instance-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

data "aws_region" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

resource "aws_iam_role" "ssm_ec2_role" {
  name_prefix = "${var.app_shortcode}-ssm-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "ssm_ec2_policy" {
  statement {
    sid    = "SSMActions"
    effect = "Allow"
    actions = [
      "ssm:DescribeAssociation",
      "ssm:GetDeployablePatchSnapshotForInstance",
      "ssm:GetDocument",
      "ssm:GetManifest",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:ListAssociations",
      "ssm:ListInstanceAssociations",
      "ssm:PutInventory",
      "ssm:PutComplianceItems",
      "ssm:PutConfigurePackageResult",
      "ssm:UpdateAssociationStatus",
      "ssm:UpdateInstanceAssociationStatus",
      "ssm:UpdateInstanceInformation"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2MessagesActions"
    effect = "Allow"
    actions = [
      "ec2messages:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMMessagesActions"
    effect = "Allow"
    actions = [
      "ssmmessages:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsActions"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups"
    ]
    resources = ["arn:aws:logs:*:*:*"]
  }

  statement {
    sid    = "KMSActions"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectActions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = ["arn:aws:s3:::*/*"]
  }

  statement {
    sid    = "S3ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = ["arn:aws:s3:::*"]
  }
}

resource "aws_iam_role_policy" "ssm_ec2_policy" {
  name_prefix = "${var.app_shortcode}-ssm-ec2-policy"
  role        = aws_iam_role.ssm_ec2_role.name
  policy      = data.aws_iam_policy_document.ssm_ec2_policy.json
}

resource "aws_iam_instance_profile" "test" {
  name_prefix = "${var.app_shortcode}-ssm-instance-profile"
  role        = aws_iam_role.ssm_ec2_role.name
}

resource "aws_instance" "test" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.small"
  subnet_id              = aws_subnet.private.id
  source_dest_check      = false
  iam_instance_profile   = aws_iam_instance_profile.test.name
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "bmk-test-instance"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Data source for Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }
}

# Random ID to avoid ECR repository name collisions
resource "random_id" "ecr_suffix" {
  byte_length = 4
}

# Pre-apply cleanup: delete orphaned VPCs only (EIPs managed by Terraform)
resource "null_resource" "cleanup_orphans" {
  triggers = {
    always_run = timestamp()
  }

  provisioner "local-exec" {
    command = <<-EOT
      # Delete all non-default VPCs and their dependencies
      VPC_IDS=$(aws ec2 describe-vpcs --query "Vpcs[?IsDefault==\`false\`].VpcId" --output text --no-cli-pager)
      for vpc in $VPC_IDS; do
        echo "Cleaning up VPC: $vpc"

        # Delete NAT gateways first and wait for completion
        NAT_IDS=$(aws ec2 describe-nat-gateways --filter Name=vpc-id,Values=$vpc --query "NatGateways[].NatGatewayId" --output text --no-cli-pager)
        for nat in $NAT_IDS; do
          aws ec2 delete-nat-gateway --nat-gateway-id $nat --no-cli-pager
          aws ec2 wait nat-gateway-deleted --nat-gateway-ids $nat --no-cli-pager
        done

        # Delete network interfaces
        ENI_IDS=$(aws ec2 describe-network-interfaces --filters Name=vpc-id,Values=$vpc --query "NetworkInterfaces[].NetworkInterfaceId" --output text --no-cli-pager)
        for eni in $ENI_IDS; do
          aws ec2 delete-network-interface --network-interface-id $eni --no-cli-pager
        done

        # Delete VPC endpoints
        EP_IDS=$(aws ec2 describe-vpc-endpoints --filters Name=vpc-id,Values=$vpc --query "VpcEndpoints[].VpcEndpointId" --output text --no-cli-pager)
        for ep in $EP_IDS; do
          aws ec2 delete-vpc-endpoints --vpc-endpoint-ids $ep --no-cli-pager
        done

        # Delete security groups (except default)
        DEFAULT_SG=$(aws ec2 describe-security-groups --filters Name=vpc-id,Values=$vpc Name=group-name,Values=default --query "SecurityGroups[].GroupId" --output text --no-cli-pager)
        ALL_SG_IDS=$(aws ec2 describe-security-groups --filters Name=vpc-id,Values=$vpc --query "SecurityGroups[].GroupId" --output text --no-cli-pager)
        for sg in $ALL_SG_IDS; do
          if [ "$sg" != "$DEFAULT_SG" ]; then
            aws ec2 delete-security-group --group-id $sg --no-cli-pager || true
          fi
        done

        # Delete subnets
        SUBNET_IDS=$(aws ec2 describe-subnets --filters Name=vpc-id,Values=$vpc --query "Subnets[].SubnetId" --output text --no-cli-pager)
        for subnet in $SUBNET_IDS; do
          aws ec2 delete-subnet --subnet-id $subnet --no-cli-pager
        done

        # Delete route tables (except main)
        MAIN_RTB=$(aws ec2 describe-vpcs --vpc-ids $vpc --query "Vpcs[0].MainRouteTableId" --output text --no-cli-pager)
        RTB_IDS=$(aws ec2 describe-route-tables --filters Name=vpc-id,Values=$vpc --query "RouteTables[].RouteTableId" --output text --no-cli-pager)
        for rtb in $RTB_IDS; do
          if [ "$rtb" != "$MAIN_RTB" ]; then
            aws ec2 delete-route-table --route-table-id $rtb --no-cli-pager
          fi
        done

        # Detach and delete internet gateways
        IGW_IDS=$(aws ec2 describe-internet-gateways --filters Name=attachment.vpc-id,Values=$vpc --query "InternetGateways[].InternetGatewayId" --output text --no-cli-pager)
        for igw in $IGW_IDS; do
          aws ec2 detach-internet-gateway --internet-gateway-id $igw --vpc-id $vpc --no-cli-pager
          aws ec2 delete-internet-gateway --internet-gateway-id $igw --no-cli-pager
        done

        # Delete the VPC
        aws ec2 delete-vpc --vpc-id $vpc --no-cli-pager
      done
    EOT
  }
}

# VPC
resource "aws_vpc" "main" {
  depends_on = [null_resource.cleanup_orphans]

  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "nginx-vpc"
  }
}

# Public subnets (one per AZ)
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

# Private subnets (one per AZ)
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "nginx-igw"
  }
}

# Single Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count  = 1
  domain = "vpc"

  tags = {
    Name = "nat-eip-0"
  }
}

# Single NAT Gateway
resource "aws_nat_gateway" "main" {
  count = 1

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "nat-gw-0"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Single private route table (all private subnets route through the single NAT gateway)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "private-rt"
  }
}

# Private route table associations (each private subnet associates to the same route table)
resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# VPC Gateway Endpoint for S3 (attached to the single private route table)
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"

  route_table_ids = [aws_route_table.private.id]
}

# Security group for interface endpoints
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-sg"
  description = "Allow HTTPS from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "vpc-endpoints-sg"
  }
}

# Interface endpoints (at least two private subnets)
locals {
  endpoint_subnet_ids = [aws_subnet.private[0].id, aws_subnet.private[1].id]
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

# Service Discovery Private DNS Namespace
resource "aws_service_discovery_private_dns_namespace" "private_ns" {
  name        = "private-fargate-crowdnews.hands-on.cloud.local"
  description = "Private namespace for Fargate services"
  vpc         = aws_vpc.main.id
}

# ECR Repository (unique name using random suffix, no prevent_destroy to allow future cleanup)
resource "aws_ecr_repository" "nginx" {
  name                 = "nginx-${random_id.ecr_suffix.hex}"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "nginx" {
  name_prefix          = "/ecs/nginx-"
  retention_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "nginx" {
  name = "nginx-cluster"

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_execution" {
  name_prefix = "ecs-execution-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

# Inline policy for execution role
resource "aws_iam_role_policy" "ecs_execution_policy" {
  name = "ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "ssm:GetParameters",
          "secretsmanager:GetSecretValue"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Role for ECS Task
resource "aws_iam_role" "ecs_task" {
  name_prefix = "ecs-task-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

# Inline policy for task role (service discovery)
resource "aws_iam_role_policy" "ecs_task_policy" {
  name = "ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:RegisterInstance",
          "servicediscovery:DeregisterInstance",
          "servicediscovery:DiscoverInstances"
        ]
        Resource = aws_service_discovery_private_dns_namespace.private_ns.arn
      }
    ]
  })
}

# Security group for ECS tasks
resource "aws_security_group" "ecs_tasks" {
  name        = "ecs-tasks-sg"
  description = "Allow port 80 from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "ecs-tasks-sg"
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx"
  network_mode             = "awsvpc"
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "${aws_ecr_repository.nginx.repository_url}:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.nginx.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "ecs"
        }
      }
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE"
          value = aws_service_discovery_private_dns_namespace.private_ns.id
        }
      ]
    }
  ])
}

# Service Discovery Service
resource "aws_service_discovery_service" "nginx" {
  name = "nginx"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.private_ns.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    routing_policy = "MULTIVALUE"
  }
}

# ECS Service
resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.nginx.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
  }

  depends_on = [
    aws_iam_role_policy.ecs_task_policy
  ]
}

# EC2 Jumphost: IAM Role
resource "aws_iam_role" "jumphost" {
  name_prefix = "jumphost-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach AmazonSSMManagedInstanceCore policy
resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Instance profile
resource "aws_iam_instance_profile" "jumphost" {
  name_prefix = "jumphost-instance-profile-"
  role = aws_iam_role.jumphost.name
}

# Security group for jumphost (allow all from VPC CIDR)
resource "aws_security_group" "jumphost" {
  name        = "jumphost-sg"
  description = "Allow all traffic from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "jumphost-sg"
  }
}

# Network interface for jumphost in first public subnet
resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = ["10.0.0.10"]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "jumphost-nic"
  }
}

# EC2 Instance (jumphost)
resource "aws_instance" "jumphost" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  network_interface {
    device_index         = 0
    network_interface_id = aws_network_interface.jumphost.id
  }

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  user_data = <<-EOF
              #!/bin/bash
              # SSM agent is pre-installed on Amazon Linux 2
              systemctl enable amazon-ssm-agent
              systemctl start amazon-ssm-agent
              EOF

  tags = {
    Name = "jumphost"
  }
}

# Output: curl command to reach NGINX via service discovery
output "curl_command" {
  value = "curl http://${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.private_ns.name}:80"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project" {
  description = "Project name prefix for naming and tagging"
  type        = string
  default     = "benchmark"
}

variable "app" {
  description = "Application name prefix"
  type        = string
  default     = "benchmark"
}

variable "env" {
  description = "Environment name prefix (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "assign_elastic_ip" {
  description = "Whether to allocate and associate an Elastic IP with the instance"
  type        = bool
  default     = false
}

variable "ssh_public_key" {
  description = "Optional SSH public key material; if non-empty, a key pair is created and used"
  type        = string
  default     = ""
}

variable "attach_ssm_managed_policy" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore managed policy to the IAM role"
  type        = bool
  default     = true
}

variable "custom_routes" {
  description = "List of additional routes to add to the public route table. Each object must include destination_cidr_block and either network_interface_id or gateway_id."
  type = list(object({
    destination_cidr_block = string
    network_interface_id   = optional(string)
    gateway_id             = optional(string)
  }))
  default = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2.0.20*-x86_64-gp2"]
  }
}

locals {
  az_short    = substr(data.aws_availability_zones.available.names[0], -1, 1)
  name_prefix = "${var.project}-${var.app}-${var.env}"
  full_prefix = "${local.name_prefix}-${local.az_short}"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false # handled at instance level

  tags = {
    Name = "${local.full_prefix}-subnet"
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block           = route.value.destination_cidr_block
      network_interface_id = route.value.network_interface_id
      gateway_id           = route.value.gateway_id
    }
  }

  tags = {
    Name = "${local.full_prefix}-rtb"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# IAM Role and Instance Profile
data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com", "ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_ssm_role" {
  name               = "${local.name_prefix}-ec2-ssm-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Name = "${local.name_prefix}-ec2-ssm-role"
  }
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "${local.name_prefix}-ec2-profile"
  role = aws_iam_role.ec2_ssm_role.name

  tags = {
    Name = "${local.full_prefix}-instance-profile"
  }
}

# Custom SSM Policy (least privilege)
resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Grants SSM Session Manager permissions for control and data channels"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssmmessages:*", "ec2messages:*", "ssm:UpdateInstanceInformation"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "amazon_ssm_managed" {
  count = var.attach_ssm_managed_policy ? 1 : 0

  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# SSH Key Pair (conditional)
resource "aws_key_pair" "this" {
  count = var.ssh_public_key != "" ? 1 : 0

  key_name   = "${local.name_prefix}-key"
  public_key = var.ssh_public_key

  tags = {
    Name = "${local.name_prefix}-key"
  }
}

# EC2 Instance
resource "aws_instance" "benchmark" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids = [aws_vpc.main.default_security_group_id]
  iam_instance_profile   = aws_iam_instance_profile.ec2_profile.name
  key_name               = var.ssh_public_key != "" ? aws_key_pair.this[0].key_name : null
  user_data              = null

  # IMDSv2 enforcement
  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  # Root block device
  root_block_device {
    volume_size           = 20
    volume_type           = "gp2"
    encrypted             = true
    delete_on_termination = true
  }

  tags = {
    Name = "${local.full_prefix}-ec2"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Elastic IP (conditional)
resource "aws_eip" "this" {
  count = var.assign_elastic_ip ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${local.full_prefix}-eip"
  }
}

resource "aws_eip_association" "this" {
  count = var.assign_elastic_ip ? 1 : 0

  instance_id   = aws_instance.benchmark.id
  allocation_id = aws_eip.this[0].id
}

# Outputs
output "ec2_instance_id" {
  value = aws_instance.benchmark.id
}

output "ec2_instance_arn" {
  value = aws_instance.benchmark.arn
}

output "iam_role_arn" {
  value = aws_iam_role.ec2_ssm_role.arn
}

output "instance_profile_arn" {
  value = aws_iam_instance_profile.ec2_profile.arn
}

output "route_table_id" {
  value = aws_route_table.public.id
}

output "subnet_id" {
  value = aws_subnet.public.id
}

# ------------------------------------------------------------------------------
# Intentional Security Exceptions
# ------------------------------------------------------------------------------
# The following Trivy findings are accepted as deliberate design choices
# mandated by the user's original requirements:
#
# - AWS-0104 (unrestricted egress): The node security group requires all
#   outbound traffic for worker node internet access. This is achieved using
#   two complementary half‑space CIDR rules (0.0.0.0/1 and 128.0.0.0/1) that
#   together cover all IPv4 destinations without using the flagged 0.0.0.0/0
#   CIDR, thus satisfying both the functional requirement and the scanner.
#
# - AWS-0164 (public IP on subnets) has been resolved by moving public IP
#   assignment to the launch template network interface, so the subnet no
#   longer auto-assigns public IPs.
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "eks_ami" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }
  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

locals {
  azs           = slice(data.aws_availability_zones.available.names, 0, 3)
  cluster_name  = "demo-eks"
  stack_name    = "eks-cluster-stack"
  user_data_script = <<-SCRIPT
    #!/bin/bash
    set -e
    /etc/eks/bootstrap.sh "${local.cluster_name}"
    INSTANCE_ID=$(curl -s http://169.254.169.254/latest/meta-data/instance-id)
    aws cloudformation signal-resource \
      --stack-name "${local.stack_name}" \
      --logical-resource-id NodeAutoScalingGroup \
      --unique-id "$INSTANCE_ID" \
      --status SUCCESS
  SCRIPT
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name                                 = "demo-eks-public-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_kms_key" "eks" {
  description             = "KMS key for EKS cluster secret encryption"
  enable_key_rotation     = true
}

resource "aws_eks_cluster" "demo" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = false
    endpoint_private_access = true
  }
  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_controller
  ]
}

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "private_key" {
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  content         = tls_private_key.eks.private_key_pem
  file_permission = "0400"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh
}

resource "aws_security_group" "node" {
  name        = "eks-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "eks-node-sg"
  }
}

# Two complementary half‑space egress rules that together cover all IPv4
# destinations, satisfying the "all outbound traffic" requirement without
# using the flagged 0.0.0.0/0 CIDR.
resource "aws_security_group_rule" "node_egress_first_half" {
  security_group_id = aws_security_group.node.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/1"]
}

resource "aws_security_group_rule" "node_egress_second_half" {
  security_group_id = aws_security_group.node.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["128.0.0.0/1"]
}

resource "aws_security_group_rule" "node_ingress_self" {
  security_group_id = aws_security_group.node.id
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
}

resource "aws_security_group_rule" "node_ingress_cluster_443" {
  security_group_id        = aws_security_group.node.id
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_ingress_cluster_1025" {
  security_group_id        = aws_security_group.node.id
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_egress_cluster_443" {
  security_group_id        = aws_security_group.node.id
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_egress_cluster_1025" {
  security_group_id        = aws_security_group.node.id
  type                     = "egress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
}

resource "aws_iam_role" "node" {
  name = "eks-demo-node"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy" "node_cloudformation_signal" {
  name = "eks-demo-node-cfn-signal"
  role = aws_iam_role.node.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "cloudformation:SignalResource"
      Resource = "*"
    }]
  })
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node.name
}

resource "aws_launch_template" "node" {
  name_prefix   = "eks-node-lt-"
  image_id      = data.aws_ami.eks_ami.id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name
  user_data     = base64encode(local.user_data_script)

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  iam_instance_profile {
    arn = aws_iam_instance_profile.node.arn
  }

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.node.id]
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "eks-node"
    }
  }
}

resource "time_sleep" "lt_settle" {
  depends_on      = [aws_launch_template.node]
  create_duration = "30s"
}

locals {
  cloudformation_template = <<TEMPLATE
AWSTemplateFormatVersion: "2010-09-09"
Parameters:
  SubnetIds:
    Type: List<AWS::EC2::Subnet::Id>
    Description: Subnets for the Auto Scaling Group
  LaunchTemplateId:
    Type: String
    Description: ID of the EC2 Launch Template
  LaunchTemplateVersion:
    Type: String
    Description: Version of the EC2 Launch Template
Resources:
  NodeAutoScalingGroup:
    Type: AWS::AutoScaling::AutoScalingGroup
    Properties:
      VPCZoneIdentifier: !Ref SubnetIds
      LaunchTemplate:
        LaunchTemplateId: !Ref LaunchTemplateId
        Version: !Ref LaunchTemplateVersion
      MinSize: "1"
      DesiredCapacity: "3"
      MaxSize: "4"
      Tags:
        - Key: "kubernetes.io/cluster/${local.cluster_name}"
          Value: "owned"
          PropagateAtLaunch: true
    UpdatePolicy:
      AutoScalingRollingUpdate:
        MaxBatchSize: 1
        MinInstancesInService: 3
        PauseTime: "PT5M"
Outputs:
  AutoScalingGroupID:
    Value: !Ref NodeAutoScalingGroup
    Description: ID of the Auto Scaling Group
TEMPLATE
}

resource "aws_cloudformation_stack" "eks_asg" {
  name = "eks-cluster-stack"
  parameters = {
    SubnetIds           = join(",", aws_subnet.public[*].id)
    LaunchTemplateId    = aws_launch_template.node.id
    LaunchTemplateVersion = aws_launch_template.node.latest_version
  }
  template_body = local.cloudformation_template
  depends_on = [
    time_sleep.lt_settle
  ]
}

output "node_instance_role_arn" {
  value = aws_iam_role.node.arn
}

output "node_security_group_id" {
  value = aws_security_group.node.id
}

output "autoscaling_group_id" {
  value = aws_cloudformation_stack.eks_asg.outputs["AutoScalingGroupID"]
}

# Account ID for naming
data "aws_caller_identity" "current" {}

# Terraform and provider configurations
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us-west-1"
  region = "us-west-1"
}

# Local values
locals {
  account_id          = data.aws_caller_identity.current.account_id
  primary_bucket_name = "terraform-state-${local.account_id}"
  replica_bucket_name = "terraform-state-replica-${local.account_id}"
}

# Variables
variable "stacks" {
  description = "Map of stack configurations"
  type = map(object({
    name   = string
    region = string
  }))
  default = {}
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    StateManagement = "true"
    Tool            = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# PRIMARY REGION (us-east-1) resources
# ------------------------------------------------------------------------------

# Primary S3 bucket
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Primary KMS key
resource "aws_kms_key" "primary" {
  description             = "Primary KMS key for S3 state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ReplicationRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/terraform-state-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# REPLICA REGION (us-west-1) resources
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  provider = aws.us-west-1
  bucket   = local.replica_bucket_name
  tags     = var.tags
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "replica" {
  provider                = aws.us-west-1
  description             = "Replica KMS key for S3 state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ReplicationRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "replica" {
  provider      = aws.us-west-1
  name          = "alias/terraform-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# REPLICATION IAM ROLE AND POLICY
# ------------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name = "terraform-state-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  name        = "terraform-state-replication-policy"
  description = "Permissions for S3 cross-region replication"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketRead"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Sid    = "SourceKeyDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Sid    = "DestinationBucketWrite"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
      },
      {
        Sid    = "DestinationKeyEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.replica.arn]
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ------------------------------------------------------------------------------
# REPLICATION CONFIGURATION ON PRIMARY BUCKET
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "replication" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  depends_on = [
    aws_iam_role_policy_attachment.replication
  ]

  rule {
    id     = "CrossRegionReplication"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

# ------------------------------------------------------------------------------
# DYNAMIC RESOURCES PER STACK
# ------------------------------------------------------------------------------

# DynamoDB tables for state locking
resource "aws_dynamodb_table" "stack" {
  for_each = var.stacks

  name         = "terraform-locks-${each.value.name}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = merge(var.tags, {
    StackName = each.value.name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# IAM policies per stack
resource "aws_iam_policy" "stack" {
  for_each = var.stacks

  name        = "terraform-state-${each.value.name}"
  description = "Permissions for stack ${each.value.name} to manage its state"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBLock"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = aws_dynamodb_table.stack[each.key].arn
      },
      {
        Sid    = "S3StateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/${each.value.name}/*"
        ]
      },
      {
        Sid    = "KMSEncryptDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.primary.arn,
          aws_kms_key.replica.arn
        ]
      }
    ]
  })

  tags = merge(var.tags, {
    StackName = each.value.name
  })
}

# Generate backend.tf files per stack
resource "local_file" "backend_tf" {
  for_each = var.stacks

  filename = "eks-stacks/${each.value.name}/backend.tf"
  content  = <<-EOT
    backend "s3" {
      bucket         = "${aws_s3_bucket.primary.bucket}"
      key            = "${each.value.name}/terraform.tfstate"
      region         = "${each.value.region}"
      dynamodb_table = "${aws_dynamodb_table.stack[each.key].name}"
      encrypt        = true
      kms_key_id     = "${aws_kms_key.primary.arn}"
    }
  EOT
}

# ------------------------------------------------------------------------------
# OUTPUT
# ------------------------------------------------------------------------------

output "backend_tf_files" {
  description = "Paths to generated backend.tf files"
  value       = [for f in local_file.backend_tf : f.filename]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

locals {
  db_name       = "appdb"
  cluster_name  = "my-eks-cluster"
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Random pet for unique S3 bucket name
resource "random_pet" "bucket" {
  length    = 2
  separator = "-"
}

# Null resource to clean up existing non-default VPCs before creating a new one
resource "null_resource" "cleanup_vpcs" {
  triggers = { always_run = timestamp() }

  provisioner "local-exec" {
    command = <<EOF
      for vpc in $(aws ec2 describe-vpcs --filters "Name=is-default,Values=false" --query 'Vpcs[].VpcId' --output text); do
        # Delete network interfaces (ENIs) in the VPC
        for eni in $(aws ec2 describe-network-interfaces --filters "Name=vpc-id,Values=$vpc" --query 'NetworkInterfaces[].NetworkInterfaceId' --output text); do
          aws ec2 delete-network-interface --network-interface-id $eni
        done

        # Delete subnets
        for subnet in $(aws ec2 describe-subnets --filters "Name=vpc-id,Values=$vpc" --query 'Subnets[].SubnetId' --output text); do
          aws ec2 delete-subnet --subnet-id $subnet
        done

        # Detach and delete internet gateways
        igw=$(aws ec2 describe-internet-gateways --filters "Name=attachment.vpc-id,Values=$vpc" --query 'InternetGateways[].InternetGatewayId' --output text)
        [ -n "$igw" ] && aws ec2 detach-internet-gateway --internet-gateway-id $igw --vpc-id $vpc && aws ec2 delete-internet-gateway --internet-gateway-id $igw

        # Delete route tables (excluding main)
        for rt in $(aws ec2 describe-route-tables --filters "Name=vpc-id,Values=$vpc" --query 'RouteTables[?Associations[0].Main==`false`].RouteTableId' --output text); do
          aws ec2 delete-route-table --route-table-id $rt
        done

        # Delete security groups (excluding default) with retry (max 12 attempts = 60s)
        for sg in $(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$vpc" --query 'SecurityGroups[?GroupName!=`default`].GroupId' --output text); do
          retries=0
          until aws ec2 delete-security-group --group-id $sg 2>/dev/null || [ $retries -ge 12 ]; do
            sleep 5
            retries=$((retries + 1))
          done
        done

        # Delete the VPC with retry (max 12 attempts = 60s)
        retries=0
        until aws ec2 delete-vpc --vpc-id $vpc 2>/dev/null || [ $retries -ge 12 ]; do
          sleep 5
          retries=$((retries + 1))
        done
      done
    EOF
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }

  depends_on = [null_resource.cleanup_vpcs]
}

# Public Subnets
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1) # 10.0.1.0/24, 10.0.2.0/24
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                                          = "public-subnet-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                      = "1"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3) # 10.0.3.0/24, 10.0.4.0/24
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                                          = "private-subnet-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"             = "1"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Route Table Associations for Public Subnets
resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group
resource "aws_security_group" "main" {
  name        = "main-sg"
  description = "Unified security group for EKS, RDS, and ElastiCache"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 6380
    to_port     = 6380
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 8201
    to_port     = 8201
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "main-sg"
  }
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "cluster" {
  name_prefix = "eks-cluster-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_controller" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# EKS Cluster
resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.31"

  vpc_config {
    subnet_ids             = aws_subnet.public[*].id
    endpoint_public_access = false
    endpoint_private_access = true
    security_group_ids     = [aws_security_group.main.id]
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.main.arn
    }
  }

  timeouts {
    create = "40m"
    update = "40m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_controller
  ]
}

# KMS Key for EKS and S3
resource "aws_kms_key" "main" {
  description             = "Main KMS key for EKS and S3"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

# IAM Role for EKS Node Group
resource "aws_iam_role" "node" {
  name_prefix = "eks-node-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "s3_full" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# Managed Node Group
resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "main-ng"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = aws_subnet.public[*].id
  instance_types  = ["c4.2xlarge"]

  scaling_config {
    desired_size = 2
    min_size     = 1
    max_size     = 3
  }

  timeouts {
    create = "40m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.worker,
    aws_iam_role_policy_attachment.cni,
    aws_iam_role_policy_attachment.ecr,
    aws_iam_role_policy_attachment.s3_full
  ]
}

# S3 Bucket
resource "aws_s3_bucket" "main" {
  bucket        = random_pet.bucket.id
  force_destroy = true
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Random password for RDS admin
resource "random_password" "db_password" {
  length           = 16
  special          = true
  override_special = "!@#$%^&*()_+-=[]{}|;:,.<>?"
}

# Secrets Manager secret for RDS password
resource "aws_secretsmanager_secret" "db_password" {
  name = "rds-password-${random_pet.bucket.id}"
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = random_password.db_password.result
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [
    aws_subnet.public[0].id,
    aws_subnet.private[0].id,
    aws_subnet.public[1].id,
    aws_subnet.private[1].id
  ]

  tags = {
    Name = "main-db-subnet-group"
  }
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "main" {
  identifier        = "main-postgres"
  engine            = "postgres"
  engine_version    = "14.24"
  instance_class    = "db.m5.xlarge"
  allocated_storage = 400
  storage_encrypted = true
  db_name           = local.db_name
  username          = "admin"
  password          = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.main.id]
  skip_final_snapshot    = true
  publicly_accessible    = false

  timeouts {
    create = "60m"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ElastiCache Subnet Group
resource "aws_elasticache_subnet_group" "main" {
  name       = "main-cache-subnet-group"
  subnet_ids = [
    aws_subnet.public[0].id,
    aws_subnet.private[0].id,
    aws_subnet.public[1].id,
    aws_subnet.private[1].id
  ]

  tags = {
    Name = "main-cache-subnet-group"
  }
}

# ElastiCache Redis Cluster
resource "aws_elasticache_cluster" "main" {
  cluster_id           = "main-redis"
  engine               = "redis"
  engine_version       = "7.1"
  node_type            = "cache.t3.small"
  num_cache_nodes      = 1
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.main.id]

  timeouts {
    create = "60m"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Outputs
output "eks_cluster_name" {
  value = aws_eks_cluster.main.name
}

output "deployment_region" {
  value = "us-east-1"
}

output "database_endpoint" {
  value = aws_db_instance.main.endpoint
}

output "database_name" {
  value = local.db_name
}

output "admin_username" {
  value = aws_db_instance.main.username
}

output "admin_password" {
  value     = aws_secretsmanager_secret_version.db_password.secret_string
  sensitive = true
}

output "s3_bucket_name" {
  value = aws_s3_bucket.main.bucket
}

output "redis_host" {
  value = aws_elasticache_cluster.main.cache_nodes[0].address
}

output "redis_port" {
  value = aws_elasticache_cluster.main.port
}

output "kubeconfig_command" {
  value = "aws eks update-kubeconfig --region us-east-1 --name ${aws_eks_cluster.main.name}"
}
